window.DATA = [{"id": "A01", "section": "A", "num": 1, "page": 5, "topic": "함수의 수렴과 발산", "answer": "2", "rate": "", "problem": "", "explanation": "$f(x)=x+4$라 하면 $y=f(x)$의 그래프는 기울기 $1$, $y$절편 $4$인 직선이다.\n$x$의 값이 $-2$가 아니면서 $-2$에 한없이 가까워질 때, $f(x)$의 값은 $2$에 한없이 가까워지므로 $\\lim_{x \\to -2}(x+4)=2$", "img": "IMG_4910.jpg"}, {"id": "A02", "section": "A", "num": 2, "page": 5, "topic": "함수의 수렴과 발산", "answer": "5", "rate": "", "problem": "", "explanation": "$f(x)=x^{2}+1$이라 하면 $y=f(x)$의 그래프는 꼭짓점이 $(0, 1)$인 포물선이다.\n$x$의 값이 $2$가 아니면서 $2$에 한없이 가까워질 때, $f(x)$의 값은 $5$에 한없이 가까워지므로 $\\lim_{x \\to 2}(x^{2}+1)=5$", "img": "IMG_4910.jpg"}, {"id": "A03", "section": "A", "num": 3, "page": 5, "topic": "함수의 수렴과 발산", "answer": "1", "rate": "", "problem": "", "explanation": "$f(x)=\\sqrt{x-3}$이라 하면 $y=f(x)$의 그래프는 $(3, 0)$에서 시작하는 곡선이다.\n$x$의 값이 $4$가 아니면서 $4$에 한없이 가까워질 때, $f(x)$의 값은 $1$에 한없이 가까워지므로 $\\lim_{x \\to 4}\\sqrt{x-3}=1$", "img": "IMG_4910.jpg"}, {"id": "A04", "section": "A", "num": 4, "page": 5, "topic": "함수의 수렴과 발산", "answer": "1", "rate": "", "problem": "", "explanation": "$f(x)=\\frac{1}{x+2}$이라 하면 $y=f(x)$의 그래프는 점근선이 $x=-2$, $y=0$인 쌍곡선이다.\n$x$의 값이 $-1$이 아니면서 $-1$에 한없이 가까워질 때, $f(x)$의 값은 $1$에 한없이 가까워지므로 $\\lim_{x \\to -1} \\frac{1}{x+2}=1$", "img": "IMG_4910.jpg"}, {"id": "A05", "section": "A", "num": 5, "page": 5, "topic": "함수의 수렴과 발산", "answer": "$\\sqrt{7}$", "rate": "", "problem": "", "explanation": "$f(x)=\\sqrt{7}$이라 하면 $y=f(x)$의 그래프(상수함수)에서 $\\lim_{x \\to \\infty}\\sqrt{7}=\\sqrt{7}$", "img": "IMG_4910.jpg"}, {"id": "A06", "section": "A", "num": 6, "page": 5, "topic": "함수의 수렴과 발산", "answer": "5", "rate": "", "problem": "", "explanation": "$f(x)=5-\\frac{1}{x}$이라 하면 $y=f(x)$의 그래프(점근선 $x=0$, $y=5$)에서 $\\lim_{x \\to -\\infty}\\left(5-\\frac{1}{x}\\right)=5$", "img": "IMG_4910.jpg"}, {"id": "A07", "section": "A", "num": 7, "page": 5, "topic": "함수의 수렴과 발산", "answer": "$\\infty$", "rate": "", "problem": "", "explanation": "$f(x)=\\frac{1}{|x|}-3$이라 하면 $y=f(x)$의 그래프(점근선 $x=0$, $y=-3$)에서 $\\lim_{x \\to 0}\\left(\\frac{1}{|x|}-3\\right)=\\infty$", "img": "IMG_4910.jpg"}, {"id": "A08", "section": "A", "num": 8, "page": 5, "topic": "함수의 수렴과 발산", "answer": "$\\infty$", "rate": "", "problem": "", "explanation": "$f(x)=\\frac{2}{|x-1|}$이라 하면 $y=f(x)$의 그래프(점근선 $x=1$, $y=0$)에서 $\\lim_{x \\to 1} \\frac{2}{|x-1|}=\\infty$", "img": "IMG_4910.jpg"}, {"id": "A09", "section": "A", "num": 9, "page": 5, "topic": "함수의 수렴과 발산", "answer": "$-\\infty$", "rate": "", "problem": "", "explanation": "$f(x)=-x+7$이라 하면 $y=f(x)$의 그래프에서 $\\lim_{x \\to \\infty}(-x+7)=-\\infty$", "img": "IMG_4910.jpg"}, {"id": "A10", "section": "A", "num": 10, "page": 5, "topic": "함수의 수렴과 발산", "answer": "$\\infty$", "rate": "", "problem": "", "explanation": "$f(x)=2x^{2}$이라 하면 $y=f(x)$의 그래프에서 $\\lim_{x \\to -\\infty}2x^{2}=\\infty$", "img": "IMG_4910.jpg"}, {"id": "A11", "section": "A", "num": 11, "page": 5, "topic": "좌극한과 우극한", "answer": "7", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 2+}(3x+1)=3\\times2+1=7$", "img": "IMG_4910.jpg"}, {"id": "A12", "section": "A", "num": 12, "page": 5, "topic": "좌극한과 우극한", "answer": "$-3$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 2-}(-2x+1)=(-2)\\times2+1=-3$", "img": "IMG_4910.jpg"}, {"id": "A13", "section": "A", "num": 13, "page": 5, "topic": "좌극한과 우극한", "answer": "0", "rate": "", "problem": "", "explanation": "$|0|=0$이므로 $\\lim_{x \\to 0-}|x|=0$", "img": "IMG_4910.jpg"}, {"id": "A14", "section": "A", "num": 14, "page": 5, "topic": "좌극한과 우극한", "answer": "1", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 0+} \\frac{x}{|x|} = \\lim_{x \\to 0+} \\frac{x}{x} = 1$", "img": "IMG_4910.jpg"}, {"id": "A15", "section": "A", "num": 15, "page": 6, "topic": "좌극한과 우극한", "answer": "$-2$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 1-} \\frac{x^{2}-1}{|x-1|} = \\lim_{x \\to 1-} \\frac{(x-1)(x+1)}{|x-1|}$\n$= \\lim_{x \\to 1-} \\frac{(x-1)(x+1)}{-(x-1)}$\n$= -\\lim_{x \\to 1-}(x+1) = -2$", "img": "IMG_4911.jpg"}, {"id": "A16", "section": "A", "num": 16, "page": 6, "topic": "좌극한과 우극한", "answer": "0", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 0+}f(x)+\\lim_{x \\to 0-}f(x) = \\lim_{x \\to 0+}(x+1)+\\lim_{x \\to 0-}(-x-1)$\n$=1+(-1)=0$", "img": "IMG_4911.jpg"}, {"id": "A17", "section": "A", "num": 17, "page": 6, "topic": "좌극한과 우극한", "answer": "1", "rate": "", "problem": "", "explanation": "그림에서 $x$값이 $1$보다 작으면서 $1$에 가까워질 때, $f(x)$의 값은 $1$보다 작으면서 $1$에 가까워진다.\n$\\therefore \\lim_{x \\to 1-}f(x)=1$", "img": "IMG_4911.jpg"}, {"id": "A18", "section": "A", "num": 18, "page": 6, "topic": "좌극한과 우극한", "answer": "0", "rate": "", "problem": "", "explanation": "그림에서 $x$값이 $0$보다 크면서 $0$에 가까워질 때, $g(x)$의 값은 $0$보다 크면서 $0$에 가까워진다.\n$\\therefore \\lim_{x \\to 0+}g(x)=0$", "img": "IMG_4911.jpg"}, {"id": "A19", "section": "A", "num": 19, "page": 6, "topic": "좌극한과 우극한", "answer": "3", "rate": "", "problem": "", "explanation": "그림에서 $x$값이 $-1$보다 작으면서 $-1$에 가까워질 때, $h(x)$의 값은 $3$보다 작으면서 $3$에 가까워진다.\n$\\therefore \\lim_{x \\to -1-}h(x)=3$", "img": "IMG_4911.jpg"}, {"id": "A20", "section": "A", "num": 20, "page": 6, "topic": "함수의 극한에 대한 성질", "answer": "$-8$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 1} 8f(x) = 8 \\lim_{x \\to 1} f(x) = 8\\times(-1) = -8$", "img": "IMG_4911.jpg"}, {"id": "A21", "section": "A", "num": 21, "page": 6, "topic": "함수의 극한에 대한 성질", "answer": "5", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 1}\\left\\{f(x)+g(x)\\right\\} = \\lim_{x \\to 1}f(x)+\\lim_{x \\to 1}g(x) = -1+6 = 5$", "img": "IMG_4911.jpg"}, {"id": "A22", "section": "A", "num": 22, "page": 6, "topic": "함수의 극한에 대한 성질", "answer": "$-7$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 1}\\left\\{f(x)-g(x)\\right\\} = \\lim_{x \\to 1}f(x)-\\lim_{x \\to 1}g(x) = -1-6 = -7$", "img": "IMG_4911.jpg"}, {"id": "A23", "section": "A", "num": 23, "page": 6, "topic": "함수의 극한에 대한 성질", "answer": "$-6$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 1}f(x)g(x) = \\lim_{x \\to 1}f(x)\\times\\lim_{x \\to 1}g(x) = (-1)\\times6 = -6$", "img": "IMG_4911.jpg"}, {"id": "A24", "section": "A", "num": 24, "page": 6, "topic": "함수의 극한에 대한 성질", "answer": "$-\\frac{1}{6}$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 1} \\frac{f(x)}{g(x)} = \\frac{\\lim_{x \\to 1}f(x)}{\\lim_{x \\to 1}g(x)} = -\\frac{1}{6}$", "img": "IMG_4911.jpg"}, {"id": "A25", "section": "A", "num": 25, "page": 6, "topic": "함수의 극한에 대한 성질", "answer": "11", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to -2}(3-4x) = 3-4\\times(-2) = 3+8 = 11$", "img": "IMG_4911.jpg"}, {"id": "A26", "section": "A", "num": 26, "page": 6, "topic": "함수의 극한에 대한 성질", "answer": "7", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 3}(x^{2}-3x+7) = 3^{2}-3\\times3+7 = 9-9+7 = 7$", "img": "IMG_4911.jpg"}, {"id": "A27", "section": "A", "num": 27, "page": 6, "topic": "함수의 극한에 대한 성질", "answer": "$\\frac{4}{3}$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 1} \\frac{x+3}{5x-2} = \\frac{1+3}{5-2} = \\frac{4}{3}$", "img": "IMG_4911.jpg"}, {"id": "A28", "section": "A", "num": 28, "page": 6, "topic": "함수의 극한에 대한 성질", "answer": "$2\\sqrt{2}$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 0} \\frac{\\sqrt{2-x}+\\sqrt{2x+2}}{x+1} = \\frac{\\sqrt{2+0}+\\sqrt{0+2}}{0+1} = 2\\sqrt{2}$", "img": "IMG_4911.jpg"}, {"id": "A29", "section": "A", "num": 29, "page": 6, "topic": "함수의 극한값의 계산", "answer": "2", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 1} \\frac{x^{2}-1}{x-1} = \\lim_{x \\to 1} \\frac{(x-1)(x+1)}{x-1} = \\lim_{x \\to 1}(x+1) = 2$", "img": "IMG_4911.jpg"}, {"id": "A30", "section": "A", "num": 30, "page": 6, "topic": "함수의 극한값의 계산", "answer": "6", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 3} \\frac{x^{2}-9}{x-3} = \\lim_{x \\to 3} \\frac{(x-3)(x+3)}{x-3} = \\lim_{x \\to 3}(x+3) = 6$", "img": "IMG_4911.jpg"}, {"id": "A31", "section": "A", "num": 31, "page": 6, "topic": "함수의 극한값의 계산", "answer": "$-5$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to -2} \\frac{x^{2}-x-6}{x+2} = \\lim_{x \\to -2} \\frac{(x+2)(x-3)}{x+2} = \\lim_{x \\to -2}(x-3) = -5$", "img": "IMG_4911.jpg"}, {"id": "A32", "section": "A", "num": 32, "page": 6, "topic": "함수의 극한값의 계산", "answer": "1", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 1}\\sqrt{2x-1} = \\sqrt{2\\times1-1} = 1$", "img": "IMG_4911.jpg"}, {"id": "A33", "section": "A", "num": 33, "page": 7, "topic": "함수의 극한값의 계산", "answer": "$\\sqrt{2}+2$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 2} \\frac{x-4}{\\sqrt{x}-2} = \\lim_{x \\to 2} \\frac{(\\sqrt{x})^{2}-2^{2}}{\\sqrt{x}-2}$\n$= \\lim_{x \\to 2} \\frac{(\\sqrt{x}-2)(\\sqrt{x}+2)}{\\sqrt{x}-2}$\n$= \\sqrt{2}+2$", "img": "IMG_4912.jpg"}, {"id": "A34", "section": "A", "num": 34, "page": 7, "topic": "함수의 극한값의 계산", "answer": "2", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 0} \\frac{x}{\\sqrt{x+1}-1} = \\lim_{x \\to 0} \\frac{x(\\sqrt{x+1}+1)}{(\\sqrt{x+1}-1)(\\sqrt{x+1}+1)}$\n$= \\lim_{x \\to 0} \\frac{x(\\sqrt{x+1}+1)}{x+1-1}$\n$= \\lim_{x \\to 0}(\\sqrt{x+1}+1)$\n$= \\sqrt{1}+1 = 2$", "img": "IMG_4912.jpg"}, {"id": "A35", "section": "A", "num": 35, "page": 7, "topic": "함수의 극한값의 계산", "answer": "0", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to \\infty} \\frac{6x+2}{3x^{2}+x+1} = 0$", "img": "IMG_4912.jpg"}, {"id": "A36", "section": "A", "num": 36, "page": 7, "topic": "함수의 극한값의 계산", "answer": "3", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to \\infty} \\frac{3x+2}{x+1} = \\frac{3}{1} = 3$", "img": "IMG_4912.jpg"}, {"id": "A37", "section": "A", "num": 37, "page": 7, "topic": "함수의 극한값의 계산", "answer": "$\\infty$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to \\infty} \\frac{3x^{2}-4x}{x+2} = \\lim_{x \\to \\infty} \\frac{3x-4}{1+\\frac{2}{x}} = \\infty$", "img": "IMG_4912.jpg"}, {"id": "A38", "section": "A", "num": 38, "page": 7, "topic": "함수의 극한값의 계산", "answer": "$\\frac{1}{2}$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to \\infty} \\frac{x^{2}-x+1}{2x^{2}+3} = \\frac{1}{2}$", "img": "IMG_4912.jpg"}, {"id": "A39", "section": "A", "num": 39, "page": 7, "topic": "함수의 극한값의 계산", "answer": "$\\frac{2}{5}$", "rate": "", "problem": "", "explanation": "$$\\lim_{x \\to \\infty} \\frac{(x-3)(2x+1)}{5x^{2}-x+2} = \\lim_{x \\to \\infty} \\frac{2x^{2}-5x-3}{5x^{2}-x+2}$$\n$$= \\lim_{x \\to \\infty} \\frac{2-\\frac{5}{x}-\\frac{3}{x^{2}}}{5-\\frac{1}{x}+\\frac{2}{x^{2}}}$$\n$$= \\frac{2}{5}$$", "img": "IMG_4912.jpg"}, {"id": "A40", "section": "A", "num": 40, "page": 7, "topic": "함수의 극한값의 계산", "answer": "$3$", "rate": "", "problem": "", "explanation": "$$\\lim_{x \\to \\infty} \\frac{3x}{\\sqrt{x^{2}+4x}-7} = \\lim_{x \\to \\infty} \\frac{3}{\\sqrt{1+\\frac{4}{x}}-\\frac{7}{x}} = \\frac{3}{\\sqrt{1}} = 3$$", "img": "IMG_4912.jpg"}, {"id": "A41", "section": "A", "num": 41, "page": 7, "topic": "함수의 극한값의 계산", "answer": "$\\infty$", "rate": "", "problem": "", "explanation": "$$\\lim_{x \\to \\infty}(x^{2}+3x-1) = \\lim_{x \\to \\infty} x^{2}\\left(1+\\frac{3}{x}-\\frac{1}{x^{2}}\\right) = \\infty$$", "img": "IMG_4912.jpg"}, {"id": "A42", "section": "A", "num": 42, "page": 7, "topic": "함수의 극한값의 계산", "answer": "$0$", "rate": "", "problem": "", "explanation": "$$\\lim_{x \\to \\infty}\\left(\\sqrt{4x^{2}+1}-2x\\right) = \\lim_{x \\to \\infty} \\frac{4x^{2}+1-4x^{2}}{\\sqrt{4x^{2}+1}+2x}$$\n$$= \\lim_{x \\to \\infty} \\frac{1}{\\sqrt{4x^{2}+1}+2x} = 0$$", "img": "IMG_4912.jpg"}, {"id": "A43", "section": "A", "num": 43, "page": 7, "topic": "함수의 극한값의 계산", "answer": "$4$", "rate": "", "problem": "", "explanation": "$$\\lim_{x \\to \\infty}\\left(\\sqrt{x^{2}+8x}-x\\right) = \\lim_{x \\to \\infty} \\frac{x^{2}+8x-x^{2}}{\\sqrt{x^{2}+8x}+x}$$\n$$= \\lim_{x \\to \\infty} \\frac{8x}{\\sqrt{x^{2}+8x}+x}$$\n$$= \\lim_{x \\to \\infty} \\frac{8}{\\sqrt{1+\\frac{8}{x}}+1} = 4$$", "img": "IMG_4912.jpg"}, {"id": "A44", "section": "A", "num": 44, "page": 7, "topic": "함수의 극한값의 계산", "answer": "$\\frac{1}{2}$", "rate": "", "problem": "", "explanation": "$$\\lim_{x \\to 0} \\frac{1}{2x}\\left(1-\\frac{1}{x+1}\\right) = \\lim_{x \\to 0} \\frac{1}{2x} \\times \\frac{x}{x+1}$$\n$$= \\lim_{x \\to 0} \\frac{1}{2(x+1)} = \\frac{1}{2}$$", "img": "IMG_4912.jpg"}, {"id": "A45", "section": "A", "num": 45, "page": 7, "topic": "함수의 극한값의 계산", "answer": "$3$", "rate": "", "problem": "", "explanation": "$$\\lim_{x \\to -2} \\frac{1}{x+2}\\left(2x+\\frac{3x+2}{x+1}\\right)$$\n$$= \\lim_{x \\to -2} \\frac{1}{x+2} \\times \\frac{2x^{2}+5x+2}{x+1}$$\n$$= \\lim_{x \\to -2} \\frac{1}{x+2} \\times \\frac{(2x+1)(x+2)}{x+1}$$\n$$= \\lim_{x \\to -2} \\frac{2x+1}{x+1} = 3$$", "img": "IMG_4912.jpg"}, {"id": "A46", "section": "A", "num": 46, "page": 7, "topic": "미정계수의 결정", "answer": "$1$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to -1} \\frac{x^{2}+2x+a}{x+1}$가 수렴하고 $\\lim_{x \\to -1}(x+1)=0$이므로\n$\\lim_{x \\to -1}(x^{2}+2x+a)=0$\n$1-2+a=0 \\quad \\therefore a=1$", "img": "IMG_4912.jpg"}, {"id": "A47", "section": "A", "num": 47, "page": 8, "topic": "미정계수의 결정", "answer": "$-\\frac{1}{2}$", "rate": "", "problem": "", "explanation": "$\\lim_{x \\to 2} \\frac{\\frac{1}{2}x+a}{x-2}=b$로 수렴하고 $\\lim_{x \\to 2}(x-2)=0$이므로 $\\lim_{x \\to 2}\\left(\\frac{1}{2}x+a\\right)=0$\n$\\frac{1}{2}\\times 2+a=0 \\quad \\therefore a=-1$\n$\\therefore b=\\lim_{x \\to 2} \\frac{\\frac{1}{2}x-1}{x-2} = \\lim_{x \\to 2} \\frac{\\frac{1}{2}(x-2)}{x-2} = \\frac{1}{2}$\n$\\therefore a+b=-\\frac{1}{2}$", "img": "IMG_4913.jpg"}, {"id": "A48", "section": "A", "num": 48, "page": 8, "topic": "미정계수의 결정", "answer": "$a=9$, $b=\\frac{3}{2}$", "rate": "", "problem": "", "explanation": "$x \\to 0$일 때, (분모)$\\to 0$이고 극한값이 존재하므로 (분자)$\\to 0$이다.\n즉, $\\lim_{x \\to 0}\\left(\\sqrt{x+a}-2b\\right)=0$이므로 $\\sqrt{a}-2b=0$\n$\\therefore b=\\frac{\\sqrt{a}}{2}$ ⋯ ㉠\n㉠을 주어진 등식의 좌변에 대입하면\n$$\\lim_{x \\to 0} \\frac{\\sqrt{x+a}-2b}{x} = \\lim_{x \\to 0} \\frac{x+a-a}{x\\left(\\sqrt{x+a}+\\sqrt{a}\\right)}$$\n$$= \\lim_{x \\to 0} \\frac{x}{x\\left(\\sqrt{x+a}+\\sqrt{a}\\right)}$$\n$$= \\lim_{x \\to 0} \\frac{1}{\\sqrt{x+a}+\\sqrt{a}} = \\frac{1}{2\\sqrt{a}}$$\n이므로 $\\frac{1}{2\\sqrt{a}}=\\frac{1}{6} \\quad \\therefore a=9$\n$a=9$를 ㉠에 대입하면 $b=\\frac{3}{2}$", "img": "IMG_4913.jpg"}, {"id": "A49", "section": "A", "num": 49, "page": 8, "topic": "함수의 극한의 대소 관계", "answer": "$3$", "rate": "", "problem": "", "explanation": "$\\frac{3x^{2}+1}{x^{2}} \\le f(x) \\le \\frac{3x+1}{x}$\n각 변에 $\\lim_{x \\to \\infty}$를 취하면\n$\\lim_{x \\to \\infty}\\frac{3x^{2}+1}{x^{2}} \\le \\lim_{x \\to \\infty}f(x) \\le \\lim_{x \\to \\infty}\\frac{3x+1}{x}$\n여기서 $\\lim_{x \\to \\infty}\\frac{3x^{2}+1}{x^{2}}=3$, $\\lim_{x \\to \\infty}\\frac{3x+1}{x}=3$\n$\\therefore \\lim_{x \\to \\infty}f(x)=3$", "img": "IMG_4913.jpg"}, {"id": "A50", "section": "A", "num": 50, "page": 8, "topic": "함수의 극한의 대소 관계", "answer": "$1$", "rate": "", "problem": "", "explanation": "$x+7 < (x+1)f(x) < x+9$\n각 변에 $\\frac{1}{x+1}$을 곱하면\n$\\frac{x+7}{x+1} < f(x) < \\frac{x+9}{x+1}$\n각 변에 $\\lim_{x \\to \\infty}$를 취하면\n$\\lim_{x \\to \\infty}\\frac{x+7}{x+1} \\le \\lim_{x \\to \\infty}f(x) \\le \\lim_{x \\to \\infty}\\frac{x+9}{x+1}$\n여기서 $\\lim_{x \\to \\infty}\\frac{x+7}{x+1}=1$, $\\lim_{x \\to \\infty}\\frac{x+9}{x+1}=1$\n$\\therefore \\lim_{x \\to \\infty}f(x)=1$", "img": "IMG_4913.jpg"}, {"id": "A51", "section": "A", "num": 51, "page": 8, "topic": "함수의 좌극한과 우극한", "answer": "①", "rate": "95%", "problem": "닫힌구간 $[-2, 2]$에서 정의된 함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0-}f(x)+\\lim_{x \\to 1+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to 0-$는 $x=0$의 왼쪽에서 $x=0$으로 접근하는 것이고, $x \\to 1+$는 $x=1$의 오른쪽에서 $x=1$로 접근하는 것이다.\n1st 주어진 그래프를 이용하여 극한값을 구해.\n$x=0$의 왼쪽에서 함수 $y=f(x)$의 그래프를 따라 $x=0$으로 접근하면 $y$의 값은 $-1$에 한없이 가까워지므로 $\\lim_{x \\to 0-}f(x)=-1$ ($x=0$에서의 좌극한값이야.)\n또, $x=1$의 오른쪽에서 함수 $y=f(x)$의 그래프를 따라 $x=1$로 접근하면 $y$의 값은 $2$에 한없이 가까워지므로 $\\lim_{x \\to 1+}f(x)=2$ ($x=1$에서의 우극한값이야.)\n$\\therefore \\lim_{x \\to 0-}f(x)+\\lim_{x \\to 1+}f(x)=-1+2=1$", "img": "IMG_4913.jpg", "answer_value": "$1$"}, {"id": "A52", "section": "A", "num": 52, "page": 8, "topic": "함수의 좌극한과 우극한", "answer": "②", "rate": "94%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 1-}f(x)+\\lim_{x \\to 3+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to 1-$는 $x=1$의 왼쪽에서 $x=1$로 접근하는 것이고, $x \\to 3+$는 $x=3$의 오른쪽에서 $x=3$으로 접근하는 것이다.\n1st 주어진 그래프를 이용하여 극한값을 구해.\n$x=1$의 왼쪽에서 함수 $y=f(x)$의 그래프를 따라 $x=1$로 접근하면 $y$의 값은 $1$에 한없이 가까워지므로 $\\lim_{x \\to 1-}f(x)=1$ ($x=1$에서의 좌극한값이야.)\n또, $x=3$의 오른쪽에서 함수 $y=f(x)$의 그래프를 따라 $x=3$으로 접근하면 $y$의 값은 $-2$에 한없이 가까워지므로 $\\lim_{x \\to 3+}f(x)=-2$ ($x=3$에서의 우극한값이야.)\n$\\therefore \\lim_{x \\to 1-}f(x)+\\lim_{x \\to 3+}f(x)=1-2=-1$", "img": "IMG_4913.jpg", "answer_value": "$-1$"}, {"id": "A53", "section": "A", "num": 53, "page": 9, "topic": "함수의 좌극한과 우극한", "answer": "④", "rate": "93%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -1-}f(x)+\\lim_{x \\to 0+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to -1-$는 $x=-1$의 왼쪽에서 $x=-1$로 접근하는 것이고, $x \\to 0+$는 $x=0$의 오른쪽에서 $x=0$으로 접근하는 것이다.\n1st 주어진 그래프에서 $x=-1$에서의 좌극한값과 $x=0$에서의 우극한값을 각각 구하여 계산해.\n$x=-1$의 왼쪽에서 함수 $y=f(x)$의 그래프를 따라 $x=-1$로 접근하면 $y$의 값은 $3$에 한없이 가까워지므로 $\\lim_{x \\to -1-}f(x)=3$ ($x=-1$에서의 좌극한값이야.)\n또, $x=0$의 오른쪽에서 함수 $y=f(x)$의 그래프를 따라 $x=0$으로 접근하면 $y$의 값은 $1$에 한없이 가까워지므로 $\\lim_{x \\to 0+}f(x)=1$ ($x=0$에서의 우극한값이야.)\n$\\therefore \\lim_{x \\to -1-}f(x)+\\lim_{x \\to 0+}f(x)=3+1=4$", "img": "IMG_4914.jpg", "answer_value": "$4$"}, {"id": "A54", "section": "A", "num": 54, "page": 9, "topic": "함수의 좌극한과 우극한", "answer": "④", "rate": "83%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -1}f(x)+\\lim_{x \\to 1-}f(x)$의 값은? (3점)", "explanation": "정답 공식: 함수의 그래프가 제시된 경우 그래프를 따라가며 좌극한과 우극한의 값을 구한다.\n1st $x=-1$에서의 극한값과 $x=1$에서의 좌극한값을 각각 구하여 계산하자.\n$x=-1$에서의 좌극한값은 $\\lim_{x \\to -1-}f(x)=-1$\n$x=-1$에서의 우극한값은 $\\lim_{x \\to -1+}f(x)=-1$ ($x=-1$에서 좌극한값과 우극한값이 일치해야 $x=-1$에서의 극한값이 존재해.)\n따라서 $\\lim_{x \\to -1}f(x)=-1$\n$x=1$에서의 좌극한값은 $\\lim_{x \\to 1-}f(x)=2$ ($x=1$의 왼쪽에서 주어진 함수의 그래프를 따라 $x=1$로 접근할 때 $y$의 값은 $2$에 수렴해.)\n$\\therefore \\lim_{x \\to -1}f(x)+\\lim_{x \\to 1-}f(x)=-1+2=1$", "img": "IMG_4914.jpg", "answer_value": "$1$"}, {"id": "A55", "section": "A", "num": 55, "page": 9, "topic": "함수의 좌극한과 우극한", "answer": "③", "rate": "94%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0+}f(x)+\\lim_{x \\to 1-}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to 0+$는 $x=0$의 오른쪽에서 $x=0$으로 접근하는 것이고, $x \\to 1-$는 $x=1$의 왼쪽에서 $x=1$로 접근하는 것이다.\n1st 주어진 그래프를 이용하여 극한값을 구해.\n$x=0$의 오른쪽에서 함수 $y=f(x)$의 그래프를 따라 $x=0$으로 접근하면 $y$의 값은 $2$에 한없이 가까워지므로 $\\lim_{x \\to 0+}f(x)=2$ ($x=0$에서의 우극한값이야.)\n또, $x=1$의 왼쪽에서 함수 $y=f(x)$의 그래프를 따라 $x=1$로 접근하면 $y$의 값은 $1$에 한없이 가까워지므로 $\\lim_{x \\to 1-}f(x)=1$ ($x=1$에서의 좌극한값이야.)\n$\\therefore \\lim_{x \\to 0+}f(x)+\\lim_{x \\to 1-}f(x)=2+1=3$", "img": "IMG_4914.jpg", "answer_value": "$3$"}, {"id": "A56", "section": "A", "num": 56, "page": 9, "topic": "함수의 좌극한과 우극한", "answer": "③", "rate": "91%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0-}f(x)+\\lim_{x \\to 1+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x$가 특정 값에 가까워질 때 함숫값이 가까워지는 값을 그래프에서 찾아본다.\n1st 각 점에서의 좌극한값과 우극한값을 각각 구해.\n$x=0$에서의 좌극한값은 $\\lim_{x \\to 0-}f(x)=0$\n$x=1$에서의 우극한값은 $\\lim_{x \\to 1+}f(x)=3$\n$\\therefore \\lim_{x \\to 0-}f(x)+\\lim_{x \\to 1+}f(x)=0+3=3$", "img": "IMG_4914.jpg", "answer_value": "$3$"}, {"id": "A57", "section": "A", "num": 57, "page": 10, "topic": "함수의 좌극한과 우극한", "answer": "①", "rate": "92%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -2+}f(x)+\\lim_{x \\to 1-}f(x)$의 값은? (3점)", "explanation": "정답 공식: 그래프를 따라가며 우극한, 좌극한을 찾는다.\n1st 주어진 그래프에서 $x=-2$에서의 우극한, $x=1$에서의 좌극한을 구하자.\n함수 $y=f(x)$의 그래프에서 $x=-2$의 우극한을 구하면 $\\lim_{x \\to -2+}f(x)=-2$ ($x$의 값이 $-2$의 오른쪽에서 $-2$로 접근할 때 그래프를 따라가면 $f(x)$는 $-2$에 접근해.)\n마찬가지로 함수 $y=f(x)$의 그래프에서 $x=1$의 좌극한을 구하면 $\\lim_{x \\to 1-}f(x)=0$ ($x$의 값이 $1$의 왼쪽에서 $1$로 접근할 때 그래프를 따라가면 $f(x)$는 $0$에 접근해.)\n$\\therefore \\lim_{x \\to -2+}f(x)+\\lim_{x \\to 1-}f(x)=-2+0=-2$", "img": "IMG_4915.jpg", "answer_value": "$-2$"}, {"id": "A58", "section": "A", "num": 58, "page": 10, "topic": "함수의 좌극한과 우극한", "answer": "⑤", "rate": "98%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -1+}f(x)+\\lim_{x \\to 1-}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to -1+$는 $x=-1$의 오른쪽에서 그래프를 따라 $-1$로 접근하는 것이고, $x \\to 1-$는 $x=1$의 왼쪽에서 그래프를 따라 $1$로 접근하는 것이다.\n1st 그래프를 이용하여 $x=-1$에서의 우극한값과 $x=1$에서의 좌극한값을 찾자.\n$\\lim_{x \\to -1+}f(x)+\\lim_{x \\to 1-}f(x)=2+1=3$", "img": "IMG_4915.jpg", "answer_value": "$3$"}, {"id": "A59", "section": "A", "num": 59, "page": 10, "topic": "함수의 좌극한과 우극한", "answer": "④", "rate": "95%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0-}f(x)+\\lim_{x \\to 2+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to 0-$는 $x=0$의 왼쪽에서 그래프를 따라 $0$으로 접근하는 것이고, $x \\to 2+$는 $x=2$의 오른쪽에서 그래프를 따라 $2$로 접근하는 것이다.\n1st $x=0$에서의 좌극한값과 $x=2$에서의 우극한값을 각각 구해.\n$x=0$에서의 좌극한값은 $\\lim_{x \\to 0-}f(x)=4$ ($y=f(x)$의 그래프를 따라가면 $x=0$의 왼쪽에서 $0$으로 한없이 접근할 때, 함숫값 $f(x)$는 $4$에 수렴해.)\n$x=2$에서의 우극한값은 $\\lim_{x \\to 2+}f(x)=2$ ($y=f(x)$의 그래프를 따라가면 $x=2$의 오른쪽에서 $2$로 한없이 접근할 때, 함숫값 $f(x)$는 $2$에 수렴해.)\n$\\therefore \\lim_{x \\to 0-}f(x)+\\lim_{x \\to 2+}f(x)=4+2=6$", "img": "IMG_4915.jpg", "answer_value": "$6$"}, {"id": "A60", "section": "A", "num": 60, "page": 10, "topic": "함수의 좌극한과 우극한", "answer": "④", "rate": "95%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0-}f(x)-\\lim_{x \\to 1+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to 0-$는 $x=0$의 왼쪽에서 $0$에 가까이 가는 것이고 $x \\to 1+$는 $x=1$의 오른쪽에서 $1$로 가까이 가는 것이다.\n1st $x=0$에서의 좌극한값과 $x=1$에서의 우극한값을 구하자.\n$x=0$에서의 좌극한값은 $2$이므로 $\\lim_{x \\to 0-}f(x)=2$ ($x=0$의 왼쪽에서 $x=0$으로 가까이 갈 때, 함숫값은 $2$이므로 $x \\to 0-$일 때 $f(x) \\to 2$야.)\n$x=1$에서의 우극한값은 $1$이므로 $\\lim_{x \\to 1+}f(x)=1$ ($x=1$의 오른쪽에서 $x=1$로 가까이 갈 때, 함숫값은 $1$에 가까워지므로 $x \\to 1+$일 때 $f(x) \\to 1$이야.)\n$\\therefore \\lim_{x \\to 0-}f(x)-\\lim_{x \\to 1+}f(x)=2-1=1$", "img": "IMG_4915.jpg", "answer_value": "$1$"}, {"id": "A61", "section": "A", "num": 61, "page": 11, "topic": "함수의 좌극한과 우극한", "answer": "②", "rate": "96%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $f(3)+\\lim_{x \\to 1-}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to 1-$는 $x=1$의 왼쪽에서 그래프를 따라 $1$로 접근하는 것이다.\n1st $x=3$에서의 함숫값과 $x=1$에서의 좌극한값을 구하자.\n$f(3)=1, \\lim_{x \\to 1-}f(x)=1$\n(주의: $x=1$에서의 함숫값과 우극한값은 $0$이지만 $x=1$에서의 좌극한값은 $1$이야. 극한값과 함숫값을 혼동하지 않도록 해.)\n$\\therefore f(3)+\\lim_{x \\to 1-}f(x)=1+1=2$", "img": "IMG_4916.jpg", "answer_value": "$2$"}, {"id": "A62", "section": "A", "num": 62, "page": 11, "topic": "함수의 좌극한과 우극한", "answer": "⑤", "rate": "95%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -1-}f(x)+\\lim_{x \\to 1+}f(x)$의 값은? (3점)", "explanation": "정답 공식: 그래프가 주어진 경우의 $x=a$에서의 좌극한값과 우극한값은 $x=a$의 왼쪽과 오른쪽에서 각각 그래프를 따라 $x=a$로 다가갈 때의 $y$의 값을 읽어준다.\n1st 함수 $y=f(x)$의 그래프를 이용하여 극한값을 구해.\n$\\lim_{x \\to -1-}f(x)=1$ ($x=-1$의 왼쪽에서 $x=-1$로 가까이 다가갈 때의 $f(x)$의 값이야.), $\\lim_{x \\to 1+}f(x)=2$ ($x=1$의 오른쪽에서 $x=1$로 가까이 다가갈 때의 $f(x)$의 값이야.)이므로\n$\\lim_{x \\to -1-}f(x)+\\lim_{x \\to 1+}f(x)=1+2=3$", "img": "IMG_4916.jpg", "answer_value": "$3$"}, {"id": "A63", "section": "A", "num": 63, "page": 11, "topic": "함수의 좌극한과 우극한", "answer": "③", "rate": "98%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -1+}f(x)+\\lim_{x \\to 1-}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to -1+$는 $x=-1$의 오른쪽에서 $-1$로 접근하는 것이고, $x \\to 1-$는 $x=1$의 왼쪽에서 $1$로 접근하는 것이다.\n1st $x=-1$에서의 우극한과 $x=1$에서의 좌극한을 각각 구해.\n함수 $y=f(x)$의 그래프에서 $x$의 값이 $-1$의 오른쪽에서 $-1$로 접근할 때, 그래프를 따라가면 $2$에 수렴한다. ($x=-1$에서의 우극한값이 $2$라는 뜻이야.)\n$\\therefore \\lim_{x \\to -1+}f(x)=2$\n또, 함수 $y=f(x)$의 그래프에서 $x$의 값이 $1$의 왼쪽에서 $1$로 접근할 때, 그래프를 따라가면 $1$에 수렴한다. ($x=1$에서의 좌극한값이 $1$이라는 뜻이야.)\n$\\therefore \\lim_{x \\to 1-}f(x)=1$\n$\\therefore \\lim_{x \\to -1+}f(x)+\\lim_{x \\to 1-}f(x)=2+1=3$", "img": "IMG_4916.jpg", "answer_value": "$3$"}, {"id": "A64", "section": "A", "num": 64, "page": 11, "topic": "함수의 좌극한값과 우극한값", "answer": "⑤", "rate": "96%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0-}f(x) \\times \\lim_{x \\to 1+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to 0-$는 $x=0$의 왼쪽에서 $0$으로 접근하는 것이고, $x \\to 1+$는 $x=1$의 오른쪽에서 $1$로 접근하는 것이다.\n1st 주어진 그래프에서 $x=0$에서의 좌극한값, $x=1$에서의 우극한값을 찾아봐.\n함수 $y=f(x)$의 그래프에서 $x$의 값이 $0$의 왼쪽에서 $0$으로 접근할 때, 그래프를 따라가면 $f(x)$의 값은 $2$에 수렴한다. ($x=0$에서의 좌극한값이 $2$라는 뜻이야.)\n$\\therefore \\lim_{x \\to 0-}f(x)=2$\n또, 함수 $y=f(x)$의 그래프에서 $x$의 값이 $1$의 오른쪽에서 $1$로 접근할 때, 그래프를 따라가면 $f(x)$의 값은 $1$에 수렴한다. ($x=1$에서의 우극한값이 $1$이라는 뜻이야.)\n$\\therefore \\lim_{x \\to 1+}f(x)=1$\n$\\therefore \\lim_{x \\to 0-}f(x) \\times \\lim_{x \\to 1+}f(x)=2 \\times 1=2$", "img": "IMG_4916.jpg", "answer_value": "$2$"}, {"id": "A65", "section": "A", "num": 65, "page": 12, "topic": "함수의 좌극한과 우극한", "answer": "⑤", "rate": "96%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $f(3)+\\lim_{x \\to 1-}f(x)$의 값은? (3점)", "explanation": "정답 공식: $\\lim_{x \\to a-}f(x)=p$일 때, $p$를 $x=a$에서의 함수 $f(x)$의 좌극한이라 하고, $\\lim_{x \\to a+}f(x)=q$일 때, $q$를 $x=a$에서의 함수 $f(x)$의 우극한이라 한다.\n1st $x=3$에서의 함숫값과 $x=1$에서의 좌극한값을 구해.\n$f(3)+\\lim_{x \\to 1-}f(x)=1+1=2$ (함수 $y=f(x)$의 그래프를 보면 $x$의 값이 $1$보다 작으면서 $1$에 한없이 가까워질 때, $f(x)$의 값은 $1$에 한없이 가까워지는 것을 알 수 있어.)", "img": "IMG_4917.jpg", "answer_value": "$2$"}, {"id": "A66", "section": "A", "num": 66, "page": 12, "topic": "함수의 좌극한과 우극한", "answer": "⑤", "rate": "94%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -2+}f(x)+\\lim_{x \\to 2-}f(x)$의 값은? (3점)", "explanation": "정답 공식: $\\lim_{x \\to a-}f(x)=p$일 때, $p$를 $x=a$에서의 함수 $f(x)$의 좌극한이라 하고, $\\lim_{x \\to a+}f(x)=q$일 때, $q$를 $x=a$에서의 함수 $f(x)$의 우극한이라 한다.\n1st 그래프를 따라가며 $x=-2$에서의 우극한값과 $x=2$에서의 좌극한값을 찾자.\n$\\lim_{x \\to -2+}f(x)=4$ (함수 $f(x)$의 그래프에서 $x=-2$의 오른쪽에서 $-2$로 가까이 가면 함숫값은 $4$에 점점 가까워지므로 $x=-2$에서의 우극한값은 $4$야.)\n$\\lim_{x \\to 2-}f(x)=2$이므로 (함수 $f(x)$의 그래프에서 $x=2$의 왼쪽에서 $2$로 가까이 가면 함숫값은 $2$에 점점 가까워지므로 $x=2$에서의 좌극한값은 $2$야.)\n$\\lim_{x \\to -2+}f(x)+\\lim_{x \\to 2-}f(x)=4+2=6$\n(실수 주의: $\\lim$ 아래를 잘 보고 어떤 $x$의 값에서 좌극한인지 우극한인지 정확히 확인해.)", "img": "IMG_4917.jpg", "answer_value": "$6$"}, {"id": "A67", "section": "A", "num": 67, "page": 12, "topic": "함수의 좌극한과 우극한", "answer": "③", "rate": "98%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $f(0)+\\lim_{x \\to 1+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $\\lim_{x \\to a-}f(x)=p$일 때, $p$를 $x=a$에서의 함수 $f(x)$의 좌극한이라 하고, $\\lim_{x \\to a+}f(x)=q$일 때, $q$를 $x=a$에서의 함수 $f(x)$의 우극한이라 한다.\n1st $x=0$에서의 함숫값과 $x=1$에서의 우극한값을 구해.\n주어진 함수 $y=f(x)$의 그래프에서 $f(0)=1$이고, $\\lim_{x \\to 1+}f(x)=2$이므로 (실수 주의: $x=1$에서의 좌극한값인지, 우극한값인지, 함숫값인지 정확히 확인해야 해.)\n$f(0)+\\lim_{x \\to 1+}f(x)=1+2=3$ (함수 $y=f(x)$의 그래프를 보면 $x$의 값이 $1$보다 크면서 $1$에 한없이 가까워질 때, $f(x)$의 값은 $2$에 한없이 가까워지는 걸 알 수 있어.)", "img": "IMG_4917.jpg", "answer_value": "$3$"}, {"id": "A68", "section": "A", "num": 68, "page": 12, "topic": "함수의 좌극한과 우극한", "answer": "②", "rate": "97%", "problem": "닫힌구간 $[-2, 2]$에서 정의된 함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -1+}f(x)+\\lim_{x \\to 1-}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to -1+$는 $x=-1$의 오른쪽에서 $-1$로 접근하는 것이고, $x \\to 1-$는 $x=1$의 왼쪽에서 $1$로 접근하는 것이다.\n1st 주어진 함수의 우극한값과 좌극한값을 구하자.\n$x=-1$에서의 우극한값은 $\\lim_{x \\to -1+}f(x)=0$ ($x=-1$의 오른쪽에서 주어진 함수의 그래프를 따라 $x=-1$로 접근할 때 $y$의 값은 $0$에 수렴해.)\n$x=1$에서의 좌극한값은 $\\lim_{x \\to 1-}f(x)=2$ ($x=1$의 왼쪽에서 주어진 함수의 그래프를 따라 $x=1$로 접근할 때 $y$의 값은 $2$에 수렴해.)\n$\\therefore \\lim_{x \\to -1+}f(x)+\\lim_{x \\to 1-}f(x)=0+2=2$", "img": "IMG_4917.jpg", "answer_value": "$2$"}, {"id": "A69", "section": "A", "num": 69, "page": 13, "topic": "함수의 좌극한과 우극한", "answer": "⑤", "rate": "94%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 1-}f(x)+\\lim_{x \\to 3+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to 1-$는 $x=1$의 왼쪽에서 $x=1$로 접근하는 것이고 $x \\to 3+$는 $x=3$의 오른쪽에서 $x=3$으로 접근하는 것이다.\n1st $x=1$에서의 좌극한값과 $x=3$에서의 우극한값을 각각 구해.\n$x$가 $1$보다 작으면서 $1$에 한없이 가까워지면 $f(x)$의 값은 $2$보다 크면서 $2$에 한없이 가까워지므로\n$\\lim_{x \\to 1-}f(x)=2$ ($x=1$의 왼쪽에서 함수 $y=f(x)$의 그래프를 따라 $x=1$로 가까이 다가갈 때의 $f(x)$의 값을 읽으면 돼.)\n또, $x$가 $3$보다 크면서 $3$에 한없이 가까워지면 $f(x)$의 값은 $3$보다 작으면서 $3$에 가까워지므로\n$\\lim_{x \\to 3+}f(x)=3$ ($x=3$의 오른쪽에서 함수 $y=f(x)$의 그래프를 따라 $x=3$으로 가까이 다가갈 때의 $f(x)$의 값을 읽으면 돼.)\n$\\therefore \\lim_{x \\to 1-}f(x)+\\lim_{x \\to 3+}f(x)=2+3=5$", "img": "IMG_4918.jpg", "answer_value": "$5$"}, {"id": "A70", "section": "A", "num": 70, "page": 13, "topic": "함수의 좌극한과 우극한", "answer": "④", "rate": "95%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -1-}f(x)-\\lim_{x \\to 1+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to -1-$는 $x=-1$의 왼쪽에서 $-1$로 접근하는 것이고, $x \\to 1+$는 $x=1$의 오른쪽에서 $1$로 접근하는 것이다. 그래프를 따라가며 극한값을 찾는다.\n1st 각 점에서의 좌극한값과 우극한값을 각각 구해.\n$x=-1$에서의 좌극한값은 $\\lim_{x \\to -1-}f(x)=2$ ($y=f(x)$의 그래프를 따라가면 $x=-1$의 왼쪽에서 $-1$로 한없이 접근할 때, 함숫값 $f(x)$는 $2$에 수렴해.)\n$x=1$에서의 우극한값은 $\\lim_{x \\to 1+}f(x)=1$ ($y=f(x)$의 그래프를 따라가면 $x=1$의 오른쪽에서 $1$로 한없이 접근할 때, 함숫값 $f(x)$는 $1$에 수렴해.)\n$\\therefore \\lim_{x \\to -1-}f(x)-\\lim_{x \\to 1+}f(x)=2-1=1$", "img": "IMG_4918.jpg", "answer_value": "$1$"}, {"id": "A71", "section": "A", "num": 71, "page": 13, "topic": "함수의 좌극한과 우극한", "answer": "③", "rate": "95%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0-}f(x)+\\lim_{x \\to 1+}f(x)$의 값은? (3점)", "explanation": "정답 공식: 함수의 그래프가 제시된 경우 그래프를 따라가며 좌극한과 우극한의 값을 구한다.\n1st $x=0$에서의 좌극한과 $x=1$에서의 우극한을 각각 구하여 계산하자.\n[$x=a$에서의 좌극한과 우극한] ① 함수 $f(x)$에서 $x$가 $a$보다 작은 값을 가지면서 $a$에 한없이 가까워질 때, $f(x)$의 값이 일정한 값 $\\alpha$에 가까워지면 $\\lim_{x \\to a-}f(x)=\\alpha$ ② 함수 $f(x)$에서 $x$가 $a$보다 큰 값을 가지면서 $a$에 한없이 가까워질 때, $f(x)$의 값이 일정한 값 $\\beta$에 가까워지면 $\\lim_{x \\to a+}f(x)=\\beta$\n$\\lim_{x \\to 0-}f(x)=-1, \\lim_{x \\to 1+}f(x)=2$\n$\\therefore \\lim_{x \\to 0-}f(x)+\\lim_{x \\to 1+}f(x)=-1+2=1$", "img": "IMG_4918.jpg", "answer_value": "$1$"}, {"id": "A72", "section": "A", "num": 72, "page": 13, "topic": "함수의 좌극한과 우극한", "answer": "③", "rate": "93%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -1-}f(x)+\\lim_{x \\to 0+}f(x)$의 값은? (3점)", "explanation": "정답 공식: 함수의 그래프가 제시된 경우 그래프를 따라가며 좌극한과 우극한의 값을 구한다.\n1st $x=-1$에서의 좌극한과 $x=0$에서의 우극한을 각각 구하여 계산하자.\n[$x=a$에서의 좌극한과 우극한] ① 함수 $f(x)$에서 $x$가 $a$보다 작은 값을 가지면서 $a$에 한없이 가까워질 때, $f(x)$의 값이 일정한 값 $\\alpha$에 가까워지면 $\\lim_{x \\to a-}f(x)=\\alpha$ ② 함수 $f(x)$에서 $x$가 $a$보다 큰 값을 가지면서 $a$에 한없이 가까워질 때, $f(x)$의 값이 일정한 값 $\\beta$에 가까워지면 $\\lim_{x \\to a+}f(x)=\\beta$\n$\\lim_{x \\to -1-}f(x)=2$ (좌극한은 그래프의 왼쪽에서 접근하는 경우에 함숫값이 어디에 가까워지는지 확인하자.)\n$\\lim_{x \\to 0+}f(x)=-1$ (우극한은 그래프의 오른쪽에서 접근하는 경우에 함숫값이 어디에 가까워지는지 확인하자.)\n$\\therefore \\lim_{x \\to -1-}f(x)+\\lim_{x \\to 0+}f(x)=2+(-1)=1$", "img": "IMG_4918.jpg", "answer_value": "$1$"}, {"id": "A73", "section": "A", "num": 73, "page": 14, "topic": "함수의 좌극한과 우극한", "answer": "②", "rate": "92%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 1-}f(x)+\\lim_{x \\to 2+}f(x)$의 값은? (3점)", "explanation": "정답 공식: 그래프에서 좌극한값과 우극한값을 구한다.\n1st 각 점에서의 좌극한값과 우극한값을 각각 구하자.\n$x=1$에서의 좌극한값은 $\\lim_{x \\to 1-}f(x)=1$ ($x=1$의 왼쪽에서 $1$로 접근할 때, $y=f(x)$의 그래프를 따라가면 함숫값 $f(x)$는 $1$에 수렴해.)\n$x=2$에서의 우극한값은 $\\lim_{x \\to 2+}f(x)=1$ ($x=2$의 오른쪽에서 $2$로 접근할 때, $y=f(x)$의 그래프를 따라가면 함숫값 $f(x)$는 $1$에 수렴해.)\n($\\lim_{x \\to a-}f(x)=p$일 때 $p$를 $x=a$에서 $f(x)$의 좌극한값이라 하고, $\\lim_{x \\to a+}f(x)=q$일 때 $q$를 $x=a$에서 $f(x)$의 우극한값이라고 해.)\n$\\therefore \\lim_{x \\to 1-}f(x)+\\lim_{x \\to 2+}f(x)=1+1=2$\n[개념·공식] 좌극한과 우극한: ① $\\lim_{x \\to a-}f(x)=p$일 때, $p$를 $x=a$에서 $f(x)$의 좌극한값이라 한다. ② $\\lim_{x \\to a+}f(x)=q$일 때, $q$를 $x=a$에서 $f(x)$의 우극한값이라 한다.", "img": "IMG_4919.jpg", "answer_value": "$2$"}, {"id": "A74", "section": "A", "num": 74, "page": 14, "topic": "함수의 좌극한과 우극한", "answer": "④", "rate": "94%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0+}f(x)+\\lim_{x \\to 2-}f(x)$의 값은? (3점)", "explanation": "정답 공식: 그래프가 주어진 경우의 $x=a$에서의 좌극한값과 우극한값은 $x=a$의 왼쪽과 오른쪽에서 각각 그래프를 따라 $x=a$로 다가갈 때의 $y$의 값을 읽어준다.\n1st 주어진 그래프에서 좌극한값과 우극한값을 각각 계산해.\n$x=0$에서의 우극한값은 $\\lim_{x \\to 0+}f(x)=1$ ($x=0$의 오른쪽에서 $x=0$으로 가까이 다가갈 때의 $f(x)$의 값이야.)\n$x=2$에서의 좌극한값은 $\\lim_{x \\to 2-}f(x)=3$ ($x=2$의 왼쪽에서 $x=2$로 가까이 다가갈 때의 $f(x)$의 값이야.)\n$\\therefore \\lim_{x \\to 0+}f(x)+\\lim_{x \\to 2-}f(x)=1+3=4$", "img": "IMG_4919.jpg", "answer_value": "$4$"}, {"id": "A75", "section": "A", "num": 75, "page": 14, "topic": "함수의 좌극한과 우극한", "answer": "⑤", "rate": "91%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0-}f(x)+\\lim_{x \\to 1+}f(x)$의 값은? (3점)", "explanation": "정답 공식: $x$가 특정 값에 가까워질 때 함숫값이 가까워지는 값을 그래프에서 찾아본다.\n1st 그래프에서 $x=0$에서의 좌극한값과 $x=1$에서의 우극한값을 찾아봐.\n$y=f(x)$의 그래프에서 $x=0$의 왼쪽에서 $x=0$으로 가까이 갈 때, $y$의 값은 $1$에 한없이 가까워지므로 $\\lim_{x \\to 0-}f(x)=1$ ($x \\to a-$는 $x=a$의 왼쪽에서 $x=a$에 가까이 갈 때를 의미해.)\n$y=f(x)$의 그래프에서 $x=1$의 오른쪽에서 $x=1$로 가까이 갈 때, $y$의 값은 $1$에 한없이 가까워지므로 $\\lim_{x \\to 1+}f(x)=1$ ($x \\to a+$는 $x=a$의 오른쪽에서 $x=a$에 가까이 갈 때를 의미해.)\n$\\therefore \\lim_{x \\to 0-}f(x)+\\lim_{x \\to 1+}f(x)=1+1=2$\n[개념·공식] 좌극한과 우극한: ① $\\lim_{x \\to a-}f(x)=p$일 때, $p$를 $x=a$에서 $f(x)$의 좌극한값이라 한다. ② $\\lim_{x \\to a+}f(x)=q$일 때, $q$를 $x=a$에서 $f(x)$의 우극한값이라 한다.", "img": "IMG_4919.jpg", "answer_value": "$2$"}, {"id": "A76", "section": "A", "num": 76, "page": 14, "topic": "함수의 좌극한과 우극한", "answer": "③", "rate": "84%", "problem": "$-3<x<3$에서 정의된 함수 $y=f(x)$의 그래프가 그림과 같다. 부등식 $\\lim_{x \\to a-}f(x) > \\lim_{x \\to a+}f(x)$를 만족시키는 상수 $a$의 값은? (단, $-3<a<3$) (4점)", "explanation": "정답 공식: $x$의 값이 $a$보다 작으면서 $a$에 한없이 가까워질 때의 $f(x)$가 수렴하는 값을 $\\lim_{x \\to a-}f(x)$라 하고, $x$의 값이 $a$보다 크면서 $a$에 한없이 가까워질 때의 $f(x)$가 수렴하는 값을 $\\lim_{x \\to a+}f(x)$라 한다.\n(단서: 그래프에서 좌극한값과 우극한값이 다른 점은 $3$개이므로 이 세 점에서의 좌극한값과 우극한값을 찾아 비교해.)\n1st 함수 $f(x)$의 그래프를 이용하여 부등식을 만족시키는 $a$의 값을 찾아.\n주어진 그래프에서 $x=-1, x=0, x=1$인 점에서의 좌극한값과 우극한값이 다르므로 이 세 점에서 주어진 부등식을 만족시키는지 확인하자. ($\\lim_{x \\to a-}f(x) > \\lim_{x \\to a+}f(x)$에 의해 $x=a$에서 $f(x)$의 좌극한값과 우극한값이 다름을 알 수 있어.)\n(i) $x=-1$에서 $\\lim_{x \\to -1-}f(x)=0, \\lim_{x \\to -1+}f(x)=3$이므로 $\\lim_{x \\to -1-}f(x) < \\lim_{x \\to -1+}f(x)$\n($x \\to a+$일 때, $f(x)$의 값이 일정한 값 $\\alpha$에 한없이 가까워지면 $\\alpha$를 $x=a$에서 함수 $f(x)$의 우극한이라 하고, 이것을 기호로 $\\lim_{x \\to a+}f(x)=\\alpha$로 나타내. 또, $x \\to a-$일 때, $f(x)$의 값이 일정한 값 $\\beta$에 한없이 가까워지면 $\\beta$를 $x=a$에서 함수 $f(x)$의 좌극한이라 하고, 이것을 기호로 $\\lim_{x \\to a-}f(x)=\\beta$로 나타내.)\n(ii) $x=0$에서 $\\lim_{x \\to 0-}f(x)=2, \\lim_{x \\to 0+}f(x)=0$이므로 $\\lim_{x \\to 0-}f(x) > \\lim_{x \\to 0+}f(x)$\n(iii) $x=1$에서 $\\lim_{x \\to 1-}f(x)=-1, \\lim_{x \\to 1+}f(x)=1$이므로 $\\lim_{x \\to 1-}f(x) < \\lim_{x \\to 1+}f(x)$ (실수 주의: $f(1)$, 즉 함숫값과 좌극한값, 우극한값은 다를 수도 있어.)\n따라서 주어진 부등식을 만족시키는 $a$의 값은 $0$이다.", "img": "IMG_4919.jpg, IMG_4920.jpg", "answer_value": "$0$"}, {"id": "A77", "section": "A", "num": 77, "page": 15, "topic": "함수의 좌극한과 우극한", "answer": "①", "rate": "71%", "problem": "정의역이 $\\{x|-2 \\le x \\le 2\\}$인 함수 $y=f(x)$의 그래프가 구간 $[0, 2]$에서 그림과 같고, 정의역에 속하는 모든 실수 $x$에 대하여 $f(-x)=-f(x)$이다. $\\lim_{x \\to -1+}f(x)+\\lim_{x \\to 2-}f(x)$의 값은? (4점)", "explanation": "정답 공식: $f(-x)=-f(x)$를 만족시키는 함수 $y=f(x)$의 그래프는 원점에 대하여 대칭이다.\n1st 정의역에서 함수 $y=f(x)$의 그래프를 그려.\n함수 $y=f(x)$가 정의역에 속하는 모든 실수 $x$에 대하여 $f(-x)=-f(x)$이면 함수 $f(x)$의 그래프는 원점에 대하여 대칭이다.\n따라서 정의역 $\\{x|-2 \\le x \\le 2\\}$에서 함수 $y=f(x)$의 그래프는 그림과 같다.\n2nd 주어진 점에서의 우극한값과 좌극한값을 각각 구해.\n($\\lim_{x \\to a+}f(x)=q$일 때 $q$를 $x=a$에서 $f(x)$의 우극한값이라고 해. $\\lim_{x \\to a-}f(x)=p$일 때 $p$를 $x=a$에서 $f(x)$의 좌극한값이라고 해.)\n$\\therefore \\lim_{x \\to -1+}f(x)+\\lim_{x \\to 2-}f(x)=-1+(-2)=-3$\n[다른 풀이: $-x=t$로 치환하여 $x \\to -1+$ 대신 $t \\to 1-$ 구하기]\n$\\lim_{x \\to -1+}f(x)$에서 $-x=t$라 하면 $f(-t)=-f(t)$이므로\n$\\lim_{x \\to -1+}f(x)=\\lim_{t \\to 1-}f(-t)=\\lim_{t \\to 1-}\\left\\{-f(t)\\right\\}=-\\lim_{t \\to 1-}f(t)=-1$이고, $\\lim_{x \\to 2-}f(x)=-2$\n$\\therefore \\lim_{x \\to -1+}f(x)+\\lim_{x \\to 2-}f(x)=-1+(-2)=-3$ (실수 주의: 치환하면서 부호뿐만 아니라 좌우극한도 바뀌는 걸 명심해.)", "img": "IMG_4920.jpg", "answer_value": "$-3$"}, {"id": "A78", "section": "A", "num": 78, "page": 15, "topic": "함수의 극한값의 존재", "answer": "③", "rate": "84%", "problem": "두 함수 $y=f(x)$, $y=g(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0}\\left\\{f(x)+kg(x)\\right\\}$의 값이 존재할 때, 상수 $k$의 값은? (3점)", "explanation": "정답 공식: $\\lim_{x \\to a}f(x)$의 값이 존재하면 $\\lim_{x \\to a+}f(x)=\\lim_{x \\to a-}f(x)$이다.\n1st $x=0$에서의 두 함수 $f(x)$, $g(x)$의 좌극한값과 우극한값을 구해.\n두 함수 $y=f(x)$, $y=g(x)$의 그래프에 의하여\n$\\lim_{x \\to 0-}f(x)=2$, $\\lim_{x \\to 0-}g(x)=1$이고, ($x=0$의 왼쪽에서 그래프를 따라 $x=0$에 가까이 갈 때의 $y$의 값이야.)\n$\\lim_{x \\to 0+}f(x)=-1$, $\\lim_{x \\to 0+}g(x)=3$이다. ($x=0$의 오른쪽에서 그래프를 따라 $x=0$에 가까이 갈 때의 $y$의 값이야.)\n2nd 극한값이 존재함을 이용하여 $k$의 값을 구해.\n$\\lim_{x \\to 0}\\left\\{f(x)+kg(x)\\right\\}$의 값이 존재하려면 함수 $f(x)+kg(x)$의 $x=0$에서의 좌극한과 우극한이 같아야 한다.\n$\\lim_{x \\to 0-}\\left\\{f(x)+kg(x)\\right\\} = \\lim_{x \\to 0-}f(x)+k\\lim_{x \\to 0-}g(x) = 2+k\\times 1 = k+2$\n(상수 $t$와 수렴하는 두 함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to a}tf(x)=t\\lim_{x \\to a}f(x)$, $\\lim_{x \\to a}\\left\\{f(x)+g(x)\\right\\}=\\lim_{x \\to a}f(x)+\\lim_{x \\to a}g(x)$)\n$\\lim_{x \\to 0+}\\left\\{f(x)+kg(x)\\right\\} = \\lim_{x \\to 0+}f(x)+k\\lim_{x \\to 0+}g(x) = -1+k\\times 3 = 3k-1$\n즉, $\\lim_{x \\to 0-}\\left\\{f(x)+kg(x)\\right\\} = \\lim_{x \\to 0+}\\left\\{f(x)+kg(x)\\right\\}$에서\n$k+2=3k-1$\n$2k=3$\n$\\therefore k=\\frac{3}{2}$\n[개념·공식] 좌극한과 우극한: ① $\\lim_{x \\to a-}f(x)=p$일 때, $p$를 $x=a$에서 $f(x)$의 좌극한값이라 한다. ② $\\lim_{x \\to a+}f(x)=q$일 때, $q$를 $x=a$에서 $f(x)$의 우극한값이라 한다.", "img": "IMG_4920.jpg", "answer_value": "$\\frac{3}{2}$"}, {"id": "A79", "section": "A", "num": 79, "page": 16, "topic": "함수의 극한값의 존재", "answer": "④", "rate": "89%", "problem": "함수 $f(x)=\\begin{cases} 2x^{3}+3 & (x \\ge 1) \\\\ x^{3}+k & (x<1) \\end{cases}$에 대하여 $\\lim_{x \\to 1}f(x)$의 값이 존재하도록 하는 상수 $k$의 값은? (3점)", "explanation": "정답 공식: $\\lim_{x \\to a}f(x)$의 값이 존재하려면 $\\lim_{x \\to a-}f(x)=\\lim_{x \\to a+}f(x)$이어야 한다.\n1st 함수 $f(x)$가 $x=1$에서 극한값을 갖도록 하는 상수 $k$의 값을 구하자.\n함수 $f(x)$의 $x=1$에서의 우극한값은\n$\\lim_{x \\to 1+}f(x)=\\lim_{x \\to 1+}(2x^{3}+3)=2\\times 1^{3}+3=5$ … ㉠ ($x \\to 1+$의 의미는 $x$가 $1$보다 큰 쪽에서 $1$로 가까이 다가간다는 것이므로 $x \\to 1+$일 때 $f(x)=2x^{3}+3$이야.)\n또, 함수 $f(x)$의 $x=1$에서의 좌극한값은\n$\\lim_{x \\to 1-}f(x)=\\lim_{x \\to 1-}(x^{3}+k)=1^{3}+k=1+k$ … ㉡ ($x \\to 1-$의 의미는 $x$가 $1$보다 작은 쪽에서 $1$로 가까이 다가간다는 것이므로 $x \\to 1-$일 때 $f(x)=x^{3}+k$야.)\n이때, 함수 $f(x)$에 대하여 $\\lim_{x \\to 1}f(x)$의 값이 존재하려면 ㉠=㉡이어야 하므로 $5=1+k$ $\\therefore k=4$", "img": "IMG_4921.jpg", "answer_value": "$4$"}, {"id": "A80", "section": "A", "num": 80, "page": 16, "topic": "함수의 극한값의 존재", "answer": "⑤", "rate": "80%", "problem": "정의역이 $\\left\\{x \\mid -1 \\le x \\le 3\\right\\}$인 함수 $y=f(x)$의 그래프가 그림과 같을 때, [보기]에서 옳은 것을 모두 고른 것은? (3점) [보기] ㄱ. $\\lim_{x \\to 1}f(x)$가 존재한다. ㄴ. $\\lim_{x \\to 2}f(x)$가 존재한다. ㄷ. $-1<a<1$인 실수 $a$에 대하여 $\\lim_{x \\to a}f(x)$가 존재한다.", "explanation": "정답 공식: 함수의 극한값이 존재하기 위해서는 좌극한값과 우극한값이 같아야 한다.\n1st 그래프를 보고 ㄱ, ㄴ, ㄷ의 각각에 대해 극한값이 존재하는지를 확인해.\nㄱ. $\\lim_{x \\to 1+}f(x)=0$, $\\lim_{x \\to 1-}f(x)=-2$이므로 $\\lim_{x \\to 1+}f(x) \\ne \\lim_{x \\to 1-}f(x)$\n따라서 $\\lim_{x \\to 1}f(x)$는 존재하지 않는다. (거짓) (좌극한과 우극한이 모두 존재하지만 두 값이 같지 않으므로 극한값은 존재하지 않아.)\nㄴ. $\\lim_{x \\to 2+}f(x)=1$, $\\lim_{x \\to 2-}f(x)=1$이므로 $\\lim_{x \\to 2+}f(x)=\\lim_{x \\to 2-}f(x)=1$\n따라서 $\\lim_{x \\to 2}f(x)$가 존재한다. (참) (좌극한과 우극한이 모두 존재하고 그 값이 같으므로 극한값이 존재해.)\nㄷ. $-1<a<1$인 실수 $a$에 대하여 $\\lim_{x \\to a-}f(x)=\\lim_{x \\to a+}f(x)$이므로 $\\lim_{x \\to a}f(x)$는 존재한다. (참)\n따라서 옳은 것은 ㄴ, ㄷ이다.", "img": "IMG_4921.jpg", "answer_value": "ㄴ, ㄷ"}, {"id": "A81", "section": "A", "num": 81, "page": 16, "topic": "함수의 극한값의 존재", "answer": "①", "rate": "80%", "problem": "그림은 함수 $y=f(x)$의 그래프이다. $0<k<5$일 때, $\\lim_{x \\to k}f(x)$의 값이 존재하지 않는 모든 실수 $k$의 값의 합은? (3점)", "explanation": "정답 공식: 그래프가 끊어진 점에서 극한값이 존재하지 않을 수 있으므로 그 점에서만 극한값의 존재성을 따져주자.\n1st 극한값이 존재하지 않는 점을 찾아.\n(i) $\\lim_{x \\to 1-}f(x)=2$, $\\lim_{x \\to 1+}f(x)=2$이므로 함수 $f(x)$는 $x=1$에서 극한값 $2$를 갖는다. ($x=1$에서의 좌극한값과 우극한값이 모두 $2$이므로 $\\lim_{x \\to 1}f(x)=2$야. 주의: 극한값이 존재해도 실제 함숫값과는 다를 수 있어.)\n(ii) $\\lim_{x \\to 2-}f(x)=1$, $\\lim_{x \\to 2+}f(x)=2$이므로 함수 $f(x)$는 $x=2$에서 극한값이 존재하지 않는다. ($x=2$에서의 좌극한값과 우극한값이 모두 존재하지만 그 값이 서로 같지 않으므로 $x=2$에서 극한값은 존재하지 않아.)\n(iii) $\\lim_{x \\to 3-}f(x)=2$, $\\lim_{x \\to 3+}f(x)=1$이므로 함수 $f(x)$는 $x=3$에서 극한값이 존재하지 않는다. ($x=3$에서의 좌극한값과 우극한값이 모두 존재하지만 그 값이 서로 같지 않으므로 $x=3$에서 극한값은 존재하지 않아.)\n(iv) $\\alpha=1$, $\\alpha=2$, $\\alpha=3$을 제외한 $0<\\alpha<5$인 모든 $\\alpha$에 대하여 $\\lim_{x \\to \\alpha-}f(x)=f(\\alpha)$, $\\lim_{x \\to \\alpha+}f(x)=f(\\alpha)$이므로 함수 $f(x)$는 $x=\\alpha$에서 극한값 $f(\\alpha)$를 갖는다.\n(i)~(iv)에서 $0<x<5$에서 함수 $f(x)$의 극한값이 존재하지 않는 $x$의 값은 $2$ 또는 $3$이므로 $k=2$ 또는 $k=3$\n따라서 구하는 모든 실수 $k$의 값의 합은 $2+3=5$이다.", "img": "IMG_4921.jpg", "answer_value": "$5$"}, {"id": "A82", "section": "A", "num": 82, "page": 16, "topic": "함수의 극한에 대한 성질", "answer": "①", "rate": "82%", "problem": "함수 $f(x)$가 $\\lim_{x \\to 2}\\frac{f(x-2)}{x-2}=15$를 만족시킬 때, $\\lim_{x \\to 2}\\frac{2xf(x-2)}{x^{2}+x-6}$의 값은? (3점)", "explanation": "정답 공식: 수렴하는 두 함수를 더하거나 빼거나 곱하거나 나누어도((분모)$\\ne 0$) 수렴한다.\n1st 함수의 극한에 대한 성질을 이용하여 주어진 극한값을 구하자.\n$\\lim_{x \\to 2}\\frac{f(x-2)}{x-2}=15$이므로\n$\\lim_{x \\to 2}\\frac{2xf(x-2)}{x^{2}+x-6} = \\lim_{x \\to 2}\\frac{2xf(x-2)}{(x-2)(x+3)} = \\lim_{x \\to 2}\\frac{f(x-2)}{x-2} \\times \\lim_{x \\to 2}\\frac{2x}{x+3}$\n$=15\\times\\frac{2\\times 2}{2+3}=12$\n(실수 $\\alpha$, $\\beta$에 대하여 $\\lim_{x \\to a}f(x)=\\alpha$, $\\lim_{x \\to a}g(x)=\\beta$일 때 $\\lim_{x \\to a}f(x)g(x)=\\lim_{x \\to a}f(x)\\times\\lim_{x \\to a}g(x)=\\alpha\\beta$)", "img": "IMG_4921.jpg", "answer_value": "$12$"}, {"id": "A83", "section": "A", "num": 83, "page": 17, "topic": "함수의 극한에 대한 성질", "answer": "③", "rate": "93%", "problem": "두 함수 $f(x)$, $g(x)$가 $\\lim_{x \\to 2}f(x)=1$, $\\lim_{x \\to 2}\\left\\{2f(x)+g(x)\\right\\}=8$을 만족시킬 때, $\\lim_{x \\to 2}g(x)$의 값은? (3점)", "explanation": "정답 공식: 수렴하는 두 함수를 더하거나 빼거나 곱하거나 나누어도((분모)$\\ne 0$) 수렴한다.\n(단서: 수렴하는 두 함수에 대하여 이 두 함수끼리 빼도 수렴하지? 즉, $\\lim_{x \\to 2}g(x)=\\lim_{x \\to 2}\\left\\{2f(x)+g(x)-2f(x)\\right\\}$임을 이용해.)\n1st 함수의 극한의 성질을 이용하여 $\\lim_{x \\to 2}g(x)$의 값을 구하자.\n$\\lim_{x \\to 2}f(x)=1$에서 $\\lim_{x \\to 2}2f(x)=2\\times\\lim_{x \\to 2}f(x)=2\\times 1=2$ (함수 $F(x)$에 대하여 $\\lim_{x \\to a}F(x)=\\alpha$일 때, $\\lim_{x \\to a}kF(x)=k\\lim_{x \\to a}F(x)=k\\alpha$ (단, $k$는 상수))\n$\\therefore \\lim_{x \\to 2}g(x)=\\lim_{x \\to 2}\\left\\{2f(x)+g(x)-2f(x)\\right\\}$\n$=\\lim_{x \\to 2}\\left\\{2f(x)+g(x)\\right\\}-\\lim_{x \\to 2}2f(x)=8-2=6$\n($2f(x)+g(x)$, $2f(x)$를 각각 수렴하는 새로운 함수로 생각하면 다음의 수렴하는 함수의 성질을 적용할 수 있어. 두 함수 $F(x)$, $G(x)$에 대하여 $\\lim_{x \\to a}F(x)=\\alpha$, $\\lim_{x \\to a}G(x)=\\beta$일 때, $\\lim_{x \\to a}\\left\\{F(x)\\pm G(x)\\right\\}=\\lim_{x \\to a}F(x)\\pm\\lim_{x \\to a}G(x)=\\alpha\\pm\\beta$ (복부호동순))", "img": "IMG_4922.jpg", "answer_value": "$6$"}, {"id": "A84", "section": "A", "num": 84, "page": 17, "topic": "함수의 극한에 대한 성질", "answer": "②", "rate": "90%", "problem": "함수 $f(x)$가 $\\lim_{x \\to 1}(x-1)f(x)=3$을 만족시킬 때, $\\lim_{x \\to 1}(x^{2}-1)f(x)$의 값은? (3점)", "explanation": "정답 공식: $x \\to 1$일 때 두 함수 $F(x)$와 $G(x)$가 각각 수렴하면 $x \\to 1$일 때 함수 $F(x)G(x)$도 수렴한다.\n(단서: $x$의 값이 $1$에 한없이 가까워질 때 함수 $y=x+1$과 함수 $y=(x-1)f(x)$의 값이 각각 일정한 값에 가까워지므로 $\\lim_{x \\to 1}(x^{2}-1)f(x)$, 즉 $\\lim_{x \\to 1}(x+1)(x-1)f(x)$의 값을 구할 수 있어.)\n1st $(x^{2}-1)f(x)=(x+1)(x-1)f(x)$이므로 함수의 극한의 성질을 이용하여 $\\lim_{x \\to 1}(x^{2}-1)f(x)$의 값을 구해.\n$\\lim_{x \\to 1}(x-1)f(x)=3$이고 $\\lim_{x \\to 1}(x+1)=1+1=2$이므로\n$\\lim_{x \\to 1}(x^{2}-1)f(x)=\\lim_{x \\to 1}(x+1)(x-1)f(x)$\n$=\\lim_{x \\to 1}(x+1)\\times\\lim_{x \\to 1}(x-1)f(x)$\n$=2\\times 3=6$\n(두 함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to a}f(x)=\\alpha$, $\\lim_{x \\to a}g(x)=\\beta$ ($\\alpha$, $\\beta$는 실수)일 때 $\\lim_{x \\to a}f(x)g(x)=\\lim_{x \\to a}f(x)\\times\\lim_{x \\to a}g(x)=\\alpha\\beta$)", "img": "IMG_4922.jpg", "answer_value": "$6$"}, {"id": "A85", "section": "A", "num": 85, "page": 17, "topic": "함수의 극한에 대한 성질", "answer": "$16$", "rate": "80%", "problem": "두 함수 $f(x)$, $g(x)$가 $\\lim_{x \\to 1}\\frac{f(x)}{x-1}=8$, $\\lim_{x \\to 1}\\frac{g(x)}{x^{2}-1}=\\frac{1}{2}$을 만족시킬 때, $\\lim_{x \\to 1}\\frac{(x+1)f(x)}{g(x)}$의 값을 구하시오. (4점)", "explanation": "정답 공식: $\\lim_{x \\to a}f(x)=\\alpha$ ($\\alpha$는 $0$이 아닌 실수)이면 $\\lim_{x \\to a}\\frac{1}{f(x)}=\\frac{1}{\\alpha}$이다.\n(단서: 구해야 하는 식을 보면 $g(x)$가 분모에 있네? 따라서 $\\lim_{x \\to 1}\\frac{g(x)}{x^{2}-1}=\\frac{1}{2}$을 이용해 $\\lim_{x \\to 1}\\frac{x^{2}-1}{g(x)}$의 값을 구해봐.)\n1st 함수의 극한의 성질을 이용하여 $\\lim_{x \\to 1}\\frac{(x+1)f(x)}{g(x)}$의 값을 구해.\n$\\lim_{x \\to 1}\\frac{g(x)}{x^{2}-1}=\\frac{1}{2}$이므로 $\\lim_{x \\to 1}\\frac{x^{2}-1}{g(x)}=2$이다.\n$\\therefore \\lim_{x \\to 1}\\frac{(x+1)f(x)}{g(x)} = \\lim_{x \\to 1}\\frac{(x-1)(x+1)f(x)}{(x-1)g(x)}$\n$=\\lim_{x \\to 1}\\left\\{\\frac{f(x)}{x-1}\\times\\frac{x^{2}-1}{g(x)}\\right\\}$\n$=\\lim_{x \\to 1}\\frac{f(x)}{x-1}\\times\\lim_{x \\to 1}\\frac{x^{2}-1}{g(x)}$\n$=8\\times 2$\n$=16$\n(두 함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to a}f(x)=\\alpha$, $\\lim_{x \\to a}g(x)=\\beta$ ($\\alpha$, $\\beta$는 실수)일 때 $\\lim_{x \\to a}f(x)g(x)=\\lim_{x \\to a}f(x)\\times\\lim_{x \\to a}g(x)=\\alpha\\beta$)", "img": "IMG_4922.jpg"}, {"id": "A86", "section": "A", "num": 86, "page": 17, "topic": "함수의 극한에 대한 성질", "answer": "②", "rate": "83%", "problem": "다항함수 $f(x)$가 $\\lim_{x \\to 2}(x+1)f(x)=6$을 만족시킨다. $\\lim_{x \\to 2}(x^{2}+ax-1)f(x)=26$일 때, $a+f(2)$의 값은? (단, $a$는 상수이다.) (3점)", "explanation": "정답 공식: $\\lim_{x \\to a}f(x)=\\alpha$, $\\lim_{x \\to a}g(x)=\\beta$ ($\\alpha$, $\\beta$는 실수)이면 $\\lim_{x \\to a}f(x)g(x)=\\alpha\\beta$이다.\n(단서: 다항함수는 극한값과 함숫값이 같아. 따라서 $\\lim_{x \\to 2}(x+1)f(x)=(2+1)\\times f(2)=6$이야.)\n1st 먼저 $f(2)$의 값을 구하자.\n$f(x)$가 다항함수이므로\n$\\lim_{x \\to 2}(x+1)f(x)=\\lim_{x \\to 2}(x+1)\\times\\lim_{x \\to 2}f(x)$ (두 함수가 모두 수렴하면 두 함수의 곱도 수렴해. 즉, 실수 $\\alpha$, $\\beta$에 대하여 $\\lim_{x \\to a}f(x)=\\alpha$, $\\lim_{x \\to a}g(x)=\\beta$이면 $\\lim_{x \\to a}f(x)g(x)=\\alpha\\beta$가 성립해.)\n$=3\\times\\lim_{x \\to 2}f(x)=6$\n즉, $\\lim_{x \\to 2}f(x)=2$이므로 $f(2)=2$ (다항함수는 모든 실수 $x$에서 극한값이 존재하고 그 값은 함숫값과 같아. 즉, $\\lim_{x \\to 2}f(x)=f(2)$야.)\n2nd $\\lim_{x \\to 2}(x^{2}+ax-1)f(x)=26$에서 $f(2)=2$임을 이용해 $a$의 값을 구하자.\n$\\lim_{x \\to 2}(x^{2}+ax-1)f(x)=\\lim_{x \\to 2}(x^{2}+ax-1)\\times\\lim_{x \\to 2}f(x)$\n$=(2a+3)\\times 2=26$ ($\\lim_{x \\to 2}(x^{2}+ax-1)=2^{2}+a\\times 2-1$)\n$2a+3=13$, $2a=10$ $\\therefore a=5$\n$\\therefore a+f(2)=5+2=7$", "img": "IMG_4922.jpg", "answer_value": "$7$"}, {"id": "A87", "section": "A", "num": 87, "page": 17, "topic": "함수의 극한에 대한 성질", "answer": "$30$", "rate": "86%", "problem": "함수 $f(x)$가 $\\lim_{x \\to 1}(x+1)f(x)=1$을 만족시킬 때, $\\lim_{x \\to 1}(2x^{2}+1)f(x)=a$이다. $20a$의 값을 구하시오. (3점)", "explanation": "정답 공식: 수렴하는 두 함수를 더하거나 빼거나 곱하거나 나누어도((분모)$\\ne 0$) 수렴한다.\n(단서: 함수 $f(x)$에 대하여 $(x+1)f(x)$를 새로운 함수로 치환해서 생각해 봐.)\n1st $g(x)=(x+1)f(x)$로 치환하고, 함수의 극한의 성질을 이용하자.\n$\\lim_{x \\to 1}(x+1)f(x)=1$에서 $g(x)=(x+1)f(x)$로 놓으면\n$\\lim_{x \\to 1}g(x)=1$\n한편, $x \\ne -1$일 때, $f(x)=\\frac{g(x)}{x+1}$이므로 (주의: 문제에서 $x \\to 1$이기 때문에 이러한 변형이 가능한 거야. $x=-1$에서 $f(x)$가 정의되지 않는다는 걸 잊지 마.)\n$\\lim_{x \\to 1}(2x^{2}+1)f(x)=\\lim_{x \\to 1}\\left\\{(2x^{2}+1)\\times\\frac{g(x)}{x+1}\\right\\}$\n$=\\lim_{x \\to 1}\\frac{2x^{2}+1}{x+1}\\times\\lim_{x \\to 1}g(x)$ ($\\lim_{x \\to 1}\\frac{2x^{2}+1}{x+1}=\\frac{2\\times 1^{2}+1}{1+1}=\\frac{3}{2}$)\n$=\\frac{3}{2}\\times 1=\\frac{3}{2}$\n(두 실수 $\\alpha$, $\\beta$에 대하여 $\\lim_{x \\to a}f(x)=\\alpha$, $\\lim_{x \\to a}g(x)=\\beta$일 때 $\\lim_{x \\to a}f(x)g(x)=\\lim_{x \\to a}f(x)\\times\\lim_{x \\to a}g(x)=\\alpha\\beta$)\n따라서 $a=\\frac{3}{2}$이므로\n$20a=20\\times\\frac{3}{2}=30$", "img": "IMG_4922.jpg, IMG_4923.jpg", "note": "(경미) 주의 박스의 \"x=-1에서 f(x)가 정의되지 않는다\"는 부정확한 표현이다. 정의되지 않는 것은 식 g(x)/(x+1)이며 f(-1)은 정의될 수도 있다. 풀이와 정답(30)은 맞고, 사진과 데이터도 같다."}, {"id": "A88", "section": "A", "num": 88, "page": 18, "topic": "함수의 극한에 대한 성질", "answer": "②", "rate": "79%", "problem": "두 함수 $f(x)$, $g(x)$가 $\\lim_{x \\to \\infty}\\left\\{2f(x)-3g(x)\\right\\}=1$, $\\lim_{x \\to \\infty}g(x)=\\infty$를 만족시킬 때, $\\lim_{x \\to \\infty}\\frac{4f(x)+g(x)}{3f(x)-g(x)}$의 값은? (4점)", "explanation": "정답 공식: 수렴하는 두 함수를 더하거나 빼거나 곱하거나 나누어도((분모)$\\ne 0$) 수렴한다.\n(단서1: $h(x)=2f(x)-3g(x)$라 놓고 $f(x)$에 대하여 정리해봐. 단서2: $\\lim_{x \\to \\infty}g(x)=\\infty$이므로 $\\lim_{x \\to \\infty}\\frac{1}{g(x)}=0$임을 이용해. 단서3: 수렴하는 함수의 극한을 이용하여 식을 변형한 후 극한값을 계산하는 거야.)\n1st $h(x)=2f(x)-3g(x)$로 놓고, $\\lim_{x \\to \\infty}\\frac{h(x)}{g(x)}$의 값을 구하자.\n$h(x)=2f(x)-3g(x)$라 하면 $\\lim_{x \\to \\infty}h(x)=1$이고,\n$2f(x)=3g(x)+h(x)$에서 $f(x)=\\frac{3g(x)+h(x)}{2}$ … ㉠이다.\n또, $\\lim_{x \\to \\infty}g(x)=\\infty$이므로 $\\lim_{x \\to \\infty}\\frac{1}{g(x)}=0$이다.\n따라서 함수의 극한의 성질에 의해 (두 함수 $f(x)$, $g(x)$에서 $\\lim_{x \\to \\infty}f(x)=\\alpha$, $\\lim_{x \\to \\infty}g(x)=\\beta$ ($\\alpha$, $\\beta$는 실수)일 때, $\\lim_{x \\to \\infty}\\left\\{f(x)g(x)\\right\\}=\\lim_{x \\to \\infty}f(x)\\times\\lim_{x \\to \\infty}g(x)=\\alpha\\beta$)\n$\\lim_{x \\to \\infty}\\frac{h(x)}{g(x)}=\\lim_{x \\to \\infty}h(x)\\times\\lim_{x \\to \\infty}\\frac{1}{g(x)}=1\\times 0=0$\n2nd 구해야 하는 극한식을 변형하여 극한값을 구하자.\n$\\therefore \\lim_{x \\to \\infty}\\frac{4f(x)+g(x)}{3f(x)-g(x)}$\n$=\\lim_{x \\to \\infty}\\frac{4\\left\\{\\frac{3g(x)+h(x)}{2}\\right\\}+g(x)}{3\\left\\{\\frac{3g(x)+h(x)}{2}\\right\\}-g(x)}$ ($\\because$ ㉠)\n$=\\lim_{x \\to \\infty}\\frac{12g(x)+4h(x)+2g(x)}{9g(x)+3h(x)-2g(x)}$\n$=\\lim_{x \\to \\infty}\\frac{14g(x)+4h(x)}{7g(x)+3h(x)}$ ($\\lim_{x \\to \\infty}g(x)=\\infty$이므로 분모, 분자를 $g(x)$로 나눠봐.)\n$=\\lim_{x \\to \\infty}\\frac{14+4\\times\\frac{h(x)}{g(x)}}{7+3\\times\\frac{h(x)}{g(x)}} = \\frac{14+4\\times 0}{7+3\\times 0}$ ($\\lim_{x \\to \\infty}\\frac{h(x)}{g(x)}=0$이야.)\n$=2$\n[다른 풀이: 구하는 식의 분모와 분자를 $2f(x)-3g(x)$와 $\\frac{1}{g(x)}$이 나오도록 바꾸기]\n$\\lim_{x \\to \\infty}\\left\\{2f(x)-3g(x)\\right\\}=1$, $\\lim_{x \\to \\infty}g(x)=\\infty$를 바로 적용할 수 있도록 구해야 하는 극한식의 분자, 분모를 변형하면\n$4f(x)+g(x)=2\\left\\{2f(x)-3g(x)\\right\\}+7g(x)$\n$3f(x)-g(x)=\\frac{3}{2}\\left\\{2f(x)-3g(x)\\right\\}+\\frac{7}{2}g(x)$\n$\\therefore \\lim_{x \\to \\infty}\\frac{4f(x)+g(x)}{3f(x)-g(x)}$\n$=\\lim_{x \\to \\infty}\\frac{2\\left\\{2f(x)-3g(x)\\right\\}+7g(x)}{\\frac{3}{2}\\left\\{2f(x)-3g(x)\\right\\}+\\frac{7}{2}g(x)}$\n$=\\lim_{x \\to \\infty}\\frac{\\frac{2\\left\\{2f(x)-3g(x)\\right\\}}{g(x)}+7}{\\frac{3\\left\\{2f(x)-3g(x)\\right\\}}{2g(x)}+\\frac{7}{2}}$\n$=\\frac{2\\times 1\\times 0+7}{\\frac{3}{2}\\times 1\\times 0+\\frac{7}{2}}=\\frac{7}{\\frac{7}{2}}=2$\n($\\lim_{x \\to \\infty}\\left\\{2f(x)-3g(x)\\right\\}=1$, $\\lim_{x \\to \\infty}\\frac{1}{g(x)}=0$에서 두 함수 $\\left\\{2f(x)-3g(x)\\right\\}$, $\\frac{1}{g(x)}$이 모두 수렴하므로 함수의 극한의 성질을 이용할 수 있어.)", "img": "IMG_4923.jpg", "answer_value": "$2$"}, {"id": "A89", "section": "A", "num": 89, "page": 18, "topic": "함수 극한에 대한 성질", "answer": "①", "rate": "75%", "problem": "함수 $f(x)$에 대하여 $\\lim_{x \\to \\infty}\\frac{f(x)}{x}=3$일 때, $\\lim_{x \\to \\infty}\\frac{2x^{2}-1}{\\left\\{f(x)\\right\\}^{2}+3x^{2}}$의 값은? (3점)", "explanation": "정답 공식: 수렴하는 두 함수를 더하거나 빼거나 곱하거나 나누어도 수렴한다.\n(단서: $\\lim_{x \\to \\infty}\\frac{f(x)}{x}=3$을 이용할 수 있도록 식을 변형해.)\n1st 함수의 극한의 성질을 이용하여 값을 구해.\n주어진 식의 분모와 분자를 $x^{2}$으로 각각 나누면 ($\\lim_{x \\to \\infty}\\frac{f(x)}{x}=3$을 이용할 수 있도록 식을 변형한거야.)\n$\\lim_{x \\to \\infty}\\frac{2x^{2}-1}{\\left\\{f(x)\\right\\}^{2}+3x^{2}} = \\lim_{x \\to \\infty}\\frac{2-\\frac{1}{x^{2}}}{\\left\\{\\frac{f(x)}{x}\\right\\}^{2}+3}$ … ㉠\n이때, $\\lim_{x \\to \\infty}\\frac{f(x)}{x}=3$이고 $\\lim_{x \\to \\infty}\\frac{1}{x^{2}}=0$이므로 ㉠에서\n(구하는 값)$=\\lim_{x \\to \\infty}\\frac{2-\\frac{1}{x^{2}}}{\\left\\{\\frac{f(x)}{x}\\right\\}^{2}+3} = \\frac{\\lim_{x \\to \\infty}2-\\lim_{x \\to \\infty}\\frac{1}{x^{2}}}{\\left[\\lim_{x \\to \\infty}\\left\\{\\frac{f(x)}{x}\\right\\}\\right]^{2}+\\lim_{x \\to \\infty}3}$\n$=\\frac{2-0}{3^{2}+3}=\\frac{2}{12}=\\frac{1}{6}$\n($\\lim_{x \\to \\infty}\\left\\{\\frac{f(x)}{x}\\right\\}^{2}=\\lim_{x \\to \\infty}\\frac{f(x)}{x}\\times\\lim_{x \\to \\infty}\\frac{f(x)}{x}=3\\times 3$)\n[개념·공식] 함수의 극한에 관한 기본 성질: 두 실수 $\\alpha$, $\\beta$에 대하여 $\\lim_{x \\to a}f(x)=\\alpha$, $\\lim_{x \\to a}g(x)=\\beta$일 때, ① $\\lim_{x \\to a}kf(x)=k\\lim_{x \\to a}f(x)=k\\alpha$ (단, $k$는 상수) ② $\\lim_{x \\to a}\\left\\{f(x)\\pm g(x)\\right\\}=\\lim_{x \\to a}f(x)\\pm\\lim_{x \\to a}g(x)=\\alpha\\pm\\beta$ (복부호동순) ③ $\\lim_{x \\to a}f(x)g(x)=\\lim_{x \\to a}f(x)\\times\\lim_{x \\to a}g(x)=\\alpha\\beta$ ④ $\\lim_{x \\to a}\\frac{f(x)}{g(x)}=\\frac{\\lim_{x \\to a}f(x)}{\\lim_{x \\to a}g(x)}=\\frac{\\alpha}{\\beta}$ (단, $g(x) \\ne 0$, $\\beta \\ne 0$)", "img": "IMG_4923.jpg", "answer_value": "$\\frac{1}{6}$"}, {"id": "A90", "section": "A", "num": 90, "page": 19, "topic": "간단한 함수의 극한값의 계산", "answer": "$11$", "rate": "97%", "problem": "$\\lim_{x \\to 2}\\frac{x^{2}+7}{x-1}$의 값을 구하시오. (3점)", "explanation": "정답 공식: 분수 꼴의 극한에서 분모가 $0$이 아닌 경우 $x$의 값을 대입하여 극한값을 구한다.\n1st $x=2$를 분자, 분모에 대입해. $\\lim_{x \\to 2}\\frac{x^{2}+7}{x-1} = \\frac{2^{2}+7}{2-1} = 11$ ($f(x)$, $g(x)$가 다항함수이고 $g(a) \\ne 0$이면 $\\lim_{x \\to a}\\frac{f(x)}{g(x)} = \\frac{f(a)}{g(a)}$)", "img": "IMG_4924.jpg"}, {"id": "A91", "section": "A", "num": 91, "page": 19, "topic": "간단한 함수의 극한값의 계산", "answer": "①", "rate": "94%", "problem": "$\\lim_{x \\to 1}(3x^{2}+2)$의 값은? (2점)", "explanation": "정답 공식: 임의의 실수 $a$와 다항함수 $f(x)$에 대하여 $\\lim_{x \\to a}f(x)=f(a)$이다.\n1st 주어진 극한값을 구해. $\\lim_{x \\to 1}(3x^{2}+2)=3\\times 1^{2}+2=5$ (함수 $y=3x^{2}+2$는 다항함수이므로 $\\lim_{x \\to 1}(3x^{2}+2)$의 값은 $x=1$일 때의 함숫값과 같아.)", "img": "IMG_4924.jpg", "answer_value": "$5$"}, {"id": "A92", "section": "A", "num": 92, "page": 19, "topic": "간단한 함수의 극한값의 계산", "answer": "$9$", "rate": "96%", "problem": "$\\lim_{x \\to 2}(x^{2}+5)$의 값을 구하시오. (3점)", "explanation": "정답 공식: 다항함수 $f(x)$와 실수 $a$에 대하여 $\\lim_{x \\to a}f(x)=f(a)$이다.\n1st 함수의 극한값을 계산하자. $\\lim_{x \\to 2}(x^{2}+5)=2^{2}+5=4+5=9$ ($f(x)=x^{2}+5$는 다항함수이므로 $\\lim_{x \\to 2}(x^{2}+5)$의 값은 $x=2$에서의 $f(x)$의 함숫값 $f(2)$와 같아.)", "img": "IMG_4924.jpg"}, {"id": "A93", "section": "A", "num": 93, "page": 19, "topic": "간단한 함수의 극한값의 계산", "answer": "$5$", "rate": "96%", "problem": "$\\lim_{x \\to 1}(x^{2}+3x+1)$의 값을 구하시오. (3점)", "explanation": "정답 공식: 임의의 실수 $a$와 다항함수 $f(x)$에 대하여 $\\lim_{x \\to a}f(x)=f(a)$이다.\n1st 주어진 극한값을 구해. $\\lim_{x \\to 1}(x^{2}+3x+1)=1^{2}+3\\times 1+1=5$ (함수 $f(x)$가 다항함수이면 $\\lim_{x \\to a}f(x)=f(a)$야.)", "img": "IMG_4924.jpg"}, {"id": "A94", "section": "A", "num": 94, "page": 19, "topic": "간단한 함수의 극한값의 계산", "answer": "$27$", "rate": "98%", "problem": "$\\lim_{x \\to 3}\\frac{x^{3}}{x-2}$의 값을 구하시오. (3점)", "explanation": "정답 공식: 분수 꼴의 극한에서 분모가 $0$이 아닌 경우 $x$의 값을 대입하여 극한값을 구한다.\n1st 함수의 극한값을 구하자. $\\lim_{x \\to 3}\\frac{x^{3}}{x-2} = \\frac{3^{3}}{3-2} = 27$ ($f(x)$, $g(x)$가 다항함수이고 $g(a) \\ne 0$이면 $\\lim_{x \\to a}\\frac{f(x)}{g(x)}=\\frac{f(a)}{g(a)}$)", "img": "IMG_4924.jpg"}, {"id": "A95", "section": "A", "num": 95, "page": 19, "topic": "간단한 함수의 극한값의 계산", "answer": "$3$", "rate": "96%", "problem": "$\\lim_{x \\to 0}\\sqrt{2x+9}$의 값을 구하시오. (3점)", "explanation": "정답 공식: $x \\ge a$에서 정의된 무리함수 $f(x)$에 대하여 $k>a$이면 $\\lim_{x \\to k}f(x)=f(k)$이다.\n1st 함수의 극한인데, 부정형이 아니니까 바로 $x=0$을 대입해. $\\lim_{x \\to 0}\\sqrt{2x+9}=\\sqrt{9}=3$ ($\\frac{0}{0}$, $\\frac{\\infty}{\\infty}$, $\\infty-\\infty$, $\\infty\\times 0$ 꼴이 아니니까 $x=0$을 $\\sqrt{2x+9}$에 직접 대입해.)", "img": "IMG_4924.jpg"}, {"id": "A96", "section": "A", "num": 96, "page": 19, "topic": "간단한 함수의 극한값의 계산", "answer": "④", "rate": "67%", "problem": "$a>1$일 때, $\\lim_{x \\to 1}\\frac{|x-a|-(a-1)}{x-1}$의 값은? (3점)", "explanation": "정답 공식: $|1-a|=a-1$ ($a>1$)임을 이용한다.\n1st $x \\to 1$의 의미를 파악하자. 주어진 식은 $x$가 $1$에 한없이 가까이 갈 때의 값이다. $x$가 $1$에 한없이 가까이 간다는 것은 $x \\to 1+$ 또는 $x \\to 1-$라는 것이므로 $x$는 $1$ 근방에 있는 임의의 실수라고 할 수 있다.\n그런데 $a>1$에서 $a>x$이므로 $|x-a|=-(x-a)=-x+a$ (절댓값의 성질: 실수 $x$에 대하여 $x \\ge 0$이면 $|x|=x$, $x<0$이면 $|x|=-x$)\n$\\therefore \\lim_{x \\to 1}\\frac{|x-a|-(a-1)}{x-1} = \\lim_{x \\to 1}\\frac{-x+a-(a-1)}{x-1} = \\lim_{x \\to 1}\\frac{-x+1}{x-1} = \\lim_{x \\to 1}\\frac{-(x-1)}{x-1} = -1$", "img": "IMG_4924.jpg", "answer_value": "$-1$"}, {"id": "A97", "section": "A", "num": 97, "page": 20, "topic": "가우스 기호를 포함한 함수의 극한", "answer": "②", "rate": "65%", "problem": "함수 $f(x)=[x^{2}]-a[x]$에 대하여 $\\lim_{x \\to -2}f(x)$의 값이 존재할 때, $\\lim_{x \\to a-}f(x)$의 값은? (단, $a$는 상수이고, $[x]$는 $x$보다 크지 않은 최대의 정수이다.) (3점)", "explanation": "정답 공식: 정수 $n$에 대하여 $x \\to n-$이면 $[x]=n-1$이고, $x \\to n+$이면 $[x]=n$이다.\n1st $\\lim_{x \\to -2}f(x)$의 값이 존재하도록 하는 $a$의 값을 구하자. $\\lim_{x \\to -2}f(x)$의 값이 존재하므로 $\\lim_{x \\to -2-}f(x)=\\lim_{x \\to -2+}f(x)$이다.\n이때 $\\lim_{x \\to -2-}f(x)=\\lim_{x \\to -2-}\\left\\{[x^{2}]-a[x]\\right\\}=4+3a$ ($x \\to -2-$일 때 $[x]=-3$이고 $x^{2} \\to 4+$이므로 $[x^{2}]=4$)\n$\\lim_{x \\to -2+}f(x)=\\lim_{x \\to -2+}\\left\\{[x^{2}]-a[x]\\right\\}=3+2a$ ($x \\to -2+$일 때 $[x]=-2$이고 $x^{2} \\to 4-$이므로 $[x^{2}]=3$)\n이므로 $4+3a=3+2a$ $\\therefore a=-1$\n2nd $\\lim_{x \\to a-}f(x)$의 값을 구하자. 따라서 $a=-1$이므로 $f(x)=[x^{2}]+[x]$에 대하여 $\\lim_{x \\to -1-}f(x)=\\lim_{x \\to -1-}\\left\\{[x^{2}]+[x]\\right\\}=1+(-2)=-1$ ($x \\to -1-$일 때 $[x]=-2$이고 $x^{2} \\to 1+$이므로 $[x^{2}]=1$)", "img": "IMG_4925.jpg", "answer_value": "$-1$"}, {"id": "A98", "section": "A", "num": 98, "page": 20, "topic": "가우스 기호를 포함한 함수의 극한", "answer": "①", "rate": "81%", "problem": "극한값이 존재하는 것만을 [보기]에서 있는 대로 고른 것은? (단, $[x]$는 $x$보다 크지 않은 최대의 정수이다.) (3점) [보기] ㄱ. $\\lim_{x \\to 1}|x-1|$ ㄴ. $\\lim_{x \\to 2}\\frac{|x-2|}{x^{2}-4}$ ㄷ. $\\lim_{x \\to 3}\\frac{[x]^{2}}{x+3}$", "explanation": "정답 공식: $\\lim_{x \\to a}f(x)$의 값이 존재하려면 $\\lim_{x \\to a-}f(x)=\\lim_{x \\to a+}f(x)$이어야 한다.\n1st 각각의 극한값이 존재하는지 판단하자. (주의: 절댓값, 가우스 기호를 포함하는 함수는 $x$의 값의 범위에 따라 함수가 달라질 수 있기 때문에 좌극한과 우극한을 구해서 극한값의 유무를 조사해봐야 해.)\nㄱ. $|x-1| = \\begin{cases} x-1 & (x \\ge 1) \\\\ -x+1 & (x<1) \\end{cases}$에서 $\\lim_{x \\to 1+}|x-1|=\\lim_{x \\to 1+}(x-1)=0$, $\\lim_{x \\to 1-}|x-1|=\\lim_{x \\to 1-}(-x+1)=0$\n즉, $\\lim_{x \\to 1+}|x-1|=\\lim_{x \\to 1-}|x-1|=0$이므로 $\\lim_{x \\to 1}|x-1|=0$이다. (우극한과 좌극한이 모두 존재하고 그 값이 $0$으로 같으니까 $\\lim_{x \\to 1}|x-1|=0$이야.) 따라서 주어진 극한의 극한값은 존재한다.\nㄴ. $\\frac{|x-2|}{x^{2}-4} = \\frac{|x-2|}{(x-2)(x+2)} = \\begin{cases} \\frac{1}{x+2} & (x \\ge 2) \\\\ -\\frac{1}{x+2} & (x<2) \\end{cases}$에서 ($|x-2| = \\begin{cases} x-2 & (x \\ge 2) \\\\ -x+2 & (x<2) \\end{cases}$)\n$\\lim_{x \\to 2+}\\frac{|x-2|}{x^{2}-4}=\\lim_{x \\to 2+}\\frac{1}{x+2}=\\frac{1}{4}$, $\\lim_{x \\to 2-}\\frac{|x-2|}{x^{2}-4}=\\lim_{x \\to 2-}\\left(-\\frac{1}{x+2}\\right)=-\\frac{1}{4}$\n즉, 우극한과 좌극한이 모두 존재하지만 이 두 값이 같지 않으므로 주어진 극한의 극한값은 존재하지 않는다.\nㄷ. $\\lim_{x \\to 3+}\\frac{[x]^{2}}{x+3}=\\lim_{x \\to 3+}\\frac{9}{x+3}=\\frac{9}{3+3}=\\frac{3}{2}$ ($x \\to 3+$는 $x$가 $3$의 오른쪽에서 $3$으로 가까이 다가가니까 $x$의 값의 범위는 $3<x<4$야. 즉, $\\lim_{x \\to 3+}[x]=3$이야.)\n$\\lim_{x \\to 3-}\\frac{[x]^{2}}{x+3}=\\lim_{x \\to 3-}\\frac{4}{x+3}=\\frac{4}{3+3}=\\frac{2}{3}$ ($x \\to 3-$는 $x$가 $3$의 왼쪽에서 $3$으로 가까이 다가가니까 $x$의 값의 범위는 $2<x<3$이야. 즉, $\\lim_{x \\to 3-}[x]=2$야.)\n즉, $\\lim_{x \\to 3+}\\frac{[x]^{2}}{x+3} \\ne \\lim_{x \\to 3-}\\frac{[x]^{2}}{x+3}$이므로 주어진 극한의 극한값은 존재하지 않는다.\n따라서 극한값이 존재하는 것은 ㄱ이다.", "img": "IMG_4925.jpg", "answer_value": "ㄱ"}, {"id": "A99", "section": "A", "num": 99, "page": 20, "topic": "가우스 기호를 포함한 함수의 극한", "answer": "①", "rate": "71%", "problem": "다음 중 극한값 $a$, $b$, $c$ 사이의 대소 관계를 바르게 나타낸 것은? (단, $[x]$는 $x$를 넘지 않는 최대의 정수이다.) (3점) $\\lim_{x \\to 0-}\\frac{x}{[x]}=a$, $\\lim_{x \\to 0-}\\frac{[x+2]}{x+2}=b$, $\\lim_{x \\to 0+}\\frac{[x-1]}{x-1}=c$", "explanation": "정답 공식: 정수 $n$에 대하여 $x \\to n-$이면 $[x]=n-1$이고 $x \\to n+$이면 $[x]=n$이다.\n1st $x \\to 0-$일 때의 극한값을 구하자.\n(i) $\\lim_{x \\to 0-}[x]=-1$이므로 $\\lim_{x \\to 0-}\\frac{x}{[x]}=\\frac{0}{-1}=0$ $\\therefore a=0$\n(ii) $\\lim_{x \\to 0-}[x+2]=1$이므로 $\\lim_{x \\to 0-}\\frac{[x+2]}{x+2}=\\frac{1}{2}$ $\\therefore b=\\frac{1}{2}$\n2nd $x \\to 0+$일 때의 극한값을 구하자.\n(iii) $\\lim_{x \\to 0+}[x-1]=-1$이므로 $\\lim_{x \\to 0+}\\frac{[x-1]}{x-1}=\\frac{-1}{-1}=1$ $\\therefore c=1$\n(i), (ii), (iii)에 의하여 $a<b<c$이다.\n[수능 핵강] $\\lim_{x \\to 0-}[x]$와 $\\left[\\lim_{x \\to 0-}x\\right]$의 값 알아보기: $\\lim_{x \\to 0-}[x]$는 $x$가 $0$보다 작은 쪽(수직선 상 왼쪽)에서 $0$에 한없이 가까이 가고 있는 상태의 $[x]$가 어떤 값을 가질지 생각해야 한다. $x$가 $0$보다 '작은' 쪽에서 $0$에 가까이 다가가는 것이기 때문에 $\\lim_{x \\to 0-}[x]=-1$이다. 헷갈린다면 $y=[x]$의 그래프를 그려봐도 좋다. 그렇다면 $\\left[\\lim_{x \\to 0-}x\\right]$는 가우스 기호 안에 있는 극한을 먼저 계산해 준 다음에 가우스 기호를 적용해야 하기 때문에 $\\left[\\lim_{x \\to 0-}x\\right]=[0]=0$이다.", "img": "IMG_4925.jpg", "answer_value": "$a<b<c$"}, {"id": "A100", "section": "A", "num": 100, "page": 21, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "⑤", "rate": "95%", "problem": "$\\lim_{x \\to 3}\\frac{(x-3)(x+2)}{x-3}$의 값은? (2점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한은 인수분해한 후 분모, 분자의 공통인수를 약분한다.\n1st $\\frac{0}{0}$ 꼴의 극한식에서는 분모, 분자의 공통인수를 약분한 후 계산하자. $\\lim_{x \\to 3}\\frac{(x-3)(x+2)}{x-3} = \\lim_{x \\to 3}(x+2)=3+2=5$ (분자, 분모를 $x-3$으로 약분하고 $x=3$을 대입)", "img": "IMG_4926.jpg", "answer_value": "$5$"}, {"id": "A101", "section": "A", "num": 101, "page": 21, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "$8$", "rate": "90%", "problem": "$\\lim_{x \\to 1}\\frac{x^{2}+6x-7}{x-1}$의 값을 구하시오. (3점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한은 분모, 분자의 공통인수로 약분한 후 극한값을 구한다.\n1st 분모, 분자를 $0$이 되게 하는 공통인수를 약분해. $\\lim_{x \\to 1}\\frac{x^{2}+6x-7}{x-1} = \\lim_{x \\to 1}\\frac{(x-1)(x+7)}{x-1} = \\lim_{x \\to 1}(x+7) = 1+7 = 8$ (분모, 분자에 공통으로 있는 인수 $x-1$은 $x \\to 1$이면 $0$으로 수렴하니까 약분한 후 극한값을 구해.)", "img": "IMG_4926.jpg"}, {"id": "A102", "section": "A", "num": 102, "page": 21, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "②", "rate": "98%", "problem": "$\\lim_{x \\to 0}\\frac{x(x+2)}{x}$의 값은? (2점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴일 때는 분모, 분자의 공통인수를 약분하고 극한값을 계산한다.\n1st 분모, 분자에 공통으로 있는 $x$를 약분하자. $\\lim_{x \\to 0}\\frac{x(x+2)}{x} = \\lim_{x \\to 0}(x+2)=0+2=2$ ($x \\to 0$이면 $x \\ne 0$이야. 따라서 분모, 분자를 $x$로 약분할 수 있어.)", "img": "IMG_4926.jpg", "answer_value": "$2$"}, {"id": "A103", "section": "A", "num": 103, "page": 21, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "③", "rate": "97%", "problem": "$\\lim_{x \\to 1}\\frac{(x-1)(x+2)}{x-1}$의 값은? (2점)", "explanation": "정답 공식: 분수식으로 된 $\\frac{0}{0}$ 꼴의 극한은 분모와 분자의 공통인수를 약분한 후 계산한다.\n1st 분모와 분자의 공통인수를 약분해서 극한값을 구해. $\\lim_{x \\to 1}\\frac{(x-1)(x+2)}{x-1} = \\lim_{x \\to 1}(x+2)=1+2=3$ ($x \\to 1$일 때, $x-1 \\ne 0$이므로 분모와 분자의 공통인수인 $x-1$을 약분할 수 있어.)", "img": "IMG_4926.jpg", "answer_value": "$3$"}, {"id": "A104", "section": "A", "num": 104, "page": 21, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "③", "rate": "97%", "problem": "$\\lim_{x \\to 4}\\frac{(x-4)(x+2)}{x-4}$의 값은? (2점)", "explanation": "정답 공식: $x \\to 4$이므로 $x-4 \\ne 0$이다. 분모, 분자를 $x-4$로 나눈 후 극한값을 구한다.\n1st 분모, 분자를 $x-4$로 나누고 함수의 극한값을 계산해. $\\lim_{x \\to 4}\\frac{(x-4)(x+2)}{x-4} = \\lim_{x \\to 4}(x+2)=4+2=6$ (연속함수 $f(x)$에 대하여 $\\lim_{x \\to a}f(x)=f(a)$야.)\n[개념·공식] $\\frac{0}{0}$ 꼴의 극한: 두 함수 $f(x)$, $g(x)$와 임의의 실수 $a$에 대하여 $f(a)=g(a)=0$이면 $\\lim_{x \\to a}\\frac{f(x)}{g(x)}$는 $\\frac{0}{0}$ 꼴이다. 이때, ① $f(x)$, $g(x)$가 모두 다항식이면 $f(x)$, $g(x)$를 각각 인수분해하고 공통인수를 약분하여 극한값을 구한다. ② $f(x)$, $g(x)$ 중 무리식이 있으면 근호를 포함한 쪽을 유리화하고 공통인수를 약분하여 극한값을 구한다.", "img": "IMG_4926.jpg", "answer_value": "$6$"}, {"id": "A105", "section": "A", "num": 105, "page": 21, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "$7$", "rate": "93%", "problem": "$\\lim_{x \\to 1}\\frac{(x-1)(x+6)}{x-1}$의 값을 구하시오. (3점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한은 인수분해한 후 분모, 분자의 공통인수를 약분한다.\n1st 분모, 분자의 공통인 인수를 약분하자. $\\lim_{x \\to 1}\\frac{(x-1)(x+6)}{x-1} = \\lim_{x \\to 1}(x+6)=1+6=7$ (분모, 분자의 공통인 인수 $x-1$을 약분하고 $x=1$을 대입!)", "img": "IMG_4926.jpg"}, {"id": "A106", "section": "A", "num": 106, "page": 21, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "①", "rate": "93%", "problem": "$\\lim_{x \\to 2}\\frac{(x-2)(x^{3}+1)}{x-2}$의 값은? (2점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한은 인수분해한 후 분모, 분자의 공통인수를 약분한다.\n1st 약분하여 극한값을 구해. $\\lim_{x \\to 2}\\frac{(x-2)(x^{3}+1)}{x-2} = \\lim_{x \\to 2}(x^{3}+1)=2^{3}+1=9$ (다항함수 $f(x)$와 임의의 실수 $a$에 대하여 $\\lim_{x \\to a}f(x)=f(a)$야.)\n$x \\to 2$라는 것은 $x$가 $2$에 가까이 간다는 것이지 $x=2$가 아니야. 즉, $x \\to 2$일 때, $x-2 \\ne 0$이므로 분모, 분자를 $x-2$로 약분할 수 있어.", "img": "IMG_4926.jpg", "answer_value": "$9$"}, {"id": "A107", "section": "A", "num": 107, "page": 22, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "④", "rate": "95%", "problem": "$\\lim_{x \\to 2}\\frac{x^{2}(x-2)}{x-2}$의 값은? (2점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한에서 분모, 분자가 모두 다항식이면 분모, 분자를 각각 인수분해하여 약분한다.\n1st 분모, 분자를 $x-2$로 나누자. $\\lim_{x \\to 2}\\frac{x^{2}(x-2)}{x-2} = \\lim_{x \\to 2}x^{2} = 4$ (분자, 분모를 $0$으로 만드는 인수 $x-2$를 약분해. $x \\ne 2$이기 때문에 약분할 수 있어.)", "img": "IMG_4927.jpg", "answer_value": "$4$"}, {"id": "A108", "section": "A", "num": 108, "page": 22, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "③", "rate": "96%", "problem": "$\\lim_{x \\to -2}\\frac{(x+2)(x^{2}+5)}{x+2}$의 값은? (2점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한은 인수분해한 후 분모, 분자의 공통인수를 약분한다.\n1st 약분한 후 극한값을 계산해. $\\lim_{x \\to -2}\\frac{(x+2)(x^{2}+5)}{x+2} = \\lim_{x \\to -2}(x^{2}+5)=(-2)^{2}+5=9$ ($x+2$가 분자, 분모의 공통인수이므로 약분하자.)", "img": "IMG_4927.jpg", "answer_value": "$9$"}, {"id": "A109", "section": "A", "num": 109, "page": 22, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "③", "rate": "95%", "problem": "$\\lim_{x \\to 7}\\frac{(x-7)(x+3)}{x-7}$의 값은? (3점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한은 인수분해한 후 분모, 분자의 공통인수를 약분한다.\n1st $\\frac{0}{0}$ 꼴의 극한식에서는 분모, 분자의 공통인수를 약분하여 계산하자. $\\lim_{x \\to 7}\\frac{(x-7)(x+3)}{x-7} = \\lim_{x \\to 7}(x+3)=7+3=10$ ($x-7$이 분자, 분모의 공통인수이므로 약분하자.)", "img": "IMG_4927.jpg", "answer_value": "$10$"}, {"id": "A110", "section": "A", "num": 110, "page": 22, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "①", "rate": "88%", "problem": "함수 $f(x)=x^{2}+ax$가 $\\lim_{x \\to 0}\\frac{f(x)}{x}=4$를 만족시킬 때, 상수 $a$의 값은? (3점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한은 인수분해한 후 분모, 분자의 공통인수를 약분한다.\n1st $\\lim_{x \\to 0}\\frac{f(x)}{x}=4$에 $f(x)$의 식을 대입하여 $a$의 값을 구하자. $\\lim_{x \\to 0}\\frac{f(x)}{x} = \\lim_{x \\to 0}\\frac{x^{2}+ax}{x} = \\lim_{x \\to 0}(x+a) = a$ ($x^{2}+ax=x(x+a)$)\n$\\therefore a=4$", "img": "IMG_4927.jpg", "answer_value": "$4$"}, {"id": "A111", "section": "A", "num": 111, "page": 22, "topic": "0/0 꼴의 극한값의 계산(분수식)", "answer": "③", "rate": "71%", "problem": "최고차항의 계수가 $1$인 삼차함수 $f(x)$가 $f(-1)=2$, $f(0)=0$, $f(1)=-2$를 만족시킬 때, $\\lim_{x \\to 0}\\frac{f(x)}{x}$의 값은? (3점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한은 인수분해한 후 분모, 분자의 공통인수를 약분한다.\n1st $f(x)=x^{3}+ax^{2}+bx+c$로 놓고 $f(x)$의 식을 완성하자. $f(0)=0$이라 하므로 $f(0)=c=0$ $\\therefore f(x)=x^{3}+ax^{2}+bx$\n또, $f(-1)=2$, $f(1)=-2$이므로 $f(-1)=-1+a-b=2$에서 $a-b=3$ … ㉠, $f(1)=1+a+b=-2$에서 $a+b=-3$ … ㉡\n㉠과 ㉡을 연립하면 $a=0$, $b=-3$ $\\therefore f(x)=x^{3}-3x$\n2nd $\\lim_{x \\to 0}\\frac{f(x)}{x}$의 값을 구하자. $\\lim_{x \\to 0}\\frac{f(x)}{x} = \\lim_{x \\to 0}\\frac{x^{3}-3x}{x} = \\lim_{x \\to 0}(x^{2}-3) = -3$ ($x^{3}-3x=x(x^{2}-3)$이야.)\n[톡톡 풀이: 방정식 $f(x)=-2x$의 세 근 이용하기] $f(-1)=2$, $f(0)=0$, $f(1)=-2$에서 $f(-1)=-2\\times(-1)$, $f(0)=-2\\times 0$, $f(1)=-2\\times 1$로 생각하면 방정식 $f(x)=-2x$의 세 근이 $x=-1$ 또는 $x=0$ 또는 $x=1$이야. 이때, 삼차함수 $f(x)$의 최고차항의 계수가 $1$이므로 $f(x)+2x=x(x+1)(x-1)$에서 $f(x)=x(x+1)(x-1)-2x$ (삼차방정식 $f(x)+2x=0$의 세 근이 $x=-1$ 또는 $x=0$ 또는 $x=1$이니까 삼차식 $f(x)+2x$는 $x+1$, $x$, $x-1$을 인수로 갖겠지?)\n$\\therefore \\lim_{x \\to 0}\\frac{f(x)}{x} = \\lim_{x \\to 0}\\frac{x(x+1)(x-1)-2x}{x} = \\lim_{x \\to 0}\\left\\{(x+1)(x-1)-2\\right\\} = -1-2 = -3$ ($\\frac{0}{0}$ 꼴이므로 분모, 분자를 $0$으로 만드는 인수 $x$로 분모, 분자를 각각 나눠.)", "img": "IMG_4927.jpg", "answer_value": "$-3$"}, {"id": "A112", "section": "A", "num": 112, "page": 22, "topic": "0/0 꼴의 극한값의 계산(무리식)", "answer": "⑤", "rate": "91%", "problem": "$\\lim_{x \\to 2}\\frac{3x-6}{\\sqrt{x+2}-2}$의 값은? (2점)", "explanation": "정답 공식: 근호가 포함된 $\\frac{0}{0}$ 꼴의 극한은 유리화를 이용하여 식을 정리한다.\n1st 분모를 유리화하여 식을 정리하자. $\\lim_{x \\to 2}\\frac{3x-6}{\\sqrt{x+2}-2} = \\lim_{x \\to 2}\\frac{3(x-2)(\\sqrt{x+2}+2)}{(\\sqrt{x+2}-2)(\\sqrt{x+2}+2)} = \\lim_{x \\to 2}\\frac{3(x-2)(\\sqrt{x+2}+2)}{(\\sqrt{x+2})^{2}-2^{2}}$ ($\\frac{0}{0}$ 꼴이고 분모에 무리식이 있으니까 유리화하자.) $= \\lim_{x \\to 2}\\frac{3(x-2)(\\sqrt{x+2}+2)}{x+2-4} = \\lim_{x \\to 2}\\frac{3(x-2)(\\sqrt{x+2}+2)}{x-2} = \\lim_{x \\to 2}3(\\sqrt{x+2}+2) = 3(\\sqrt{2+2}+2) = 12$", "img": "IMG_4927.jpg", "answer_value": "$12$"}, {"id": "A113", "section": "A", "num": 113, "page": 23, "topic": "0/0 꼴의 극한값의 계산(무리식)", "answer": "⑤", "rate": "91%", "problem": "$\\lim_{x \\to 1}\\frac{x^{3}-x^{2}+x-1}{\\sqrt{x+8}-3}$의 값은? (2점)", "explanation": "정답 공식: 근호가 포함된 $\\frac{0}{0}$ 꼴의 극한은 유리화를 이용하여 식을 정리한다.\n1st $x \\to 1$일 때 (분자)$\\to 0$이므로 분자는 $x-1$을 인수로 가져. 우선 분수식의 분자를 인수분해하자. $x^{3}-x^{2}+x-1=x^{2}(x-1)+(x-1)=(x-1)(x^{2}+1)$ (조립제법을 이용해도 돼.)\n2nd 무리식이 있는 $\\frac{0}{0}$ 꼴은 유리화를 먼저 생각하자. $\\lim_{x \\to 1}\\frac{x^{3}-x^{2}+x-1}{\\sqrt{x+8}-3} = \\lim_{x \\to 1}\\frac{(x-1)(x^{2}+1)(\\sqrt{x+8}+3)}{(\\sqrt{x+8}-3)(\\sqrt{x+8}+3)}$ ($(\\sqrt{x+8})^{2}-3^{2}=x+8-9=x-1$) $= \\lim_{x \\to 1}\\frac{(x-1)(x^{2}+1)(\\sqrt{x+8}+3)}{x-1} = \\lim_{x \\to 1}(x^{2}+1)(\\sqrt{x+8}+3)$ ($x-1$이 분자, 분모의 공통인수이므로 약분하자.) $= 2\\times 6 = 12$", "img": "IMG_4928.jpg", "answer_value": "$12$"}, {"id": "A114", "section": "A", "num": 114, "page": 23, "topic": "0/0 꼴의 극한값의 계산(무리식)", "answer": "$4$", "rate": "91%", "problem": "$\\lim_{x \\to 3}\\frac{x-3}{\\sqrt{x+1}-2}$의 값을 구하시오. (3점)", "explanation": "정답 공식: 근호가 포함된 $\\frac{0}{0}$ 꼴의 극한은 유리화를 이용하여 식을 정리한다.\n1st 분모를 유리화한 후 분모, 분자를 인수분해하자. $\\lim_{x \\to 3}\\frac{x-3}{\\sqrt{x+1}-2} = \\lim_{x \\to 3}\\frac{(x-3)(\\sqrt{x+1}+2)}{(\\sqrt{x+1}-2)(\\sqrt{x+1}+2)}$ (분모를 유리화해.) $= \\lim_{x \\to 3}\\frac{(x-3)(\\sqrt{x+1}+2)}{(x+1)-4} = \\lim_{x \\to 3}\\frac{(x-3)(\\sqrt{x+1}+2)}{x-3} = \\lim_{x \\to 3}(\\sqrt{x+1}+2)$ (분모, 분자를 $0$으로 만드는 인수 $(x-3)$을 약분해.) $= \\sqrt{3+1}+2 = 2+2 = 4$", "img": "IMG_4928.jpg"}, {"id": "A115", "section": "A", "num": 115, "page": 23, "topic": "0/0 꼴의 극한값의 계산(무리식)", "answer": "②", "rate": "93%", "problem": "$\\lim_{x \\to 1}\\frac{x^{2}-1}{\\sqrt{x+3}-2}$의 값은? (2점)", "explanation": "정답 공식: 근호가 포함된 $\\frac{0}{0}$ 꼴의 극한은 유리화를 이용하여 식을 정리한다.\n1st 분모를 유리화하자. $\\lim_{x \\to 1}\\frac{x^{2}-1}{\\sqrt{x+3}-2} = \\lim_{x \\to 1}\\left\\{\\frac{x^{2}-1}{\\sqrt{x+3}-2}\\times\\frac{\\sqrt{x+3}+2}{\\sqrt{x+3}+2}\\right\\} = \\lim_{x \\to 1}\\frac{(x-1)(x+1)(\\sqrt{x+3}+2)}{x-1}$ ($x^{2}-1=(x+1)(x-1)$, $(\\sqrt{x+3})^{2}-2^{2}=(x+3)-4=x-1$) $= 2\\times 4 = 8$", "img": "IMG_4928.jpg", "answer_value": "$8$"}, {"id": "A116", "section": "A", "num": 116, "page": 23, "topic": "0/0 꼴의 극한값의 계산(무리식)", "answer": "①", "rate": "91%", "problem": "$\\lim_{x \\to 3} \\frac{x^{2}-9}{\\sqrt{x+1}-2}$의 값은? (2점)", "explanation": "정답 공식: 근호가 포함된 $\\frac{0}{0}$ 꼴의 극한은 유리화를 이용하여 식을 정리한다.\n1st 분모를 유리화한 후 분모, 분자를 인수분해하자. $\\lim_{x \\to 3} \\frac{x^{2}-9}{\\sqrt{x+1}-2} = \\lim_{x \\to 3} \\frac{(x^{2}-9)(\\sqrt{x+1}+2)}{(\\sqrt{x+1}-2)(\\sqrt{x+1}+2)}$ (분모의 무리식을 유리화) $= \\lim_{x \\to 3} \\frac{(x-3)(x+3)(\\sqrt{x+1}+2)}{x-3} = \\lim_{x \\to 3}(x+3)(\\sqrt{x+1}+2)$ (분모, 분자를 0으로 만드는 인수를 약분) $= 6 \\times 4 = 24$", "img": "IMG_4928.jpg", "answer_value": "24"}, {"id": "A117", "section": "A", "num": 117, "page": 23, "topic": "0/0 꼴의 극한값의 계산(무리식)", "answer": "$20$", "rate": "87%", "problem": "$\\lim_{x \\to 2} \\frac{x^{2}+x-6}{\\sqrt{x+2}-2}$의 값을 구하시오. (3점)", "explanation": "정답 공식: 근호가 포함된 $\\frac{0}{0}$ 꼴의 극한은 유리화를 이용하여 식을 정리한다.\n1st 분모에 무리식이 있으니까 유리화하여 식을 정리하자. $\\lim_{x \\to 2} \\frac{x^{2}+x-6}{\\sqrt{x+2}-2} = \\lim_{x \\to 2} \\frac{(x^{2}+x-6)(\\sqrt{x+2}+2)}{(\\sqrt{x+2}-2)(\\sqrt{x+2}+2)}$ (유리화하려면 항상 $(a+b)(a-b)=a^{2}-b^{2}$을 이용해야 해.) $= \\lim_{x \\to 2} \\frac{(x-2)(x+3)(\\sqrt{x+2}+2)}{(\\sqrt{x+2})^{2}-2^{2}} = \\lim_{x \\to 2} \\frac{(x-2)(x+3)(\\sqrt{x+2}+2)}{x+2-4} = \\lim_{x \\to 2} \\frac{(x-2)(x+3)(\\sqrt{x+2}+2)}{x-2} = (2+3)(\\sqrt{2+2}+2) = 20$ (분모, 분자가 0이 되는 $x-2$가 약분되어서 없어졌으니까 $x=2$를 대입하기만 하면 돼.)", "img": "IMG_4928.jpg"}, {"id": "A118", "section": "A", "num": 118, "page": 23, "topic": "∞/∞ 꼴의 극한", "answer": "③", "rate": "94%", "problem": "$\\lim_{x \\to \\infty} \\frac{3x+2}{(x+1)^{2}-x^{2}}$의 값은? (2점)", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한에서는 분모의 최고차항으로 분모, 분자를 각각 나눈다.\n1st 주어진 극한을 계산해. $\\lim_{x \\to \\infty} \\frac{3x+2}{(x+1)^{2}-x^{2}} = \\lim_{x \\to \\infty} \\frac{3x+2}{2x+1} = \\lim_{x \\to \\infty} \\frac{3+\\frac{2}{x}}{2+\\frac{1}{x}} = \\frac{3}{2}$ ($\\lim_{x \\to \\infty} \\frac{1}{x}=0$, $\\lim_{x \\to \\infty} \\frac{2}{x}=0$)", "img": "IMG_4928.jpg", "answer_value": "$\\frac{3}{2}$"}, {"id": "A119", "section": "A", "num": 119, "page": 24, "topic": "∞/∞ 꼴의 극한", "answer": "④", "rate": "94%", "problem": "$\\lim_{x \\to \\infty} \\frac{(2x+1)^{2}}{x^{2}+4x+5}$의 값은? (2점)", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한에서는 분모의 최고차항으로 분모, 분자를 각각 나눈다.\n1st 분모, 분자를 $x^{2}$으로 나누어 주어진 극한값을 구해. $\\lim_{x \\to \\infty} \\frac{(2x+1)^{2}}{x^{2}+4x+5} = \\lim_{x \\to \\infty} \\frac{4x^{2}+4x+1}{x^{2}+4x+5}$ ($(ax+b)^{2}=a^{2}x^{2}+2abx+b^{2}$) $= \\lim_{x \\to \\infty} \\frac{4+\\frac{4}{x}+\\frac{1}{x^{2}}}{1+\\frac{4}{x}+\\frac{5}{x^{2}}} = \\frac{4}{1} = 4$ ($\\lim_{x \\to \\infty} \\frac{1}{x^{2}}=0$, $\\lim_{x \\to \\infty} \\frac{5}{x^{2}}=0$, $\\lim_{x \\to \\infty} \\frac{4}{x}=0$)", "img": "IMG_4929.jpg", "answer_value": "4"}, {"id": "A120", "section": "A", "num": 120, "page": 24, "topic": "∞/∞ 꼴의 극한", "answer": "$3$", "rate": "92%", "problem": "$\\lim_{x \\to \\infty} \\frac{9x^{2}+1}{3x^{2}+5x}$의 값을 구하시오. (3점)", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한에서는 분모의 최고차항으로 분모, 분자를 각각 나눈다.\n1st 분모, 분자를 $x^{2}$으로 나누어 주어진 극한값을 구해. $\\lim_{x \\to \\infty} \\frac{9x^{2}+1}{3x^{2}+5x} = \\lim_{x \\to \\infty} \\frac{9+\\frac{1}{x^{2}}}{3+\\frac{5}{x}} = \\frac{9}{3} = 3$ ($\\lim_{x \\to \\infty} \\frac{1}{x^{2}}=0$, $\\lim_{x \\to \\infty} \\frac{5}{x}=0$)", "img": "IMG_4929.jpg"}, {"id": "A121", "section": "A", "num": 121, "page": 24, "topic": "∞/∞ 꼴의 극한", "answer": "②", "rate": "91%", "problem": "$\\lim_{x \\to -\\infty} \\frac{x-\\sqrt{x^{2}-1}}{x+1}$의 값은? (2점)", "explanation": "정답 공식: $x=-t$로 치환하여 $\\frac{\\infty}{\\infty}$ 꼴로 바꾸어 극한값을 구한다.\n1st 주어진 식이 $\\frac{\\infty}{\\infty}$ 꼴임을 주의하여 계산하자. $x=-t$로 놓으면 $x \\to -\\infty$일 때 $t \\to \\infty$이므로\n$\\lim_{x \\to -\\infty} \\frac{x-\\sqrt{x^{2}-1}}{x+1} = \\lim_{t \\to \\infty} \\frac{-t-\\sqrt{t^{2}-1}}{-t+1} = \\lim_{t \\to \\infty} \\frac{t+\\sqrt{t^{2}-1}}{t-1}$ ($\\frac{\\infty}{\\infty}$ 꼴이므로 분모의 최고차항인 $t$로 분자, 분모를 나누자.) $= \\lim_{t \\to \\infty} \\frac{1+\\sqrt{1-\\frac{1}{t^{2}}}}{1-\\frac{1}{t}} = 2$ ($\\lim_{t \\to \\infty} \\frac{1}{t^{2}}=0$, $\\lim_{t \\to \\infty} \\frac{1}{t}=0$)", "img": "IMG_4929.jpg", "answer_value": "2"}, {"id": "A122", "section": "A", "num": 122, "page": 24, "topic": "∞/∞ 꼴의 극한", "answer": "④", "rate": "96%", "problem": "$\\lim_{x \\to \\infty} \\frac{\\sqrt{x^{2}-2}+3x}{x+5}$의 값은? (2점)", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한에서는 분모의 최고차항으로 분모, 분자를 각각 나눈다.\n1st 주어진 극한을 계산하자. $\\lim_{x \\to \\infty} \\frac{\\sqrt{x^{2}-2}+3x}{x+5} = \\lim_{x \\to \\infty} \\frac{\\sqrt{1-\\frac{2}{x^{2}}}+3}{1+\\frac{5}{x}}$ (분모, 분자를 분모의 최고차항인 $x$로 각각 나눈 거야.) $= \\frac{\\sqrt{1-0}+3}{1+0} = 4$ ($\\lim_{x \\to \\infty} \\frac{2}{x^{2}} = \\lim_{x \\to \\infty} \\frac{5}{x} = 0$)\n[선배 조언] 백규민(영남대 약학과 2023년 입학): 수능 수학에서 초반에 배치된 문제는 빠르고 정확하게 푸는 게 중요하다. 이 유형은 분자와 분모를 각각 $x$로 나누어주면 극한값을 쉽게 구할 수 있지만, $x \\to \\infty$인지, $x \\to 0$인지 등을 제대로 확인하지 않고 무작정 계산부터 시작한다면 실수할 수도 있으니 주의하자.", "img": "IMG_4929.jpg", "answer_value": "4"}, {"id": "A123", "section": "A", "num": 123, "page": 24, "topic": "∞/∞ 꼴의 극한", "answer": "②", "rate": "93%", "problem": "함수 $f(x)=2x^{2}+5x+3$에 대하여 $\\lim_{x \\to \\infty} \\frac{xf(x)}{3x^{3}}$의 값은? (3점)", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한에서는 분모의 최고차항으로 분모, 분자를 각각 나눈다.\n1st 주어진 극한값을 구해. $\\lim_{x \\to \\infty} \\frac{xf(x)}{3x^{3}} = \\lim_{x \\to \\infty} \\frac{2x^{3}+5x^{2}+3x}{3x^{3}}$ (분모의 최고차항인 $x^{3}$으로 분모, 분자를 각각 나눠.) $= \\lim_{x \\to \\infty} \\frac{2+\\frac{5}{x}+\\frac{3}{x^{2}}}{3} = \\frac{2}{3}$ ($\\lim_{x \\to \\infty} \\frac{5}{x} = \\lim_{x \\to \\infty} \\frac{3}{x^{2}} = 0$)", "img": "IMG_4929.jpg", "answer_value": "$\\frac{2}{3}$"}, {"id": "A124", "section": "A", "num": 124, "page": 25, "topic": "∞/∞ 꼴의 극한", "answer": "$3$", "rate": "84%", "problem": "두 상수 $a$, $b$에 대하여 $\\lim_{x \\to \\infty} \\frac{ax^{2}}{x^{2}-1}=2$, $\\lim_{x \\to 1} \\frac{a(x-1)}{x^{2}-1}=b$일 때, $a+b$의 값을 구하시오. (4점)", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴은 분모의 최고차항으로 분모, 분자를 각각 나누어 극한값을 구하고, $\\frac{0}{0}$ 꼴은 분모, 분자의 공통인수를 약분하여 극한값을 구한다.\n1st $\\lim_{x \\to \\infty} \\frac{ax^{2}}{x^{2}-1}$에서 분모의 최고차항으로 분모, 분자를 각각 나누어 극한값을 구해봐. $\\lim_{x \\to \\infty} \\frac{ax^{2}}{x^{2}-1}$에서 분모, 분자를 각각 $x^{2}$으로 나누면 $\\lim_{x \\to \\infty} \\frac{ax^{2}}{x^{2}-1} = \\lim_{x \\to \\infty} \\frac{a}{1-\\frac{1}{x^{2}}} = \\frac{a}{1-0} = 2$ ($\\lim_{x \\to \\infty} \\frac{1}{x^{2}}=0$) $\\therefore a=2$\n(주의: 이렇게 $\\frac{\\infty}{\\infty}$ 꼴은 분모, 분자를 '최고차항'으로 나눠줘야 해. $x$나 $x^{3}$ 등이 아닌 $x^{2}$으로 나눠줘야 문제가 풀려.)\n2nd $\\lim_{x \\to 1} \\frac{a(x-1)}{x^{2}-1}$에서 분모, 분자의 공통인수를 약분하여 극한값을 구해. $\\lim_{x \\to 1} \\frac{a(x-1)}{x^{2}-1}$의 분모를 인수분해하면 $\\lim_{x \\to 1} \\frac{2(x-1)}{x^{2}-1} = \\lim_{x \\to 1} \\frac{2(x-1)}{(x+1)(x-1)} = \\lim_{x \\to 1} \\frac{2}{x+1}$ ($x-1$이 분모, 분자의 공통인수이므로 약분하자.) $= \\frac{2}{1+1} = b$ $\\therefore b=1$\n$\\therefore a+b=2+1=3$", "img": "IMG_4930.jpg"}, {"id": "A125", "section": "A", "num": 125, "page": 25, "topic": "∞/∞ 꼴의 극한", "answer": "②", "rate": "82%", "problem": "$\\lim_{x \\to -\\infty} \\frac{x+1}{\\sqrt{x^{2}+x}-x}$의 값은? (2점)", "explanation": "정답 공식: $x=-t$로 치환하여 $\\frac{\\infty}{\\infty}$ 꼴로 바꾸어 극한값을 구한다.\n1st $-x=t$라 놓고 주어진 식을 $t$에 관한 식으로 바꿔 봐. $-x=t$라 하면 $x \\to -\\infty$일 때, $t \\to \\infty$이므로\n$\\lim_{x \\to -\\infty} \\frac{x+1}{\\sqrt{x^{2}+x}-x} = \\lim_{t \\to \\infty} \\frac{-t+1}{\\sqrt{t^{2}-t}+t} = \\lim_{t \\to \\infty} \\frac{-1+\\frac{1}{t}}{\\sqrt{1-\\frac{1}{t}}+1}$ (분모, 분자를 분모의 최고차항인 $t$로 각각 나눈 거야. $t$로 나눌 때 제곱근 안에선 $t^{2}$으로 나눠줘야 해.) $= \\frac{-1+0}{1+1} = -\\frac{1}{2}$", "img": "IMG_4930.jpg", "answer_value": "$-\\frac{1}{2}$"}, {"id": "A126", "section": "A", "num": 126, "page": 25, "topic": "∞/∞ 꼴의 극한", "answer": "④", "rate": "77%", "problem": "$\\lim_{x \\to \\infty} \\frac{f(x)}{x}=2$일 때, $\\lim_{x \\to \\infty} \\frac{2x^{2}+xf(x)}{3x^{2}-f(x)}$의 값은? (3점)", "explanation": "정답 공식: 조건식을 이용할 수 있도록 구하는 극한식을 변형한다.\n1st 주어진 조건을 이용하여 $\\lim_{x \\to \\infty} \\frac{2x^{2}+xf(x)}{3x^{2}-f(x)}$의 값을 구하자. $\\lim_{x \\to \\infty} \\frac{2x^{2}+xf(x)}{3x^{2}-f(x)} = \\lim_{x \\to \\infty} \\frac{2+\\frac{f(x)}{x}}{3-\\frac{f(x)}{x} \\times \\frac{1}{x}} = \\frac{2+2}{3-2 \\times 0} = \\frac{4}{3}$\n(실수 $\\alpha$, $\\beta$에 대하여 $\\lim_{x \\to a} f(x)=\\alpha$, $\\lim_{x \\to a} g(x)=\\beta$ ($g(x) \\ne 0$, $\\beta \\ne 0$)이면 $\\lim_{x \\to a} \\frac{f(x)}{g(x)} = \\frac{\\lim f(x)}{\\lim g(x)} = \\frac{\\alpha}{\\beta}$)", "img": "IMG_4930.jpg", "answer_value": "$\\frac{4}{3}$"}, {"id": "A127", "section": "A", "num": 127, "page": 25, "topic": "∞/∞ 꼴의 극한", "answer": "③", "rate": "76%", "problem": "함수 $f(x) = \\begin{cases} x^{2}-4 & (|x|<2) \\\\ -x & (|x| \\ge 2) \\end{cases}$에 대하여 $\\lim_{x \\to \\infty} f\\left(\\frac{2x+1}{x}\\right) - \\lim_{x \\to \\infty} f\\left(\\frac{1}{x}\\right)$의 값은? (3점)", "explanation": "정답 공식: $\\frac{1}{x}=t$라 하면 $x \\to \\infty$일 때 $t \\to 0+$이므로 함수 $y=f(x)$의 그래프를 그려 주어진 극한값을 계산한다.\n1st $\\frac{1}{x}=t$로 치환한 후 구하는 식을 정리해. (주의: $\\frac{1}{x}=t$로 치환해서 해결하는 것이 간단해. 이때, 함수 $y=\\frac{1}{x}$의 그래프에서 $x \\to \\infty$일 때 $\\frac{1}{x}$은 0보다 큰 값에서 0에 한없이 가까이 가니까 $x \\to \\infty$일 때, $t \\to 0$이 아니라 $t \\to 0+$야.)\n$\\lim_{x \\to \\infty} f\\left(\\frac{2x+1}{x}\\right) - \\lim_{x \\to \\infty} f\\left(\\frac{1}{x}\\right) = \\lim_{x \\to \\infty} f\\left(2+\\frac{1}{x}\\right) - \\lim_{x \\to \\infty} f\\left(\\frac{1}{x}\\right)$에서 $\\frac{1}{x}=t$라 하면 $x \\to \\infty$일 때, $t \\to 0+$이므로 ($x \\to \\infty$이면 $t$는 $t>0$이면서 0에 한없이 가까워져)\n$\\lim_{x \\to \\infty} f\\left(2+\\frac{1}{x}\\right) - \\lim_{x \\to \\infty} f\\left(\\frac{1}{x}\\right) = \\lim_{t \\to 0+} f(2+t) - \\lim_{t \\to 0+} f(t)$\n2nd 함수 $y=f(x)$의 그래프를 그려 주어진 극한값을 구하자. 따라서 함수 $y=f(x)$의 그래프는 그림과 같으므로\n$\\lim_{x \\to \\infty} f\\left(\\frac{2x+1}{x}\\right) - \\lim_{x \\to \\infty} f\\left(\\frac{1}{x}\\right) = \\lim_{t \\to 0+} f(2+t) - \\lim_{t \\to 0+} f(t) = -2-(-4) = 2$ ($t \\to 0+$일 때, $2+t \\to 2+$이므로 $\\lim_{t \\to 0+} f(2+t)=-2$야.)", "img": "IMG_4930.jpg", "answer_value": "2"}, {"id": "A128", "section": "A", "num": 128, "page": 26, "topic": "∞−∞ 꼴의 극한", "answer": "③", "rate": "91%", "problem": "$\\lim_{x \\to \\infty}\\left(\\sqrt{x^{2}+3x-6}-x\\right)$의 값은? (2점)", "explanation": "정답 공식: $\\infty-\\infty$ 꼴의 극한에서 근호를 포함한 경우 근호를 포함한 쪽을 유리화한다.\n1st 주어진 극한값을 구해. $\\lim_{x \\to \\infty}\\left(\\sqrt{x^{2}+3x-6}-x\\right) = \\lim_{x \\to \\infty} \\frac{\\left(\\sqrt{x^{2}+3x-6}-x\\right)\\left(\\sqrt{x^{2}+3x-6}+x\\right)}{\\sqrt{x^{2}+3x-6}+x} = \\lim_{x \\to \\infty} \\frac{3x-6}{\\sqrt{x^{2}+3x-6}+x}$ ($\\frac{\\infty}{\\infty}$ 꼴의 극한으로 바뀌었으므로 분모, 분자를 분모의 최고차항으로 각각 나누어야 해.) $= \\lim_{x \\to \\infty} \\frac{3-\\frac{6}{x}}{\\sqrt{1+\\frac{3}{x}-\\frac{6}{x^{2}}}+1} = \\frac{3-0}{\\sqrt{1+0-0}+1} = \\frac{3}{2}$\n[개념·공식] $\\infty-\\infty$ 꼴의 극한값: ① 다항식은 최고차항으로 묶어 극한값을 계산한다. ② 무리식은 근호를 포함한 쪽을 유리화하여 $\\frac{\\infty}{\\infty}$ 꼴로 변형하여 극한값을 계산한다.", "img": "IMG_4931.jpg", "answer_value": "$\\frac{3}{2}$"}, {"id": "A129", "section": "A", "num": 129, "page": 26, "topic": "∞−∞ 꼴의 극한", "answer": "③", "rate": "91%", "problem": "$\\lim_{x \\to \\infty}\\left(\\sqrt{x^{2}+3x+3}-\\sqrt{x^{2}-3x-3}\\right)$의 값은? (2점)", "explanation": "정답 공식: $\\infty-\\infty$ 꼴의 극한에서 근호를 포함한 경우 근호를 포함한 쪽을 유리화한다.\n1st 주어진 극한값을 구해. $\\lim_{x \\to \\infty}\\left(\\sqrt{x^{2}+3x+3}-\\sqrt{x^{2}-3x-3}\\right) = \\lim_{x \\to \\infty} \\frac{\\left(\\sqrt{x^{2}+3x+3}-\\sqrt{x^{2}-3x-3}\\right)\\left(\\sqrt{x^{2}+3x+3}+\\sqrt{x^{2}-3x-3}\\right)}{\\sqrt{x^{2}+3x+3}+\\sqrt{x^{2}-3x-3}} = \\lim_{x \\to \\infty} \\frac{6x+6}{\\sqrt{x^{2}+3x+3}+\\sqrt{x^{2}-3x-3}} = \\lim_{x \\to \\infty} \\frac{6+\\frac{6}{x}}{\\sqrt{1+\\frac{3}{x}+\\frac{3}{x^{2}}}+\\sqrt{1-\\frac{3}{x}-\\frac{3}{x^{2}}}} = \\frac{6+0}{\\sqrt{1+0+0}+\\sqrt{1-0-0}} = 3$ ($\\frac{\\infty}{\\infty}$ 꼴의 극한이니까 분모, 분자를 분모의 최고차항으로 각각 나눈 거야.)", "img": "IMG_4931.jpg", "answer_value": "3"}, {"id": "A130", "section": "A", "num": 130, "page": 26, "topic": "∞−∞ 꼴의 극한", "answer": "①", "rate": "90%", "problem": "$\\lim_{x \\to \\infty} \\frac{1}{x-\\sqrt{x^{2}-9x+3}}$의 값은? (2점)", "explanation": "정답 공식: $\\infty-\\infty$ 꼴의 극한에서 근호를 포함한 경우 근호를 포함한 쪽을 유리화한다.\n1st 주어진 극한값을 구해. $\\lim_{x \\to \\infty} \\frac{1}{x-\\sqrt{x^{2}-9x+3}} = \\lim_{x \\to \\infty} \\frac{x+\\sqrt{x^{2}-9x+3}}{\\left(x-\\sqrt{x^{2}-9x+3}\\right)\\left(x+\\sqrt{x^{2}-9x+3}\\right)} = \\lim_{x \\to \\infty} \\frac{x+\\sqrt{x^{2}-9x+3}}{9x-3}$ (분모의 최고차항인 $x$로 분모, 분자를 각각 나눠.) $= \\lim_{x \\to \\infty} \\frac{1+\\sqrt{1-\\frac{9}{x}+\\frac{3}{x^{2}}}}{9-\\frac{3}{x}} = \\frac{1+1}{9} = \\frac{2}{9}$ ($\\lim_{x \\to \\infty} \\frac{9}{x} = \\lim_{x \\to \\infty} \\frac{3}{x^{2}} = \\lim_{x \\to \\infty} \\frac{3}{x} = 0$)", "img": "IMG_4931.jpg", "answer_value": "$\\frac{2}{9}$"}, {"id": "A131", "section": "A", "num": 131, "page": 26, "topic": "∞−∞ 꼴의 극한", "answer": "④", "rate": "76%", "problem": "함수 $f(x)=a(x-1)^{2}+1$에 대하여 $\\lim_{x \\to \\infty}\\left\\{\\sqrt{f(-x)}-\\sqrt{f(x)}\\right\\}=6$일 때, 양수 $a$의 값은? (4점)", "explanation": "정답 공식: $\\infty-\\infty$ 꼴의 극한에서 근호를 포함한 경우 근호를 포함한 쪽을 유리화한다.\n1st $f(x)$를 주어진 식에 대입하여 $a$의 값을 구하자. $\\lim_{x \\to \\infty}\\left\\{\\sqrt{f(-x)}-\\sqrt{f(x)}\\right\\} = \\lim_{x \\to \\infty}\\left\\{\\sqrt{a(-x-1)^{2}+1} - \\sqrt{a(x-1)^{2}+1}\\right\\} = \\lim_{x \\to \\infty} \\frac{\\left\\{\\sqrt{a(-x-1)^{2}+1}-\\sqrt{a(x-1)^{2}+1}\\right\\}\\left\\{\\sqrt{a(-x-1)^{2}+1}+\\sqrt{a(x-1)^{2}+1}\\right\\}}{\\sqrt{a(-x-1)^{2}+1}+\\sqrt{a(x-1)^{2}+1}} = \\lim_{x \\to \\infty} \\frac{4ax}{\\sqrt{a(-x-1)^{2}+1}+\\sqrt{a(x-1)^{2}+1}}$ (분모의 최고차항인 $x$로 분모, 분자를 각각 나눠.) $= \\lim_{x \\to \\infty} \\frac{4a}{\\sqrt{a\\left(-1-\\frac{1}{x}\\right)^{2}+\\frac{1}{x^{2}}}+\\sqrt{a\\left(1-\\frac{1}{x}\\right)^{2}+\\frac{1}{x^{2}}}} = \\frac{4a}{2\\sqrt{a}} = 2\\sqrt{a} = 6$ ($\\lim_{x \\to \\infty} \\frac{1}{x} = \\lim_{x \\to \\infty} \\frac{1}{x^{2}} = 0$)\n$\\sqrt{a}=3$ $\\therefore a=9$\n[개념·공식] $\\infty-\\infty$ 꼴의 극한값: ① 다항식은 최고차항으로 묶어 극한값을 계산한다. ② 무리식은 근호를 포함한 쪽을 유리화하여 $\\frac{\\infty}{\\infty}$ 꼴로 변형하여 극한값을 계산한다.", "img": "IMG_4931.jpg", "answer_value": "9"}, {"id": "A132", "section": "A", "num": 132, "page": 27, "topic": "∞×0 꼴의 극한", "answer": "②", "rate": "85%", "problem": "$\\lim_{x \\to 1} \\frac{1}{x-1}\\left(\\frac{1}{x-2}+1\\right)$의 값은? (2점)", "explanation": "정답 공식: $\\infty \\times 0$ 꼴의 극한에서 분모 또는 분자에 다항식이 있는 경우 통분 또는 인수분해한다.\n1st 주어진 극한값을 구하자. $\\lim_{x \\to 1} \\frac{1}{x-1}\\left(\\frac{1}{x-2}+1\\right) = \\lim_{x \\to 1}\\left(\\frac{1}{x-1} \\times \\frac{1+x-2}{x-2}\\right) = \\lim_{x \\to 1} \\frac{1}{x-2} = -1$ ($\\frac{1}{x-2}$에 $x=1$을 대입하여 구할 수 있어.)", "img": "IMG_4932.jpg", "answer_value": "$-1$"}, {"id": "A133", "section": "A", "num": 133, "page": 27, "topic": "∞×0 꼴의 극한", "answer": "②", "rate": "85%", "problem": "$\\lim_{x \\to 0} \\frac{1}{x}\\left\\{1-\\frac{1}{(x+1)^{2}}\\right\\}$의 값은? (2점)", "explanation": "정답 공식: $\\infty \\times 0$ 꼴의 극한에서 분모 또는 분자에 다항식이 있는 경우 통분 또는 인수분해한다.\n1st 주어진 극한값을 구하자. $\\lim_{x \\to 0} \\frac{1}{x}\\left\\{1-\\frac{1}{(x+1)^{2}}\\right\\} = \\lim_{x \\to 0}\\left\\{\\frac{1}{x} \\times \\frac{(x+1)^{2}-1}{(x+1)^{2}}\\right\\} = \\lim_{x \\to 0}\\left\\{\\frac{1}{x} \\times \\frac{x^{2}+2x}{(x+1)^{2}}\\right\\} = \\lim_{x \\to 0} \\frac{x+2}{(x+1)^{2}} = \\frac{0+2}{(0+1)^{2}} = 2$ ($\\frac{x+2}{(x+1)^{2}}$에 $x=0$을 대입하여 구할 수 있어.)", "img": "IMG_4932.jpg", "answer_value": "2"}, {"id": "A134", "section": "A", "num": 134, "page": 27, "topic": "∞×0 꼴의 극한", "answer": "②", "rate": "85%", "problem": "$\\lim_{x \\to \\infty} x\\left(1-\\frac{\\sqrt{x+4}}{\\sqrt{x}}\\right)$의 값은? (2점)", "explanation": "정답 공식: $\\infty \\times 0$ 꼴의 극한에서 분모 또는 분자에 다항식이 있는 경우 통분 또는 인수분해한다.\n1st 주어진 극한값을 구하자. $\\lim_{x \\to \\infty} x\\left(1-\\frac{\\sqrt{x+4}}{\\sqrt{x}}\\right) = \\lim_{x \\to \\infty}\\left(x \\times \\frac{\\sqrt{x}-\\sqrt{x+4}}{\\sqrt{x}}\\right) = \\lim_{x \\to \\infty}\\left(x-\\sqrt{x^{2}+4x}\\right)$ ($\\infty-\\infty$ 꼴이므로 유리화를 해봐.) $= \\lim_{x \\to \\infty} \\frac{\\left(x-\\sqrt{x^{2}+4x}\\right)\\left(x+\\sqrt{x^{2}+4x}\\right)}{x+\\sqrt{x^{2}+4x}} = \\lim_{x \\to \\infty} \\frac{-4x}{x+\\sqrt{x^{2}+4x}} = \\lim_{x \\to \\infty} \\frac{-4}{1+\\sqrt{1+\\frac{4}{x}}}$ (분모의 최고차항인 $x$로 분모, 분자를 각각 나눠.) $= \\frac{-4}{1+\\sqrt{1+0}} = -2$ ($\\lim_{x \\to \\infty} \\frac{4}{x}=0$)\n(함정: $x$를 먼저 전개하지 않고 유리화를 시도하면 계산하기 힘들어지니 무턱대고 유리화해보지 말 것!)", "img": "IMG_4932.jpg", "answer_value": "$-2$"}, {"id": "A135", "section": "A", "num": 135, "page": 27, "topic": "인수분해를 이용한 미정계수의 결정", "answer": "①", "rate": "84%", "problem": "두 상수 $a$, $b$에 대하여 $\\lim_{x \\to 1} \\frac{4x-a}{x-1}=b$일 때, $a+b$의 값은? (3점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st $x \\to 1$일 때, (분모)$\\to 0$이고 극한값이 존재하므로 (분자)$\\to 0$이어야 하지? $\\lim_{x \\to 1} \\frac{4x-a}{x-1}=b$에서 $x \\to 1$일 때, (분모)$\\to 0$이고 극한값이 존재하므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 1}(4x-a)=0$이므로 $4-a=0$ $\\therefore a=4$\n2nd $a$의 값을 주어진 식에 대입하면 $b$의 값을 구할 수 있어. 따라서 $a=4$를 주어진 식에 대입하면 $b = \\lim_{x \\to 1} \\frac{4x-4}{x-1} = \\lim_{x \\to 1} \\frac{4(x-1)}{x-1} = 4$ ($x-1$이 분자, 분모의 공통인수이므로 약분해.)\n$\\therefore a+b=4+4=8$\n[개념·공식] 미정계수의 결정: ① $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ (단, $\\alpha$는 상수)일 때 $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$ ② $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ (단, $\\alpha \\ne 0$인 상수)일 때 $\\lim_{x \\to a} f(x)=0$이면 $\\lim_{x \\to a} g(x)=0$", "img": "IMG_4932.jpg", "answer_value": "8"}, {"id": "A136", "section": "A", "num": 136, "page": 27, "topic": "인수분해를 이용한 미정계수의 결정", "answer": "②", "rate": "83%", "problem": "$\\lim_{x \\to 3} \\frac{2x^{2}+ax+b}{x^{2}-9}=3$일 때, $a+b$의 값은? (단, $a$와 $b$는 상수이다.) (3점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st 분모가 0으로 수렴함을 이용하여 $a$, $b$ 사이의 관계식을 구해. $\\lim_{x \\to 3} \\frac{2x^{2}+ax+b}{x^{2}-9}=3$에서 $x \\to 3$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 3}(2x^{2}+ax+b)=0$에서 $18+3a+b=0$ $\\therefore b=-3a-18=-3(a+6)$ … ㉠\n2nd $a$, $b$의 값을 각각 구하여 $a+b$의 값을 계산해. ㉠을 주어진 식에 대입하면 $\\lim_{x \\to 3} \\frac{2x^{2}+ax+b}{x^{2}-9}=3$에서 $\\lim_{x \\to 3} \\frac{2x^{2}+ax-3(a+6)}{x^{2}-9}=3$, $\\lim_{x \\to 3} \\frac{(x-3)(2x+a+6)}{(x-3)(x+3)}=3$ ($\\frac{0}{0}$ 꼴의 극한이고 $x-3$이 분모, 분자의 공통인수이므로 약분하자.)\n$\\lim_{x \\to 3} \\frac{2x+a+6}{x+3}=3$, $\\frac{a+12}{6}=3$, $a+12=18$\n따라서 $a=6$이므로 ㉠에 의하여 $b=-3 \\times 12=-36$ $\\therefore a+b=6+(-36)=-30$", "img": "IMG_4932.jpg", "answer_value": "$-30$"}, {"id": "A137", "section": "A", "num": 137, "page": 28, "topic": "인수분해를 이용한 미정계수의 결정", "answer": "③", "rate": "88%", "problem": "두 상수 $a$, $b$에 대하여 $\\lim_{x \\to 1} \\frac{x^{2}+ax}{x-1}=b$일 때, $a+b$의 값은? (3점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st $x \\to 1$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이지? $x \\to 1$일 때, 극한값이 존재하고 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 1}(x^{2}+ax)=1+a=0$ $\\therefore a=-1$\n2nd $a$의 값을 대입하고 분자를 인수분해하자. $\\lim_{x \\to 1} \\frac{x^{2}-x}{x-1} = \\lim_{x \\to 1} \\frac{x(x-1)}{x-1} = \\lim_{x \\to 1} x = 1$ $\\therefore b=1$ ($x-1$이 분자, 분모의 공통인수이므로 약분)\n$\\therefore a+b=(-1)+1=0$", "img": "IMG_4933.jpg", "answer_value": "0"}, {"id": "A138", "section": "A", "num": 138, "page": 28, "topic": "인수분해를 이용한 미정계수의 결정", "answer": "①", "rate": "86%", "problem": "두 상수 $a$, $b$에 대하여 $\\lim_{x \\to 3} \\frac{x^{2}+ax+b}{x-3}=14$일 때, $a+b$의 값은? (2점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st 극한값이 존재할 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 해. $\\lim_{x \\to 3} \\frac{x^{2}+ax+b}{x-3}=14$에서 $x \\to 3$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이다. 즉, $\\lim_{x \\to 3}(x^{2}+ax+b)=0$에서 $9+3a+b=0$이므로 $b=-3a-9$ … ㉠\n2nd 분자를 인수분해한 후에 극한값을 계산해. ㉠을 주어진 식에 대입하여 공통인수를 정리하면 $\\lim_{x \\to 3} \\frac{x^{2}+ax-3(a+3)}{x-3} = \\lim_{x \\to 3} \\frac{(x-3)(x+a+3)}{x-3}$ ($x-3$이 분자, 분모의 공통인수이므로 약분해.) $= \\lim_{x \\to 3}(x+a+3) = 6+a = 14$\n따라서 $a=8$, $b=-33$ ($\\because$ ㉠)이므로 $a+b=-25$", "img": "IMG_4933.jpg", "answer_value": "$-25$"}, {"id": "A139", "section": "A", "num": 139, "page": 28, "topic": "인수분해를 이용한 미정계수의 결정", "answer": "④", "rate": "84%", "problem": "$\\lim_{x \\to 1} \\frac{x^{2}+ax-b}{x^{3}-1}=3$이 성립하도록 상수 $a$, $b$의 값을 정할 때, $a+b$의 값은? (2점)", "explanation": "정답 공식: 극한값이 존재하고 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다.\n1st 주어진 식의 극한값이 존재하니까 $\\frac{0}{0}$ 꼴이 되어야 해. $\\lim_{x \\to 1} \\frac{x^{2}+ax-b}{x^{3}-1}=3$에서 $x \\to 1$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이 되어야 한다. 즉, $\\lim_{x \\to 1}(x^{2}+ax-b)=0$에서 $1+a-b=0$ $\\therefore b=a+1$ … ㉠\n2nd 분자, 분모를 각각 인수분해한 후 공통인수를 약분해 봐. ㉠을 주어진 식에 대입하여 정리하면 $\\lim_{x \\to 1} \\frac{x^{2}+ax-(a+1)}{(x-1)(x^{2}+x+1)} = \\lim_{x \\to 1} \\frac{(x-1)(x+a+1)}{(x-1)(x^{2}+x+1)}$ ($a^{3}-b^{3}=(a-b)(a^{2}+ab+b^{2})$; $x-1$이 분자, 분모의 공통인수이므로 약분해.) $= \\lim_{x \\to 1} \\frac{x+a+1}{x^{2}+x+1} = \\frac{a+2}{3} = 3$\n$\\therefore a=7$, ㉠에서 $b=8$ $\\therefore a+b=7+8=15$", "img": "IMG_4933.jpg", "answer_value": "15"}, {"id": "A140", "section": "A", "num": 140, "page": 28, "topic": "인수분해를 이용한 미정계수의 결정", "answer": "①", "rate": "84%", "problem": "두 상수 $a$, $b$가 $\\lim_{x \\to 2} \\frac{x^{2}-(a+2)x+2a}{x^{2}-b}=3$을 만족시킬 때, $a+b$의 값은? (2점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st $x \\to 2$일 때 (분자)$\\to 0$이네? 그럼, 분모는? $\\lim_{x \\to 2} \\frac{x^{2}-(a+2)x+2a}{x^{2}-b}=3$ … ㉠에서 $\\lim_{x \\to 2}\\left\\{x^{2}-(a+2)x+2a\\right\\}=4-2(a+2)+2a=0$이므로 $\\lim_{x \\to 2}(x^{2}-b)=4-b=0$ $\\therefore b=4$ (분자가 0으로 가고 0이 아닌 극한값이 존재하므로 분모도 0으로 가야 해.)\n2nd 구한 $b$의 값을 주어진 식에 대입해서 $a$도 구해. $b=4$를 ㉠에 대입하면 $\\lim_{x \\to 2} \\frac{x^{2}-(a+2)x+2a}{x^{2}-4} = \\lim_{x \\to 2} \\frac{(x-2)(x-a)}{(x-2)(x+2)}$ ($a^{2}-b^{2}=(a+b)(a-b)$) $= \\lim_{x \\to 2} \\frac{x-a}{x+2} = \\frac{2-a}{4} = 3$\n$2-a=12$ $\\therefore a=-10$ $\\therefore a+b=-10+4=-6$\n[개념·공식] 미정계수의 결정: ① $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ (단, $\\alpha$는 상수)일 때 $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$ ② $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ (단, $\\alpha \\ne 0$인 상수)일 때 $\\lim_{x \\to a} f(x)=0$이면 $\\lim_{x \\to a} g(x)=0$", "img": "IMG_4933.jpg", "answer_value": "$-6$"}, {"id": "A141", "section": "A", "num": 141, "page": 29, "topic": "인수분해를 이용한 미정계수의 결정", "answer": "④", "rate": "60%", "problem": "최고차항의 계수가 1인 이차함수 $f(x)$가 $\\lim_{x \\to a} \\frac{f(x)-(x-a)}{f(x)+(x-a)} = \\frac{3}{5}$를 만족시킨다. 방정식 $f(x)=0$의 두 근을 $\\alpha$, $\\beta$라 할 때, $|\\alpha-\\beta|$의 값은? (단, $a$는 상수이다.) (4점)", "explanation": "정답 공식: $\\lim_{x \\to a} f(x)=f(a)=0$인 경우와 $\\lim_{x \\to a} f(x)=f(a) \\ne 0$인 경우로 나누어 $f(a)$의 값을 추론한다.\n1st 주어진 극한값이 $\\frac{3}{5}$임을 이용하여 다항식 $f(x)$의 인수를 확인해 보자. 0이 아닌 상수 $k$에 대하여 $\\lim_{x \\to a} f(x)=k$라 하면 (이차함수 $f(x)$는 임의의 실수 $a$에 대하여 $\\lim_{x \\to a} f(x)$의 값이 항상 존재해.)\n$\\lim_{x \\to a} \\frac{f(x)-(x-a)}{f(x)+(x-a)} = \\frac{\\lim f(x) - \\lim (x-a)}{\\lim f(x) + \\lim (x-a)} = \\frac{k-(a-a)}{k+(a-a)} = 1 \\ne \\frac{3}{5}$ ($\\lim f(x)=\\alpha$, $\\lim g(x)=\\beta$일 때 $\\lim\\left\\{f(x) \\pm g(x)\\right\\}=\\alpha \\pm \\beta$(복호동순), $\\lim \\frac{f(x)}{g(x)}=\\frac{\\alpha}{\\beta}$ (단, $g(x) \\ne 0$, $\\beta \\ne 0$))\n따라서 $\\lim_{x \\to a} f(x)=0$이어야 하므로 $f(a)=0$이다. 즉, 방정식 $f(x)=0$의 한 실근이 $x=a$이므로 $\\alpha=a$라 하면 $f(x)=(x-a)(x-\\beta)$ … ㉠ 라 놓을 수 있다. (방정식 $f(x)=0$의 두 근이 $\\alpha$, $\\beta$이므로 $f(x)=(x-\\alpha)(x-\\beta)$에서 $f(x)=(x-a)(x-\\beta)$)\n2nd $|\\alpha-\\beta|$의 값을 구하자. ㉠을 주어진 식에 대입하면 (주의: $f(x)$는 최고차항의 계수가 1인 이차함수면서 주어진 식을 $\\frac{0}{0}$ 꼴이 되게 해야 해.)\n$\\lim_{x \\to a} \\frac{f(x)-(x-a)}{f(x)+(x-a)} = \\lim_{x \\to a} \\frac{(x-a)(x-\\beta)-(x-a)}{(x-a)(x-\\beta)+(x-a)} = \\lim_{x \\to a} \\frac{(x-a)(x-\\beta-1)}{(x-a)(x-\\beta+1)} = \\lim_{x \\to a} \\frac{x-\\beta-1}{x-\\beta+1} = \\frac{\\lim(x-\\beta-1)}{\\lim(x-\\beta+1)} = \\frac{a-\\beta-1}{a-\\beta+1} = \\frac{3}{5}$\n$5(a-\\beta)-5=3(a-\\beta)+3$, $2(a-\\beta)=8$, $a-\\beta=4$ $\\therefore |\\alpha-\\beta|=4$\n[개념·공식] 미정계수의 결정: ① $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ (단, $\\alpha$는 상수)일 때 $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$ ② $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ (단, $\\alpha \\ne 0$인 상수)일 때 $\\lim_{x \\to a} f(x)=0$이면 $\\lim_{x \\to a} g(x)=0$", "img": "IMG_4934.jpg", "answer_value": "4"}, {"id": "A142", "section": "A", "num": 142, "page": 29, "topic": "인수분해를 이용한 미정계수의 결정", "answer": "$15$", "rate": "87%", "problem": "두 상수 $a$, $b$에 대하여 $\\lim_{x \\to 9} \\frac{x-a}{\\sqrt{x}-3}=b$일 때, $a+b$의 값을 구하시오. (3점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st 극한값이 존재하도록 $a$의 값부터 결정해. $\\lim_{x \\to 9} \\frac{x-a}{\\sqrt{x}-3}=b$에서 $\\lim_{x \\to 9}(\\sqrt{x}-3)=0$이므로 $\\lim_{x \\to 9}(x-a)=0$이어야 한다. 즉, $9-a=0$이므로 $a=9$이다.\n2nd $a$의 값을 주어진 극한식에 대입하여 $b$의 값을 구해. $\\therefore \\lim_{x \\to 9} \\frac{x-a}{\\sqrt{x}-3} = \\lim_{x \\to 9} \\frac{x-9}{\\sqrt{x}-3} = \\lim_{x \\to 9} \\frac{(x-9)(\\sqrt{x}+3)}{(\\sqrt{x}-3)(\\sqrt{x}+3)} = \\lim_{x \\to 9} \\frac{(x-9)(\\sqrt{x}+3)}{x-9} = \\lim_{x \\to 9}(\\sqrt{x}+3) = 6 = b$ (근호가 포함된 $\\frac{0}{0}$ 꼴의 극한은 근호가 있는 쪽을 유리화하여 계산해.)\n따라서 $a=9$, $b=6$이므로 $a+b=15$\n[다른 풀이: $x-9$를 인수분해하여 해결하기] $x-9$를 인수분해하여 해결하는 게 더 편리해. $\\lim_{x \\to 9} \\frac{x-9}{\\sqrt{x}-3} = \\lim_{x \\to 9} \\frac{(\\sqrt{x}-3)(\\sqrt{x}+3)}{\\sqrt{x}-3} = \\lim_{x \\to 9}(\\sqrt{x}+3) = 6 = b$ (이하 동일)", "img": "IMG_4934.jpg"}, {"id": "A143", "section": "A", "num": 143, "page": 29, "topic": "유리화를 이용한 미정계수의 결정", "answer": "②", "rate": "81%", "problem": "두 상수 $a$, $b$에 대하여 $\\lim_{x \\to 1} \\frac{\\sqrt{x+a}-2}{x-1}=b$일 때, $a+4b$의 값은? (3점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st 분모가 0으로 수렴함을 이용하여 $a$의 값을 구해. $\\lim_{x \\to 1} \\frac{\\sqrt{x+a}-2}{x-1}=b$에서 $x \\to 1$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 1}(\\sqrt{x+a}-2)=0$에서 $\\sqrt{1+a}-2=0$, $\\sqrt{1+a}=2$, $1+a=4$ $\\therefore a=3$ ($\\lim_{x \\to a} \\frac{f(x)}{g(x)}=c$ ($c$는 실수)이고 $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이야.)\n2nd $b$의 값을 구하고 $a+4b$의 값을 계산해. $a=3$을 주어진 극한식에 대입하면 $b = \\lim_{x \\to 1} \\frac{\\sqrt{x+3}-2}{x-1} = \\lim_{x \\to 1} \\frac{(\\sqrt{x+3}-2)(\\sqrt{x+3}+2)}{(x-1)(\\sqrt{x+3}+2)}$ (유리화를 이용하여 극한값을 구해야겠지?) $= \\lim_{x \\to 1} \\frac{x-1}{(x-1)(\\sqrt{x+3}+2)} = \\lim_{x \\to 1} \\frac{1}{\\sqrt{x+3}+2} = \\frac{1}{\\sqrt{1+3}+2} = \\frac{1}{4}$\n$\\therefore a+4b=3+4 \\times \\frac{1}{4}=4$", "img": "IMG_4934.jpg", "answer_value": "4"}, {"id": "A144", "section": "A", "num": 144, "page": 30, "topic": "유리화를 이용한 미정계수의 결정", "answer": "$21$", "rate": "85%", "problem": "두 상수 $a$, $b$에 대하여 $\\lim_{x \\to 2} \\frac{\\sqrt{x+a}-2}{x-2}=b$일 때, $10a+4b$의 값을 구하시오. (3점)", "explanation": "정답 공식: 극한값이 존재하고 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다.\n1st 분수식의 극한값이 존재할 때, (분모)$\\to 0$이면 (분자)$\\to 0$임을 이용해서 $a$의 값부터 구하자. $\\lim_{x \\to 2} \\frac{\\sqrt{x+a}-2}{x-2}=b$에서 $x \\to 2$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 2}(\\sqrt{x+a}-2)=\\sqrt{2+a}-2=0$에서 $\\sqrt{2+a}=2$, $2+a=4$ $\\therefore a=2$\n2nd $a=2$를 주어진 식에 대입하여 $b$의 값을 구하자. $\\lim_{x \\to 2} \\frac{\\sqrt{x+2}-2}{x-2} = \\lim_{x \\to 2} \\frac{(\\sqrt{x+2}-2)(\\sqrt{x+2}+2)}{(x-2)(\\sqrt{x+2}+2)}$ ($\\frac{0}{0}$ 꼴이고 무리식이 포함되어 있으니까 무리식을 유리화해야 해.) $= \\lim_{x \\to 2} \\frac{x-2}{(x-2)(\\sqrt{x+2}+2)}$ ($(\\sqrt{x+2})^{2}-2^{2}=(x+2)-4=x-2$) $= \\lim_{x \\to 2} \\frac{1}{\\sqrt{x+2}+2} = \\frac{1}{4} = b$\n$\\therefore 10a+4b=10 \\times 2+4 \\times \\frac{1}{4}=21$\n[개념·공식] 분모의 유리화: 분모에 근호가 있을 때 분모와 분자에 0이 아닌 같은 수를 곱하여 분모를 근호가 없는 형태로 변형하는 것을 분모의 유리화라 한다. ① $\\frac{b}{\\sqrt{a}} = \\frac{b \\times \\sqrt{a}}{\\sqrt{a} \\times \\sqrt{a}} = \\frac{b\\sqrt{a}}{a}$ ② $\\frac{c}{a\\sqrt{b}} = \\frac{c \\times \\sqrt{b}}{a\\sqrt{b} \\times \\sqrt{b}} = \\frac{c\\sqrt{b}}{ab}$", "img": "IMG_4935.jpg"}, {"id": "A145", "section": "A", "num": 145, "page": 30, "topic": "유리화를 이용한 미정계수의 결정", "answer": "①", "rate": "86%", "problem": "두 상수 $a$, $b$에 대하여 $\\lim_{x \\to 3} \\frac{\\sqrt{x+a}-b}{x-3}=\\frac{1}{4}$일 때, $a+b$의 값은? (2점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st $x \\to 3$일 때 (분모)$\\to 0$이면 (분자)$\\to 0$임을 이용해. $\\lim_{x \\to 3} \\frac{\\sqrt{x+a}-b}{x-3}=\\frac{1}{4}$에서 $x \\to 3$일 때 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 3}(\\sqrt{x+a}-b)=\\sqrt{3+a}-b=0$이므로 $b=\\sqrt{3+a}$ … ㉠\n$\\therefore \\lim_{x \\to 3} \\frac{\\sqrt{x+a}-b}{x-3} = \\lim_{x \\to 3} \\frac{\\sqrt{x+a}-\\sqrt{3+a}}{x-3} = \\lim_{x \\to 3}\\left\\{\\frac{\\sqrt{x+a}-\\sqrt{3+a}}{x-3} \\times \\frac{\\sqrt{x+a}+\\sqrt{3+a}}{\\sqrt{x+a}+\\sqrt{3+a}}\\right\\} = \\lim_{x \\to 3} \\frac{x+a-3-a}{(x-3)(\\sqrt{x+a}+\\sqrt{3+a})}$ ($(\\sqrt{x+a})^{2}-(\\sqrt{3+a})^{2}=(x+a)-(3+a)=x-3$) $= \\lim_{x \\to 3} \\frac{1}{\\sqrt{x+a}+\\sqrt{3+a}}$ ($x-3$이 분자, 분모의 공통인수이므로 약분해.) $= \\frac{1}{2\\sqrt{3+a}} = \\frac{1}{4}$\n$2\\sqrt{3+a}=4$에서 $a=1$. 따라서 $a=1$, $b=2$ ($\\because$ ㉠)이므로 $a+b=1+2=3$", "img": "IMG_4935.jpg", "answer_value": "3"}, {"id": "A146", "section": "A", "num": 146, "page": 30, "topic": "유리화를 이용한 미정계수의 결정", "answer": "⑤", "rate": "83%", "problem": "$\\lim_{x \\to -3} \\frac{\\sqrt{x^{2}-x-3}+ax}{x+3}=b$가 성립하도록 상수 $a$, $b$의 값을 정할 때, $a+b$의 값은? (2점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st (분모)$\\to 0$이면 (분자)$\\to 0$임을 적용해서 $a$부터 구해. $x \\to -3$일 때 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to -3}\\left(\\sqrt{x^{2}-x-3}+ax\\right)=\\sqrt{(-3)^{2}-(-3)-3}-3a=3-3a=0$ $\\therefore a=1$\n2nd 분자에 $\\sqrt{\\phantom{x}}$가 있으므로 유리화하자. $\\lim_{x \\to -3} \\frac{\\sqrt{x^{2}-x-3}+x}{x+3} = \\lim_{x \\to -3} \\frac{\\left(\\sqrt{x^{2}-x-3}+x\\right)\\left(\\sqrt{x^{2}-x-3}-x\\right)}{(x+3)\\left(\\sqrt{x^{2}-x-3}-x\\right)} = \\lim_{x \\to -3} \\frac{-(x+3)}{(x+3)\\left(\\sqrt{x^{2}-x-3}-x\\right)}$ ($\\left(\\sqrt{x^{2}-x-3}\\right)^{2}-x^{2}=(x^{2}-x-3)-x^{2}=-(x+3)$) $= \\lim_{x \\to -3} \\frac{-1}{\\sqrt{x^{2}-x-3}-x} = \\frac{-1}{\\sqrt{(-3)^{2}-(-3)-3}-(-3)} = -\\frac{1}{6} = b$\n$\\therefore a+b=\\frac{5}{6}$", "img": "IMG_4935.jpg", "answer_value": "$\\frac{5}{6}$"}, {"id": "A147", "section": "A", "num": 147, "page": 30, "topic": "유리화를 이용한 미정계수의 결정", "answer": "③", "rate": "85%", "problem": "두 상수 $a$, $b$에 대하여 $\\lim_{x \\to 1} \\frac{ax+b}{\\sqrt{x+1}-\\sqrt{2}}=2\\sqrt{2}$일 때, $ab$의 값은? (2점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st 함수의 극한에서 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 해. $\\lim_{x \\to 1} \\frac{ax+b}{\\sqrt{x+1}-\\sqrt{2}}=2\\sqrt{2}$에서 $\\lim_{x \\to 1}(\\sqrt{x+1}-\\sqrt{2})=0$이므로 $\\lim_{x \\to 1}(ax+b)=0$이어야 한다. 즉, $a+b=0$이므로 $b=-a$ … ㉠\n㉠을 원래의 식에 대입하면 $\\lim_{x \\to 1} \\frac{a(x-1)}{\\sqrt{x+1}-\\sqrt{2}}=2\\sqrt{2}$\n2nd 분모에 $\\sqrt{\\phantom{x}}$가 있으니까 유리화하자. $\\lim_{x \\to 1} \\frac{a(x-1)(\\sqrt{x+1}+\\sqrt{2})}{(\\sqrt{x+1}-\\sqrt{2})(\\sqrt{x+1}+\\sqrt{2})} = \\lim_{x \\to 1} \\frac{a(x-1)(\\sqrt{x+1}+\\sqrt{2})}{x+1-2}$ ($(\\sqrt{x+1})^{2}-(\\sqrt{2})^{2}=(x+1)-2=x-1$) $= \\lim_{x \\to 1} \\frac{a(x-1)(\\sqrt{x+1}+\\sqrt{2})}{x-1}$ ($x-1$이 분자, 분모의 공통인수이므로 약분해.) $= \\lim_{x \\to 1} a(\\sqrt{x+1}+\\sqrt{2}) = 2\\sqrt{2}a = 2\\sqrt{2}$\n따라서 $a=1$, $b=-1$ ($\\because$ ㉠)이므로 $ab=-1$", "img": "IMG_4935.jpg", "answer_value": "$-1$"}, {"id": "A148", "section": "A", "num": 148, "page": 31, "topic": "유리화를 이용한 미정계수의 결정", "answer": "④", "rate": "83%", "problem": "두 상수 $a$, $b$에 대하여 $\\lim_{x \\to 1} \\frac{\\sqrt{2x+a}-\\sqrt{x+3}}{x^{2}-1}=b$일 때, $ab$의 값은? (2점)", "explanation": "정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ ($\\alpha$는 상수)이고 $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이야. $\\lim_{x \\to 1} \\frac{\\sqrt{2x+a}-\\sqrt{x+3}}{x^{2}-1}=b$에서 $\\lim_{x \\to 1}(x^{2}-1)=0$이므로 $\\lim_{x \\to 1}(\\sqrt{2x+a}-\\sqrt{x+3})=0$에서 $\\sqrt{2+a}-2=0$ $\\therefore a=2$\n2nd 구한 값을 대입하여 $b$를 구하자. $b = \\lim_{x \\to 1} \\frac{\\sqrt{2x+2}-\\sqrt{x+3}}{x^{2}-1} = \\lim_{x \\to 1} \\frac{(\\sqrt{2x+2}-\\sqrt{x+3})(\\sqrt{2x+2}+\\sqrt{x+3})}{(x+1)(x-1)(\\sqrt{2x+2}+\\sqrt{x+3})}$ ($(\\sqrt{a}-\\sqrt{b})(\\sqrt{a}+\\sqrt{b})=a-b$이므로 $(\\sqrt{2x+2})^{2}-(\\sqrt{x+3})^{2}=(2x+2)-(x+3)=x-1$이야.) $= \\lim_{x \\to 1} \\frac{x-1}{(x+1)(x-1)(\\sqrt{2x+2}+\\sqrt{x+3})} = \\lim_{x \\to 1} \\frac{1}{(x+1)(\\sqrt{2x+2}+\\sqrt{x+3})} = \\frac{1}{2(2+2)} = \\frac{1}{8}$\n$\\therefore ab=2 \\times \\frac{1}{8}=\\frac{1}{4}$", "img": "IMG_4936.jpg", "answer_value": "$\\frac{1}{4}$"}, {"id": "A149", "section": "A", "num": 149, "page": 31, "topic": "분수식의 극한값이 존재할 조건", "answer": "⑤", "rate": "80%", "problem": "함수 $f(x)$에 대하여 $\\lim_{x \\to 2} \\frac{f(x)-3}{x-2}=5$일 때, $\\lim_{x \\to 2} \\frac{x-2}{\\{f(x)\\}^{2}-9}$의 값은? (3점)", "explanation": "정답 공식: 극한값이 존재하고 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다.\n1st 분수식의 극한값이 존재하고, 분모가 0으로 수렴하면 분자도 0으로 수렴하지. $\\lim_{x \\to 2} \\frac{f(x)-3}{x-2}=5$에서 $x \\to 2$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 2}\\{f(x)-3\\}=0$이므로 $\\lim_{x \\to 2} f(x)=3$ … ㉠\n2nd ㉠과 $\\lim_{x \\to 2} \\frac{f(x)-3}{x-2}=5$임을 이용하여 주어진 극한값을 계산해. ㉠에 의해 $\\lim_{x \\to 2} \\frac{1}{f(x)+3}=\\frac{1}{6}$이고 $\\lim_{x \\to 2} \\frac{f(x)-3}{x-2}=5$이므로\n$\\lim_{x \\to 2} \\frac{x-2}{\\{f(x)\\}^{2}-9} = \\lim_{x \\to 2} \\frac{x-2}{\\{f(x)-3\\}\\{f(x)+3\\}} = \\lim_{x \\to 2} \\frac{x-2}{f(x)-3} \\times \\lim_{x \\to 2} \\frac{1}{f(x)+3} = \\lim_{x \\to 2} \\frac{1}{\\frac{f(x)-3}{x-2}} \\times \\lim_{x \\to 2} \\frac{1}{f(x)+3}$ (분자, 분모를 각각 $x-2$로 나눈 거야.) $= \\frac{1}{5} \\times \\frac{1}{6} = \\frac{1}{30}$\n(함정: $\\frac{0}{0}$ 꼴이기 때문에 계산할 수 있는 형태로 바꿔줘야 답을 구할 수 있어.)", "img": "IMG_4936.jpg", "answer_value": "$\\frac{1}{30}$"}, {"id": "A150", "section": "A", "num": 150, "page": 31, "topic": "분수식의 극한값이 존재할 조건", "answer": "④", "rate": "82%", "problem": "함수 $f(x)$에 대하여 $\\lim_{x \\to 2} \\frac{f(x-2)}{x^{2}-2x}=4$일 때, $\\lim_{x \\to 0} \\frac{f(x)}{x}$의 값은? (3점)", "explanation": "정답 공식: 극한값이 존재하고 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다.\n1st 치환을 이용하여 주어진 극한값을 구하자. $x-2=t$라 하면 $x=t+2$이고, $x \\to 2$일 때 $t \\to 0$이므로 $\\lim_{x \\to 2} \\frac{f(x-2)}{x^{2}-2x} = \\lim_{x \\to 2} \\frac{f(x-2)}{x(x-2)} = \\lim_{t \\to 0} \\frac{f(t)}{t(t+2)} = \\lim_{t \\to 0}\\left\\{\\frac{f(t)}{t} \\times \\frac{1}{t+2}\\right\\} = \\frac{1}{2} \\lim_{t \\to 0} \\frac{f(t)}{t} = 4$ ($\\lim_{t \\to 0}\\left\\{\\frac{f(t)}{t} \\times \\frac{1}{t+2}\\right\\} = \\lim_{t \\to 0} \\frac{f(t)}{t} \\times \\lim_{t \\to 0} \\frac{1}{t+2} = \\frac{1}{2} \\lim_{t \\to 0} \\frac{f(t)}{t}$)\n따라서 $\\lim_{t \\to 0} \\frac{f(t)}{t}=8$이므로 $\\lim_{x \\to 0} \\frac{f(x)}{x}=8$", "img": "IMG_4936.jpg", "answer_value": "8"}, {"id": "A151", "section": "A", "num": 151, "page": 31, "topic": "분수식의 극한값이 존재할 조건", "answer": "①", "rate": "61%", "problem": "다항함수 $g(x)$에 대하여 극한값 $\\lim_{x \\to 1} \\frac{g(x)-2x}{x-1}$가 존재한다. 다항함수 $f(x)$가 $f(x)+x-1=(x-1)g(x)$를 만족시킬 때, $\\lim_{x \\to 1} \\frac{f(x)g(x)}{x^{2}-1}$의 값은? (3점)", "explanation": "정답 공식: 극한값이 존재하고 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다.\n1st $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ ($\\alpha$는 상수)일 때, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$임을 이용하여 $g(1)$의 값을 구해. $\\lim_{x \\to 1} \\frac{g(x)-2x}{x-1}$의 값이 존재하고 $x \\to 1$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 1}\\{g(x)-2x\\}=g(1)-2=0$ $\\therefore g(1)=2$ … ㉠\n2nd $f(x)+x-1=(x-1)g(x)$에서 $f(x)$를 구해. 한편, $f(x)+x-1=(x-1)g(x)$에서 $f(x)=(x-1)\\{g(x)-1\\}$ … ㉡\n㉡에서 $x=1$을 대입하면 $f(1)=0$이므로 $f(x)-f(1)=(x-1)\\{g(x)-1\\}$에서 $\\lim_{x \\to 1} \\frac{f(x)-f(1)}{x-1} = \\lim_{x \\to 1}\\{g(x)-1\\} = g(1)-1 = 1$ ($\\because$ ㉠) … ㉢ ($g(x)$가 다항함수이므로 $\\lim_{x \\to a} g(x)=g(a)$)\n3rd 구한 값들을 이용하여 $\\lim_{x \\to 1} \\frac{f(x)g(x)}{x^{2}-1}$의 값을 구해. $\\lim_{x \\to 1} \\frac{f(x)g(x)}{x^{2}-1} = \\lim_{x \\to 1}\\left\\{\\frac{f(x)}{x-1} \\times \\frac{g(x)}{x+1}\\right\\}$ (㉢의 꼴을 만들어 주기 위해 식을 변형해야 해.) $= \\lim_{x \\to 1} \\frac{f(x)-f(1)}{x-1} \\times \\lim_{x \\to 1} \\frac{g(x)}{x+1} = 1 \\times \\frac{g(1)}{2} = 1$ ($\\because$ ㉠, ㉢)", "img": "IMG_4936.jpg", "answer_value": "1"}, {"id": "A152", "section": "A", "num": 152, "page": 32, "topic": "분수식의 극한값이 존재할 조건", "answer": "④", "rate": "55%", "problem": "함수 $f(x)=x^{2}+6x+12$에 대하여 다음 조건을 만족시키는 모든 정수 $k$의 개수는? (4점) [조건] 모든 실수 $a$에 대하여 $\\lim_{x \\to a} \\frac{x^{2}}{\\{f(x)\\}^{2}-k(x+2)f(x)}$의 값이 존재한다.", "explanation": "정답 공식: $\\lim_{x \\to a} \\frac{f(x)}{g(x)}$에 대하여 $\\lim_{x \\to a} g(x) \\ne 0$이면 극한값이 존재한다. $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ ($\\alpha$는 실수)일 때, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이다.\n1st $\\lim_{x \\to a} \\frac{x^{2}}{\\{f(x)\\}^{2}-k(x+2)f(x)}$의 값이 존재하기 위한 $k$의 값의 범위를 구해. 함수 $f(x)=x^{2}+6x+12$에서 $f(x)=x^{2}+6x+12=(x+3)^{2}+3>0$이므로 함수 $f(x)=x^{2}+6x+12$는 모든 실수 $x$에 대하여 $f(x)>0$이다. 주어진 조건에서 모든 실수 $a$에 대하여 $\\lim_{x \\to a} \\frac{x^{2}}{\\{f(x)\\}^{2}-k(x+2)f(x)}$의 값이 존재하는 경우는 다음과 같은 두 가지 경우가 있다.\n(i) 모든 실수 $a$에 대하여 $\\lim_{x \\to a}\\left[\\{f(x)\\}^{2}-k(x+2)f(x)\\right] \\ne 0$인 경우: $\\lim_{x \\to a}\\left[\\{f(x)\\}^{2}-k(x+2)f(x)\\right] = \\{f(a)\\}^{2}-k(a+2)f(a) = f(a)\\{f(a)-k(a+2)\\}$ (함수 $f(x)$는 이차함수이므로 함수 $\\{f(x)\\}^{2}-k(x+2)f(x)$는 연속함수야. 따라서 $\\lim_{x \\to a}\\left[\\{f(x)\\}^{2}-k(x+2)f(x)\\right]=\\{f(a)\\}^{2}-k(a+2)f(a)$가 성립해.)\n$f(a)>0$이므로 $f(a) \\ne k(a+2)$ (모든 실수 $a$에 대하여 $f(x)>0$이야.) 즉, $x$에 대한 방정식 $f(x)=k(x+2)$의 실근이 존재하지 않아야 하므로 이차방정식 $x^{2}+6x+12=kx+2k$의 실근이 존재하지 않아야 한다. $x^{2}+(6-k)x+12-2k=0$의 판별식을 $D$라 하면 $D=(6-k)^{2}-4(12-2k)<0$이어야 한다. (이차방정식의 실근이 존재하지 않으려면 이차방정식이 서로 다른 두 허근을 가져야 하므로 $D<0$이어야 해.)\n$k^{2}-4k-12<0$, $(k+2)(k-6)<0$ $\\therefore -2<k<6$\n(ii) $\\lim_{x \\to a}\\left[\\{f(x)\\}^{2}-k(x+2)f(x)\\right]=0$인 실수 $a$가 존재하는 경우: (분모)$\\to 0$이고 극한값이 존재하므로 (분자)$\\to 0$이어야 한다. ($\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ ($\\alpha$는 실수)일 때, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이야.) 즉, $\\lim_{x \\to a} x^{2}=0$이어야 하므로 $a^{2}=0$ $\\therefore a=0$ ($y=x^{2}$은 연속함수이므로 $\\lim_{x \\to a} x^{2}=a^{2}$이야.)\n$\\lim_{x \\to 0}\\left[\\{f(x)\\}^{2}-k(x+2)f(x)\\right] = \\{f(0)\\}^{2}-2kf(0) = f(0)\\{f(0)-2k\\} = 0$\n$f(0)>0$이므로 $f(0)=2k$, $12=2k$에서 $k=6$\n이때, $\\lim_{x \\to 0} \\frac{x^{2}}{\\{f(x)\\}^{2}-6(x+2)f(x)} = \\lim_{x \\to 0} \\frac{x^{2}}{f(x)\\{f(x)-6x-12\\}} = \\lim_{x \\to 0} \\frac{x^{2}}{(x^{2}+6x+12)x^{2}} = \\lim_{x \\to 0} \\frac{1}{x^{2}+6x+12} = \\frac{1}{12}$\n따라서 극한값이 존재하므로 조건을 만족시킨다.\n2nd 정수 $k$의 개수를 구해. (i), (ii)에 의하여 $-2<k \\le 6$이므로 조건을 만족시키는 모든 정수 $k$는 $-1, 0, 1, \\cdots, 6$이고 그 개수는 8이다.\n(함정: 이 문제에서 극한식의 분모가 0이 아니면 된다고만 생각해 (i)의 경우만 확인하면 오답이 될 확률이 높아. (ii)의 경우도 반드시 확인해야 해.)", "img": "IMG_4937.jpg", "answer_value": "8"}, {"id": "A153", "section": "A", "num": 153, "page": 32, "topic": "분수식의 극한값이 존재할 조건", "answer": "$60$", "rate": "45%", "problem": "다항함수 $f(x)$가 다음 조건을 만족시킨다. (가) 모든 실수 $a$에 대하여 $\\lim_{x \\to a} \\frac{f(x)-5x}{x^{2}-4}$의 값이 존재한다. (나) $\\lim_{x \\to \\infty}\\left(\\sqrt{f(x)}-3x+1\\right)$의 값이 존재한다. $f(3)$의 값을 구하시오. (4점)", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한에서 $x \\to a$일 때, 극한값이 존재하고 (분모)$\\to 0$이면 (분자)$\\to 0$이다.\n1st 조건 (가)에서 모든 실수 $a$에 대하여 주어진 극한값이 존재하려면 (분모)$\\to 0$이 되도록 하는 $a$의 값, 즉 $a=2$, $a=-2$일 때도 극한값이 존재해야 해. 조건 (가)에서 모든 실수 $a$에 대하여 $\\lim_{x \\to a} \\frac{f(x)-5x}{x^{2}-4}$의 값이 존재하므로 $a=2$일 때와 $a=-2$일 때도 극한값이 존재해야 한다.\n(i) $a=2$일 때, 극한값이 존재하려면 (분모)$\\to 0$이므로 (분자)$\\to 0$이 되어야 한다. 즉, $\\lim_{x \\to 2} \\frac{f(x)-5x}{x^{2}-4}$에서 $\\lim_{x \\to 2}\\{f(x)-5x\\}=0$이어야 하므로 $f(2)-5 \\times 2=0$ $\\therefore f(2)=10$\n(ii) $a=-2$일 때, 극한값이 존재하려면 (분모)$\\to 0$이므로 (분자)$\\to 0$이 되어야 한다. 즉, $\\lim_{x \\to -2} \\frac{f(x)-5x}{x^{2}-4}$에서 $\\lim_{x \\to -2}\\{f(x)-5x\\}=0$이어야 하므로 $f(-2)-5 \\times (-2)=0$ $\\therefore f(-2)=-10$\n2nd 조건 (나)를 이용하여 다항함수 $f(x)$의 차수를 알아보자. $\\lim_{x \\to \\infty}\\left(\\sqrt{f(x)}-3x+1\\right) = \\lim_{x \\to \\infty} \\frac{\\left\\{\\sqrt{f(x)}-(3x-1)\\right\\}\\left\\{\\sqrt{f(x)}+(3x-1)\\right\\}}{\\sqrt{f(x)}+3x-1} = \\lim_{x \\to \\infty} \\frac{f(x)-(3x-1)^{2}}{\\sqrt{f(x)}+3x-1}$ … ㉠ ($\\infty-\\infty$ 꼴의 무리식의 극한이므로 분자, 분모에 $\\sqrt{f(x)}+3x-1$을 곱해 분자를 유리화하자.)\n이때, $f(x)$를 $n$차 다항함수라 하면 $f(x)=kx^{n}+\\cdots$ ($k \\ne 0$)로 놓을 수 있고 $\\sqrt{f(x)}=\\sqrt{kx^{n}+\\cdots}$이므로 ㉠의 극한값이 존재하기 위해서는 분모의 차수가 분자의 차수보다 크거나 같아야 하므로 $f(x)$는 이차항의 계수가 9인 이차함수이다. ((분모의 차수)$>$(분자의 차수)인 경우 극한값은 항상 0이야. 또, (분모의 차수)$=$(분자의 차수)일 때는 $\\frac{\\infty}{\\infty}$ 꼴이므로 분모의 최고차항으로 분모, 분자를 각각 나누어 극한값을 구해야 해.)\n(함정: 분자의 차수가 분모의 차수보다 커지면 안 되기 때문에 다항함수 $f(x)$의 차수가 삼차 이상이 안 된다는 걸 알아야 해.)\n따라서 $f(x)=9x^{2}+bx+c$라 하면\n$f(2)=9 \\times 2^{2}+b \\times 2+c=10$ … ㉡\n$f(-2)=9 \\times (-2)^{2}+b \\times (-2)+c=-10$ … ㉢\n㉡, ㉢을 연립하여 풀면 $b=5$, $c=-36$\n따라서 $f(x)=9x^{2}+5x-36$이므로 $f(3)=9 \\times 3^{2}+5 \\times 3-36=60$\n[톡톡 풀이: 방정식 $f(x)-5x=0$의 두 근 이용하기] $\\lim_{x \\to 2}\\{f(x)-5x\\}=0$, $\\lim_{x \\to -2}\\{f(x)-5x\\}=0$이므로 ($f(2)-5 \\times 2=0$, $f(-2)-5 \\times (-2)=0$이므로 $g(x)=f(x)-5x$라 하면 다항함수 $g(x)$는 $x-2$, $x+2$를 인수로 가져.) $f(x)-5x=9(x+2)(x-2)$로 놓을 수 있어. 따라서 $f(3)-15=9 \\times 5 \\times 1$에서 $f(3)=60$", "img": "IMG_4937.jpg"}, {"id": "A154", "section": "A", "num": 154, "page": 33, "topic": "새롭게 정의된 함수의 극한", "answer": "⑤", "rate": "82%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 1+} f(x)f(1-x)$의 값은? (3점)", "explanation": "정답 공식: $1-x=t$라 하면 $x \\to 1+$일 때, $t \\to 0-$이다.\n1st 함수의 극한에서 $x \\to 1+$는 $x=1$에서의 우극한을 의미하지? 함수 $y=f(x)$의 그래프에서 $\\lim_{x \\to 1+} f(x)=1$이고 $1-x=t$라 하면 $x \\to 1+$일 때, $t \\to 0-$이므로 $\\lim_{x \\to 1+} f(1-x)=\\lim_{t \\to 0-} f(t)=2$ ($x \\to 1+$에서 $-x \\to -1-$이고 $1-x \\to 0-$가 되는 거야.)\n2nd 두 상수 $\\alpha$, $\\beta$에 대하여 $\\lim_{x \\to a} f(x)=\\alpha$, $\\lim_{x \\to a} g(x)=\\beta$일 때, $\\lim_{x \\to a}\\{f(x) \\times g(x)\\}=\\lim_{x \\to a} f(x) \\times \\lim_{x \\to a} g(x)=\\alpha\\beta$임을 이용해.\n$\\therefore \\lim_{x \\to 1+} f(x)f(1-x)=\\lim_{x \\to 1+} f(x) \\times \\lim_{x \\to 1+} f(1-x)=1 \\times 2=2$\n(주의: 이와 같이 식을 치환할 때 $x$의 부호를 고려하고 상수항을 계산해야 좌우극한 방향을 틀리지 않을 수 있어.)", "img": "IMG_4938.jpg", "answer_value": "2"}, {"id": "A155", "section": "A", "num": 155, "page": 33, "topic": "새롭게 정의된 함수의 극한", "answer": "④", "rate": "84%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같을 때, $\\lim_{x \\to 1+} f(x)+\\lim_{x \\to 1-} f(-x)$의 값은? (3점)", "explanation": "정답 공식: $-x=t$라 하면 $x \\to 1-$일 때, $t \\to -1+$이다.\n1st 그래프를 보고 극한값을 구하자. $x$가 $1$보다 크면서 $1$에 가까워질 때, $f(x)$는 $0$보다 크면서 $0$에 가까워지므로 $\\lim_{x \\to 1+} f(x)=0$\n2nd $-x=t$로 치환하여 $f(-x)$에 대한 극한값을 구하자. $-x=t$로 치환하면 $x \\to 1-$일 때, $t \\to -1+$이므로 ($x \\to 1-$에 $-1$을 양쪽에 곱한다고 생각하면 $-x \\to -1+$이고 $-x=t$라 치환했으니까 $t \\to -1+$가 나온 거야.) $\\lim_{x \\to 1-} f(-x)=\\lim_{t \\to -1+} f(t)=1$\n$\\therefore \\lim_{x \\to 1+} f(x)+\\lim_{x \\to 1-} f(-x)=1$", "img": "IMG_4938.jpg", "answer_value": "$1$"}, {"id": "A156", "section": "A", "num": 156, "page": 33, "topic": "새롭게 정의된 함수의 극한", "answer": "④", "rate": "72%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to -1-} f(x)=a$일 때, $\\lim_{x \\to a+} f(x+3)$의 값은? (3점)", "explanation": "정답 공식: $x+3=t$라 하면 $x \\to a+$이면 $t \\to (a+3)+$이다.\n1st 그래프를 보고 $f(x)$의 $x=-1$에서의 좌극한값을 구하자. $x$가 $-1$보다 작으면서 $-1$에 가까워질 때, $f(x)$는 $-2$보다 크면서 $-2$에 가까워지므로 $\\lim_{x \\to -1-} f(x)=-2=a$\n2nd $f(x+3)$의 그래프를 새로 그리지 말고 $x+3=t$로 치환하여 생각하자. $\\lim_{x \\to a+} f(x+3)=\\lim_{x \\to -2+} f(x+3)$에서 $x+3=t$로 치환하면 $x \\to -2+$일 때, $x+3 \\to 1+$, 즉 $t \\to 1+$\n$\\therefore \\lim_{x \\to -2+} f(x+3)=\\lim_{t \\to 1+} f(t)=\\lim_{x \\to 1+} f(x)$ ($t$ 대신 다시 $x$로 바꿔서 생각해도 돼. 같은 변수끼리는 똑같이 바꿔도 되기 때문이야.)\n그래프에서 $x$가 $1$보다 크면서 $1$에 가까워질 때, $f(x)$는 $1$이므로 $\\lim_{x \\to 1+} f(x)=1$", "img": "IMG_4938.jpg", "answer_value": "$1$"}, {"id": "A157", "section": "A", "num": 157, "page": 34, "topic": "합성함수의 극한", "answer": "⑤", "rate": "63%", "problem": "정의역이 $\\{x|0 \\le x \\le 4\\}$인 함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0+} f(f(x))+\\lim_{x \\to 2+} f(f(x))$의 값은? (3점)", "explanation": "정답 공식: $f(x)=t$라 할 때, 실수 $a$에 대하여 $x \\to a+$ 또는 $x \\to a-$이면 $t$의 값이 어떤 값으로 수렴하는지 파악하여 합성함수의 극한값을 구한다.\n1st 먼저 $\\lim_{x \\to 0+} f(f(x))$의 값을 구하자. (i) 그림에서 $x \\to 0+$일 때, $f(x) \\to 3-$이므로 (실수: $x \\to 0+$일 때 $f(x)$의 값이 $3$보다 작은 값에서 $3$으로 다가가기 때문에 $f(x) \\to 3-$라고 해야 올바른 치환이야.) $f(x)=t$로 놓으면 $\\lim_{x \\to 0+} f(f(x))=\\lim_{t \\to 3-} f(t)=3$ (합성함수의 극한은 치환을 이용하자.)\n2nd 이번엔 $\\lim_{x \\to 2+} f(f(x))$의 값을 구하자. (ii) 그림에서 $x \\to 2+$일 때, $f(x)=3$이므로 (실수: $x \\to 2+$일 때 $f(x)$의 값은 $y=3$을 따라 다가오므로 $f(x)=3$이라고 해야 해.) $\\lim_{x \\to 2+} f(f(x))=f(3)=2$\n$\\therefore \\lim_{x \\to 0+} f(f(x))+\\lim_{x \\to 2+} f(f(x))=3+2=5$\n[개념·공식: 합성함수의 극한] 합성함수 $(f \\circ g)(x)$의 극한값, 즉 $\\lim_{x \\to a}(f \\circ g)(x)=\\lim_{x \\to a} f(g(x))$의 값은 $g(x)=t$라 하고 다음을 이용하여 구한다. ① $x \\to a$일 때, $t \\to b+$이면 $\\lim_{x \\to a}(f \\circ g)(x)=\\lim_{t \\to b+} f(t)$ ② $x \\to a$일 때, $t \\to b-$이면 $\\lim_{x \\to a}(f \\circ g)(x)=\\lim_{t \\to b-} f(t)$ ③ $x \\to a$일 때, $t=b$이면 $\\lim_{x \\to a}(f \\circ g)(x)=f(b)$", "img": "IMG_4939.jpg", "answer_value": "$5$"}, {"id": "A158", "section": "A", "num": 158, "page": 34, "topic": "합성함수의 극한", "answer": "④", "rate": "76%", "problem": "함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{x \\to 0+} f(x-1)+\\lim_{x \\to 1+} f(f(x))$의 값은? (3점)", "explanation": "정답 공식: 실수 $a$에 대하여 $x \\to a$일 때 $f(\\square)$에서 $\\square$가 어떤 값으로 수렴하는지 파악한 후 그래프를 따라가며 $f(\\square)$의 극한값을 구한다.\n1st $x-1=t$라 놓고 $f(t)$의 극한값을 구해. $x-1=t$라 하면 $x \\to 0+$일 때, $t \\to -1+$이므로 ($x$가 $0$보다 큰 값을 가지며 $0$에 가까워지면 $x-1$은 $-1$보다 큰 값을 가지며 $-1$에 가까워지지?) $\\lim_{x \\to 0+} f(x-1)=\\lim_{t \\to -1+} f(t)=-1$\n2nd $f(x)=s$라 놓고 $f(s)$의 극한값을 구해. $f(x)=s$라 하면 $x \\to 1+$일 때, $s \\to -1-$이므로 ($x$가 $1$보다 큰 값을 가지며 $1$에 가까워지면 주어진 그래프에서 $f(x)$의 값은 $-1$보다 작은 값을 가지며 $-1$에 가까워짐을 알 수 있어.) $\\lim_{x \\to 1+} f(f(x))=\\lim_{s \\to -1-} f(s)=2$\n$\\therefore \\lim_{x \\to 0+} f(x-1)+\\lim_{x \\to 1+} f(f(x))=(-1)+2=1$\n[개념·공식: 합성함수의 극한] 합성함수 $(f \\circ g)(x)$의 극한값은 $g(x)=t$라 하고 ① $x \\to a$일 때 $t \\to b+$이면 $\\lim_{t \\to b+} f(t)$ ② $t \\to b-$이면 $\\lim_{t \\to b-} f(t)$ ③ $t=b$이면 $f(b)$를 이용하여 구한다.", "img": "IMG_4939.jpg", "answer_value": "$1$"}, {"id": "A159", "section": "A", "num": 159, "page": 35, "topic": "합성함수의 극한", "answer": "①", "rate": "68%", "problem": "다항함수 $f(x)$가 $\\lim_{x \\to 0} \\frac{x}{f(x)}=1$, $\\lim_{x \\to 1} \\frac{x-1}{f(x)}=2$를 만족시킬 때, $\\lim_{x \\to 1} \\frac{f(f(x))}{2x^{2}-x-1}$의 값은? (3점)", "explanation": "정답 공식: $0$이 아닌 극한값이 존재하고 (분자)$\\to 0$이면 (분모)$\\to 0$이어야 한다.\n1st $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$($\\alpha \\ne 0$인 상수)일 때, $\\lim_{x \\to a} f(x)=0$이면 $\\lim_{x \\to a} g(x)=0$이야. $\\lim_{x \\to 1} \\frac{x-1}{f(x)}=2$에서 $x \\to 1$일 때, (분자)$\\to 0$이고 극한값이 $2$이므로 (분모)$\\to 0$이어야 한다. 즉, $f(x)$가 다항함수이므로 $\\lim_{x \\to 1} f(x)=0 \\therefore f(1)=0 \\cdots$ ㉠\n2nd $f(x)=t$라 치환하자. $f(x)=t$라 하면 $x \\to 1$일 때 $t \\to 0$ ($\\because$ ㉠)이므로 (주의: 문제에서 주어진 극한의 꼴이 나오도록 변형하는 게 중요해!)\n$\\lim_{x \\to 1} \\frac{f(f(x))}{2x^{2}-x-1}=\\lim_{x \\to 1}\\left\\{ \\frac{f(f(x))}{f(x)} \\times \\frac{f(x)}{(x-1)(2x+1)} \\right\\}$\n$=\\lim_{x \\to 1} \\frac{f(f(x))}{f(x)} \\times \\lim_{x \\to 1} \\frac{f(x)}{x-1} \\times \\lim_{x \\to 1} \\frac{1}{2x+1}$\n$=\\lim_{t \\to 0} \\frac{f(t)}{t} \\times \\lim_{x \\to 1} \\frac{f(x)}{x-1} \\times \\lim_{x \\to 1} \\frac{1}{2x+1}$\n$=\\lim_{t \\to 0} \\frac{1}{\\frac{t}{f(t)}} \\times \\lim_{x \\to 1} \\frac{1}{\\frac{x-1}{f(x)}} \\times \\lim_{x \\to 1} \\frac{1}{2x+1}$ (분자, 분모를 $f(t)$, $f(x)$로 각각 나눠)\n$=1 \\times \\frac{1}{2} \\times \\frac{1}{3}=\\frac{1}{6}$\n[톡톡 풀이: $f(0)$, $f'(0)$, $f(1)$, $f'(1)$의 값 이용하기] $\\lim_{x \\to 0} \\frac{x}{f(x)}=1$에서 $x \\to 0$일 때, (분자)$\\to 0$이므로 (분모)$\\to 0$이어야 해. $\\therefore f(0)=0 \\cdots$ ㉡\n$\\lim_{x \\to 0} \\frac{x}{f(x)}=\\lim_{x \\to 0} \\frac{x}{f(x)-f(0)}$ ($\\because$ ㉡)$=\\lim_{x \\to 0} \\frac{1}{\\frac{f(x)-f(0)}{x}}=\\frac{1}{f'(0)}=1 \\therefore f'(0)=1$\n또, $\\lim_{x \\to 1} \\frac{x-1}{f(x)}=2$에서 $x \\to 1$일 때, (분자)$\\to 0$이므로 (분모)$\\to 0$이어야 해. $\\therefore f(1)=0 \\cdots$ ㉢\n㉢, ㉡에서 $f(f(1))=f(0)=0 \\cdots$ ㉣\n$\\lim_{x \\to 1} \\frac{x-1}{f(x)}=\\lim_{x \\to 1} \\frac{x-1}{f(x)-f(1)}$ ($\\because$ ㉢)$=\\lim_{x \\to 1} \\frac{1}{\\frac{f(x)-f(1)}{x-1}}=\\frac{1}{f'(1)}=2 \\therefore f'(1)=\\frac{1}{2}$\n$\\therefore \\lim_{x \\to 1} \\frac{f(f(x))}{2x^{2}-x-1}=\\lim_{x \\to 1} \\frac{f(f(x))-f(f(1))}{f(x)-f(1)} \\times \\frac{f(x)-f(1)}{x-1} \\times \\frac{1}{2x+1}$ ($\\because$ ㉣)$=f'(f(1)) \\times f'(1) \\times \\frac{1}{3}=f'(0) \\times \\frac{1}{2} \\times \\frac{1}{3}=1 \\times \\frac{1}{2} \\times \\frac{1}{3}=\\frac{1}{6}$", "img": "IMG_4940.jpg", "answer_value": "$\\frac{1}{6}$"}, {"id": "A160", "section": "A", "num": 160, "page": 35, "topic": "합성함수의 극한", "answer": "⑤", "rate": "67%", "problem": "함수 $f(x)$가 $f(x)=\\begin{cases} -x & (x<0) \\\\ 1 & (0 \\le x<1) \\\\ x-1 & (x \\ge 1) \\end{cases}$이고, 그 그래프는 그림과 같다. 이때, [보기]의 설명 중 옳은 것을 모두 고른 것은? (4점) ㄱ. $\\lim_{x \\to 1} f(x)=0$ ㄴ. $\\lim_{x \\to 1+} f(f(x))=1$ ㄷ. $\\lim_{x \\to 1-} f(f(x))=0$", "explanation": "정답 공식: $f(x)=t$라 할 때, 실수 $a$에 대하여 $x \\to a+$ 또는 $x \\to a-$이면 $t$의 값이 어떤 값으로 수렴하는지 파악하여 합성함수의 극한값을 구한다.\n1st ㄱ은 좌극한값과 우극한값이 같아야 극한값이 존재함을 이용해서 참·거짓을 따져. ㄱ. 그래프에서 $x=1$에서의 좌극한은 $\\lim_{x \\to 1-} f(x)=1$이고, 우극한은 $\\lim_{x \\to 1+} f(x)=0$으로 좌극한값과 우극한값이 같지 않으므로 $\\lim_{x \\to 1} f(x)$의 값은 존재하지 않는다. (거짓) ($x=1$에서 함수 $f(x)$의 극한값이 존재하려면 좌극한과 우극한이 모두 존재하고 그 값이 일치해야 해.)\n2nd ㄴ, ㄷ은 합성함수에 주의하면서! ㄴ. $x \\ge 1$일 때, $f(x)=x-1$이므로 $x \\to 1+$일 때, $x-1 \\to 0+$, $\\lim_{x \\to 1+} f(f(x))=\\lim_{x \\to 1+} f(x-1)=\\lim_{h \\to 0+} f(h)=1$ (참) ($x-1=h$로 치환, 합성함수의 극한은 치환을 이용하자.)\nㄷ. $0 \\le x<1$일 때, $f(x)=1$이므로 $\\lim_{x \\to 1-} f(f(x))=\\lim_{x \\to 1-} f(1)=0$ (참) ($x \\ge 1$일 때 $f(x)=x-1$이므로 $f(1)=0$이야.)\n따라서 옳은 것은 ㄴ, ㄷ이다.\n[수능 핵강: 그래프에서 좌극한과 우극한, 알아보기] 그래프에서 $x=a$에서의 좌극한값은 $x=a$의 왼쪽에서 $x=a$에 한없이 가까이 갈 때, 즉 $\\nearrow$ 방향일 때의 $y$값이야. 또, $x=a$에서의 우극한값은 $x=a$의 오른쪽에서 $x=a$에 한없이 가까이 갈 때, 즉 $\\nwarrow$ 방향일 때의 $y$값이야.", "img": "IMG_4940.jpg", "answer_value": "ㄴ, ㄷ"}, {"id": "A161", "section": "A", "num": 161, "page": 36, "topic": "합성함수의 극한", "answer": "③", "rate": "46%", "problem": "실수 전체의 집합에서 정의된 함수 $y=f(x)$의 그래프가 그림과 같다. $\\lim_{t \\to \\infty} f\\left(\\frac{t-1}{t+1}\\right)+\\lim_{t \\to -\\infty} f\\left(\\frac{4t-1}{t+1}\\right)$의 값은? (3점)", "explanation": "정답 공식: $\\frac{t-1}{t+1}=1-\\frac{2}{t+1}$, $\\frac{4t-1}{t+1}=4-\\frac{5}{t+1}$이다. $t \\to \\pm \\infty$일 때 어떤 값에 가까워지는지 살핀다.\n1st $y=f(x)$는 $x=1$, $x=4$에서 (좌극한값)$\\ne$(우극한값)이지? 따라서 $t$에 관한 함수에 대하여 좌극한, 우극한을 정확히 판단해서 계산하자.\n$\\lim_{t \\to \\infty} f\\left(\\frac{t-1}{t+1}\\right)$에서 $x=\\frac{t-1}{t+1}$이라 하면 $x=1-\\frac{2}{t+1}$이므로 $t \\to \\infty$일 때, $x \\to 1- \\left(x=\\frac{(t+1)-2}{t+1}=1-\\frac{2}{t+1}\\right)$\n$\\lim_{t \\to -\\infty} f\\left(\\frac{4t-1}{t+1}\\right)$에서 $x=\\frac{4t-1}{t+1}$이라 하면 $x=4-\\frac{5}{t+1}$이므로 $t \\to -\\infty$일 때, $x \\to 4+ \\left(x=\\frac{4(t+1)-5}{t+1}=4-\\frac{5}{t+1}\\right)$\n2nd $x=1$에서 좌극한값, $x=4$에서 우극한값을 계산해야 해.\n$\\lim_{t \\to \\infty} f\\left(\\frac{t-1}{t+1}\\right)=\\lim_{x \\to 1-} f(x)=2$\n$\\lim_{t \\to -\\infty} f\\left(\\frac{4t-1}{t+1}\\right)=\\lim_{x \\to 4+} f(x)=3$ (실수: $t \\to \\infty$이거나 $t \\to -\\infty$이면 $\\frac{\\text{상수}}{t+1} \\to 0$이란 것과 $t$의 부호를 확인하면서 계산해!)\n$\\therefore \\lim_{t \\to \\infty} f\\left(\\frac{t-1}{t+1}\\right)+\\lim_{t \\to -\\infty} f\\left(\\frac{4t-1}{t+1}\\right)=2+3=5$", "img": "IMG_4941.jpg", "answer_value": "$5$"}, {"id": "A162", "section": "A", "num": 162, "page": 36, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "②", "rate": "78%", "problem": "다항함수 $f(x)$가 다음 조건을 만족시킨다. (가) $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}}=2$ (나) $\\lim_{x \\to 0} \\frac{f(x)}{x}=3$ $f(2)$의 값은? (3점)", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한에서 함수의 차수와 최고차항의 계수를 파악하고 $\\frac{0}{0}$ 꼴의 극한에서 상수항을 파악한다.\n1st 다항식 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{n}}=c$ (단, $c$는 $0$이 아닌 상수)이면 $f(x)$의 차수는 $n$이고, 최고차항의 계수는 $c$야. 조건 (가)에 의하여 다항함수 $f(x)$는 $f(x)=2x^{2}+ax+b$ ($a$, $b$는 상수)로 놓을 수 있다. ($\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}}=2$에서 분모의 차수가 $2$이니까 분자의 차수도 $2$이고, 분자인 $f(x)$의 최고차항의 계수가 $2$이어야 해.)\n2nd 조건 (나)를 이용하여 상수 $a$, $b$의 값을 구하자. 조건 (나)에서 $x \\to 0$일 때, 극한값이 존재하고 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 0}(2x^{2}+ax+b)=b=0$ (주의: (분모)$\\to 0$일 때는 $\\frac{0}{0}$ 꼴이 되어야 극한값이 존재할 수 있다는 걸 기억해. $\\lim_{x \\to 0} \\frac{f(x)}{x}$가 수렴하므로 분모가 $0$에 수렴할 때, 분자도 $0$에 수렴해야 해. 즉, $f(0)=0$이어야 하지.)\n따라서 $\\lim_{x \\to 0} \\frac{f(x)}{x}=\\lim_{x \\to 0} \\frac{2x^{2}+ax}{x}=\\lim_{x \\to 0}(2x+a)=a=3$ ($2x^{2}+ax=x(2x+a)$야.)\n이므로 $f(x)=2x^{2}+3x$\n$\\therefore f(2)=2 \\times 2^{2}+3 \\times 2=14$", "img": "IMG_4941.jpg", "answer_value": "$14$"}, {"id": "A163", "section": "A", "num": 163, "page": 36, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "$22$", "rate": "80%", "problem": "다항함수 $f(x)$가 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}}=2$, $\\lim_{x \\to 2} \\frac{f(x)}{x-2}=7$을 만족시킬 때, $f(4)$의 값을 구하시오. (3점)", "explanation": "정답 공식: 다항함수 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{n}}=c$($c$는 $c \\ne 0$인 상수)이면 $f(x)$의 차수는 $n$이고, 최고차항의 계수는 $c$이다. 또한, $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$($\\alpha$는 실수)일 때, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이다.\n1st $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}}=2$를 이용하여 함수 $f(x)$의 차수와 최고차항의 계수를 구해. $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}}=2$이므로 (두 다항함수 $F(x)$, $G(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{F(x)}{G(x)}=\\alpha$($\\alpha \\ne 0$인 실수)이면 $F(x)$, $G(x)$의 차수는 같고, $\\alpha=\\frac{F(x)\\text{의 최고차항의 계수}}{G(x)\\text{의 최고차항의 계수}}$야.) 함수 $f(x)$는 최고차항의 계수가 $2$인 이차함수이다. 즉, $f(x)=2x^{2}+ax+b$($a$, $b$는 상수)라 하자.\n2nd $\\lim_{x \\to 2} \\frac{f(x)}{x-2}=7$을 이용하여 함수 $f(x)$의 식을 완성해. 한편, $\\lim_{x \\to 2} \\frac{f(x)}{x-2}=7$에서 $x \\to 2$일 때, 극한값이 존재하고 $\\lim_{x \\to 2}(x-2)=0$이므로 $\\lim_{x \\to 2} f(x)=f(2)=0$이어야 한다. (두 함수 $F(x)$, $G(x)$에 대하여 $\\lim_{x \\to a} \\frac{F(x)}{G(x)}=\\alpha$($\\alpha$는 실수)이고 $\\lim_{x \\to a} G(x)=0$이면 $\\lim_{x \\to a} F(x)=0$이야.)\n$8+2a+b=0 \\therefore b=-2(a+4)$\n$f(x)=2x^{2}+ax+b$에 $b=-2(a+4)$를 대입하여 정리하면 $f(x)=2x^{2}+ax-2(a+4)=(x-2)(2x+a+4)$이므로 $(f(x)=2x^{2}+ax-2a-8=2(x^{2}-4)+a(x-2)=2(x+2)(x-2)+a(x-2)=(x-2)(2x+a+4))$\n$\\lim_{x \\to 2} \\frac{f(x)}{x-2}=\\lim_{x \\to 2} \\frac{(x-2)(2x+a+4)}{x-2}=\\lim_{x \\to 2}(2x+a+4)=4+a+4=a+8=7$\n$\\therefore a=-1$, $b=-2 \\times (-1+4)=-6$\n따라서 $f(x)=2x^{2}-x-6$이므로 $f(4)=32-4-6=22$\n[다른 풀이: 함수 $f(x)$가 $x-2$를 인수로 가짐을 이용하기] $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}}=2$이므로 함수 $f(x)$는 최고차항의 계수가 $2$인 이차함수야. 또, $\\lim_{x \\to 2} \\frac{f(x)}{x-2}=7$에서 $x \\to 2$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 해. 즉, $\\lim_{x \\to 2} f(x)=f(2)=0$이므로 함수 $f(x)$는 $x-2$를 인수로 가져. (다항함수 $f(x)$가 $f(a)=0$을 만족시키면 함수 $f(x)$는 $x-a$를 인수로 가져.)\n즉, $f(x)=2(x-2)(x-a)$ ($a$는 상수)라 하면 $\\lim_{x \\to 2} \\frac{f(x)}{x-2}=\\lim_{x \\to 2} \\frac{2(x-2)(x-a)}{x-2}=\\lim_{x \\to 2} 2(x-a)=2(2-a)=4-2a=7$\n$2a=-3 \\therefore a=-\\frac{3}{2}$\n따라서 $f(x)=2(x-2)\\left(x+\\frac{3}{2}\\right)$이므로 $f(4)=2 \\times 2 \\times \\frac{11}{2}=22$", "img": "IMG_4941.jpg,IMG_4942.jpg"}, {"id": "A164", "section": "A", "num": 164, "page": 37, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "④", "rate": "89%", "problem": "다항함수 $f(x)$가 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}}=2$, $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=3$을 만족시킬 때, $f(3)$의 값은? (3점)", "explanation": "정답 공식: 다항함수 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{n}}=c$($c$는 $0$이 아닌 실수, $n$은 자연수)이면 $f(x)$의 차수는 $n$이고, 최고차항의 계수는 $c$이다. 또한, $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$($\\alpha$는 실수)일 때, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이다.\n1st 다항함수 $f(x)$의 차수와 최고차항의 계수를 구하자. $f(x)$가 $3$차 이상의 다항함수이면 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}}$는 발산한다. 또한, $f(x)$가 $1$차 이하의 다항함수이면 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}}=0$이다. 따라서 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}}=2$이려면 $f(x)$는 이차함수이어야 한다. 즉, $f(x)=ax^{2}+bx+c$ ($a$, $b$, $c$는 상수, $a \\ne 0$)이라 하면 $\\lim_{x \\to \\infty} \\frac{ax^{2}+bx+c}{x^{2}}=2$에서 $a=2$ ($\\frac{\\infty}{\\infty}$ 꼴이므로 분모와 분자를 각각 분모의 최고차항인 $x^{2}$으로 나누어서 계산하면 돼.)\n2nd 함수 $f(x)$를 구하자. $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=\\lim_{x \\to 1} \\frac{2x^{2}+bx+c}{x-1}=3$에서 $\\lim_{x \\to 1}(x-1)=0$이므로 $\\lim_{x \\to 1}(2x^{2}+bx+c)=0$ (분모가 $0$에 수렴하므로 분자도 $0$에 수렴하는 $\\frac{0}{0}$ 꼴이어야 극한값이 존재해.)\n$2+b+c=0 \\therefore c=-2-b \\cdots$ ㉠\n$\\lim_{x \\to 1} \\frac{2x^{2}+bx+c}{x-1}=\\lim_{x \\to 1} \\frac{2x^{2}+bx-2-b}{x-1}$ ($\\because$ ㉠)$=\\lim_{x \\to 1} \\frac{(2x+2+b)(x-1)}{x-1}=\\lim_{x \\to 1}(2x+2+b)=4+b$\n$4+b=3 \\therefore b=-1$\n$b=-1$을 ㉠에 대입하면 $c=-2-(-1)=-1$\n따라서 $f(x)=2x^{2}-x-1$이므로 $f(3)=2 \\times 3^{2}-3-1=14$", "img": "IMG_4942.jpg", "answer_value": "$14$"}, {"id": "A165", "section": "A", "num": 165, "page": 37, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "⑤", "rate": "83%", "problem": "다항함수 $f(x)$가 $\\lim_{x \\to \\infty} \\frac{f(x)-3x^{2}}{x}=10$, $\\lim_{x \\to 1} f(x)=20$을 만족시킬 때, $f(0)$의 값은? (3점)", "explanation": "정답 공식: 다항함수 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{n}}=c$($c$는 상수)이면 $f(x)$의 차수는 $n$이고, 최고차항의 계수는 $c$이다.\n1st $\\lim_{x \\to \\infty} \\frac{f(x)-3x^{2}}{x}$을 이용하여 함수 $f(x)$를 유추해. $\\lim_{x \\to \\infty} \\frac{f(x)-3x^{2}}{x}=10$과 같이 수렴하려면 분모와 분자의 차수가 $1$로 같고, 분자인 $f(x)-3x^{2}$의 최고차항의 계수는 $10$이어야 한다. (다항함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)}=\\alpha$($\\alpha \\ne 0$인 실수)이면 $f(x)$, $g(x)$의 차수는 같고, $\\alpha=\\frac{f(x)\\text{의 최고차항의 계수}}{g(x)\\text{의 최고차항의 계수}}$야.) 즉, $f(x)-3x^{2}=10x+a$ ($a$는 상수)라 놓을 수 있으므로 $f(x)=3x^{2}+10x+a$이다.\n2nd $\\lim_{x \\to 1} f(x)=20$을 이용하여 함수 $f(x)$를 완성해. 이때, $\\lim_{x \\to 1} f(x)=20$이므로 ($f(x)$가 다항함수이므로 $\\lim_{x \\to 1} f(x)=f(1)$이야.) $f(1)=3+10+a=20 \\therefore a=7$\n따라서 $f(x)=3x^{2}+10x+7$이므로 $f(0)=7$", "img": "IMG_4942.jpg", "answer_value": "$7$"}, {"id": "A166", "section": "A", "num": 166, "page": 37, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "$34$", "rate": "77%", "problem": "다항함수 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)-2x^{3}}{x^{2}}=\\lim_{x \\to 0} \\frac{f(x)}{x}=3$일 때, $f(2)$의 값을 구하시오. (3점)", "explanation": "정답 공식: 다항함수 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{n}}=c$ ($c$는 $0$이 아닌 실수, $n$은 자연수)이면 $f(x)$의 차수는 $n$이고, 최고차항의 계수는 $c$이다. $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ ($\\alpha$는 실수)일 때, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이다.\n1st $\\lim_{x \\to \\infty} \\frac{f(x)-2x^{3}}{x^{2}}=3$을 이용하여 함수 $f(x)$의 차수와 최고차항의 계수를 구해. $\\lim_{x \\to \\infty} \\frac{f(x)-2x^{3}}{x^{2}}=3$이므로 다항함수 $f(x)$에 대하여 $f(x)-2x^{3}$은 최고차항의 계수가 $3$인 이차함수이다. ($f(x)-2x^{3}$은 최고차항의 계수가 $3$인 이차함수가 되어야 하므로 함수 $f(x)$는 $2x^{3}$을 항으로 갖는 삼차함수가 되어야 해.) 즉, $f(x)-2x^{3}=3x^{2}+ax+b$ ($a$, $b$는 상수)라 할 수 있다. 따라서 $f(x)=2x^{3}+3x^{2}+ax+b$ ($a$, $b$는 상수)라 하자.\n2nd $\\lim_{x \\to 0} \\frac{f(x)}{x}=3$을 이용하여 함수 $f(x)$의 식을 완성하고 $f(2)$의 값을 구해. 한편, $\\lim_{x \\to 0} \\frac{f(x)}{x}=3$에서 $x \\to 0$일 때 극한값이 존재하고, $\\lim_{x \\to 0} x=0$이므로 $\\lim_{x \\to 0} f(x)=f(0)=0$이어야 한다. (두 함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ ($\\alpha$는 실수)이고, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이야.)\n$f(x)=2x^{3}+3x^{2}+ax+b$에서 $f(0)=0$이므로 $f(0)=b=0$\n$\\therefore f(x)=2x^{3}+3x^{2}+ax$\n$\\lim_{x \\to 0} \\frac{f(x)}{x}=\\lim_{x \\to 0} \\frac{2x^{3}+3x^{2}+ax}{x}=\\lim_{x \\to 0} \\frac{x(2x^{2}+3x+a)}{x}$ ($x \\to 0$이므로 분모와 분자의 인수 $x$는 약분이 돼.)$=\\lim_{x \\to 0}(2x^{2}+3x+a)=a$\n$\\therefore a=3$\n따라서 $f(x)=2x^{3}+3x^{2}+3x$이므로 $f(2)=16+12+6=34$이다.", "img": "IMG_4942.jpg,IMG_4943.jpg"}, {"id": "A167", "section": "A", "num": 167, "page": 38, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "$9$", "rate": "77%", "problem": "다항함수 $f(x)$가 $\\lim_{x \\to \\infty} \\frac{f(x)}{2x^{2}}=1$, $\\lim_{x \\to 1} \\frac{f(x)-3}{(x-1)(x-2)}=4$를 만족시킬 때, $f(4)$의 값을 구하시오. (4점)", "explanation": "정답 공식: 두 다항함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to a} \\frac{f(x)}{g(x)}$가 $\\frac{0}{0}$ 꼴이면 분자, 분모를 인수분해한 후 공통인수를 약분한다.\n1st $\\lim_{x \\to \\infty} \\frac{f(x)}{2x^{2}}=1$에서 $f(x)$의 식을 유추하자. $f(x)$가 다항함수이고 $\\lim_{x \\to \\infty} \\frac{f(x)}{2x^{2}}=1$이므로 $f(x)$는 이차함수이고, (다항함수 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{n}}=c$($c$는 $0$이 아닌 실수, $n$은 자연수)이면 $f(x)$의 차수는 $n$이고, 최고차항의 계수는 $c$야.) $\\frac{f(x)\\text{의 최고차항의 계수}}{2}=1$이므로 $f(x)$의 최고차항의 계수는 $2$이다. 따라서 $f(x)=2x^{2}+ax+b$ ($a$, $b$는 상수) $\\cdots$ ㉠라 놓을 수 있다.\n2nd $\\lim_{x \\to 1} \\frac{f(x)-3}{(x-1)(x-2)}$의 극한값이 존재함을 이용하자. $\\lim_{x \\to 1} \\frac{f(x)-3}{(x-1)(x-2)}=4$이고 $\\lim_{x \\to 1}(x-1)(x-2)=0$이므로 $\\lim_{x \\to 1}\\{f(x)-3\\}=0$이어야 한다. ($\\lim_{x \\to a} \\frac{g(x)}{h(x)}=\\alpha$ (단, $\\alpha$는 상수)이고, $\\lim_{x \\to a} h(x)=0$이면 $\\lim_{x \\to a} g(x)=0$이 성립해.) 즉, $f(1)-3=0$에서 $f(1)=3$이므로 ㉠에 의해 $2+a+b=3 \\therefore b=-a+1$\n3rd $\\lim_{x \\to 1} \\frac{f(x)-3}{(x-1)(x-2)}=4$임을 이용해 $a$, $b$의 값을 구하자. $f(x)-3=2x^{2}+ax-a+1-3=2x^{2}+ax-a-2=(x-1)(2x+a+2)$이므로 ($f(x)=2x^{2}+ax+b$에 $b=-a+1$을 대입한 거야. $2x^{2}+ax-a-2=2(x^{2}-1)+a(x-1)=2(x+1)(x-1)+a(x-1)=(x-1)(2x+2+a)$)\n$\\lim_{x \\to 1} \\frac{f(x)-3}{(x-1)(x-2)}=\\lim_{x \\to 1} \\frac{(x-1)(2x+a+2)}{(x-1)(x-2)}=\\lim_{x \\to 1} \\frac{2x+a+2}{x-2}=\\frac{2+a+2}{-1}=4$\n$a+4=-4 \\therefore a=-8$\n$a=-8$을 $b=-a+1$에 대입하면 $b=-(-8)+1=9$\n따라서 $f(x)=2x^{2}-8x+9$이므로 $f(4)=2 \\times 4^{2}-8 \\times 4+9=9$", "img": "IMG_4943.jpg"}, {"id": "A168", "section": "A", "num": 168, "page": 38, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "③", "rate": "67%", "problem": "상수항과 계수가 모두 정수인 두 다항함수 $f(x)$, $g(x)$가 다음 조건을 만족시킬 때, $f(2)$의 최댓값은? (4점) (가) $\\lim_{x \\to \\infty} \\frac{f(x)g(x)}{x^{3}}=2$ (나) $\\lim_{x \\to 0} \\frac{f(x)g(x)}{x^{2}}=-4$", "explanation": "정답 공식: 다항식 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{n}}=c$($c$는 $0$이 아닌 실수, $n$은 자연수)이면 $f(x)$의 차수는 $n$이고, 최고차항의 계수는 $c$이다. $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$($\\alpha$는 실수)일 때, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이다.\n1st 주어진 조건을 이용하여 함수 $f(x)g(x)$를 유추해. 조건 (가)에서 $\\lim_{x \\to \\infty} \\frac{f(x)g(x)}{x^{3}}=2$이므로 다항함수 $f(x)g(x)$는 최고차항의 계수가 $2$인 삼차함수이다. (두 다항함수 $F(x)$, $G(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{F(x)}{G(x)}=\\alpha$($\\alpha \\ne 0$인 실수)이면 $F(x)$, $G(x)$의 차수는 같고, $\\alpha=\\frac{F(x)\\text{의 최고차항의 계수}}{G(x)\\text{의 최고차항의 계수}}$야.)\n또, 조건 (나)에서 $\\lim_{x \\to 0} \\frac{f(x)g(x)}{x^{2}}=-4$에서 극한값이 존재하고 $x \\to 0$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. $\\therefore \\lim_{x \\to 0} f(x)g(x)=f(0)g(0)=0$ ($f(x)$, $g(x)$가 다항함수이므로 $\\lim_{x \\to 0} f(x)g(x)=f(0)g(0)$이지? 즉, $f(0)g(0)=0$이야.)\n즉, 함수 $f(x)g(x)$는 $x^{2}$을 인수로 갖는 최고차항의 계수가 $2$인 삼차함수이므로 $f(x)g(x)=2x^{2}(x+a)$ (단, $a$는 상수)로 놓을 수 있다. ($f(x)g(x)$는 $x=0$이라는 $x$를 인수로 갖는데, $\\lim_{x \\to 0} \\frac{f(x)g(x)}{x^{2}}$의 값이 존재하므로 $x^{2}$을 인수로 가져야 해.)\n2nd 조건 (나)에 $f(x)g(x)$의 식을 대입하여 상수 $a$의 값을 구하자. $\\lim_{x \\to 0} \\frac{f(x)g(x)}{x^{2}}=\\lim_{x \\to 0} \\frac{2x^{2}(x+a)}{x^{2}}=\\lim_{x \\to 0} 2(x+a)=2(0+a)=-4$에서 $a=-2$이므로 $f(x)g(x)=2x^{2}(x-2)$\n3rd $f(2)$의 최댓값을 구하자. 상수항과 계수가 모두 정수인 두 다항함수 $f(x)$, $g(x)$의 곱이 $f(x)g(x)=2x^{2}(x-2)$이므로 $f(x)$는 $2x^{2}(x-2)$의 인수이고, $f(2)$의 값이 최대가 되려면 $f(x)=2x^{2}$이다. ($f(x)$가 $2x^{2}(x-2)$의 인수 중 $x-2$를 가지면 $f(2)=0$인데 주어진 선택지를 보면 $f(2)$의 최댓값이 자연수임을 알 수 있지? 즉, $f(x)$는 $x-2$를 인수로 갖지 않아.)\n따라서 구하는 $f(2)$의 최댓값은 $2 \\times 2^{2}=8$이다.\n(선배 코멘트) 조건 (가)를 통해서는 $f(x)g(x)$의 최고차항이 $3$차이고 그 계수가 $2$인 것을, 조건 (나)를 통해서는 $f(x)g(x)$의 최소 차항이 $2$차이고 그 계수가 $-4$인 것을 알 수 있어. 그렇다면 $f(x)g(x)=2x^{2}(x-2)$인데, $f(x)$의 상수항과 계수는 모두 정수이므로 $f(x)$는 상수함수 또는 일차함수 또는 이차함수 또는 삼차함수면서 최고차항의 계수가 $\\pm 1$ 또는 $\\pm 2$가 돼. 그런데 구하는 값이 $f(2)$의 최댓값이고, $f(x)$가 $x-2$를 인수로 가지면 $f(2)$의 값은 $0$이 되니까 $f(2)$의 값이 가장 큰 경우는 $f(x)=2x^{2}$일 때야.", "img": "IMG_4943.jpg", "answer_value": "$8$"}, {"id": "A169", "section": "A", "num": 169, "page": 39, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "③", "rate": "71%", "problem": "다항함수 $f(x)$가 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{3}}=1$, $\\lim_{x \\to -1} \\frac{f(x)}{x+1}=2$를 만족시킨다. $f(1) \\le 12$일 때, $f(2)$의 최댓값은? (4점)", "explanation": "정답 공식: 다항식 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{n}}=c$($c$는 $0$이 아닌 상수)이면 $f(x)$의 차수는 $n$이고, 최고차항의 계수는 $c$이다. 또한, $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$($\\alpha$는 상수)일 때 $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이다.\n1st 주어진 조건을 이용하여 다항함수 $f(x)$의 식을 유추해. $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{3}}=1$이므로 다항함수 $f(x)$는 최고차항의 계수가 $1$인 삼차함수이다. $\\cdots$ ㉠ (두 다항함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)}=\\alpha$($\\alpha \\ne 0$인 실수)이면 $f(x)$, $g(x)$의 차수는 같고, $\\alpha=\\frac{f(x)\\text{의 최고차항의 계수}}{g(x)\\text{의 최고차항의 계수}}$야.)\n또, $\\lim_{x \\to -1} \\frac{f(x)}{x+1}=2$에서 $x \\to -1$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to -1} f(x)=f(-1)=0$이다. $\\cdots$ ㉡\n따라서 ㉠, ㉡에서 $f(x)=(x+1)(x^{2}+ax+b)$ (단, $a$, $b$는 상수)로 놓을 수 있다. ($f(-1)=0$이므로 $f(x)$는 $x+1$을 인수로 가져.)\n2nd $f(1) \\le 12$를 이용하여 $f(2)$의 최댓값을 구하자. (이렇게 $f(x)$의 식을 세우면 계산이 훨씬 간단해져.) 이때, $\\lim_{x \\to -1} \\frac{f(x)}{x+1}=2$에서 $\\lim_{x \\to -1} \\frac{f(x)}{x+1}=\\lim_{x \\to -1} \\frac{(x+1)(x^{2}+ax+b)}{x+1}=\\lim_{x \\to -1}(x^{2}+ax+b)=1-a+b=2$\n이므로 $b=a+1$\n즉, $f(x)=(x+1)(x^{2}+ax+a+1)$이고, $f(1) \\le 12$이므로 $f(1)=2(2a+2)=4(a+1) \\le 12$\n$a+1 \\le 3 \\therefore a \\le 2$\n따라서 $f(2)=3(3a+5)=9a+15$이고 $9a+15 \\le 9 \\times 2+15=33$이므로 $f(2)$의 최댓값은 $33$이다.\n[톡톡 풀이: $f(-1)$, $f'(-1)$의 값 이용하기] $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{3}}=1$에서 다항함수 $f(x)$는 최고차항의 계수가 $1$인 삼차함수야. 또, $\\lim_{x \\to -1} \\frac{f(x)}{x+1}=2$에서 $x \\to -1$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 해. 즉, $\\lim_{x \\to -1} f(x)=f(-1)=0$이므로\n$\\lim_{x \\to -1} \\frac{f(x)}{x+1}=\\lim_{x \\to -1} \\frac{f(x)-f(-1)}{x-(-1)}=f'(-1)=2 \\left(f'(a)=\\lim_{x \\to a} \\frac{f(x)-f(a)}{x-a}\\right)$\n따라서 $f(x)=x^{3}+px^{2}+qx+r$ (단, $p$, $q$, $r$는 상수)라 하면 $f(-1)=0$에서 $-1+p-q+r=0 \\therefore p-q+r=1 \\cdots$ ㉢\n또, $f'(x)=3x^{2}+2px+q$이므로 $f'(-1)=2$에서 $3-2p+q=2 \\therefore q=2p-1 \\cdots$ ㉣\n㉣을 ㉢에 대입하면 $p-(2p-1)+r=1 \\therefore r=p \\cdots$ ㉤\n㉣, ㉤을 $f(x)$의 식에 대입하면 $f(x)=x^{3}+px^{2}+(2p-1)x+p$\n이때, $f(1) \\le 12$이므로 $f(1)=1+p+2p-1+p=4p \\le 12 \\therefore p \\le 3$\n따라서 $f(2)=8+4p+4p-2+p=9p+6 \\le 9 \\times 3+6=33$이므로 $f(2)$의 최댓값은 $33$이야.", "img": "IMG_4944.jpg", "answer_value": "$33$"}, {"id": "A170", "section": "A", "num": 170, "page": 39, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "③", "rate": "60%", "problem": "다음 조건을 만족시키는 모든 다항함수 $f(x)$에 대하여 $f(1)$의 최댓값은? (4점) $\\lim_{x \\to \\infty} \\frac{f(x)-4x^{3}+3x^{2}}{x^{n+1}+1}=6$, $\\lim_{x \\to 0} \\frac{f(x)}{x^{n}}=4$인 자연수 $n$이 존재한다.", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한값이 존재하면 분모와 분자의 차수가 같아야 하고, $\\frac{0}{0}$ 꼴의 극한값이 존재하면 분모와 분자를 $0$으로 만드는 공통인수가 존재한다.\n1st 함수 $f(x)$가 다항함수이고 $n$이 자연수이므로 먼저 $n=1$일 때의 $f(1)$의 값을 구해봐. (함정: $\\lim_{x \\to \\infty} \\frac{f(x)-4x^{3}+3x^{2}}{x^{n+1}+1}=6$에서 분자가 $f(x)$가 아닌 $f(x)-4x^{3}+3x^{2}$이기 때문에 $n=1$, $n=2$, $n \\ge 3$인 경우로 각각 나눠서 생각해야 해.)\n(i) $n=1$일 때, $\\lim_{x \\to \\infty} \\frac{f(x)-4x^{3}+3x^{2}}{x^{2}+1}=6$이므로 $f(x)-4x^{3}+3x^{2}=6x^{2}+ \\cdots$이어야 한다. ($\\frac{\\infty}{\\infty}$ 꼴이므로 분모, 분자의 차수가 같아야 극한값이 존재해. 따라서 분모의 차수가 $2$이므로 분자의 차수도 $2$이고 극한값이 $6$이므로 $x^{2}$의 계수가 $6$이어야 하지.) 즉, $f(x)=4x^{3}+3x^{2}+ax+b$ ($a$, $b$는 상수)라 하면 $\\lim_{x \\to 0} \\frac{f(x)}{x}=4$이므로 $\\lim_{x \\to 0} \\frac{4x^{3}+3x^{2}+ax+b}{x}=\\lim_{x \\to 0}\\left(4x^{2}+3x+a+\\frac{b}{x}\\right)=4 \\therefore a=4$, $b=0$ ($\\lim_{x \\to 0+} \\frac{1}{x}=\\infty$, $\\lim_{x \\to 0-} \\frac{1}{x}=-\\infty$이므로 $b$가 $0$이 아닌 상수이면 주어진 극한값이 존재하지 않아. 따라서 $b=0$이고, $\\lim_{x \\to 0}(4x^{2}+3x+a)=a=4$야.)\n따라서 $f(x)=4x^{3}+3x^{2}+4x$이므로 $f(1)=4+3+4=11$\n2nd $n=2$일 때, $f(1)$의 값을 구해. (ii) $n=2$일 때, $\\lim_{x \\to \\infty} \\frac{f(x)-4x^{3}+3x^{2}}{x^{3}+1}=6$이므로 $f(x)-4x^{3}+3x^{2}=6x^{3}+ \\cdots$이어야 한다. ($\\frac{\\infty}{\\infty}$ 꼴이므로 분모, 분자의 차수가 같아야 극한값이 존재해. 따라서 분모의 차수가 $3$이므로 분자의 차수도 $3$이고 극한값이 $6$이므로 $x^{3}$의 계수가 $6$이어야 해.) 즉, $f(x)=10x^{3}+ax^{2}+bx+c$ ($a$, $b$, $c$는 상수)라 하면 $\\lim_{x \\to 0} \\frac{f(x)}{x^{2}}=4$이므로 $\\lim_{x \\to 0} \\frac{10x^{3}+ax^{2}+bx+c}{x^{2}}=\\lim_{x \\to 0}\\left(10x+a+\\frac{b}{x}+\\frac{c}{x^{2}}\\right)=4 \\therefore a=4$, $b=0$, $c=0$ ($\\lim_{x \\to 0+} \\frac{1}{x}=\\infty$, $\\lim_{x \\to 0-} \\frac{1}{x}=-\\infty$, $\\lim_{x \\to 0} \\frac{1}{x^{2}}=\\infty$이므로 $b$와 $c$가 $0$이 아닌 상수이면 주어진 극한값이 존재하지 않지? 따라서 $b=0$, $c=0$이고, $\\lim_{x \\to 0}(10x+a)=a=4$야.)\n따라서 $f(x)=10x^{3}+4x^{2}$이므로 $f(1)=10+4=14$\n3rd $n \\ge 3$일 때, $f(1)$의 값을 구하자. (iii) $n \\ge 3$일 때, $\\lim_{x \\to \\infty} \\frac{f(x)-4x^{3}+3x^{2}}{x^{n+1}+1}=6$이므로 $f(x)-4x^{3}+3x^{2}=6x^{n+1}+ \\cdots$이어야 한다. ($\\frac{\\infty}{\\infty}$ 꼴이므로 분모, 분자의 차수가 같아야 극한값이 존재해. 따라서 분모의 차수가 $n+1$이므로 분자의 차수도 $n+1$이고 극한값이 $6$이므로 $x^{n+1}$의 계수가 $6$이어야 해.) 즉, $f(x)=6x^{n+1}+a_{n} x^{n}+a_{n-1}x^{n-1}+ \\cdots +a_{1} x+a_{0}$ ($a_{n}$, $a_{n-1}$, $\\cdots$, $a_{1}$, $a_{0}$은 상수)라 하면 $\\lim_{x \\to 0} \\frac{f(x)}{x^{n}}=4$이므로 $\\lim_{x \\to 0} \\frac{6x^{n+1}+a_{n} x^{n}+a_{n-1}x^{n-1}+ \\cdots +a_{0}}{x^{n}}=\\lim_{x \\to 0}\\left(6x+a_{n}+\\frac{a_{n-1}}{x}+ \\cdots +\\frac{a_{0}}{x^{n}}\\right)=4$\n$\\therefore a_{n}=4$, $a_{n-1}= \\cdots=a_{0}=0$\n따라서 $f(x)=6x^{n+1}+4x^{n}$이므로 $f(1)=6+4=10$\n(i)~(iii)에 의하여 $f(1)$의 최댓값은 $14$이다.", "img": "IMG_4944.jpg,IMG_4945.jpg", "answer_value": "$14$"}, {"id": "A171", "section": "A", "num": 171, "page": 40, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "④", "rate": "61%", "problem": "최고차항의 계수가 $1$인 이차함수 $f(x)$가 $\\lim_{x \\to 0}|x|\\left\\{ f\\left(\\frac{1}{x}\\right)-f\\left(-\\frac{1}{x}\\right) \\right\\}=a$, $\\lim_{x \\to \\infty} f\\left(\\frac{1}{x}\\right)=3$을 만족시킬 때, $f(2)$의 값은? (단, $a$는 상수이다.) (4점)", "explanation": "정답 공식: 최고차항의 계수가 $1$인 이차함수 $f(x)$를 $f(x)=x^{2}+px+q$라 두고 주어진 극한식에 대입한다.\n1st 최고차항의 계수가 $1$인 이차함수 $f(x)$를 정하고 $\\lim_{x \\to 0}|x|\\left\\{ f\\left(\\frac{1}{x}\\right)-f\\left(-\\frac{1}{x}\\right) \\right\\}$이 수렴함을 이용하여 이차함수의 계수를 구하자. $f(x)$는 최고차항의 계수가 $1$인 이차함수이므로 $f(x)=x^{2}+px+q$ (단, $p$, $q$는 상수)라 하자.\n이때, $\\lim_{x \\to 0}|x|\\left\\{ f\\left(\\frac{1}{x}\\right)-f\\left(-\\frac{1}{x}\\right) \\right\\}=a$이므로 ($x \\to 0$일 때, 주어진 식이 극한값 $a$를 가지므로 $x=0$에서의 좌극한값과 우극한값이 같아야 해.) $\\lim_{x \\to 0+} x\\left\\{ f\\left(\\frac{1}{x}\\right)-f\\left(-\\frac{1}{x}\\right) \\right\\}=\\lim_{x \\to 0-}(-x)\\left\\{ f\\left(\\frac{1}{x}\\right)-f\\left(-\\frac{1}{x}\\right) \\right\\}=a$ $\\left(|x|=\\begin{cases} x & (x \\ge 0) \\\\ -x & (x<0) \\end{cases}\\right)$\n$\\frac{1}{x}=t$로 치환하면 $x \\to 0+$일 때, $t \\to \\infty$이고, $x \\to 0-$일 때, $t \\to -\\infty$이므로 (식을 치환할 때 그래프를 그려보면 실수를 방지할 수 있어.)\n(i) $\\lim_{x \\to 0+} x\\left\\{ f\\left(\\frac{1}{x}\\right)-f\\left(-\\frac{1}{x}\\right) \\right\\}=\\lim_{t \\to \\infty} \\frac{f(t)-f(-t)}{t}=\\lim_{t \\to \\infty} \\frac{t^{2}+pt+q-\\{(-t)^{2}-pt+q\\}}{t}=\\lim_{t \\to \\infty} \\frac{2pt}{t}=2p$ ($f(x)=x^{2}+px+q$에서 $x$ 대신에 $t$, $-t$를 각각 대입한 거야.)\n(ii) $\\lim_{x \\to 0-}(-x)\\left\\{ f\\left(\\frac{1}{x}\\right)-f\\left(-\\frac{1}{x}\\right) \\right\\}=\\lim_{t \\to -\\infty} \\frac{f(t)-f(-t)}{-t}=\\lim_{t \\to -\\infty} \\frac{t^{2}+pt+q-\\{(-t)^{2}-pt+q\\}}{-t}=\\lim_{t \\to -\\infty}\\left(-\\frac{2pt}{t}\\right)=-2p$\n(i), (ii)에서 $2p=-2p=a \\therefore p=0$\n즉, $f(x)=x^{2}+q$이다.\n2nd $\\lim_{x \\to \\infty} f\\left(\\frac{1}{x}\\right)=3$을 이용하여 이차함수의 식을 완성하자. 따라서 $\\lim_{x \\to \\infty} f\\left(\\frac{1}{x}\\right)=\\lim_{x \\to \\infty}\\left(\\frac{1}{x^{2}}+q\\right)=q=3$이므로 $\\left(\\lim_{x \\to \\infty} \\frac{1}{x^{2}}=0\\right) f(x)=x^{2}+3 \\therefore f(2)=2^{2}+3=7$\n[다른 풀이: 최고차항의 계수가 $1$인 이차함수 $f(x)$를 직접 대입하여 해결하기] $f(x)=x^{2}+px+q$ (단, $p$, $q$는 상수)라 할 때, $\\lim_{x \\to \\infty} f\\left(\\frac{1}{x}\\right)=\\lim_{x \\to \\infty}\\left(\\frac{1}{x^{2}}+\\frac{p}{x}+q\\right)=q=3$\n한편, $\\lim_{x \\to 0}|x|\\left\\{ f\\left(\\frac{1}{x}\\right)-f\\left(-\\frac{1}{x}\\right) \\right\\}=\\lim_{x \\to 0}|x|\\left\\{ \\left(\\frac{1}{x^{2}}+\\frac{p}{x}+q\\right)-\\left(\\frac{1}{x^{2}}-\\frac{p}{x}+q\\right) \\right\\}=\\lim_{x \\to 0} \\frac{2p|x|}{x}=a$\n이므로 $\\lim_{x \\to 0} \\frac{2p|x|}{x}$의 값이 존재해야 하지? 즉, $\\lim_{x \\to 0+} \\frac{2p|x|}{x}=\\lim_{x \\to 0+} \\frac{2px}{x}=2p$, $\\lim_{x \\to 0-} \\frac{2p|x|}{x}=\\lim_{x \\to 0-} \\frac{-2px}{x}=-2p$에서 $2p=-2p \\therefore p=0$\n따라서 $f(x)=x^{2}+3$이므로 $f(2)=2^{2}+3=7$", "img": "IMG_4945.jpg", "answer_value": "$7$"}, {"id": "A172", "section": "A", "num": 172, "page": 40, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "$36$", "rate": "65%", "problem": "이차함수 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}+2x+3}=1$, $\\lim_{x \\to 3} \\frac{f(x)}{x-3}=5$일 때, $f(7)$의 값을 구하시오. (3점)", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한에서 함수의 차수와 최고차항의 계수를 파악하고 $\\frac{0}{0}$ 꼴의 극한에서 상수항을 파악한다.\n1st $\\lim_{x \\to \\infty} \\frac{g(x)}{h(x)}=\\alpha$(단, $\\alpha \\ne 0$인 상수)이면 두 함수 $g(x)$, $h(x)$는 같은 차수의 다항식이야. $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}+2x+3}=1$이 성립하므로 $f(x)$의 이차항의 계수는 $1$이다. ($\\lim_{x \\to \\infty} \\frac{g(x)}{h(x)}=\\alpha$($\\alpha \\ne 0$인 상수)이면 $g(x)$, $h(x)$는 같은 차수의 다항식이고, 극한값은 최고차항의 계수의 비야.)\n2nd $\\lim_{x \\to a} \\frac{g(x)}{h(x)}=\\alpha$(단, $\\alpha$는 상수)이고, $\\lim_{x \\to a} h(x)=0$이면 $\\lim_{x \\to a} g(x)=0$이 성립해. $\\lim_{x \\to 3} \\frac{f(x)}{x-3}=5$이고 $\\lim_{x \\to 3}(x-3)=0$이므로 $\\lim_{x \\to 3} f(x)=0 \\therefore \\lim_{x \\to 3} f(x)=f(3)=0$ ($f(x)$는 다항식이고, $f(a)=0$이면 인수정리에 의해 $f(x)$는 $x-a$라는 인수를 가지므로 $f(x)=(x-a)Q(x)$ 꼴로 나타낼 수 있는 거야.)\n$f(x)$는 최고차항의 계수가 $1$이고, $f(3)=0$이므로 $f(x)=(x-3)(x+a)$라 놓을 수 있다.\n3rd 구한 $f(x)$를 주어진 식에 대입하여 $f(x)$를 구하자. $\\lim_{x \\to 3} \\frac{f(x)}{x-3}=\\lim_{x \\to 3} \\frac{(x-3)(x+a)}{x-3}=\\lim_{x \\to 3}(x+a)=3+a$\n$\\lim_{x \\to 3} \\frac{f(x)}{x-3}=5$이므로 $3+a=5 \\therefore a=2$\n즉, $f(x)=(x-3)(x+2)$이므로 $f(7)=(7-3)(7+2)=36$", "img": "IMG_4945.jpg,IMG_4946.jpg"}, {"id": "A173", "section": "A", "num": 173, "page": 41, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "$13$", "rate": "69%", "problem": "다항함수 $f(x)$가 다음 조건을 만족시킬 때, $f(2)$의 값을 구하시오. (4점) (가) $\\lim_{x \\to \\infty} \\frac{f(x)-x^{3}}{3x}=2$ (나) $\\lim_{x \\to 0} f(x)=-7$", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한에서 함수의 차수와 최고차항의 계수를 파악하고 $\\frac{0}{0}$ 꼴의 극한에서 상수항을 파악한다.\n1st 다항식 $f(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{n}}=c$($c \\ne 0$인 상수)이면 $f(x)$의 차수는 $n$이고 최고차항의 계수는 $c$야. 조건 (가)에서 $\\lim_{x \\to \\infty} \\frac{f(x)-x^{3}}{3x}=2$가 되려면 분자와 분모의 차수가 같아야 하므로 분자는 일차식이어야 한다. 그리고 분모의 최고차항의 계수가 $3$이므로 분자인 $f(x)-x^{3}$의 최고차항의 계수는 $6$이어야 한다. 따라서 $f(x)-x^{3}=6x+a$ (단, $a$는 상수)라 하면 $f(x)=x^{3}+6x+a$\n2nd 조건 (나)를 이용하여 상수 $a$의 값을 구하자. 이때, 조건 (나)에서 $\\lim_{x \\to 0} f(x)=-7$이므로 $\\lim_{x \\to 0}(x^{3}+6x+a)=a=-7$ ($f(x)$가 다항함수이면 $\\lim_{x \\to a} f(x)=f(a)$야.)\n따라서 $f(x)=x^{3}+6x-7$이므로 $f(2)=2^{3}+6 \\times 2-7=13$", "img": "IMG_4946.jpg"}, {"id": "A174", "section": "A", "num": 174, "page": 41, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "⑤", "rate": "74%", "problem": "$x$에 대한 다항식 $f(x)$가 $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}+x+1}=1$, $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=2$를 만족시킬 때, $f(4)$의 값은? (3점)", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한에서 함수의 차수와 최고차항의 계수를 파악하고 $\\frac{0}{0}$ 꼴의 극한에서 상수항을 파악한다.\n1st $\\frac{\\infty}{\\infty}$ 꼴이 $0$이 아닌 극한값이 존재하려면 분모와 분자의 차수가 같아야 해. $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{2}+x+1}$가 $1$로 수렴하므로 $f(x)$는 분모의 차수와 같고 최고차항의 계수가 $1$인 이차다항식이다.\n2nd $x \\to 1$일 때, 극한값이 $2$로 존재하고 (분모)$\\to 0$이니까 (분자)$\\to 0$이어야 해. $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=2$로 극한값이 존재하고 $\\lim_{x \\to 1}(x-1)=0$이므로 $\\lim_{x \\to 1} f(x)=0 \\therefore f(1)=0$ (주의: $f(x)$가 $x-1$을 인수로 가져야 극한값이 존재해.)\n$f(x)$는 인수정리에 의해 $x-1$이라는 인수를 가진다. ([인수정리] $f(x)$가 다항식일 때, $f(a)=0$이면 $f(x)$는 $x-a$라는 인수를 가져.) 즉, $f(x)$는 $x-1$이라는 인수를 가지고 최고차항의 계수가 $1$인 이차다항식이므로 $f(x)=(x-1)(x+a)$(단, $a$는 상수)로 놓을 수 있다.\n$\\therefore \\lim_{x \\to 1} \\frac{f(x)}{x-1}=\\lim_{x \\to 1} \\frac{(x-1)(x+a)}{x-1}=\\lim_{x \\to 1}(x+a)=1+a=2$\n따라서 $a=1$이므로 $f(x)=(x-1)(x+1)$\n$\\therefore f(4)=(4-1)(4+1)=15$", "img": "IMG_4946.jpg", "answer_value": "$15$"}, {"id": "A175", "section": "A", "num": 175, "page": 41, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "$14$", "rate": "61%", "problem": "다항함수 $f(x)$가 다음 조건을 만족시킬 때, $f(3)$의 값을 구하시오. (3점) (가) $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{3}}=0$ (나) $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=1$ (다) 방정식 $f(x)=2x$의 한 근이 $2$이다.", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한에서 함수 $f(x)$의 차수를 파악하고 남은 두 조건에서 $f(x)$의 인수를 파악한다.\n1st 주어진 극한값을 이용하여 다항함수 $f(x)$의 꼴을 찾아보자. 조건 (가) $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{3}}=0$에서 극한값이 $0$이므로 $f(x)$의 차수는 $3$보다 작다. 즉, 함수 $f(x)$는 이차 이하의 다항함수이다. (주의: $\\lim_{x \\to \\infty} \\frac{f(x)}{x^{n}}=0$이면 다항함수 $f(x)$는 차수가 $n$차 미만임을 알고 있어야 해.)\n조건 (나) $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=1$에서 (분모)$\\to 0$일 때, 극한값이 존재하므로 (분자)$\\to 0$이어야 한다. 즉, $f(1)=0$이므로 $f(x)$는 $(x-1)$을 인수로 가지는 이차 이하의 다항함수이다. ($f(1)=0$이므로 $f(x)$는 일차식 $x-1$로 나누어떨어져. 즉, $f(x)$는 $x-1$을 인수로 가져.) 따라서 $f(x)=(ax+b)(x-1)$로 놓을 수 있다.\n2nd 두 조건 (나), (다)를 이용하여 $f(x)$를 구하자. 조건 (나)에 함수 $f(x)$를 대입하면 $\\lim_{x \\to 1} \\frac{(ax+b)(x-1)}{x-1}=\\lim_{x \\to 1}(ax+b)=1$ ($x-1$은 분자, 분모의 공통인수이므로 약분해.) $\\therefore a+b=1 \\cdots$ ㉠\n또한, 조건 (다)에 의해 방정식 $(ax+b)(x-1)=2x$의 한 근이 $x=2$이므로 대입하면 ($x=2$를 방정식에 대입하면 등식이 성립해야 해.) $2a+b=4 \\cdots$ ㉡ (㉡-㉠을 하면 $a=3$이고, $a=3$을 ㉠에 대입하면 $3+b=1$이므로 $b=-2$야.)\n㉠, ㉡을 연립하면 $a=3$, $b=-2$\n따라서 $f(x)=(3x-2)(x-1)$이므로 $f(3)=(3 \\times 3-2)(3-1)=14$", "img": "IMG_4946.jpg"}, {"id": "A176", "section": "A", "num": 176, "page": 42, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "②", "rate": "42%", "problem": "최고차항의 계수가 $1$인 삼차함수 $f(x)$와 최고차항의 계수가 $1$인 이차함수 $g(x)$가 다음 조건을 만족시킬 때, $f(3)+g(8)$의 값은? (4점) (가) 두 곡선 $y=f(x)$와 $y=g(x)$는 모두 직선 $y=x$ 위의 서로 다른 두 점 $A$, $B$를 지난다. (나) $\\lim_{x \\to 0} \\frac{(f(x)-x)(g(x)-x)}{x^{3}}$의 값과 $\\lim_{x \\to 0} \\frac{(f(x)+x)(g(x)+x)}{x^{3}}$의 값이 존재한다.", "explanation": "정답 공식: $\\frac{0}{0}$ 꼴의 극한에서 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st 조건 (가)를 이용하여 $f(x)-x$, $g(x)-x$의 식을 세워. 조건 (가)에서 두 곡선 $y=f(x)$와 $y=g(x)$는 모두 직선 $y=x$ 위의 서로 다른 두 점 $A$, $B$를 지나므로 두 점 $A$, $B$의 좌표를 $A(a, a)$, $B(b, b)$ (단, $a<b$)라 하자. 삼차함수 $y=f(x)$와 직선 $y=x$의 교점의 $x$좌표를 $a$, $b$, $k$라 하면 (주의: 조건 (가)에서 두 곡선이 직선과 서로 다른 두 점을 지난다고 했지? 삼차함수 $y=f(x)$의 그래프와 직선 $y=x$의 교점의 개수는 $2$ 이상이 되어야 하므로 교점의 $x$좌표를 $a$, $b$, $k$라 놓아야 해. 이때, $k$의 값이 $a$와 같다면 삼차함수 $y=f(x)$의 그래프는 직선 $y=x$와 $x=a$에서 접하고, $x=b$를 지나는 그래프가 돼. $k$의 값이 $b$와 같다면 $x=b$에서 접하고 $x=a$를 지나는 그래프가 돼. 따라서 $k$는 $a$ 또는 $b$와 같을 수도 있어.)\n$f(x)-x$는 $x-a$, $x-b$, $x-k$를 인수로 가지고, 삼차함수 $f(x)$의 최고차항의 계수가 $1$이므로 (다항식 $f(x)$에 대하여 $f(\\alpha)=0$이면 $f(x)$는 $x-\\alpha$를 인수로 가져.) $f(x)-x=(x-a)(x-b)(x-k)$ (단, $k$는 상수)라 할 수 있다. 또, 이차함수 $y=g(x)$와 직선 $y=x$의 교점의 $x$좌표를 $a$, $b$라 하면 $g(x)-x$도 $x-a$, $x-b$를 인수로 가지고, 이차함수 $g(x)$의 최고차항의 계수가 $1$이므로 $g(x)-x=(x-a)(x-b)$라 할 수 있다.\n2nd 조건 (나)에서 극한값이 존재함을 이용하여 두 함수 $f(x)$, $g(x)$를 구해. 조건 (나)에서 $\\lim_{x \\to 0} \\frac{(f(x)-x)(g(x)-x)}{x^{3}}=\\lim_{x \\to 0} \\frac{(x-a)^{2}(x-b)^{2}(x-k)}{x^{3}}$이고 극한값이 존재하려면 $\\frac{0}{0}$ 꼴이 되어야 하므로 분자에 $x^{3}$ 또는 $x^{4}$ 또는 $x^{5}$을 인수로 가져야 한다. 이때, $a \\ne b$이므로 $a$ 또는 $b$가 $0$이고 $k=0$인 경우에만 분자에 $x^{3}$을 인수로 가질 수 있다. ($a \\ne b$이므로 분자에 $x^{4}$ 또는 $x^{5}$을 인수로 가질 수 없고 $x^{3}$을 인수로 가져야 해.)\n따라서 $a=0$일 때와 $b=0$일 때로 나누어 확인한다.\n(i) $a=0$, $k=0$일 때, (삼차함수 $y=f(x)$의 그래프와 직선 $y=x$는 $x=0$에서 접하고 $x=b$를 지나는 그래프가 돼.) $f(x)-x=x^{2}(x-b)$, $f(x)=x^{2}(x-b)+x$, $g(x)-x=x(x-b)$, $g(x)=x(x-b)+x$\n이므로 $f(x)=x^{2}(x-b)+x$에서 $f(x)+x=x^{3}-bx^{2}+2x$, $g(x)=x(x-b)+x$에서 $g(x)+x=x^{2}+(2-b)x$\n한편, 조건 (나)에서 $\\lim_{x \\to 0} \\frac{(f(x)+x)(g(x)+x)}{x^{3}}$의 극한값이 존재하는지 확인하기 위해 $f(x)+x$, $g(x)+x$를 대입하면\n$\\lim_{x \\to 0} \\frac{(f(x)+x)(g(x)+x)}{x^{3}}=\\lim_{x \\to 0} \\frac{(x^{3}-bx^{2}+2x)\\{x^{2}+(2-b)x\\}}{x^{3}}=\\lim_{x \\to 0} \\frac{x^{2}(x^{2}-bx+2)\\{x+(2-b)\\}}{x^{3}}=\\lim_{x \\to 0} \\frac{(x^{2}-bx+2)\\{x+(2-b)\\}}{x} \\cdots$ ㉠\n㉠의 값이 존재하고 $x \\to 0$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 0}(x^{2}-bx+2)\\{x+(2-b)\\}$에서 $2(2-b)=0 \\therefore b=2$ (함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\alpha$ ($\\alpha$는 실수)일 때, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이야.)\n따라서 $f(x)=x^{2}(x-2)+x=x^{3}-2x^{2}+x$, $g(x)=x(x-2)+x=x^{2}-x$\n(ii) $b=0$, $k=0$일 때, $f(x)-x=x^{2}(x-a)$, $f(x)=x^{2}(x-a)+x$, $g(x)-x=x(x-a)$, $g(x)=x(x-a)+x$\n이므로 $f(x)+x=x^{3}-ax^{2}+2x$, $g(x)+x=x^{2}+(2-a)x$\n한편, 조건 (나)에서 $\\lim_{x \\to 0} \\frac{(f(x)+x)(g(x)+x)}{x^{3}}=\\lim_{x \\to 0} \\frac{(x^{3}-ax^{2}+2x)\\{x^{2}+(2-a)x\\}}{x^{3}}=\\lim_{x \\to 0} \\frac{x^{2}(x^{2}-ax+2)\\{x+(2-a)\\}}{x^{3}}=\\lim_{x \\to 0} \\frac{(x^{2}-ax+2)\\{x+(2-a)\\}}{x} \\cdots$ ㉡\n㉡의 값이 존재하고 $x \\to 0$일 때, (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 0}(x^{2}-ax+2)\\{x+(2-a)\\}$에서 $2(2-a)=0 \\therefore a=2$\n그런데 $a<b$이므로 조건을 만족시키지 않는다.\n(i), (ii)에 의하여 $f(x)=x^{3}-2x^{2}+x$, $g(x)=x^{2}-x$이다.\n3rd $f(3)+g(8)$의 값을 구해. $f(x)=x^{3}-2x^{2}+x$, $g(x)=x^{2}-x$에서 $f(3)=27-18+3=12$, $g(8)=64-8=56$이다.\n$\\therefore f(3)+g(8)=12+56=68$", "img": "IMG_4947.jpg", "answer_value": "$68$"}, {"id": "A177", "section": "A", "num": 177, "page": 43, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "$20$", "rate": "54%", "problem": "두 이차함수 $f(x)$, $g(x)$가 $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)-x^{2}}=1$, $\\lim_{x \\to 3} \\frac{g(x)-f(x)}{x-3}=8$을 만족시킬 때, $g(5)-f(5)$의 값을 구하시오. (4점)", "explanation": "정답 공식: 두 다항함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)}=\\alpha$ (단, $\\alpha \\ne 0$)이면 $f(x)$, $g(x)$의 차수는 서로 같고, $\\alpha$는 두 다항함수 $f(x)$, $g(x)$의 최고차항의 계수의 비와 같다.\n1st 함수 $g(x)-f(x)$의 최고차항의 계수를 구해. 이차함수 $f(x)$의 최고차항의 계수를 $p$라 하면 $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)-x^{2}}=1$로 $0$이 아닌 극한값이 존재하므로 $g(x)-x^{2}$은 최고차항의 계수가 $p$인 이차함수이다. 즉, $g(x)$는 최고차항의 계수가 $p+1$인 이차함수이므로 (이해가 안가면 수능 핵강을 봐.) 함수 $g(x)-f(x)$는 최고차항의 계수가 $1$인 이차함수이다. $\\cdots$ ㉠ ($f(x)=px^{2}+ \\cdots$, $g(x)=(p+1)x^{2}+ \\cdots$이므로 $g(x)-f(x)=\\{(p+1)x^{2}+ \\cdots \\}-(px^{2}+ \\cdots)=x^{2}+ \\cdots$)\n2nd 함수 $g(x)-f(x)$의 식을 완성하고 $g(5)-f(5)$의 값을 구해. $\\lim_{x \\to 3} \\frac{g(x)-f(x)}{x-3}=8$에서 $x \\to 3$일 때 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. 즉, $\\lim_{x \\to 3}\\{g(x)-f(x)\\}=g(3)-f(3)=0 \\cdots$ ㉡이므로 이차함수 $g(x)-f(x)$는 $x-3$을 인수로 가진다. ($h(x)=g(x)-f(x)$라 하면 $h(3)=0$이므로 $h(x)$는 $x-3$을 인수로 가져.) 즉, 상수 $a$에 대하여 $g(x)-f(x)=(x-3)(x+a)$라 하면 $\\lim_{x \\to 3} \\frac{g(x)-f(x)}{x-3}=\\lim_{x \\to 3} \\frac{(x-3)(x+a)}{x-3}=\\lim_{x \\to 3}(x+a)=3+a=8 \\therefore a=5$\n따라서 $g(x)-f(x)=(x-3)(x+5)$이므로 $g(5)-f(5)=(5-3)(5+5)=2 \\times 10=20$이다.\n[다른 풀이: 미분계수의 정의 이용하기] ㉠에 의하여 $g(x)-f(x)=x^{2}+mx+n$($m$, $n$은 상수)라 하자. 이때, 위의 풀이의 ㉡에 의하여 $g(3)-f(3)=0$에서 $3^{2}+3m+n=0 \\therefore n=-3m-9 \\cdots$ ㉢\n따라서 $g(x)-f(x)=x^{2}+mx-3m-9$이므로 양변을 $x$에 대하여 미분하면 $g'(x)-f'(x)=2x+m \\cdots$ ㉣\n또, ㉡에 의하여 ($g(3)-f(3)=0$에서 $g(3)=f(3)$)\n$\\lim_{x \\to 3} \\frac{g(x)-f(x)}{x-3}=\\lim_{x \\to 3} \\frac{g(x)-g(3)+f(3)-f(x)}{x-3}=\\lim_{x \\to 3} \\frac{g(x)-g(3)}{x-3}-\\lim_{x \\to 3} \\frac{f(x)-f(3)}{x-3}=g'(3)-f'(3)=8 \\cdots$ ㉤ $\\left(f'(a)=\\lim_{x \\to a} \\frac{f(x)-f(a)}{x-a}=\\lim_{h \\to 0} \\frac{f(a+h)-f(a)}{h}\\right)$\n㉣의 양변에 $x=3$을 대입하면 $g'(3)-f'(3)=2 \\times 3+m=6+m$\n따라서 ㉤에 의하여 $6+m=8 \\therefore m=2$\n이것을 ㉢에 대입하면 $n=-3 \\times 2-9=-6-9=-15$\n따라서 $g(x)-f(x)=x^{2}+2x-15$이므로 $g(5)-f(5)=5^{2}+2 \\times 5-15=25+10-15=20$\n[수능 핵강: 함수 $g(x)$의 최고차항의 계수를 함수 $f(x)$의 최고차항의 계수로 나타내기] $f(x)=px^{2}+qx+r (p \\ne 0)$, $g(x)=lx^{2}+mx+n (l \\ne 0)$이라 하면 $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)-x^{2}}=1$에서 $\\lim_{x \\to \\infty} \\frac{px^{2}+qx+r}{(l-1)x^{2}+mx+n}=\\lim_{x \\to \\infty} \\frac{p+\\frac{q}{x}+\\frac{r}{x^{2}}}{(l-1)+\\frac{m}{x}+\\frac{n}{x^{2}}}=\\frac{p+0+0}{l-1+0+0}=\\frac{p}{l-1}=1$\n$p=l-1 \\therefore l=p+1$\n따라서 이차함수 $f(x)$의 최고차항의 계수가 $p$이면 함수 $g(x)$는 최고차항의 계수가 $p+1$인 이차함수야.", "img": "IMG_4948.jpg"}, {"id": "A178", "section": "A", "num": 178, "page": 43, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "$25$", "rate": "52%", "problem": "일차함수 $f(x)$와 최고차항의 계수가 $1$인 이차함수 $g(x)$에 대하여 $\\lim_{x \\to -3} \\frac{f(x)g(x)}{(x+3)^{2}}=4$, $\\lim_{x \\to -3} \\frac{f(x)+g(x)}{x+3}=-4$일 때, $g(2)-f(2)$의 값을 구하시오. (4점)", "explanation": "정답 공식: $\\lim_{x \\to a} \\frac{g(x)}{f(x)}=k$일 때, $\\lim_{x \\to a} f(x)=0$이면 $\\lim_{x \\to a} g(x)=0$이다.\n1st $f(-3)$, $g(3)$의 값을 각각 구해. $\\lim_{x \\to -3} \\frac{f(x)g(x)}{(x+3)^{2}}=4$에서 극한값이 존재하고 $x \\to -3$일 때 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. $\\therefore \\lim_{x \\to -3} f(x)g(x)=f(-3)g(-3)=0 \\cdots$ ㉠ ($f(x)$, $g(x)$가 다항함수이므로 $f(x)g(x)$도 다항함수야. 따라서 $x \\to -3$일 때의 극한값은 $x=-3$을 대입하여 구해.)\n또한, $\\lim_{x \\to -3} \\frac{f(x)+g(x)}{x+3}=-4$에서 극한값이 존재하고 $x \\to -3$일 때 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다. $\\therefore \\lim_{x \\to -3}\\{f(x)+g(x)\\}=f(-3)+g(-3)=0 \\cdots$ ㉡\n㉠, ㉡에 의해 $f(-3)=g(-3)=0$ (합과 곱이 모두 $0$이 되려면 두 값이 모두 $0$이어야 해.)\n2nd 주어진 극한값을 이용하여 $f(x)$, $g(x)$의 식을 각각 구해. 두 함수 $f(x)$, $g(x)$는 모두 $x+3$을 인수로 갖고 $f(x)$는 일차함수, $g(x)$는 최고차항의 계수가 $1$인 이차함수이므로 상수 $a$, $b$에 대하여 $f(x)=a(x+3)$, $g(x)=(x+3)(x+b)$라 하면\n$\\lim_{x \\to -3} \\frac{f(x)g(x)}{(x+3)^{2}}=4$에서 $\\lim_{x \\to -3} \\frac{a(x+3)^{2}(x+b)}{(x+3)^{2}}=\\lim_{x \\to -3} a(x+b)=a(-3+b)=4 \\cdots$ ㉢\n또한, $\\lim_{x \\to -3} \\frac{f(x)+g(x)}{x+3}=-4$에서 $\\lim_{x \\to -3} \\frac{a(x+3)+(x+3)(x+b)}{x+3}=\\lim_{x \\to -3}(a+x+b)=a-3+b=-4 \\cdots$ ㉣\n㉣에서 $-3+b=-a-4$이고 이것을 ㉢에 대입하면 $a(-a-4)=4$, $-a^{2}-4a=4$, $a^{2}+4a+4=0$\n$(a+2)^{2}=0 \\therefore a=-2$, $b=1$\n$\\therefore f(x)=-2(x+3)$, $g(x)=(x+3)(x+1)$\n3rd $g(2)-f(2)$의 값을 구해. 따라서 $f(2)=-2(2+3)=-10$, $g(2)=(2+3)(2+1)=15$이므로 $g(2)-f(2)=15-(-10)=25$이다.\n[개념·공식: 다항함수의 결정] 두 자연수 $m$, $n$과 $m$차 다항함수 $f(x)$, $n$차 다항함수 $g(x)$에 대하여 ① $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)}=\\alpha$($\\alpha$는 $0$이 아닌 실수)이면 $m=n$이다. 이때, $\\alpha$는 $f(x)$와 $g(x)$의 최고차항의 계수의 비이다. ② $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)}=0$이면 $m<n$이다. ③ $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)}=\\infty$이면 $m>n$이다.", "img": "IMG_4948.jpg,IMG_4949.jpg", "note": "1st 소제목이 'f(-3), g(3)의 값을 각각 구해'로 되어 있으나 실제로 구하는 값은 g(-3)임. 책(사진) 자체의 오타이며 풀이와 정답(25)에는 영향 없음."}, {"id": "A179", "section": "A", "num": 179, "page": 44, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "$10$", "rate": "56%", "problem": "다항함수 $f(x)$가 $\\lim_{x \\to \\infty} \\frac{f(x)-x^{3}}{x^{2}}=-11$, $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=-9$를 만족시킬 때, $\\lim_{x \\to \\infty} xf\\left(\\frac{1}{x}\\right)$의 값을 구하시오. (4점)", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한이 수렴하려면 분모의 차수는 분자의 차수보다 크거나 같아야 한다.\n1st $f(x)$의 함수식을 구하자. $\\lim_{x \\to \\infty} \\frac{f(x)-x^{3}}{x^{2}}=-11$이므로 $f(x)$는 삼차항의 계수가 $1$, 이차항의 계수가 $-11$인 삼차함수이다. 즉, $f(x)=x^{3}-11x^{2}+ax+b \\cdots$ ㉠\n이때, $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=-9$에서 $x \\to 1$일 때 (분모)$\\to 0$이므로 (분자)$\\to 0$이 되어야 한다. 즉, 다항함수 $f(x)$에 대하여 $\\lim_{x \\to 1} f(x)=0$에서 $f(1)=0$이므로 $f(1)=1-11+a+b=0$에서 $b=-a+10 \\cdots$ ㉡\n㉡을 ㉠에 대입하면 $f(x)=x^{3}-11x^{2}+ax-a+10=(x-1)(x^{2}-10x+a-10) \\cdots$ ㉢ (조립제법: $1\\ |\\ 1\\quad -11\\quad a\\quad -a+10 \\to 1\\quad -10\\quad a-10\\ |\\ 0$ 이므로 $f(x)=(x-1)(x^{2}-10x+a-10)$)\n$\\lim_{x \\to 1} \\frac{f(x)}{x-1}=-9$에 ㉢을 대입하면 $\\lim_{x \\to 1} \\frac{(x-1)(x^{2}-10x+a-10)}{x-1}=1-10+a-10=a-19=-9$ ($x-1$이 분자, 분모의 공통인수이므로 약분해.)\n따라서 $a=10$, $b=0$($\\because$ ㉡)이므로 $f(x)=x^{3}-11x^{2}+10x$\n2nd $\\frac{0}{0}$ 꼴의 극한이 되도록 치환하자. $x=\\frac{1}{h}$이라 하면 $x \\to \\infty$일 때 $h \\to 0+$이므로 (실수: 치환을 하면서 $x \\to \\infty$가 $h \\to 0$으로 바뀌는 걸 유의해야 해.)\n$\\lim_{x \\to \\infty} xf\\left(\\frac{1}{x}\\right)=\\lim_{h \\to 0} \\frac{1}{h}f(h)=\\lim_{h \\to 0} \\frac{h^{3}-11h^{2}+10h}{h}=\\lim_{h \\to 0}(h^{2}-11h+10)=10 (h^{3}-11h^{2}+10h=h(h^{2}-11h+10))$\n[개념·공식: 다항함수의 결정] 두 자연수 $m$, $n$과 $m$차 다항함수 $f(x)$, $n$차 다항함수 $g(x)$에 대하여 ① $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)}=\\alpha$($\\alpha$는 $0$이 아닌 실수)이면 $m=n$이다. 이때, $\\alpha$는 $f(x)$와 $g(x)$의 최고차항의 계수의 비이다. ② $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)}=0$이면 $m<n$이다. ③ $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)}=\\infty$이면 $m>n$이다.", "img": "IMG_4949.jpg"}, {"id": "A180", "section": "A", "num": 180, "page": 44, "topic": "함수의 극한의 대소 관계", "answer": "①", "rate": "90%", "problem": "함수 $f(x)$가 $x>\\frac{1}{2}$인 모든 실수 $x$에 대하여 $\\frac{3}{2x+1}<f(x)<\\frac{3}{2x-1}$을 만족시킬 때, $\\lim_{x \\to \\infty} xf(x)$의 값은? (3점)", "explanation": "정답 공식: 실수 $a$와 세 함수 $f(x)$, $g(x)$, $h(x)$에 대하여 $\\lim_{x \\to a} f(x)=\\alpha$, $\\lim_{x \\to a} g(x)=\\beta$ ($\\alpha$, $\\beta$는 실수)일 때, $f(x)<h(x)<g(x)$이고 $\\alpha=\\beta$이면 $\\lim_{x \\to a} h(x)=\\alpha$이다.\n1st 주어진 부등식에서 $xf(x)$가 나오도록 변형해. $x>\\frac{1}{2}$인 모든 실수 $x$에 대하여 $\\frac{3}{2x+1}<f(x)<\\frac{3}{2x-1}$이므로 위의 부등식의 각 변에 양수 $x$를 곱하면 ($x>\\frac{1}{2}$이므로 $x$는 양수야. 따라서 각 변에 $x$를 곱해도 부등호의 방향은 바뀌지 않아.) $\\frac{3x}{2x+1}<xf(x)<\\frac{3x}{2x-1} \\cdots$ ㉠\n2nd 함수의 극한과 대소 관계를 이용하여 $\\lim_{x \\to \\infty} xf(x)$의 값을 구해. ㉠의 각 변에 $\\lim_{x \\to \\infty}$를 취하면 $\\lim_{x \\to \\infty} \\frac{3x}{2x+1} \\le \\lim_{x \\to \\infty} xf(x) \\le \\lim_{x \\to \\infty} \\frac{3x}{2x-1}$\n이때, $\\lim_{x \\to \\infty} \\frac{3x}{2x+1}=\\lim_{x \\to \\infty} \\frac{3x}{2x-1}=\\frac{3}{2}$ ($\\frac{\\infty}{\\infty}$ 꼴이므로 극한값은 분모와 분자의 최고차항의 계수의 비인 $\\frac{3}{2}$이야.)\n이므로 함수의 극한의 대소 관계에 의하여 $\\lim_{x \\to \\infty} xf(x)=\\frac{3}{2}$이다. ($f(x)<h(x)<g(x)$에서 $\\lim_{x \\to a} f(x)=\\lim_{x \\to a} g(x)=\\alpha$ ($\\alpha$는 실수)이면 $\\lim_{x \\to a} h(x)=\\alpha$야.)", "img": "IMG_4949.jpg", "answer_value": "$\\frac{3}{2}$"}, {"id": "A181", "section": "A", "num": 181, "page": 45, "topic": "함수의 극한의 대소 관계", "answer": "⑤", "rate": "83%", "problem": "함수 $f(x)$가 모든 실수 $x$에 대하여 $2x+1 \\le f(x) \\le (x+1)^{2}$을 만족시킬 때, $\\lim_{x \\to 0}(x+5)f(x)$의 값은? (3점)", "explanation": "정답 공식: 실수 $a$와 세 함수 $f(x)$, $g(x)$, $h(x)$에 대하여 $\\lim_{x \\to a} f(x)=\\alpha$, $\\lim_{x \\to a} g(x)=\\beta$ ($\\alpha$, $\\beta$는 실수)일 때, $f(x) \\le h(x) \\le g(x)$이고 $\\alpha=\\beta$이면 $\\lim_{x \\to a} h(x)=\\alpha$이다.\n1st $x \\to 0$일 때 $(x+5)f(x)$의 범위를 파악해. $x \\to 0$일 때 $x+5>0$이므로 ($x+5>0$이므로 각 변에 $x+5$를 곱해도 부등호의 방향은 바뀌지 않아.) $2x+1 \\le f(x) \\le (x+1)^{2}$의 각 변에 $x+5$를 곱하면 $(x+5)(2x+1) \\le (x+5)f(x) \\le (x+5)(x+1)^{2} \\cdots$ ㉠\n2nd 함수의 극한과 대소 관계를 이용하여 $\\lim_{x \\to 0}(x+5)f(x)$의 값을 구하자. ㉠의 각 변에 $\\lim_{x \\to 0}$를 취하면 $\\lim_{x \\to 0}(x+5)(2x+1) \\le \\lim_{x \\to 0}(x+5)f(x) \\le \\lim_{x \\to 0}(x+5)(x+1)^{2}$\n이때, $\\lim_{x \\to 0}(x+5)(2x+1)=\\lim_{x \\to 0}(x+5) \\times \\lim_{x \\to 0}(2x+1)=5 \\times 1=5$, $\\lim_{x \\to 0}(x+5)(x+1)^{2}=\\lim_{x \\to 0}(x+5) \\times \\lim_{x \\to 0}(x+1)^{2}=5 \\times 1=5$이므로 ($\\lim_{x \\to a} f(x)=\\alpha$, $\\lim_{x \\to a} g(x)=\\beta$일 때, $\\lim_{x \\to a} f(x)g(x)=\\lim_{x \\to a} f(x) \\times \\lim_{x \\to a} g(x)=\\alpha \\beta$)\n함수의 극한의 대소 관계에 의하여 $\\lim_{x \\to 0}(x+5)f(x)=5$이다.\n[다른 풀이: $\\lim_{x \\to 0} f(x)$, $\\lim_{x \\to 0}(x+5)$의 값 이용하기] 모든 실수 $x$에 대하여 $2x+1 \\le f(x) \\le (x+1)^{2}$이므로 각 변에 $\\lim_{x \\to 0}$를 취하면 $\\lim_{x \\to 0}(2x+1) \\le \\lim_{x \\to 0} f(x) \\le \\lim_{x \\to 0}(x+1)^{2}$\n이때, $\\lim_{x \\to 0}(2x+1)=2 \\times 0+1=1$, $\\lim_{x \\to 0}(x+1)^{2}=(0+1)^{2}=1$이므로 $\\lim_{x \\to 0} f(x)=1$\n또한, $\\lim_{x \\to 0}(x+5)=0+5=5$이므로 $\\lim_{x \\to 0}(x+5)f(x)=\\lim_{x \\to 0}(x+5) \\times \\lim_{x \\to 0} f(x)=5 \\times 1=5$\n[개념·공식: 함수의 극한의 대소 관계] 두 함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to a} f(x)=\\alpha$, $\\lim_{x \\to a} g(x)=\\beta$일 때, $a$의 가까운 모든 $x$의 값에 대하여 ① $f(x) \\le g(x)$이면 $\\alpha \\le \\beta$이다. ② 함수 $h(x)$가 $f(x) \\le h(x) \\le g(x)$이고 $\\alpha=\\beta$이면 $\\lim_{x \\to a} h(x)=\\alpha$이다.", "img": "IMG_4950.jpg", "answer_value": "$5$"}, {"id": "A182", "section": "A", "num": 182, "page": 45, "topic": "함수의 극한의 대소 관계", "answer": "⑤", "rate": "82%", "problem": "실수 전체의 집합에서 정의된 함수 $f(x)$가 모든 실수 $x$에 대하여 부등식 $5x-1<(x^{2}+1)f(x)<5x+2$를 만족시킬 때, $\\lim_{x \\to \\infty} xf(x)$의 값은? (3점)", "explanation": "정답 공식: 함수 $f(x)$, $g(x)$, $h(x)$에 대하여 $f(x) \\le h(x) \\le g(x)$이고 $\\lim_{x \\to a} f(x)=\\lim_{x \\to a} g(x)=\\alpha$($\\alpha$는 실수)이면 $\\lim_{x \\to a} h(x)=\\alpha$이다.\n1st 주어진 부등식에서 $xf(x)$가 나오도록 변형하자. 부등식 $5x-1<(x^{2}+1)f(x)<5x+2$의 각 변을 $x^{2}+1$로 나누면 (실수 $x$에 대하여 $x^{2}+1$은 항상 양수이므로 부등식의 각 변을 $x^{2}+1$로 나누어도 부등호의 방향은 바뀌지 않아.) $\\frac{5x-1}{x^{2}+1}<f(x)<\\frac{5x+2}{x^{2}+1}$\n또한, $x>0$일 때 위의 부등식의 각 변에 $x$를 곱하면 (구해야 하는 극한이 $x \\to \\infty$일 때이므로 $x>0$인 경우에 대해서만 부등식을 정리해도 돼.) $\\frac{x(5x-1)}{x^{2}+1}<xf(x)<\\frac{x(5x+2)}{x^{2}+1}$에서 $\\frac{5x^{2}-x}{x^{2}+1}<xf(x)<\\frac{5x^{2}+2x}{x^{2}+1}$\n2nd 극한의 대소 관계를 이용하자. 그런데 $\\lim_{x \\to \\infty} \\frac{5x^{2}-x}{x^{2}+1}=\\lim_{x \\to \\infty} \\frac{5x^{2}+2x}{x^{2}+1}=5$ ($\\frac{\\infty}{\\infty}$ 꼴이므로 극한값은 분모와 분자의 최고차항의 계수의 비인 $5$야.)\n이므로 함수의 극한의 대소 관계에 의해 $\\lim_{x \\to \\infty} xf(x)=5$ ((1) $f(x)<g(x)$이면 $\\lim_{x \\to a} f(x) \\le \\lim_{x \\to a} g(x)$ (2) $f(x)<h(x)<g(x)$에서 $\\lim_{x \\to a} f(x)=\\lim_{x \\to a} g(x)=\\alpha$($\\alpha$는 실수)이면 $\\lim_{x \\to a} h(x)=\\alpha$)", "img": "IMG_4950.jpg", "answer_value": "$5$"}, {"id": "A183", "section": "A", "num": 183, "page": 45, "topic": "함수의 극한의 대소 관계", "answer": "①", "rate": "73%", "problem": "$0$이 아닌 모든 실수 $x$에 대하여 함수 $f(x)$가 $\\frac{1}{2}x^{2}+2x<f(x)<x^{2}+2x$를 만족시킬 때, $\\lim_{x \\to 0} \\frac{xf(x)+5x}{2f(x)-x}$의 값은? (3점)", "explanation": "정답 공식: 세 함수 $f(x)$, $g(x)$, $h(x)$에 대하여 $f(x)<h(x)<g(x)$이고 $\\lim_{x \\to a} f(x)=\\alpha$, $\\lim_{x \\to a} g(x)=\\beta$($\\alpha$, $\\beta$는 실수)일 때, $\\alpha=\\beta$이면 $\\lim_{x \\to a} h(x)=\\alpha$이다.\n1st 함수의 극한의 대소 관계를 이용하여 먼저 $\\lim_{x \\to 0} f(x)$의 값을 구하자. (i) 부등식 $\\frac{1}{2}x^{2}+2x<f(x)<x^{2}+2x$에서 $\\lim_{x \\to 0}\\left(\\frac{1}{2}x^{2}+2x\\right)=\\lim_{x \\to 0}(x^{2}+2x)=0$이므로 함수의 극한의 대소 관계에 의해 $\\lim_{x \\to 0} f(x)=0 \\cdots$ ㉠ (세 함수 $f(x)$, $g(x)$, $h(x)$에 대하여 $f(x)<h(x)<g(x)$이고 $\\lim_{x \\to a} f(x)=\\lim_{x \\to a} g(x)=\\alpha$($\\alpha$는 실수)이면 $\\lim_{x \\to a} h(x)=\\alpha$)\n2nd 함수의 극한의 대소 관계를 이용하여 $\\lim_{x \\to 0} \\frac{f(x)}{x}$의 값을 구하자. $\\lim_{x \\to 0} \\frac{xf(x)+5x}{2f(x)-x}$의 분모, 분자를 $x$로 나누면 ($x \\to 0$이라는 것은 $x$가 $0$에 한없이 가까워지는 것으로 $x \\ne 0$이므로 주어진 극한식의 분모, 분자를 $x$로 나눌 수 있는 거야.) $\\lim_{x \\to 0} \\frac{f(x)+5}{2 \\times \\frac{f(x)}{x}-1}$\n(ii) 먼저, $x>0$일 때 (주의: 부등식의 각 변을 $x$로 나눌 때 $x$의 부호에 따라 부등호의 방향이 바뀌므로 $x$의 값의 범위를 나누어서 풀어야 해.) $\\frac{1}{2}x^{2}+2x<f(x)<x^{2}+2x$의 양변을 $x$로 나누면 $\\frac{1}{2}x+2<\\frac{f(x)}{x}<x+2$이고 $\\lim_{x \\to 0+}\\left(\\frac{1}{2}x+2\\right)=\\lim_{x \\to 0+}(x+2)=2$이므로 함수의 극한의 대소 관계에 의해 $\\lim_{x \\to 0+} \\frac{f(x)}{x}=2$이다.\n또, $x<0$일 때 $\\frac{1}{2}x^{2}+2x<f(x)<x^{2}+2x$의 양변을 $x$로 나누면 $x+2<\\frac{f(x)}{x}<\\frac{1}{2}x+2$이고 $\\lim_{x \\to 0-}(x+2)=\\lim_{x \\to 0-}\\left(\\frac{1}{2}x+2\\right)=2$이므로 함수의 극한의 대소 관계에 의해 $\\lim_{x \\to 0-} \\frac{f(x)}{x}=2$이다.\n즉, $\\lim_{x \\to 0+} \\frac{f(x)}{x}=\\lim_{x \\to 0-} \\frac{f(x)}{x}=2$이므로 (좌극한의 값과 우극한의 값이 같아야 극한값이 존재하는 거야.) $\\lim_{x \\to 0} \\frac{f(x)}{x}=2 \\cdots$ ㉡\n3rd $\\lim_{x \\to 0} \\frac{xf(x)+5x}{2f(x)-x}$의 값을 구하자. (i), (ii)에 의해 $\\lim_{x \\to 0} \\frac{xf(x)+5x}{2f(x)-x}=\\lim_{x \\to 0} \\frac{f(x)+5}{2 \\times \\frac{f(x)}{x}-1}=\\frac{0+5}{2 \\times 2-1}$ ($\\because$ ㉠, ㉡)$=\\frac{5}{3}$", "img": "IMG_4950.jpg,IMG_4951.jpg", "answer_value": "$\\frac{5}{3}$"}, {"id": "A184", "section": "A", "num": 184, "page": 46, "topic": "함수의 극한의 대소 관계", "answer": "④", "rate": "79%", "problem": "함수 $f(x)$가 모든 양의 실수 $x$에 대하여 $2x+1<f(x)<2x+5$를 만족시킬 때, $\\lim_{x \\to \\infty} \\frac{\\{f(x)\\}^{2}}{x^{2}-x+1}$의 값은? (3점)", "explanation": "정답 공식: $f(x) \\le h(x) \\le g(x)$이고 $\\lim_{x \\to a} f(x)=\\lim_{x \\to a} g(x)=\\alpha$($\\alpha$는 실수)이면 $\\lim_{x \\to a} h(x)=\\alpha$이다.\n1st 주어진 부등식을 변형하자. 양의 실수 $x$에 대하여 $2x+1>0$, $2x+5>0$이므로 $2x+1<f(x)<2x+5$의 각 변을 제곱하면 $(2x+1)^{2}<\\{f(x)\\}^{2}<(2x+5)^{2}$\n이때, $x^{2}-x+1>0$이므로 각 변을 $x^{2}-x+1$로 나누면 $\\left(x^{2}-x+1=\\left(x-\\frac{1}{2}\\right)^{2}+\\frac{3}{4} \\ge \\frac{3}{4}>0\\right) \\frac{(2x+1)^{2}}{x^{2}-x+1}<\\frac{\\{f(x)\\}^{2}}{x^{2}-x+1}<\\frac{(2x+5)^{2}}{x^{2}-x+1}$\n각 변에 $\\lim_{x \\to \\infty}$를 취하면 $\\lim_{x \\to \\infty} \\frac{(2x+1)^{2}}{x^{2}-x+1} \\le \\lim_{x \\to \\infty} \\frac{\\{f(x)\\}^{2}}{x^{2}-x+1} \\le \\lim_{x \\to \\infty} \\frac{(2x+5)^{2}}{x^{2}-x+1}$ ($a$에 가까운 모든 실수 $x$에 대하여 $f(x)<g(x)$이지만 $\\lim_{x \\to a} f(x)=\\lim_{x \\to a} g(x)$인 경우가 있으므로 $\\lim$를 취하면 '$<$'는 '$\\le$'로 변하게 돼.)\n2nd $\\lim_{x \\to \\infty} \\frac{\\{f(x)\\}^{2}}{x^{2}-x+1}$의 값을 구해. 이때, $\\lim_{x \\to \\infty} \\frac{(2x+1)^{2}}{x^{2}-x+1}=\\lim_{x \\to \\infty} \\frac{\\left(2+\\frac{1}{x}\\right)^{2}}{1-\\frac{1}{x}+\\frac{1}{x^{2}}}=4$, $\\lim_{x \\to \\infty} \\frac{(2x+5)^{2}}{x^{2}-x+1}=\\lim_{x \\to \\infty} \\frac{\\left(2+\\frac{5}{x}\\right)^{2}}{1-\\frac{1}{x}+\\frac{1}{x^{2}}}=4$이므로 $\\lim_{x \\to \\infty} \\frac{\\{f(x)\\}^{2}}{x^{2}-x+1}=4$", "img": "IMG_4951.jpg", "answer_value": "$4$"}, {"id": "A185", "section": "A", "num": 185, "page": 46, "topic": "길이에 대한 극한의 활용", "answer": "②", "rate": "73%", "problem": "세 함수 $f(x)=\\sqrt{x+2}$, $g(x)=-\\sqrt{x-2}+2$, $h(x)=x$의 그래프가 그림과 같다. 함수 $y=h(x)$의 그래프 위의 점 $P(a, a)$를 지나고 $x$축에 평행한 직선이 함수 $y=f(x)$의 그래프와 만나는 점을 $A$, 함수 $y=g(x)$의 그래프와 만나는 점을 $B$라 하자. 점 $B$를 지나고 $y$축에 평행한 직선이 함수 $y=h(x)$의 그래프와 만나는 점을 $C$라 할 때, $\\lim_{a \\to 2-} \\frac{BC}{AB}$의 값은? (단, $0<a<2$) (4점)", "explanation": "정답 공식: $x$축에 평행한 직선 위의 두 점 사이의 거리는 두 점의 $x$좌표의 차이고, $y$축에 평행한 직선 위의 두 점 사이의 거리는 두 점의 $y$좌표의 차이다.\n1st 선분 $AB$의 길이를 구하자. 점 $P(a, a)(0<a<2)$를 지나고 $x$축에 평행한 직선이 두 함수 $y=f(x)$, $y=g(x)$의 그래프와 만나는 점의 $y$좌표는 모두 $a$이므로 점 $A$의 좌표는 $\\sqrt{x+2}=a$에서 $x+2=a^{2}$ ($y=f(x)$의 그래프와 직선 $y=a$의 교점이므로 $f(x)=a$를 풀어야 해.) 따라서 $x=a^{2}-2$이므로 $A(a^{2}-2, a)$이다. 또, 점 $B$의 좌표는 $-\\sqrt{x-2}+2=a$에서 ($y=g(x)$의 그래프와 직선 $y=a$의 교점이므로 $g(x)=a$를 풀어야 해) $-\\sqrt{x-2}=a-2$, $x-2=a^{2}-4a+4$\n따라서 $x=a^{2}-4a+6$이므로 $B(a^{2}-4a+6, a)$이다.\n$\\therefore AB=|(a^{2}-4a+6)-(a^{2}-2)|=|-4a+8|=-4a+8$ ($0<a<2$에서 $-8<-4a<0$이므로 $-4a+8>0$이야)\n2nd 이번에는 선분 $BC$의 길이를 구하자. 점 $B$를 지나고 $y$축에 평행한 직선이 함수 $y=h(x)$의 그래프와 만나는 점의 $x$좌표는 $a^{2}-4a+6$이므로 점 $C$의 좌표는 $(a^{2}-4a+6, a^{2}-4a+6)$이다. ($h(x)=x$이므로 ($x$좌표)=($y$좌표)겠지)\n$\\therefore BC=|(a^{2}-4a+6)-a|=|a^{2}-5a+6|=a^{2}-5a+6$ ($i(a)=a^{2}-5a+6=\\left(a-\\frac{5}{2}\\right)^{2}-\\frac{1}{4}$이라 하면 함수 $i(a)$는 $a<\\frac{5}{2}$에서 감소하는 함수야. 이때, $i(2)=0$이므로 $0<a<2$에서 $i(a)>0$이야. $\\therefore BC=a^{2}-5a+6$)\n[함정] $a$의 값의 범위에 따라 절댓값 안의 부호가 결정되니까 주어진 $a$의 값의 범위를 이용하여 절댓값을 없애주어야 해.\n3rd $\\lim_{a \\to 2-} \\frac{BC}{AB}$의 값을 구하자.\n$\\therefore \\lim_{a \\to 2-} \\frac{BC}{AB} = \\lim_{a \\to 2-} \\frac{a^{2}-5a+6}{-4a+8} = \\lim_{a \\to 2-} \\frac{(a-2)(a-3)}{-4(a-2)} = \\lim_{a \\to 2-} \\frac{a-3}{-4} = \\frac{1}{4}$\n[톡톡 풀이: $\\frac{BC}{AB}=$($AC$의 기울기)임을 이용하기]\n$\\lim_{a \\to 2-} \\frac{BC}{AB}$에서 $\\frac{BC}{AB}=$($AC$의 기울기)지? 이때, $A(a^{2}-2, a)$, $C(a^{2}-4a+6, a^{2}-4a+6)$에서 $\\frac{BC}{AB}=$($AC$의 기울기)$=\\frac{(a^{2}-4a+6)-a}{(a^{2}-4a+6)-(a^{2}-2)}=-\\frac{a-3}{4}$ (두 점 $(x_{1},y_{1})$,$(x_{2},y_{2})$를 지나는 직선의 기울기는 $\\frac{y_{2}-y_{1}}{x_{2}-x_{1}}$ 또는 $\\frac{y_{1}-y_{2}}{x_{1}-x_{2}}$ (단, $x_{1} \\ne x_{2}$))\n$\\therefore \\lim_{a \\to 2-} \\frac{BC}{AB} = \\lim_{a \\to 2-} \\left(-\\frac{a-3}{4}\\right) = \\frac{1}{4}$", "img": "IMG_4951.jpg", "answer_value": "$\\frac{1}{4}$"}, {"id": "A186", "section": "A", "num": 186, "page": 47, "topic": "도형의 길이에 대한 극한", "answer": "③", "rate": "74%", "problem": "$0<t<3$인 실수 $t$에 대하여 함수 $y=\\left|\\frac{2}{x}-3\\right|$의 그래프와 직선 $y=t$가 만나는 두 점 사이의 거리를 $f(t)$라 할 때, $\\lim_{t \\to 0+} \\frac{f(t)}{t}$의 값은? (4점)\n[단서] $\\frac{2}{x}-3>0$인 경우와 $\\frac{2}{x}-3<0$인 경우로 나누어 각각의 $x$좌표를 구한 후 $f(t)$를 구해.", "explanation": "정답 공식: $x$축에 평행한 직선 위의 두 점 사이의 거리는 두 점의 $x$좌표의 차와 같다.\n1st 함수 $y=\\left|\\frac{2}{x}-3\\right|$의 그래프와 직선 $y=t$가 만나는 두 점의 $x$좌표를 각각 구해.\n함수 $y=\\left|\\frac{2}{x}-3\\right|$의 그래프가 $x$축과 만나는 점이 $x=\\frac{2}{3}$이므로\n$0<x<\\frac{2}{3}$일 때, $\\left|\\frac{2}{x}-3\\right|=\\frac{2}{x}-3$이고 $\\frac{2}{x}-3=t$에서 $x=\\frac{2}{3+t}$\n($x<0$인 경우, $\\frac{2}{x}-3<-3$이고 $\\left|\\frac{2}{x}-3\\right|=-\\frac{2}{x}+3>3$이므로 $0<t<3$인 실수 $t$에 대하여 함수 $y=\\left|\\frac{2}{x}-3\\right|$의 그래프와 직선 $y=t$는 만나지 않아.)\n$x>\\frac{2}{3}$일 때, $\\left|\\frac{2}{x}-3\\right|=-\\frac{2}{x}+3$이고 ($x>\\frac{2}{3}$일 때, $\\frac{2}{x}-3<0$이야) $-\\frac{2}{x}+3=t$에서 $x=\\frac{2}{3-t}$\n2nd $\\lim_{t \\to 0+} \\frac{f(t)}{t}$의 값을 구해.\n따라서 두 점 사이의 거리인 $f(t)$는 두 점의 $x$좌표의 차이므로\n$f(t)=\\frac{2}{3-t}-\\frac{2}{3+t}$ ($f(t)$는 거리이므로 $f(t)>0$이야. 이때, $\\frac{2}{3-t}>\\frac{2}{3+t}$이므로 다음과 같이 식을 세울 수 있어.)\n$=\\frac{6+2t-6+2t}{(3-t)(3+t)}=\\frac{4t}{(3-t)(3+t)}$\n$\\therefore \\lim_{t \\to 0+} \\frac{f(t)}{t} = \\lim_{t \\to 0+} \\left\\{ \\frac{1}{t} \\times \\frac{4t}{(3-t)(3+t)} \\right\\} = \\lim_{t \\to 0+} \\frac{4}{(3-t)(3+t)} = \\frac{4}{3 \\times 3} = \\frac{4}{9}$\n[다른 풀이: 두 그래프의 교점의 $x$좌표는 방정식의 근과 같음을 이용하기]\n함수 $y=\\left|\\frac{2}{x}-3\\right|$의 그래프와 직선 $y=t$의 교점의 $x$좌표는 방정식 $\\left|\\frac{2}{x}-3\\right|=t$의 근이야. $\\left|\\frac{2}{x}-3\\right|=t$에서 $\\frac{2}{x}-3=\\pm t$이므로 $x=\\frac{2}{3\\pm t}$야.\n따라서 함수 $y=\\left|\\frac{2}{x}-3\\right|$의 그래프와 직선 $y=t$의 교점은 $\\left(\\frac{2}{3+t}, t\\right)$, $\\left(\\frac{2}{3-t}, t\\right)$이므로\n$f(t)=\\left|\\frac{2}{3+t}-\\frac{2}{3-t}\\right|=\\frac{2}{3-t}-\\frac{2}{3+t}$ ($t>0$이므로 $3-t<3+t$이야. 분자는 $2$로 같으니까 분모가 더 작은 $\\frac{2}{3-t}$가 $\\frac{2}{3+t}$보다 크겠지?)\n(이하 동일)", "img": "IMG_4952.jpg", "answer_value": "$\\frac{4}{9}$"}, {"id": "A187", "section": "A", "num": 187, "page": 48, "topic": "도형의 길이에 대한 극한", "answer": "④", "rate": "69%", "problem": "실수 $t(t>0)$에 대하여 직선 $y=tx+t+1$과 곡선 $y=x^{2}-tx-1$이 만나는 두 점을 $A$, $B$라 할 때, $\\lim_{t \\to \\infty} \\frac{AB}{t^{2}}$의 값은? (4점)\n[단서1] 두 점 $A$, $B$의 $x$좌표를 각각 $\\alpha$, $\\beta (\\alpha <\\beta)$라 하면 두 점 $A$, $B$의 좌표를 점 $A(\\alpha, \\alpha t+t+1)$, 점 $B(\\beta, \\beta t+t+1)$라 놓을 수 있어. [단서2] $AB$를 $t$에 관한 식으로 나타내어 극한식에 대입해.", "explanation": "정답 공식: $AB$를 $t$에 관한 식으로 나타내어 극한 식에 대입한다.\n1st 두 점 $A$, $B$의 $x$좌표를 각각 $\\alpha$, $\\beta$라 하고 $\\beta -\\alpha$의 값을 구하자.\n두 점 $A$, $B$의 $x$좌표를 각각 $\\alpha$, $\\beta (\\alpha <\\beta)$라 하면 $\\alpha$, $\\beta$는 이차방정식 $x^{2}-tx-1=tx+t+1$, 즉 $x^{2}-2tx-t-2=0$의 두 실근이므로 근의 공식에 의하여 (이차방정식 $x^{2}-2bx+c=0$의 근은 $x=b\\pm \\sqrt{b^{2}-c}$)\n$\\alpha=t-\\sqrt{t^{2}+t+2}$, $\\beta=t+\\sqrt{t^{2}+t+2}$\n$\\therefore \\beta -\\alpha=2\\sqrt{t^{2}+t+2} (\\because \\beta -\\alpha >0)$\n2nd $AB$를 $t$에 관한 식으로 나타내.\n두 점 $A$, $B$는 직선 $y=tx+t+1$ 위의 점이므로 $A(\\alpha, \\alpha t+t+1)$.\n[주의] 점 $A$는 직선 $y=tx+t+1$과 곡선 $y=x^{2}-tx-1$ 위의 점이야. 따라서 점 $A$의 좌표는 $A(\\alpha, \\alpha t+t+1)$ 또는 $A(\\alpha, \\alpha^{2}-t\\alpha -1)$이라 놓을 수 있어. 그런데, $AB$를 구하기 위해서는 계산이 쉬운 $A(\\alpha, \\alpha t+t+1)$로 놓는 것이 좋아.\n점 $B(\\beta, \\beta t+t+1)$이다.\n$\\therefore AB=\\sqrt{(\\beta -\\alpha)^{2}+(\\beta t+t+1-\\alpha t-t-1)^{2}}=\\sqrt{(\\beta -\\alpha)^{2}+t^{2}(\\beta -\\alpha)^{2}}=\\sqrt{(\\beta -\\alpha)^{2}(t^{2}+1)}=(\\beta -\\alpha)\\sqrt{t^{2}+1}=2\\sqrt{t^{2}+t+2}\\sqrt{t^{2}+1}=2\\sqrt{(t^{2}+t+2)(t^{2}+1)}$\n3rd $\\lim_{t \\to \\infty} \\frac{AB}{t^{2}}$의 값을 구하자.\n$\\lim_{t \\to \\infty} \\frac{AB}{t^{2}} = \\lim_{t \\to \\infty} \\frac{2\\sqrt{(t^{2}+t+2)(t^{2}+1)}}{t^{2}}$ ($\\frac{\\infty}{\\infty}$ 꼴의 극한이므로 분모의 최고차항 $t^{2}$으로 분모, 분자를 각각 나누어 계산해. 이때, $t^{2}=\\sqrt{t^{4}}$으로 바꾸어서 루트 속에 있는 분자와 손쉽게 약분하자.)\n$=2 \\lim_{t \\to \\infty} \\sqrt{\\frac{t^{2}+t+2}{t^{2}} \\times \\frac{t^{2}+1}{t^{2}}}$\n$=2 \\lim_{t \\to \\infty} \\sqrt{\\left(1+\\frac{1}{t}+\\frac{2}{t^{2}}\\right)\\left(1+\\frac{1}{t^{2}}\\right)}$\n$=2$\n[다른 풀이: 이차방정식의 근과 계수의 관계를 이용하여 $\\beta -\\alpha$의 값 구하기]\n1st에서 이차방정식의 근과 계수의 관계에 의하여 $\\alpha +\\beta=2t$, $\\alpha \\beta=-t-2$\n$(\\beta -\\alpha)^{2}=(\\alpha +\\beta)^{2}-4\\alpha \\beta=(2t)^{2}-4(-t-2)=4t^{2}+4t+8=4(t^{2}+t+2)$\n이므로 $\\beta -\\alpha=2\\sqrt{t^{2}+t+2} (\\because \\beta -\\alpha >0)$\n(이하 동일)\n[수능 핵강] 직선 $AB$의 기울기가 $t$이므로 다음 그림과 같은 직각삼각형을 생각해 보자.\n두 점 $A$, $B$의 $x$좌표를 각각 $\\alpha$, $\\beta (\\alpha <\\beta)$라 하면 각각의 점에서 $x$축과 $y$축과 평행한 직선을 그어 만난 점을 $C$라 하면 삼각형 $ABC$와 주어진 삼각형은 닮았으므로 다음과 같아. (삼각형의 빗변의 직선의 기울기가 $t$이므로 밑변을 $1$이라 하면 높이가 $t$가 되어서 빗변의 길이가 $\\sqrt{t^{2}+1}$이 되는 거야.) 이때 삼각형 $ABC$의 밑변의 길이가 $\\beta -\\alpha$이므로 빗변의 길이는 $(\\beta -\\alpha)\\sqrt{t^{2}+1}$이야. 따라서 극한값 $\\lim_{t \\to \\infty} \\frac{AB}{t^{2}}$를 알기 위하여 $\\beta -\\alpha$를 $t$에 관한 식으로 정리하면 되겠지?\n[개념·공식: 함수의 극한값 구하는 방법] ① $\\frac{\\infty}{\\infty}$ 꼴: 분모, 분자를 분모의 최고차항으로 나눈다. ② $\\frac{0}{0}$ 꼴: 분수식은 인수분해한 후 약분하고, 무리식은 유리화한다. ③ $\\infty -\\infty$ 꼴: 다항식은 최고차항으로 묶어내고, 무리식은 유리화한다. ④ $0 \\cdot \\infty$ 꼴: $\\frac{\\infty}{\\infty}$, $\\frac{0}{0}$ 꼴로 변형한다.", "img": "IMG_4953.jpg", "answer_value": "$2$"}, {"id": "A188", "section": "A", "num": 188, "page": 48, "topic": "도형의 길이에 대한 극한", "answer": "$512$", "rate": "50%", "problem": "직선 $y=\\sqrt{2}x$ 위의 점 $A\\left(t, \\sqrt{2}t\\right)(t>0)$과 $x$축 위의 점 $B(2t, 0)$이 있다. 선분 $AB$의 중점을 $C$라 하고, 점 $C$를 지나고 선분 $AB$에 수직인 직선이 직선 $x=2t$와 만나는 점을 $D$라 하자. 선분 $CD$의 길이를 $f(t)$라 할 때, $\\lim_{t \\to 4} \\frac{t^{2}-16}{f(t)-\\sqrt{6}}=k$이다. $3k^{2}$의 값을 구하시오. (4점) [단서1] 두 점의 중점의 좌표를 구하는 공식을 이용해 점 $C$의 좌표를 $t$에 대한 식으로 나타내. [단서2] 서로 수직인 두 직선의 기울기의 곱이 $-1$임을 이용해 선분 $AB$에 수직인 직선의 방정식을 구한 후 점 $D$의 좌표를 구하자. [단서3] 두 점 $C$, $D$의 좌표를 이용해 두 점 사이의 거리 $f(t)$를 구해.", "explanation": "정답 공식: 두 점 $C$, $D$의 좌표를 이용해 $f(t)$의 식을 구한 후 주어진 극한식에 대입한다. 이때, $\\frac{0}{0}$ 꼴의 극한에서 분수식인 경우 분모, 분자를 각각 인수분해하여 공통인 인수를 약분한 후 극한값을 계산한다.\n1st 주어진 조건을 활용하여 두 점 $C$, $D$의 좌표를 구하자.\n두 점 $A\\left(t, \\sqrt{2}t\\right)$, $B(2t, 0)$에 대하여 선분 $AB$의 중점 $C$의 좌표는 $C\\left(\\frac{3}{2} t, \\frac{\\sqrt{2}}{2} t\\right)$이다. (두 점 $(x_{1},y_{1})$,$(x_{2},y_{2})$의 중점의 좌표는 $\\left(\\frac{x_{1}+x_{2}}{2}, \\frac{y_{1}+y_{2}}{2}\\right)$)\n한편, 직선 $AB$의 기울기는 $\\frac{0-\\sqrt{2}t}{2t-t}=-\\frac{\\sqrt{2}t}{t}=-\\sqrt{2}$ (두 점 $(x_{1},y_{1})$,$(x_{2},y_{2})$를 지나는 직선의 기울기는 $\\frac{y_{2}-y_{1}}{x_{2}-x_{1}}$)\n이므로 직선 $AB$에 수직인 직선의 기울기는 $\\frac{1}{\\sqrt{2}}$이다. (두 직선이 수직이면 두 직선의 기울기의 곱은 $-1$이야)\n즉, 점 $C$를 지나고 직선 $AB$에 수직인 직선을 $l$이라 하면 직선 $l$의 방정식은 $y=\\left(\\frac{\\sqrt{2}}{2}\\right)\\left(x-\\frac{3}{2} t\\right)+\\frac{\\sqrt{2}}{2} t \\cdots$ ㉠ (점 $(x_{1},y_{1})$을 지나고 기울기가 $m$인 직선의 방정식은 $y-y_{1}=m(x-x_{1})$)\n이때, 점 $D$는 직선 $l$과 직선 $x=2t$의 교점이므로 ㉠에 $x=2t$를 대입하면 $y=\\left(\\frac{\\sqrt{2}}{2}\\right)\\left(2t-\\frac{3}{2} t\\right)+\\frac{\\sqrt{2}}{2} t=\\frac{3\\sqrt{2}}{4} t$\n즉, 점 $D$의 좌표는 $D\\left(2t, \\frac{3\\sqrt{2}}{4} t\\right)$이다.\n2nd 두 점 사이의 거리 공식을 이용하여 $f(t)$를 구하자.\n$f(t)=CD=\\sqrt{\\left(2t-\\frac{3}{2} t\\right)^{2}+\\left(\\frac{3\\sqrt{2}}{4} t-\\frac{\\sqrt{2}}{2} t\\right)^{2}}=\\sqrt{\\frac{3}{8} t^{2}}=\\frac{\\sqrt{6}}{4} t (\\because t>0)$\n[주의] $t>0$이라는 조건을 놓쳐서는 안 돼. 만약 $t<0$이라는 조건이 있었다면 $f(t)=-\\frac{\\sqrt{6}}{4} t$가 되겠지?\n3rd 주어진 극한값을 계산하자.\n$\\lim_{t \\to 4} \\frac{t^{2}-16}{f(t)-\\sqrt{6}} = \\lim_{t \\to 4} \\frac{t^{2}-4^{2}}{\\frac{\\sqrt{6}}{4} t-\\sqrt{6}} = \\lim_{t \\to 4} \\frac{4(t-4)(t+4)}{\\sqrt{6}(t-4)} = \\lim_{t \\to 4} \\frac{4(t+4)}{\\sqrt{6}} = \\frac{32}{\\sqrt{6}} = \\frac{16\\sqrt{6}}{3}$\n따라서 $k=\\frac{16\\sqrt{6}}{3}$이므로 $3k^{2}=3 \\times \\left(\\frac{16\\sqrt{6}}{3}\\right)^{2}=512$", "img": "IMG_4953.jpg"}, {"id": "A189", "section": "A", "num": 189, "page": 49, "topic": "길이에 대한 극한의 활용", "answer": "③", "rate": "64%", "problem": "그림과 같이 곡선 $y=x^{2}$ 위의 점 $P(t, t^{2})(t>0)$과 원점 $O$에 대하여 선분 $OP$의 중점을 $M$이라 하고, 점 $M$을 지나면서 $x$축에 평행한 직선이 곡선 $y=x^{2}$과 만나는 두 점을 각각 $A$, $B$라 하자. $\\lim_{t \\to 0+} \\frac{AB}{OP}$의 값은? (4점)\n[단서] ❶, ❷를 이용하여 두 선분 $AB$, $OP$의 길이를 $t$에 관한 식으로 나타내 봐.", "explanation": "정답 공식: 두 점 $(x_{1}, y_{1})$, $(x_{2}, y_{2})$ 사이의 거리는 $\\sqrt{(x_{2}-x_{1})^{2}+(y_{2}-y_{1})^{2}}$이다.\n1st 두 선분 $AB$, $OP$의 길이를 각각 구하자.\n두 점 $P$, $O$ 사이의 거리는 $OP=\\sqrt{t^{2}+t^{4}}$ (두 점 $A(x_{1},y_{1})$, $B(x_{2},y_{2})$ 사이의 거리는 $AB=\\sqrt{(x_{2}-x_{1})^{2}+(y_{2}-y_{1})^{2}}$)\n선분 $OP$의 중점인 점 $M$의 좌표는 $\\left(\\frac{t}{2}, \\frac{t^{2}}{2}\\right)$이므로 점 $M$을 지나고 $x$축에 평행한 직선 $AB$의 방정식은 $y=\\frac{t^{2}}{2}$ (두 점 $A(x_{1},y_{1})$, $B(x_{2},y_{2})$에 대하여 선분 $AB$의 중점의 좌표는 $\\left(\\frac{x_{1}+x_{2}}{2}, \\frac{y_{1}+y_{2}}{2}\\right)$)\n두 점 $A$, $B$는 직선 $AB$와 곡선 $y=x^{2}$의 교점이므로 두 점의 좌표는 각각 $A\\left(-\\frac{t}{\\sqrt{2}}, \\frac{t^{2}}{2}\\right)$, $B\\left(\\frac{t}{\\sqrt{2}}, \\frac{t^{2}}{2}\\right)$ ($y=x^{2}$에 점 $M$의 $y$좌표를 대입하는 거야. 즉, $\\frac{t^{2}}{2}=x^{2}$에서 $x=\\pm \\frac{t}{\\sqrt{2}}$)\n$\\therefore AB=\\frac{t}{\\sqrt{2}}-\\left(-\\frac{t}{\\sqrt{2}}\\right)=\\frac{2t}{\\sqrt{2}}=\\sqrt{2}t$\n2nd $\\lim_{t \\to 0+} \\frac{AB}{OP}$의 값을 구해.\n$\\therefore \\lim_{t \\to 0+} \\frac{AB}{OP} = \\lim_{t \\to 0+} \\frac{\\sqrt{2}t}{\\sqrt{t^{2}+t^{4}}} = \\lim_{t \\to 0+} \\frac{\\sqrt{2}}{\\sqrt{1+t^{2}}} = \\sqrt{2}$\n($\\frac{0}{0}$ 꼴이므로 분모와 분자의 공통인수를 찾아서 약분하면 돼. 즉, $\\sqrt{t^{2}(1+t^{2})}=|t|\\sqrt{1+t^{2}}$이고, $t>0$이니까 $t\\sqrt{1+t^{2}}$)", "img": "IMG_4954.jpg", "answer_value": "$\\sqrt{2}$"}, {"id": "A190", "section": "A", "num": 190, "page": 49, "topic": "길이에 대한 극한의 활용", "answer": "②", "rate": "69%", "problem": "그림과 같이 곡선 $y=-x^{2}+6$과 직선 $y=x$가 제$1$사분면에서 만나는 점을 $A$라 하고, 점 $A$에서 $x$축에 내린 수선의 발을 $B$라 하자. 직선 $y=x$ 위의 점 $P(a, a)$에서 선분 $AB$에 내린 수선의 발을 $Q$라 하고, 점 $P$를 지나고 $y$축에 평행한 직선이 곡선 $y=-x^{2}+6$과 만나는 점을 $R$라 할 때, $\\lim_{a \\to 2-} \\frac{PQ}{PR}$의 값은? (단, $0<a<2$) (4점)\n[단서1] 곡선과 직선의 교점의 $x$좌표는 두 식을 연립하여 $x$의 값을 구하면 돼. [단서2] $PQ$의 길이는 두 점 $P$, $Q$의 $x$좌표의 차와 같고, $PR$의 길이는 두 점 $P$, $R$의 $y$좌표의 차와 같아.", "explanation": "정답 공식: $x$축에 평행한 직선 위의 두 점 사이의 거리는 두 점의 $x$좌표의 차이고, $y$축에 평행한 직선 위의 두 점 사이의 거리는 두 점의 $y$좌표의 차이다.\n1st 점 $A$의 좌표를 구하고, $PQ$, $PR$의 길이를 각각 $a$에 관한 식으로 나타내자.\n점 $A$는 곡선 $y=-x^{2}+6$과 직선 $y=x$가 만나는 점이므로 $-x^{2}+6=x$, $x^{2}+x-6=0$\n$(x+3)(x-2)=0 \\therefore x=2 (\\because x>0) \\Rightarrow A(2, 2)$\n따라서 점 $P(a, a)$에 대하여\n$PQ=2-a$ (점 $P$의 $x$좌표는 $a$, 점 $Q$의 $x$좌표는 $2$이므로 두 점 $P$, $Q$의 $x$좌표의 차는 $2-a$야)\n$PR=-a^{2}+6-a$ (점 $P$의 $y$좌표는 $a$, 점 $R$의 $y$좌표는 $-a^{2}+6$이므로 두 점 $P$, $R$의 $y$좌표의 차는 $(-a^{2}+6)-a$야)\n2nd 주어진 극한값을 구하자.\n$\\therefore \\lim_{a \\to 2-} \\frac{PQ}{PR} = \\lim_{a \\to 2-} \\frac{2-a}{-a^{2}-a+6}$ ($a$에 $2$를 대입하면 $\\frac{0}{0}$ 꼴이 나오므로 우선 분모의 식을 인수분해하자)\n$= \\lim_{a \\to 2-} \\frac{2-a}{(a+3)(2-a)} = \\lim_{a \\to 2-} \\frac{1}{a+3} = \\frac{1}{5}$ ($2-a$가 분자, 분모의 공통인수이므로 약분하자)", "img": "IMG_4954.jpg", "answer_value": "$\\frac{1}{5}$"}, {"id": "A191", "section": "A", "num": 191, "page": 50, "topic": "길이에 대한 극한의 활용", "answer": "②", "rate": "70%", "problem": "실수 $t(t>0)$에 대하여 직선 $y=x+t$와 곡선 $y=x^{2}$이 만나는 두 점을 $A$, $B$라 하자. 점 $A$를 지나고 $x$축에 평행한 직선이 곡선 $y=x^{2}$과 만나는 점 중 $A$가 아닌 점을 $C$, 점 $B$에서 선분 $AC$에 내린 수선의 발을 $H$라 하자. $\\lim_{t \\to 0+} \\frac{AH-CH}{t}$의 값은? (단, 점 $A$의 $x$좌표는 양수이다.) (4점)\n[단서1] 직선과 곡선의 식을 연립하여 두 점 $A$, $B$의 좌표를 $t$에 대한 식으로 나타내봐. [단서2] 점 $C$는 점 $A$와 $y$좌표가 같고, 점 $H$는 점 $B$와 $x$좌표가 같아. [단서3] $AH$, $CH$를 $t$에 대한 식으로 나타내고, 극한값을 구해.", "explanation": "정답 공식: 세 점 $A$, $C$, $H$의 좌표를 구한 후 $AH$, $CH$를 $t$에 대한 식으로 나타내어 극한식에 대입한다.\n1st $AH$, $CH$를 $t$에 대한 식으로 나타내.\n두 점 $A$, $B$의 $x$좌표는 각각 방정식 $x^{2}=x+t$의 두 실근이므로 이차방정식 $x^{2}-x-t=0$의 근을 구하면\n$x=\\frac{-(-1)\\pm \\sqrt{(-1)^{2}-4 \\times 1 \\times (-t)}}{2 \\times 1}=\\frac{1\\pm \\sqrt{1+4t}}{2}$\n즉, 점 $A$의 $x$좌표는 $\\frac{1+\\sqrt{1+4t}}{2}$, 점 $B$의 $x$좌표는 $\\frac{1-\\sqrt{1+4t}}{2}$이다. ($t>0$이므로 $\\frac{1+\\sqrt{1+4t}}{2}>0$, $\\frac{1-\\sqrt{1+4t}}{2}<0$이야. 따라서 점 $A$의 $x$좌표가 양수이다 했으므로 점 $A$의 $x$좌표가 $\\frac{1+\\sqrt{1+4t}}{2}$가 되는 거야.)\n이때, $x=\\frac{1+\\sqrt{1+4t}}{2}$를 $y=x+t$에 대입하면 $y=\\frac{1+\\sqrt{1+4t}}{2}+t=\\frac{1+2t+\\sqrt{1+4t}}{2}$이므로 $A\\left(\\frac{1+\\sqrt{1+4t}}{2}, \\frac{1+2t+\\sqrt{1+4t}}{2}\\right)$이다.\n한편, 점 $A$를 지나고 $x$축에 평행한 직선의 방정식은 $y=\\frac{1+2t+\\sqrt{1+4t}}{2}$이므로\n$C\\left(\\frac{-1-\\sqrt{1+4t}}{2}, \\frac{1+2t+\\sqrt{1+4t}}{2}\\right)$ (곡선 $y=x^{2}$은 $y$축에 대하여 대칭이므로 곡선 $y=x^{2}$과 $x$축에 평행한 직선이 만나는 두 점 $A$, $C$의 $x$좌표는 절댓값이 같고 부호는 반대야. 또, $y$좌표는 같아.)\n$H\\left(\\frac{1-\\sqrt{1+4t}}{2}, \\frac{1+2t+\\sqrt{1+4t}}{2}\\right)$이다. (점 $H$의 $x$좌표는 점 $B$의 $x$좌표와 같고, $y$좌표는 점 $A$의 $y$좌표와 같아.)\n따라서 $AH$, $CH$의 길이를 $t$에 대한 식으로 나타내면\n$AH=\\frac{1+\\sqrt{1+4t}}{2}-\\frac{1-\\sqrt{1+4t}}{2}=\\sqrt{1+4t}$\n$CH=\\frac{1-\\sqrt{1+4t}}{2}-\\frac{-1-\\sqrt{1+4t}}{2}=1$\n2nd $\\lim_{t \\to 0+} \\frac{AH-CH}{t}$의 값을 구해.\n$\\therefore \\lim_{t \\to 0+} \\frac{AH-CH}{t} = \\lim_{t \\to 0+} \\frac{\\sqrt{1+4t}-1}{t}$ ($\\frac{0}{0}$ 꼴이고 분자에 무리식이 포함되어 있으므로 분자를 유리화해야 해)\n$= \\lim_{t \\to 0+} \\frac{\\left(\\sqrt{1+4t}-1\\right)\\left(\\sqrt{1+4t}+1\\right)}{t\\left(\\sqrt{1+4t}+1\\right)}$\n$= \\lim_{t \\to 0+} \\frac{(1+4t)-1}{t\\left(\\sqrt{1+4t}+1\\right)}$\n$= \\lim_{t \\to 0+} \\frac{4t}{t\\left(\\sqrt{1+4t}+1\\right)}$\n$= \\lim_{t \\to 0+} \\frac{4}{\\sqrt{1+4t}+1} = \\frac{4}{1+1} = 2$\n[쉬운 풀이: 이차방정식의 근과 계수의 관계 이용하기]\n곡선 $y=x^{2}$ 위의 두 점 $A$, $B$의 좌표를 각각 $A(a, a^{2})$, $B(b, b^{2}) (a>0, b<0)$이라 하자.\n두 점 $A$, $B$의 $x$좌표는 이차방정식 $x^{2}=x+t$의 두 근이므로 이차방정식 $x^{2}-x-t=0$의 두 근이 $a$, $b$야. 즉, 이차방정식의 근과 계수의 관계에 의하여 $a+b=1$, $ab=-t$야.\n한편, 점 $A$를 지나고 $x$축에 평행한 직선의 방정식은 $y=a^{2}$이고, 점 $H$의 $x$좌표는 점 $B$의 $x$좌표와 같으므로 $H(b, a^{2})$이야.\n$\\therefore AH=a-b=\\sqrt{(a-b)^{2}}=\\sqrt{(a+b)^{2}-4ab}=\\sqrt{1+4t}$\n[함정] $(a-b)^{2}=(a+b)^{2}-4ab$를 이용하면 $a-b$의 값을 구할 수 있으므로 이차방정식의 해를 직접 구하지 않고 근과 계수의 관계를 이용하여 $AH$의 길이를 $t$에 대한 식으로 나타낼 수 있어.\n또한, 점 $C$의 좌표가 $C(-a, a^{2})$이므로 (점 $C$의 $x$좌표는 방정식 $x^{2}=a^{2}$의 음수인 해인 $-a$야) $CH=b-(-a)=a+b=1$\n(이하 동일)", "img": "IMG_4955.jpg", "answer_value": "$2$"}, {"id": "A192", "section": "A", "num": 192, "page": 50, "topic": "길이에 대한 극한의 활용", "answer": "$54$", "rate": "55%", "problem": "실수 $t(t>1)$에 대하여 곡선 $y=\\frac{2t}{x}$와 직선 $y=-\\frac{1}{t}x+3$이 만나는 두 점을 $A$, $B$라 하자. $\\lim_{t \\to 1+} \\frac{OB-OA}{t-1}=k$라 할 때, $30 \\times k^{2}$의 값을 구하시오. (단, $O$는 원점이고, 점 $B$의 $x$좌표는 점 $A$의 $x$좌표보다 크다.) (4점) [단서1] 곡선 $y=\\frac{2t}{x}$와 직선 $y=-\\frac{1}{t}x+3$을 연립하여 두 점 $A$, $B$의 좌표를 각각 $t$에 대한 식으로 나타낼 수 있어. [단서2] $OA$, $OB$의 길이를 $t$에 대한 식으로 나타내고 주어진 식에 대입하여 극한값을 구해.", "explanation": "정답 공식: $OA$, $OB$의 길이를 $t$에 대한 식으로 나타내고 극한 식에 대입하여 극한값을 구한다.\n1st 두 점 $A$, $B$의 좌표를 각각 구하고 $OA$, $OB$의 길이를 $t$에 관한 식으로 나타내.\n곡선 $y=\\frac{2t}{x}$와 직선 $y=-\\frac{1}{t}x+3$이 만나는 두 점 $A$, $B$의 $x$좌표를 구하기 위해 두 식을 연립하면 ($A$, $B$의 $x$좌표는 방정식 $\\frac{2t}{x}=-\\frac{1}{t}x+3$의 두 근이야)\n$\\frac{2t}{x}=-\\frac{1}{t}x+3$에서 $2t^{2}=-x^{2}+3tx$\n즉, $x^{2}-3tx+2t^{2}=0$, $(x-t)(x-2t)=0 \\therefore x=t$ 또는 $x=2t$\n두 점 $A$, $B$는 곡선 $y=\\frac{2t}{x}$ 위의 점이므로 $A(t, 2)$, $B(2t, 1)$이다. (실수 $t$가 $1$보다 큰 양수이므로 $t<2t$야. 따라서 점 $A$의 $x$좌표가 $t$, 점 $B$의 $x$좌표가 $2t$가 돼.)\n$\\therefore OA=\\sqrt{t^{2}+4}$, $OB=\\sqrt{4t^{2}+1}$\n2nd $\\lim_{t \\to 1+} \\frac{OB-OA}{t-1}$의 값을 구해.\n$\\therefore \\lim_{t \\to 1+} \\frac{OB-OA}{t-1} = \\lim_{t \\to 1+} \\frac{\\sqrt{4t^{2}+1}-\\sqrt{t^{2}+4}}{t-1}$ ($\\frac{0}{0}$ 꼴의 극한이고 무리식이 포함되어 있으므로 분자를 유리화한 후 분모, 분자의 공통인수를 약분하면 돼)\n$= \\lim_{t \\to 1+} \\frac{\\left(\\sqrt{4t^{2}+1}-\\sqrt{t^{2}+4}\\right)\\left(\\sqrt{4t^{2}+1}+\\sqrt{t^{2}+4}\\right)}{(t-1)\\left(\\sqrt{4t^{2}+1}+\\sqrt{t^{2}+4}\\right)}$\n$= \\lim_{t \\to 1+} \\frac{3(t^{2}-1)}{(t-1)\\left(\\sqrt{4t^{2}+1}+\\sqrt{t^{2}+4}\\right)}$\n$= \\lim_{t \\to 1+} \\frac{3(t-1)(t+1)}{(t-1)\\left(\\sqrt{4t^{2}+1}+\\sqrt{t^{2}+4}\\right)}$\n$= \\lim_{t \\to 1+} \\frac{3(t+1)}{\\sqrt{4t^{2}+1}+\\sqrt{t^{2}+4}} = \\frac{6}{2\\sqrt{5}} = \\frac{3}{5}\\sqrt{5}$\n3rd $30 \\times k^{2}$의 값을 구해.\n따라서 $k=\\frac{3}{5}\\sqrt{5}$이므로 $30 \\times k^{2}=30 \\times \\left(\\frac{3}{5}\\sqrt{5}\\right)^{2}=54$이다.", "img": "IMG_4955.jpg"}, {"id": "A193", "section": "A", "num": 193, "page": 51, "topic": "도형의 길이에 대한 극한", "answer": "②", "rate": "48%", "problem": "그림과 같이 길이가 $2$인 선분 $AB$를 지름으로 하는 반원과 선분 $AB$의 중점 $O$가 있다. 호 $AB$ 위의 점 $P$에 대하여 점 $P$를 지나고 직선 $AB$와 평행한 직선과 점 $B$를 지나고 직선 $OP$와 평행한 직선이 만나는 점을 $Q$라 하자. $BP=t$라 할 때, $\\lim_{t \\to 0+} \\frac{3-AQ}{t^{2}}$의 값은? (단, $0<t<\\sqrt{2}$) (4점)\n[단서1] 사각형 $OBQP$는 평행사변형이야. [단서2] $AQ$를 $t$에 관한 식으로 나타내어야 해.", "explanation": "정답 공식: 원의 성질과 피타고라스 정리 등을 이용하여 선분의 길이를 $t$에 대한 식으로 나타낸 후 $\\frac{0}{0}$ 꼴의 극한을 계산한다.\n1st $AQ$를 $t$에 대한 식으로 나타내자.\n그림과 같이 두 점 $P$, $Q$에서 직선 $AB$에 내린 수선의 발을 각각 $H_{1}$, $H_{2}$라 하자. (원에서 지름에 대한 원주각의 크기는 $90^{\\circ}$이니까 $\\angle APB=90^{\\circ}$야)\n직각삼각형 $ABP$에서 $AB=2$, $BP=t$이므로 피타고라스 정리에 의하여 $AP=\\sqrt{AB^{2}-BP^{2}}=\\sqrt{4-t^{2}} \\cdots$ ㉠\n또한, 직각삼각형 $OH_{1}P$에서 $OP=1$이므로 피타고라스 정리에 의하여 $OH_{1}^{2}+PH_{1}^{2}=OP^{2}=1$이고 직각삼각형 $AH_{1}P$에서 피타고라스 정리에 의하여\n$AP^{2}=AH_{1}^{2}+PH_{1}^{2}=(1+OH_{1})^{2}+PH_{1}^{2} (AH_{1}=AO+OH_{1}=1+OH_{1})$\n$=1+2OH_{1}+OH_{1}^{2}+PH_{1}^{2} (OH_{1}^{2}+PH_{1}^{2}=1)$\n$=2+2OH_{1} \\cdots$ ㉡\n㉠, ㉡에 의하여 $4-t^{2}=2+2OH_{1} \\therefore OH_{1}=1-\\frac{t^{2}}{2}$\n즉, 직각삼각형 $OH_{1}P$에서 피타고라스 정리에 의하여\n$PH_{1}=\\sqrt{OP^{2}-OH_{1}^{2}}=\\sqrt{1^{2}-\\left(1-\\frac{t^{2}}{2}\\right)^{2}}=\\sqrt{1-\\left(1-t^{2}+\\frac{t^{4}}{4}\\right)}=\\sqrt{t^{2}-\\frac{t^{4}}{4}}=\\sqrt{\\frac{4t^{2}-t^{4}}{4}}=\\sqrt{\\frac{t^{2}(4-t^{2})}{4}}=\\frac{t}{2}\\sqrt{4-t^{2}} (\\because t>0)$\n이때, 두 직각삼각형 $POH_{1}$과 $QBH_{2}$는 합동이므로 (사각형 $OBQP$가 평행사변형이므로 $OP=BQ$이고, $\\angle POB=\\angle POH_{1}=\\angle QBH_{2}$이야. 즉, 두 직각삼각형의 빗변의 길이가 같고 직각이 아닌 한 각의 크기가 같으므로 RHA 합동이야.)\n$BH_{2}=OH_{1}$, $QH_{2}=PH_{1}$\n따라서 직각삼각형 $AH_{2}Q$에서 피타고라스 정리에 의하여\n$AQ=\\sqrt{AH_{2}^{2}+QH_{2}^{2}}=\\sqrt{(2+BH_{2})^{2}+QH_{2}^{2}} (AH_{2}=AB+BH_{2}=2+BH_{2})$\n$=\\sqrt{(2+OH_{1})^{2}+PH_{1}^{2}}=\\sqrt{\\left\\{2+\\left(1-\\frac{t^{2}}{2}\\right)\\right\\}^{2}+\\frac{t^{2}}{4}(4-t^{2})}$\n$=\\sqrt{\\left(3-\\frac{t^{2}}{2}\\right)^{2}+t^{2}-\\frac{t^{4}}{4}}=\\sqrt{9-3t^{2}+\\frac{t^{4}}{4}+t^{2}-\\frac{t^{4}}{4}}$\n$=\\sqrt{9-2t^{2}}$\n2nd $\\lim_{t \\to 0+} \\frac{3-AQ}{t^{2}}$의 값을 구하자.\n$\\therefore \\lim_{t \\to 0+} \\frac{3-AQ}{t^{2}} = \\lim_{t \\to 0+} \\frac{3-\\sqrt{9-2t^{2}}}{t^{2}} = \\lim_{t \\to 0+} \\frac{9-(9-2t^{2})}{t^{2}\\left(3+\\sqrt{9-2t^{2}}\\right)}$ ($\\frac{0}{0}$ 꼴이므로 유리화를 이용하여 $t^{2}$을 약분해야 해)\n$= \\lim_{t \\to 0+} \\frac{2t^{2}}{t^{2}\\left(3+\\sqrt{9-2t^{2}}\\right)}$\n$= \\lim_{t \\to 0+} \\frac{2}{3+\\sqrt{9-2t^{2}}} = \\frac{2}{3+3} = \\frac{1}{3}$\n[다른 풀이: 이등변삼각형의 성질과 삼각형의 넓이 이용하기]\n그림과 같이 점 $O$에서 선분 $PB$에 내린 수선의 발을 $H_{1}$, 두 점 $P$, $Q$에서 직선 $AB$에 내린 수선의 발을 각각 $H_{2}$, $H_{3}$이라 하자.\n이때, $OB=OP=1$이고 $BH_{1}=PH_{1}=\\frac{t}{2}$이므로 (삼각형 $OBP$는 $OB=OP$인 이등변삼각형이므로 $BH_{1}=PH_{1}=\\frac{1}{2}BP$야) 직각삼각형 $OH_{1}P$에서 피타고라스 정리에 의하여\n$OH_{1}=\\sqrt{OP^{2}-PH_{1}^{2}}=\\sqrt{1^{2}-\\frac{1}{4}t^{2}}=\\sqrt{\\frac{4-t^{2}}{4}}=\\frac{\\sqrt{4-t^{2}}}{2}$\n따라서 삼각형 $OBP$의 넓이에 의하여 $\\triangle OBP=\\frac{1}{2} \\times BP \\times OH_{1}=\\frac{1}{2} \\times OB \\times PH_{2}$에서\n$\\frac{1}{2} \\times t \\times \\frac{\\sqrt{4-t^{2}}}{2}=\\frac{1}{2} \\times 1 \\times PH_{2} \\therefore PH_{2}=\\frac{t\\sqrt{4-t^{2}}}{2}$\n또, 직각삼각형 $OH_{2}P$에서 피타고라스 정리에 의하여\n$OH_{2}=\\sqrt{OP^{2}-PH_{2}^{2}}=\\sqrt{1-\\frac{t^{2}(4-t^{2})}{4}}=\\sqrt{\\frac{4-4t^{2}+t^{4}}{4}}=\\frac{\\sqrt{(t^{2}-2)^{2}}}{2}=\\frac{2-t^{2}}{2}=1-\\frac{t^{2}}{2}$ ($0<t<\\sqrt{2}$에서 $0<t^{2}<2$이므로 $t^{2}-2<0 \\therefore \\sqrt{(t^{2}-2)^{2}}=-(t^{2}-2)=2-t^{2}$)\n한편, $BH_{3}=OH_{2}$이므로 $AH_{3}=AB+BH_{3}=AB+OH_{2}=2+1-\\frac{t^{2}}{2}=3-\\frac{t^{2}}{2}$이고\n$QH_{3}=PH_{2}=\\frac{t\\sqrt{4-t^{2}}}{2}$이므로 직각삼각형 $AH_{3}Q$에서 피타고라스 정리에 의하여\n$AQ=\\sqrt{AH_{3}^{2}+QH_{3}^{2}}=\\sqrt{\\left(3-\\frac{t^{2}}{2}\\right)^{2}+\\left(\\frac{t\\sqrt{4-t^{2}}}{2}\\right)^{2}}=\\sqrt{9-2t^{2}}$\n(이하 동일)", "img": "IMG_4956.jpg", "answer_value": "$\\frac{1}{3}$"}, {"id": "A194", "section": "A", "num": 194, "page": 52, "topic": "길이에 대한 극한의 활용", "answer": "⑤", "rate": "55%", "problem": "그림과 같이 중심이 $C(2, 0)$이고 반지름의 길이가 $r\\left(r<\\sqrt{5}\\right)$인 원 $C$가 있다. 기울기가 $-2$이고 원 $C$에 접하는 직선을 $l$이라 하자. 직선 $l$에 접하고 중심이 $C'(3, 3)$인 원 $C'$의 반지름을 $f(r)$라 할 때, $\\lim_{r \\to 0+} f(r)$의 값은? (4점)\n[단서1] 직선 $l$의 방정식은 $y=-2x+a$라 놓을 수 있어. [단서2] 점과 직선 사이의 거리를 이용하여 $r$, $f(r)$를 나타내.", "explanation": "정답 공식: 원에 접하는 직선을 $l$이라 하면 이 원의 중심과 직선 $l$ 사이의 거리는 원의 반지름의 길이와 같다.\n1st 점과 직선 사이의 거리를 이용하여 원 $C'$의 반지름의 길이를 $r$에 대한 식으로 표현해.\n기울기가 $-2$인 직선 $l$의 $y$절편을 $a$라 하면 직선 $l$의 방정식은 $y=-2x+a \\therefore 2x+y-a=0$\n이때, 직선 $l$이 중심이 $C(2, 0)$이고 반지름의 길이가 $r$인 원 $C$에 접하므로 $r$는 점 $C(2, 0)$과 직선 $l$: $2x+y-a=0$ 사이의 거리와 같다.\n즉, $r=\\frac{|2 \\times 2-a|}{\\sqrt{2^{2}+1^{2}}}=\\frac{|4-a|}{\\sqrt{5}}$에서 $a=4 \\pm \\sqrt{5}r \\cdots$ ㉠ (점 $(x_{1}, y_{1})$과 직선 $ax+by+c=0$ 사이의 거리를 $d$라 할 때 $d=\\frac{|ax_{1}+by_{1}+c|}{\\sqrt{a^{2}+b^{2}}}$)\n마찬가지로 직선 $l$이 중심이 $C'(3, 3)$이고 반지름의 길이가 $f(r)$인 원 $C'$에 접하므로 ($f(r)$는 점 $C'(3, 3)$과 직선 $l$: $2x+y-a=0$ 사이의 거리와 같아)\n$f(r)=\\frac{|2 \\times 3+3-a|}{\\sqrt{2^{2}+1^{2}}}=\\frac{|9-a|}{\\sqrt{5}} \\cdots$ ㉡\n㉠을 ㉡에 대입하면 $f(r)=\\frac{\\left|9-\\left(4 \\pm \\sqrt{5}r\\right)\\right|}{\\sqrt{5}}=\\frac{\\left|5 \\pm \\sqrt{5}r\\right|}{\\sqrt{5}}$\n2nd $\\lim_{r \\to 0+} f(r)$의 값을 구하자.\n$\\therefore \\lim_{r \\to 0+} f(r)=\\lim_{r \\to 0+} \\frac{\\left|5 \\pm \\sqrt{5}r\\right|}{\\sqrt{5}}=\\sqrt{5}$", "img": "IMG_4957.jpg", "answer_value": "$\\sqrt{5}$"}, {"id": "A195", "section": "A", "num": 195, "page": 52, "topic": "길이에 대한 극한의 활용", "answer": "③", "rate": "57%", "problem": "그림과 같이 직선 $y=x+1$ 위에 두 점 $A(-1, 0)$과 $P(t, t+1)$이 있다. 점 $P$를 지나고 직선 $y=x+1$에 수직인 직선이 $y$축과 만나는 점을 $Q$라 할 때, $\\lim_{t \\to \\infty} \\frac{AQ^{2}}{AP^{2}}$의 값은? (3점)\n[단서] 직선 $y=x+1$에 수직이므로 기울기가 $-1$이야. 또한 이 직선은 점 $P(t, t+1)$을 지나.", "explanation": "정답 공식: 서로 수직인 두 직선의 기울기의 곱은 $-1$이다.\n1st 직선 $y=x+1$에 수직인 직선의 방정식의 기울기는 $-1$이지?\n직선 $y=x+1$에 수직이고 점 $P(t, t+1)$을 지나는 직선을 $l$이라 하고 직선 $l$의 방정식을 구하자. (점 $(a, b)$를 지나고 기울기가 $m$인 직선의 방정식은 $y=m(x-a)+b$)\n$l$: $y=(-1) \\times (x-t)+t+1=-x+2t+1$\n따라서 직선 $l$이 $y$축과 만나는 점 $Q$의 좌표는 $(0, 2t+1)$이다.\n2nd 두 점 $A(x_{1}, y_{1})$, $B(x_{2}, y_{2})$ 사이의 거리는 $\\sqrt{(x_{2}-x_{1})^{2}+(y_{2}-y_{1})^{2}}$이야.\n$AP=\\sqrt{(t+1)^{2}+(t+1)^{2}}=\\sqrt{2}(t+1)$\n$AQ=\\sqrt{(0+1)^{2}+(2t+1-0)^{2}}=\\sqrt{4t^{2}+4t+2}$\n$\\therefore \\lim_{t \\to \\infty} \\frac{AQ^{2}}{AP^{2}} = \\lim_{t \\to \\infty} \\frac{4t^{2}+4t+2}{2(t+1)^{2}} = \\lim_{t \\to \\infty} \\frac{4+\\frac{4}{t}+\\frac{2}{t^{2}}}{2+\\frac{4}{t}+\\frac{2}{t^{2}}} = 2$", "img": "IMG_4957.jpg", "answer_value": "$2$"}, {"id": "A196", "section": "A", "num": 196, "page": 53, "topic": "도형의 넓이에 대한 극한", "answer": "③", "rate": "64%", "problem": "실수 $t(t>1)$에 대하여 직선 $x=t$가 두 곡선 $y=x^{2}$, $y=\\sqrt{x}$와 만나는 점을 각각 $P$, $Q$라 하자. 점 $A(1, 1)$에 대하여 삼각형 $APQ$의 넓이를 $S(t)$라 할 때, $\\lim_{t \\to 1+} \\frac{S(t)}{(t-1)^{2}}$의 값은? (4점)\n[단서1] 두 점 $P$, $Q$를 $t$에 관한 식으로 나타낼 수 있어. [단서2] 삼각형 $APQ$의 넓이 $S(t)$를 $t$에 관한 식으로 나타낼 수 있어. [단서3] 근호가 포함된 $\\frac{0}{0}$ 꼴의 극한에서 유리화하여 식을 정리할 수 있고 인수분해한 후 분모, 분자의 공통인수를 약분할 수 있어.", "explanation": "정답 공식: 점 $P$, $Q$의 좌표를 $t$에 대한 식으로 나타낸다. 삼각형 $APQ$의 넓이 $S(t)$는 $\\frac{1}{2} \\times (t-1) \\times$($PQ$의 길이)이다.\n1st 두 점 $P$, $Q$의 좌표를 구하고 삼각형 $APQ$의 넓이 $S(t)$를 $t$에 관한 식으로 나타내.\n점 $P$의 좌표는 $P(t, t^{2})$, 점 $Q$의 좌표는 $Q\\left(t, \\sqrt{t}\\right)$이고 점 $A$에서 직선 $x=t$에 내린 수선의 발을 $H$라 하면 $H(t, 1)$이다.\n따라서 $PQ=t^{2}-\\sqrt{t}$, $AH=t-1$ (점 $A$와 점 $H$의 $y$좌표는 $1$로 같으므로 $AH$는 $x$축에 평행해. 따라서 $AH$의 길이는 점 $H$와 점 $A$의 $x$좌표 값의 차이야.)\n즉, 삼각형 $APQ$의 넓이 $S(t)$는 $S(t)=\\frac{1}{2} \\times PQ \\times AH=\\frac{1}{2} \\times \\left(t^{2}-\\sqrt{t}\\right) \\times (t-1)$\n2nd 유리화를 이용하여 극한값 $\\lim_{t \\to 1+} \\frac{S(t)}{(t-1)^{2}}$의 값을 구해.\n$\\therefore \\lim_{t \\to 1+} \\frac{S(t)}{(t-1)^{2}} = \\lim_{t \\to 1+} \\frac{\\left(t^{2}-\\sqrt{t}\\right)(t-1)}{2(t-1)^{2}}$\n$=\\frac{1}{2} \\times \\lim_{t \\to 1+} \\frac{\\left(t^{2}-\\sqrt{t}\\right)(t-1)}{(t-1)^{2}} \\times \\frac{t^{2}+\\sqrt{t}}{t^{2}+\\sqrt{t}}$ ($\\lim_{t \\to 1+} \\frac{\\left(t^{2}-\\sqrt{t}\\right)(t-1)}{(t-1)^{2}}$이 $\\frac{0}{0}$ 꼴이므로 분자에 있는 $t^{2}-\\sqrt{t}$를 유리화하기 위해 분모와 분자에 각각 $t^{2}+\\sqrt{t}$를 곱한 거야.)\n$=\\frac{1}{2} \\times \\lim_{t \\to 1+} \\frac{(t^{4}-t)(t-1)}{(t-1)^{2}\\left(t^{2}+\\sqrt{t}\\right)}$\n$=\\frac{1}{2} \\times \\lim_{t \\to 1+} \\frac{t(t-1)(t^{2}+t+1)(t-1)}{(t-1)^{2}\\left(t^{2}+\\sqrt{t}\\right)}$\n$=\\frac{1}{2} \\times \\lim_{t \\to 1+} \\frac{t(t^{2}+t+1)}{t^{2}+\\sqrt{t}}$\n$=\\frac{1}{2} \\times \\frac{3}{2}=\\frac{3}{4}$", "img": "IMG_4958.jpg", "answer_value": "$\\frac{3}{4}$"}, {"id": "A197", "section": "A", "num": 197, "page": 53, "topic": "도형의 넓이에 대한 극한", "answer": "④", "rate": "78%", "problem": "그림과 같이 좌표평면에서 양의 실수 $t$에 대하여 함수 $f(x)=\\sqrt{x}$의 그래프가 두 직선 $x=t$, $x=t+4$와 만나는 점을 각각 $A$, $B$라 하고, 점 $A$에서 직선 $x=t+4$에 내린 수선의 발을 $C$라 하자. 삼각형 $ABC$의 넓이를 $S(t)$라 할 때, $\\lim_{t \\to \\infty} \\frac{\\sqrt{t} \\times S(t)}{2}$의 값은? (4점)\n[단서1] 세 점 $A$, $B$, $C$의 좌표를 모두 $t$에 대하여 나타낼 수 있으므로 삼각형 $ABC$의 넓이 $S(t)$도 $t$에 대한 식으로 나타낼 수 있지. [단서2] $\\infty-\\infty$ 꼴의 극한에서 근호를 포함하고 있는 경우는 분자를 유리화하여 $\\frac{\\infty}{\\infty}$ 꼴로 변형해.", "explanation": "정답 공식: 세 점 $A$, $B$, $C$의 좌표를 $t$에 대한 식으로 나타낸 후 삼각형 $ABC$의 넓이 $S(t)$를 구한다.\n1st 세 점 $A$, $B$, $C$의 좌표를 구하고 삼각형 $ABC$의 넓이 $S(t)$를 $t$에 관한 식으로 나타내.\n$A\\left(t, \\sqrt{t}\\right)$, $B\\left(t+4, \\sqrt{t+4}\\right)$, $C\\left(t+4, \\sqrt{t}\\right)$이므로\n$AC=4 (AC=(t+4)-t=4)$, $BC=\\sqrt{t+4}-\\sqrt{t}$\n즉, 삼각형 $ABC$의 넓이는 $S(t)=\\frac{1}{2} \\times AC \\times BC=\\frac{1}{2} \\times 4 \\times \\left(\\sqrt{t+4}-\\sqrt{t}\\right)=2\\left(\\sqrt{t+4}-\\sqrt{t}\\right)$\n2nd 유리화를 이용하여 극한값 $\\lim_{t \\to \\infty} \\frac{\\sqrt{t} \\times S(t)}{2}$를 구해.\n$\\therefore \\lim_{t \\to \\infty} \\frac{\\sqrt{t} \\times S(t)}{2} = \\lim_{t \\to \\infty} \\sqrt{t} \\times \\frac{2\\left(\\sqrt{t+4}-\\sqrt{t}\\right)}{2}$\n$= \\lim_{t \\to \\infty} \\sqrt{t} \\times \\left(\\sqrt{t+4}-\\sqrt{t}\\right)$\n$= \\lim_{t \\to \\infty} \\sqrt{t} \\times \\frac{\\left(\\sqrt{t+4}-\\sqrt{t}\\right)\\left(\\sqrt{t+4}+\\sqrt{t}\\right)}{\\sqrt{t+4}+\\sqrt{t}}$\n$= \\lim_{t \\to \\infty} \\frac{4\\sqrt{t}}{\\sqrt{t+4}+\\sqrt{t}}$\n$= \\lim_{t \\to \\infty} \\frac{4}{\\sqrt{1+\\frac{4}{t}}+1}$ (분모, 분자를 각각 $\\sqrt{t}$로 나누면 $\\lim_{t \\to \\infty} \\frac{4\\sqrt{t}}{\\sqrt{t+4}+\\sqrt{t}}=\\lim_{t \\to \\infty} \\frac{4}{\\sqrt{\\frac{t+4}{t}}+1}=\\lim_{t \\to \\infty} \\frac{4}{\\sqrt{1+\\frac{4}{t}}+1}$)\n$=\\frac{4}{1+1}=2 \\left(\\lim_{t \\to \\infty} \\frac{1}{t}=0\\right)$", "img": "IMG_4958.jpg", "answer_value": "$2$"}, {"id": "A198", "section": "A", "num": 198, "page": 54, "topic": "도형의 넓이에 대한 극한", "answer": "2", "rate": "65%", "problem": "그림과 같이 곡선 $y=\\sqrt{4x-3}$ 위에 두 점 $A(1, 1)$과 $P\\left(t, \\sqrt{4t-3}\\right)$이 있다. 점 $A$에서 $x$축에 내린 수선의 발을 $B$, 점 $P$에서 $y$축에 내린 수선의 발을 $Q$라 할 때, 삼각형 $PAB$와 삼각형 $PQA$의 넓이를 각각 $S(t)$, $T(t)$라 하자. $\\lim_{t \\to 1+} \\frac{T(t)}{S(t)}$의 값을 구하시오. (단, $t>1$) (4점) [단서] 선분 $PQ$는 $x$축과 평행하고 선분 $AB$는 $y$축과 평행하니까 각각 길이를 구하기 쉽지. 따라서 주어진 점의 좌표를 이용하여 두 삼각형의 넓이를 각각 $t$에 대한 식으로 구할 수 있어.", "explanation": "정답 공식: 네 점 $A$, $B$, $P$, $Q$의 좌표를 이용해 $S(t)$, $T(t)$를 $t$에 대한 식으로 나타낸 후 극한을 계산한다. 이때, 무리식이 포함된 함수의 극한을 계산할 때, $\\frac{0}{0}$ 꼴은 무리식을 유리화한 후 해결한다.\n1st 점 $Q$의 좌표와 점 $B$의 좌표를 이용하여 두 삼각형 $PAB$와 $PQA$의 넓이를 구해.\n그림과 같이 점 $P$에서 $x$축에 내린 수선의 발을 $P'$이라 하면 $P'(t, 0)$이다. 또, 점 $A$에서 $y$축에 내린 수선의 발을 $A'$이라 하면 $A'(0, 1)$이고, 점 $A$의 좌표가 $A(1, 1)$이므로 점 $B$의 좌표는 $B(1, 0)$이다.\n$\\therefore S(t)=\\frac{1}{2} \\times AB \\times BP'$ ($AB$는 $y$축에 평행하므로 $AB=1-0=1$, $BP'=$(점 $P$의 $x$좌표)-(점 $B$의 $x$좌표)$=t-1$)\n$=\\frac{1}{2} \\times 1 \\times (t-1)=\\frac{1}{2}(t-1)$\n점 $P$의 좌표가 $P\\left(t, \\sqrt{4t-3}\\right)$이므로 점 $Q$의 좌표는 $Q\\left(0, \\sqrt{4t-3}\\right)$이다.\n$\\therefore T(t)=\\frac{1}{2} \\times PQ \\times A'Q$ ($PQ$는 $x$축에 평행하므로 $PQ=t-0=t$, $A'Q=$(점 $P$의 $y$좌표)-(점 $A$의 $y$좌표)$=\\sqrt{4t-3}-1$)\n$=\\frac{1}{2} \\times t \\times \\left(\\sqrt{4t-3}-1\\right)=\\frac{1}{2}t\\left(\\sqrt{4t-3}-1\\right)$\n[주의] 길이는 양수여야 하기 때문에 항상 큰 값에서 작은 값을 빼줘야 해. $t>1$에서 $t-1>0$이니까 $BP'=t-1$이야.\n2nd $\\lim_{t \\to 1+} \\frac{T(t)}{S(t)}$의 값을 구하자.\n$\\lim_{t \\to 1+} \\frac{T(t)}{S(t)} = \\lim_{t \\to 1+} \\frac{\\frac{1}{2}t\\left(\\sqrt{4t-3}-1\\right)}{\\frac{1}{2}(t-1)}$\n$= \\lim_{t \\to 1+} \\frac{t\\left(\\sqrt{4t-3}-1\\right)}{t-1}$\n$= \\lim_{t \\to 1+} \\frac{4t(t-1)}{(t-1)\\left(\\sqrt{4t-3}+1\\right)}$ ($\\lim_{t \\to 1+} \\frac{t\\left(\\sqrt{4t-3}-1\\right)}{t-1}$이 $\\frac{0}{0}$ 꼴이므로 분자에 있는 $\\sqrt{4t-3}-1$을 유리화하기 위해 분자와 분모에 각각 $\\sqrt{4t-3}+1$을 곱한 거야.)\n$= \\lim_{t \\to 1+} \\frac{4t}{\\sqrt{4t-3}+1} = \\frac{4 \\times 1}{1+1} = 2$", "img": "IMG_4959.jpg"}, {"id": "A199", "section": "A", "num": 199, "page": 54, "topic": "넓이에 대한 극한의 활용", "answer": "①", "rate": "64%", "problem": "그림과 같이 두 곡선 $y=\\frac{1}{x}$과 $y=\\sqrt{x}$가 점 $A(1, 1)$에서 만난다. 직선 $y=t(t>1)$이 두 곡선 $y=\\frac{1}{x}$, $y=\\sqrt{x}$와 만나는 점을 각각 $B$, $C$라 하자. 점 $C$를 지나고 $y$축과 평행한 직선이 곡선 $y=\\frac{1}{x}$과 만나는 점을 $D$라 하자. 삼각형 $ACB$의 넓이를 $f(t)$, 삼각형 $ADC$의 넓이를 $g(t)$라 할 때, $\\lim_{t \\to 1+} \\frac{g(t)}{f(t)}$의 값은? (4점)\n[단서1] $BC$를 밑변으로 생각하면 높이는 점 $A$와 $BC$ 사이의 거리와 같아. [단서2] $CD$를 밑변으로 생각하면 높이는 점 $A$와 $CD$ 사이의 거리와 같아.", "explanation": "정답 공식: 넓이를 구하는 삼각형의 밑변과 높이를 $x$축 또는 $y$축과 평행하도록 잡아서 넓이를 $t$에 대하여 나타낸다.\n1st 세 점 $B$, $C$, $D$의 좌표를 $t$에 대한 식으로 나타내 보자.\n세 점 $B$, $C$, $D$의 좌표는 $B\\left(\\frac{1}{t}, t\\right)$, $C(t^{2}, t)$, $D\\left(t^{2}, \\frac{1}{t^{2}}\\right)$이므로 (점 $B$는 곡선 $y=\\frac{1}{x}$과 직선 $y=t$의 교점이므로 $B\\left(\\frac{1}{t}, t\\right)$. 점 $C$는 곡선 $y=\\sqrt{x}$와 직선 $y=t$의 교점이므로 $C(t^{2}, t)$. 점 $D$는 곡선 $y=\\frac{1}{x}$과 직선 $x=t^{2}$의 교점이므로 $D\\left(t^{2}, \\frac{1}{t^{2}}\\right)$)\n$f(t)=\\frac{1}{2}\\left(t^{2}-\\frac{1}{t}\\right)(t-1)$\n$g(t)=\\frac{1}{2}\\left(t-\\frac{1}{t^{2}}\\right)(t^{2}-1)$\n2nd 주어진 극한값을 구해보자.\n$\\therefore \\lim_{t \\to 1+} \\frac{g(t)}{f(t)} = \\lim_{t \\to 1+} \\frac{\\frac{1}{2}\\left(t-\\frac{1}{t^{2}}\\right)(t^{2}-1)}{\\frac{1}{2}\\left(t^{2}-\\frac{1}{t}\\right)(t-1)}$\n$= \\lim_{t \\to 1+} \\frac{(t^{3}-1)(t^{2}-1)}{t(t^{3}-1)(t-1)}$\n$= \\lim_{t \\to 1+} \\frac{t+1}{t} = 2$ ($\\frac{0}{0}$ 꼴이므로 분자, 분모를 $0$이 되도록 하는 인수를 약분해야 해)\n[개념·공식: 함수의 극한값 구하는 방법] ① $\\frac{\\infty}{\\infty}$ 꼴: 분모, 분자를 분모의 최고차항으로 나눈다. ② $\\frac{0}{0}$ 꼴: 1) 분수식은 인수분해한 후 약분한다. 2) 무리식은 유리화한다. ③ $\\infty-\\infty$ 꼴: 1) 다항식은 최고차항으로 묶는다. 2) 무리식은 유리화한다. ④ $0 \\times \\infty$ 꼴: $\\frac{\\infty}{\\infty}$, $\\frac{0}{0}$ 꼴로 변형한다.", "img": "IMG_4959.jpg", "answer_value": "$2$"}, {"id": "A200", "section": "A", "num": 200, "page": 55, "topic": "넓이에 대한 극한의 활용", "answer": "②", "rate": "68%", "problem": "그림과 같이 원 $x^{2}+y^{2}=1$과 곡선 $y=\\sqrt{x+1}$이 직선 $x=t(0<t<1)$과 제1사분면에서 만나는 점을 각각 $P$, $Q$라 하자. 삼각형 $OPQ$의 넓이를 $S(t)$라 할 때, $\\lim_{t \\to 0+} \\frac{S(t)}{t^{2}}$의 값은? (단, $O$는 원점이다.) (4점)\n[단서] 원과 곡선이 직선과 만나는 점을 각각 $P$, $Q$로 정했으므로 점 $P$, $Q$의 좌표를 $t$로 나타내고 삼각형 $OPQ$의 넓이 $S(t)$도 $t$로 나타내야 해.", "explanation": "정답 공식: 넓이를 구하는 삼각형의 밑변과 높이를 $x$축 또는 $y$축과 평행하도록 잡아서 넓이를 $t$에 대하여 나타낸다.\n1st 두 점 $P$, $Q$의 좌표를 각각 $t$로 나타내자.\n원 $x^{2}+y^{2}=1$과 곡선 $y=\\sqrt{x+1}$이 직선 $x=t$와 각각 만나므로 두 점 $P$, $Q$의 $x$좌표는 $t$이다. (두 도형의 방정식을 연립하여 구한 $x$, $y$의 값은 두 도형의 교점의 $x$좌표, $y$좌표야)\n$x^{2}+y^{2}=1$과 $x=t$에서 $t^{2}+y^{2}=1$이고 $y= \\pm \\sqrt{1-t^{2}}$\n점 $P$의 $y$좌표가 양수이므로 $y=\\sqrt{1-t^{2}} \\therefore P\\left(t, \\sqrt{1-t^{2}}\\right)$\n$y=\\sqrt{x+1}$과 $x=t$에서 $y=\\sqrt{t+1}$이므로 $Q\\left(t, \\sqrt{t+1}\\right)$\n2nd 삼각형 $OPQ$의 넓이 $S(t)$를 $t$로 나타내자.\n삼각형 $OPQ$에서 $PQ$를 밑변으로 하면 높이는 $t$이다.\n$PQ=\\sqrt{t+1}-\\sqrt{1-t^{2}}$이므로 $S(t)=\\frac{1}{2} \\times t \\times \\left(\\sqrt{t+1}-\\sqrt{1-t^{2}}\\right)$\n[함정] (삼각형 $OPQ$의 넓이)$=\\frac{1}{2} \\times PQ \\times$(점 $Q$의 $x$좌표)라고 생각하면 넓이 구하는 식을 구해내기 쉬워져!\n3rd $\\lim_{t \\to 0+} \\frac{S(t)}{t^{2}}$의 값을 구하자.\n$\\therefore \\lim_{t \\to 0+} \\frac{S(t)}{t^{2}} = \\lim_{t \\to 0+} \\frac{\\sqrt{t+1}-\\sqrt{1-t^{2}}}{2t}$\n$=\\frac{1}{2} \\lim_{t \\to 0+} \\frac{\\left(\\sqrt{t+1}-\\sqrt{1-t^{2}}\\right)\\left(\\sqrt{t+1}+\\sqrt{1-t^{2}}\\right)}{t\\left(\\sqrt{t+1}+\\sqrt{1-t^{2}}\\right)}$\n$=\\frac{1}{2} \\lim_{t \\to 0+} \\frac{t^{2}+t}{t\\left(\\sqrt{t+1}+\\sqrt{1-t^{2}}\\right)}$ ($\\sqrt{\\ }$가 포함된 $\\frac{0}{0}$ 꼴은 유리화를 생각하자)\n$=\\frac{1}{2} \\lim_{t \\to 0+} \\frac{t+1}{\\sqrt{t+1}+\\sqrt{1-t^{2}}}$\n$=\\frac{1}{2} \\times \\frac{1}{1+1}=\\frac{1}{4}$\n[개념·공식: $\\frac{0}{0}$ 꼴의 극한] 두 함수 $f(x)$, $g(x)$와 임의의 실수 $a$에 대하여 $f(a)=g(a)=0$이면 $\\lim_{x \\to a} \\frac{f(x)}{g(x)}$는 $\\frac{0}{0}$ 꼴이다. 이때, ① $f(x)$, $g(x)$가 모두 다항식이면 $f(x)$, $g(x)$를 각각 인수분해하고 공통인수를 약분하여 극한값을 구한다. ② $f(x)$, $g(x)$ 중 무리식이 있으면 근호를 포함한 쪽을 유리화하고 공통인수를 약분하여 극한값을 구한다.", "img": "IMG_4960.jpg", "answer_value": "$\\frac{1}{4}$"}, {"id": "A201", "section": "A", "num": 201, "page": 55, "topic": "넓이에 대한 극한의 활용", "answer": "④", "rate": "54%", "problem": "그림과 같이 실수 $t(0<t<1)$에 대하여 직선 $y=2t$가 두 곡선 $y=x^{2}$, $y=tx^{2}$과 제1사분면에서 만나는 점을 각각 $A$, $B$라 하고, 직선 $y=t+1$이 두 곡선 $y=x^{2}$, $y=tx^{2}$과 제1사분면에서 만나는 점을 각각 $C$, $D$라 하자. 사각형 $ABDC$의 넓이를 $S(t)$라 할 때, $\\lim_{t \\to 1-} \\frac{S(t)}{(1-t)^{2}}$의 값은? (4점)\n[단서1] 곡선과 직선의 식을 연립하여 풀어 네 점 $A$, $B$, $C$, $D$의 좌표를 $t$에 대해 나타내야 해. [단서2] 사각형 $ABDC$는 사다리꼴이므로 점 $C$에서 직선 $AB$에 내린 수선의 발을 $H$라 할 때, 사각형 $ABDC$의 넓이는 윗변의 길이를 $CD$, 아랫변의 길이를 $AB$, 높이를 $CH$로 하는 사다리꼴의 넓이로 구할 수 있어.", "explanation": "정답 공식: 사각형 $ABDC$는 사다리꼴이므로 점 $C$에서 직선 $AB$에 내린 수선의 발을 $H$라 하면 사각형 $ABDC$의 넓이는 윗변의 길이를 $CD$, 아랫변의 길이를 $AB$, 높이를 $CH$로 하는 사다리꼴의 넓이로 구할 수 있다.\n1st 네 점 $A$, $B$, $C$, $D$의 좌표를 $t$에 대하여 나타내봐.\n점 $A$는 곡선 $y=x^{2}$과 직선 $y=2t$의 교점이므로 $x^{2}=2t$에서 $x=\\sqrt{2t} (\\because x>0) \\therefore A\\left(\\sqrt{2t}, 2t\\right)$ (점 $A$는 제1사분면 위의 점이지?)\n점 $B$는 곡선 $y=tx^{2}$과 직선 $y=2t$의 교점이므로 $tx^{2}=2t$에서 $x^{2}=2$, $x=\\sqrt{2} (\\because x>0) \\therefore B\\left(\\sqrt{2}, 2t\\right)$\n점 $C$는 곡선 $y=x^{2}$과 직선 $y=t+1$의 교점이므로 $x^{2}=t+1$에서 $x=\\sqrt{t+1} (\\because x>0) \\therefore C\\left(\\sqrt{t+1}, t+1\\right)$\n점 $D$는 곡선 $y=tx^{2}$과 직선 $y=t+1$의 교점이므로 $tx^{2}=t+1$에서 $x^{2}=\\frac{t+1}{t}$, $x=\\sqrt{\\frac{t+1}{t}} (\\because x>0) \\therefore D\\left(\\sqrt{\\frac{t+1}{t}}, t+1\\right)$\n2nd 사다리꼴 $ABDC$의 넓이 $S(t)$의 식을 구해.\n$AB=\\sqrt{2}-\\sqrt{2t}=\\sqrt{2}\\left(1-\\sqrt{t}\\right)$\n$CD=\\sqrt{\\frac{t+1}{t}}-\\sqrt{t+1}=\\sqrt{\\frac{t+1}{t}}\\left(1-\\sqrt{t}\\right)$\n점 $C$에서 직선 $AB$에 내린 수선의 발을 $H$라 하면 $CH=(t+1)-2t=1-t$이므로\n$S(t)=\\frac{1}{2} \\times (AB+CD) \\times CH$ (윗변의 길이가 $a$, 아랫변의 길이가 $b$, 높이가 $h$인 사다리꼴의 넓이는 $\\frac{1}{2}(a+b)h$)\n$=\\frac{1}{2}\\left\\{\\sqrt{2}\\left(1-\\sqrt{t}\\right)+\\sqrt{\\frac{t+1}{t}}\\left(1-\\sqrt{t}\\right)\\right\\}(1-t)$\n$=\\frac{1}{2}\\left(\\sqrt{2}+\\sqrt{\\frac{t+1}{t}}\\right)\\left(1-\\sqrt{t}\\right)(1-t)$\n3rd $\\lim_{t \\to 1-} \\frac{S(t)}{(1-t)^{2}}$의 값을 구하자.\n$\\lim_{t \\to 1-} \\frac{S(t)}{(1-t)^{2}} = \\lim_{t \\to 1-} \\frac{1}{(1-t)^{2}} \\times \\frac{1}{2}\\left(\\sqrt{2}+\\sqrt{\\frac{t+1}{t}}\\right)\\left(1-\\sqrt{t}\\right)(1-t)$\n$= \\lim_{t \\to 1-} \\frac{1-\\sqrt{t}}{2(1-t)} \\left(\\sqrt{2}+\\sqrt{\\frac{t+1}{t}}\\right)$\n$= \\lim_{t \\to 1-} \\frac{1-\\sqrt{t}}{2\\left(1-\\sqrt{t}\\right)\\left(1+\\sqrt{t}\\right)} \\left(\\sqrt{2}+\\sqrt{\\frac{t+1}{t}}\\right)$\n$= \\lim_{t \\to 1-} \\frac{1}{2\\left(1+\\sqrt{t}\\right)} \\left(\\sqrt{2}+\\sqrt{\\frac{t+1}{t}}\\right)$\n$=\\frac{1}{2 \\times 2} \\times \\left(\\sqrt{2}+\\sqrt{2}\\right)=\\frac{1}{4} \\times 2\\sqrt{2}=\\frac{\\sqrt{2}}{2}$\n[주의] $t \\to 1-$인 이유는 주어진 $t$의 값의 범위가 $0<t<1$이므로 $t=1$에서의 좌극한값만 구할 수 있기 때문이야. 따라서 극한값 $\\lim_{t \\to 1-} \\frac{S(t)}{(1-t)^{2}}$를 구할 때 식을 정리한 후 $t=1$을 대입하면 돼.\n[개념·공식: 함수의 극한에 관한 기본 성질] 두 실수 $\\alpha$, $\\beta$에 대하여 $\\lim_{x \\to a} f(x)=\\alpha$, $\\lim_{x \\to a} g(x)=\\beta$일 때, ① $\\lim_{x \\to a} kf(x)=k \\lim_{x \\to a} f(x)=k\\alpha$ (단, $k$는 상수) ② $\\lim_{x \\to a} \\{f(x) \\pm g(x)\\}=\\lim_{x \\to a} f(x) \\pm \\lim_{x \\to a} g(x)=\\alpha \\pm \\beta$ (복호동순) ③ $\\lim_{x \\to a} f(x)g(x)=\\lim_{x \\to a} f(x) \\times \\lim_{x \\to a} g(x)=\\alpha\\beta$ ④ $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\frac{\\lim_{x \\to a} f(x)}{\\lim_{x \\to a} g(x)}=\\frac{\\alpha}{\\beta}$ (단, $g(x) \\ne 0$, $\\beta \\ne 0$)", "img": "IMG_4960.jpg", "answer_value": "$\\frac{\\sqrt{2}}{2}$"}, {"id": "A202", "section": "A", "num": 202, "page": 56, "topic": "넓이에 대한 극한의 활용", "answer": "15", "rate": "41%", "problem": "그림과 같이 좌표평면에서 원 $x^{2}+y^{2}=2$와 곡선 $y=x^{2}$이 제1사분면에서 만나는 점을 $A$라 하자. 실수 $t(0<t<1)$에 대하여 직선 $y=tx$가 원 $x^{2}+y^{2}=2$, 곡선 $y=x^{2}$과 제1사분면에서 만나는 점을 각각 $P$, $Q$라 하자. 삼각형 $PAQ$의 넓이를 $S(t)$라 할 때, $\\lim_{t \\to 1-} \\frac{S(t)}{(1-t)^{2}}=k$이다. $20k$의 값을 구하시오. (4점) [단서1] $x^{2}+y^{2}=2$와 $y=x^{2}$을 연립하여 풀면 점 $A$의 좌표를 구할 수 있어. [단서2] $y=x^{2}$과 $y=tx$를 연립하여 점 $Q$의 좌표를 $t$에 대한 식으로 나타내봐. [단서3] 삼각형 $PAQ$의 밑변을 $PQ$라 놓으면 점 $A$에서 직선 $y=tx$에 내린 수선의 길이가 높이가 돼. 이를 이용하여 삼각형 $PAQ$의 넓이 $S(t)$를 구해야 해.", "explanation": "정답 공식: 원의 중심에서 원 위의 점까지의 거리는 원의 반지름의 길이와 같다. 또한, 점 $(x_{1}, y_{1})$과 직선 $ax+by+c=0$ 사이의 거리는 $\\frac{|ax_{1}+by_{1}+c|}{\\sqrt{a^{2}+b^{2}}}$이다.\n1st 점 $A$의 좌표를 구해.\n점 $A$의 좌표를 구하기 위해 $x^{2}+y^{2}=2$와 $y=x^{2}$을 연립하면 $y+y^{2}=2$, $y^{2}+y-2=0$ ($x^{2}+y^{2}=2$에 $x^{2}$ 대신 $y$를 대입한 거야. $y$ 대신에 $x^{2}$을 대입하여 $x$에 대한 사차방정식 $x^{2}+x^{4}=2$를 풀어도 되는데 식이 좀 복잡하니까 $y$에 대한 방정식으로 푼 거야.)\n$(y+2)(y-1)=0 \\therefore y=1 (\\because y>0)$\n$y=1$을 $y=x^{2}$에 대입하면 $x^{2}=1 \\therefore x=1 (\\because x>0)$ (점 $A$가 제1사분면 위의 점이므로 점 $A$의 $x$좌표, $y$좌표 모두 양수여야 해)\n즉, 점 $A$의 좌표는 $A(1, 1)$이다.\n2nd 점 $Q$의 좌표를 구해.\n점 $Q$의 좌표를 구하기 위해 $y=x^{2}$과 $y=tx$를 연립하면 $tx=x^{2}$, $x^{2}-tx=0$, $x(x-t)=0 \\therefore x=t (\\because x>0)$ (점 $Q$도 제1사분면 위의 점이고, $0<t<1$이므로 점 $Q$의 $x$좌표는 $t$야)\n$x=t$를 $y=tx$에 대입하면 $y=t^{2}$\n즉, 점 $Q$의 좌표는 $Q(t, t^{2})$이다.\n3rd 삼각형 $PAQ$의 넓이를 구하자.\n점 $P$는 원 $x^{2}+y^{2}=2$ 위의 점이므로 $OP=\\sqrt{2}$\n또, 원점과 점 $Q(t, t^{2})$ 사이의 거리는 $OQ=\\sqrt{t^{2}+t^{4}}=t\\sqrt{1+t^{2}}$\n$\\therefore PQ=OP-OQ=\\sqrt{2}-t\\sqrt{1+t^{2}}$\n[함정] $x^{2}+y^{2}=2$와 $y=tx$를 연립하여 풀면 점 $P$의 $x$좌표가 $x=\\frac{\\sqrt{2}}{\\sqrt{t^{2}+1}}$가 되어 점 $P$의 좌표를 $t$에 대한 식으로 나타낼 수 있어. 이를 이용하여 원점과 점 $P$ 사이의 거리를 구해도 되는데 이 방법은 너무 복잡해. 점 $P$가 주어진 원 위의 점이고 원점이 원의 중심임을 파악하여 반지름의 길이로 $OP$의 길이를 찾아내는 것이 이 문제를 빠르게 푸는 핵심이야.\n한편, 점 $A(1, 1)$에서 직선 $y=tx$, 즉 $tx-y=0$에 내린 수선의 발을 $H$라 하면\n$AH=\\frac{|t-1|}{\\sqrt{t^{2}+1}}=\\frac{1-t}{\\sqrt{1+t^{2}}} (\\because 0<t<1)$ (점 $(x_{1}, y_{1})$과 직선 $ax+by+c=0$ 사이의 거리는 $\\frac{|ax_{1}+by_{1}+c|}{\\sqrt{a^{2}+b^{2}}}$)\n따라서 삼각형 $PAQ$의 넓이 $S(t)$는\n$S(t)=\\frac{1}{2} \\times PQ \\times AH=\\frac{1}{2} \\times \\left(\\sqrt{2}-t\\sqrt{1+t^{2}}\\right) \\times \\frac{1-t}{\\sqrt{1+t^{2}}}=\\frac{(1-t)\\left(\\sqrt{2}-t\\sqrt{1+t^{2}}\\right)}{2\\sqrt{1+t^{2}}}$\n4th 극한값을 구하자.\n$\\lim_{t \\to 1-} \\frac{S(t)}{(1-t)^{2}} = \\lim_{t \\to 1-} \\frac{(1-t)\\left(\\sqrt{2}-t\\sqrt{1+t^{2}}\\right)}{2(1-t)^{2}\\sqrt{1+t^{2}}}$\n$= \\lim_{t \\to 1-} \\frac{\\sqrt{2}-t\\sqrt{1+t^{2}}}{2(1-t)\\sqrt{1+t^{2}}}$ ($\\frac{0}{0}$ 꼴이므로 분모, 분자에 모두 $\\sqrt{2}+t\\sqrt{1+t^{2}}$을 곱해 유리화하자)\n$= \\lim_{t \\to 1-} \\frac{2-t^{2}(1+t^{2})}{2(1-t)\\sqrt{1+t^{2}}\\left(\\sqrt{2}+t\\sqrt{1+t^{2}}\\right)}$\n$= \\lim_{t \\to 1-} \\frac{(t^{2}+2)(1+t)(1-t)}{2(1-t)\\sqrt{1+t^{2}}\\left(\\sqrt{2}+t\\sqrt{1+t^{2}}\\right)} (2-t^{2}(1+t^{2})=-(t^{4}+t^{2}-2)=-(t^{2}+2)(t^{2}-1)=(t^{2}+2)(1-t^{2})=(t^{2}+2)(1+t)(1-t))$\n$= \\lim_{t \\to 1-} \\frac{(t^{2}+2)(1+t)}{2\\sqrt{1+t^{2}}\\left(\\sqrt{2}+t\\sqrt{1+t^{2}}\\right)}$\n$=\\frac{3 \\times 2}{2\\sqrt{2}\\left(\\sqrt{2}+\\sqrt{2}\\right)}=\\frac{6}{2\\sqrt{2} \\times 2\\sqrt{2}}=\\frac{6}{8}=\\frac{3}{4}$\n따라서 $k=\\frac{3}{4}$이므로 $20k=20 \\times \\frac{3}{4}=15$", "img": "IMG_4961.jpg"}, {"id": "A203", "section": "A", "num": 203, "page": 57, "topic": "넓이에 대한 극한의 활용", "answer": "②", "rate": "47%", "problem": "곡선 $y=x^{2}-4$ 위의 점 $P(t, t^{2}-4)$에서 원 $x^{2}+y^{2}=4$에 그은 두 접선의 접점을 각각 $A$, $B$라 하자. 삼각형 $OAB$의 넓이를 $S(t)$, 삼각형 $PBA$의 넓이를 $T(t)$라 할 때, $\\lim_{t \\to 2+} \\frac{T(t)}{(t-2)S(t)} + \\lim_{t \\to \\infty} \\frac{T(t)}{(t^{4}-2)S(t)}$의 값은? (단, $O$는 원점이고, $t>2$이다.) (4점)\n[단서1] 두 점 $A$, $B$는 원 밖의 한 점 $P$에서 원에 그은 접선과 원의 접점이므로 $PA \\perp OA$, $PB \\perp OB$야. [단서2] 구해야 하는 극한식을 살펴보면 두 식 모두 $\\frac{T(t)}{S(t)}$가 있음을 알 수 있어. 즉, 두 삼각형의 넓이인 $S(t)$, $T(t)$를 직접 구하지 않고 두 삼각형의 넓이의 비만 알면 된다는 점에 주목해.", "explanation": "정답 공식: 원의 접선의 접점을 지나는 반지름은 접선과 서로 수직이다. 또한, 닮음비가 $m:n$인 두 도형의 넓이의 비는 $m^{2}:n^{2}$이다.\n1st $\\frac{T(t)}{S(t)}$를 구할 수 있는 방법을 생각해봐.\n$\\lim_{t \\to 2+} \\frac{T(t)}{(t-2)S(t)} + \\lim_{t \\to \\infty} \\frac{T(t)}{(t^{4}-2)S(t)}$에서 두 극한식에 모두 $\\frac{T(t)}{S(t)}$가 있으므로 두 삼각형 $OAB$, $PBA$의 넓이인 $S(t)$와 $T(t)$ 사이의 관계를 찾아 $\\frac{T(t)}{S(t)}$를 구해보자.\n[함정] $S(t)$, $T(t)$를 각각 구해서 주어진 극한의 값을 계산하려고 하면 풀이가 굉장히 복잡해져. 문제의 극한식에서 $\\frac{T(t)}{S(t)}$가 모두 있다는 것을 먼저 파악하여 $\\frac{T(t)}{S(t)}$를 구하는 것으로 풀이의 포커스를 맞춘 후 문제에 접근하면 풀이 시간도 줄이고 실수를 피할 수 있어.\n두 점 $A$, $B$는 점 $P$에서 원에 그은 접선의 접점이므로 $OA \\perp PA$, $OB \\perp PB$이다.\n또, 그림과 같이 두 선분 $AB$, $OP$의 교점을 $M$이라 하면 직선 $OP$는 선분 $AB$를 수직이등분한다. (선분 $AB$는 원의 현이므로 원의 중심 $O$에서 현 $AB$에 내린 수선의 발은 현을 이등분해. 즉, $OM \\perp AB$이면 $AM=BM$이야. 또, $PA=PB$에서 삼각형 $PBA$는 이등변삼각형이므로 점 $P$에서 밑변 $AB$에 내린 수선의 발은 밑변 $AB$를 이등분해. 즉, $PM \\perp AB$이면 $AM=BM$이야. 따라서 직선 $OP$는 선분 $AB$를 수직이등분함을 알 수 있어.)\n즉, $\\triangle OMB=\\frac{1}{2}\\triangle OAB=\\frac{1}{2}S(t)$이고, $\\triangle PMB=\\frac{1}{2}\\triangle PBA=\\frac{1}{2}T(t)$이므로\n$\\frac{T(t)}{S(t)}=\\frac{2\\triangle PMB}{2\\triangle OMB}=\\frac{\\triangle PMB}{\\triangle OMB}$\n한편, 두 직각삼각형 $OMB$, $BMP$에서 $\\angle OBM=\\angle BPM$이므로 $(\\angle OBM=90^{\\circ}-\\angle PBM=90^{\\circ}-(180^{\\circ}-90^{\\circ}-\\angle BPM)=\\angle BPM)$\n$\\triangle OMB \\backsim \\triangle BMP$ (AA 닮음)\n즉, 두 직각삼각형 $OMB$, $BMP$의 닮음비가 $OB:BP$이고, 넓이의 비는 $OB^{2}:BP^{2}$이므로\n$\\frac{T(t)}{S(t)}=\\frac{\\triangle PMB}{\\triangle OMB}=\\frac{BP^{2}}{OB^{2}}$\n2nd $OB$, $BP$의 길이를 이용해서 $\\frac{T(t)}{S(t)}$를 $t$에 대한 식으로 나타내.\n$OB=2$이고 ($OB$는 원 $x^{2}+y^{2}=4$의 반지름이지?), 점 $P(t, t^{2}-4)$에 대하여 $OP=\\sqrt{t^{2}+(t^{2}-4)^{2}}$이므로 직각삼각형 $OPB$에서 피타고라스 정리에 의하여\n$BP^{2}=OP^{2}-OB^{2}=t^{2}+(t^{2}-4)^{2}-2^{2}=t^{2}+t^{4}-8t^{2}+16-4=t^{4}-7t^{2}+12=(t^{2}-3)(t^{2}-4)=(t^{2}-3)(t+2)(t-2)$\n$\\therefore \\frac{T(t)}{S(t)}=\\frac{BP^{2}}{OB^{2}}=\\frac{(t^{2}-3)(t+2)(t-2)}{4}$\n3rd $\\frac{T(t)}{S(t)}$를 대입해서 극한값을 구해.\n$\\lim_{t \\to 2+} \\frac{T(t)}{(t-2)S(t)} + \\lim_{t \\to \\infty} \\frac{T(t)}{(t^{4}-2)S(t)}$\n$= \\lim_{t \\to 2+} \\frac{(t^{2}-3)(t+2)(t-2)}{4(t-2)} + \\lim_{t \\to \\infty} \\frac{(t^{2}-3)(t+2)(t-2)}{4(t^{4}-2)}$ ($t \\to 2+$에서 $t \\ne 2$이므로 분모, 분자의 공통인수인 $t-2$를 약분하여 계산할 수 있어)\n$= \\lim_{t \\to 2+} \\frac{(t^{2}-3)(t+2)}{4} + \\lim_{t \\to \\infty} \\frac{(t^{2}-3)(t+2)(t-2)}{4(t^{4}-2)}$\n$=(4-3) \\times \\frac{2+2}{4} + \\frac{1}{4}$ (차수가 같은 두 다항함수 $f(x)$, $g(x)$에 대하여 $f(x)$의 최고차항의 계수가 $\\alpha$이고, $g(x)$의 최고차항의 계수가 $\\beta$이면 $\\lim_{x \\to \\infty} \\frac{f(x)}{g(x)}=\\frac{\\alpha}{\\beta}$야)\n$=1+\\frac{1}{4}=\\frac{5}{4}$\n[다른 풀이 ①: 두 직각삼각형 $OMB$, $PMB$의 넓이의 비와 직각삼각형의 닮음 활용하기]\n1st에서 두 직각삼각형 $OMB$, $PMB$의 밑변을 각각 $OM$, $PM$이라 하면 높이가 $BM$으로 같으므로 $\\frac{T(t)}{S(t)}=\\frac{\\triangle PMB}{\\triangle OMB}=\\frac{PM}{OM}$이야.\n이때, $OB \\perp PB$, $BM \\perp OP$이고 $OP=\\sqrt{t^{2}+(t^{2}-4)^{2}}$이므로 $OB^{2}=OM \\times OP$에서 $2^{2}=OM \\times \\sqrt{t^{2}+(t^{2}-4)^{2}}$\n$\\therefore OM=\\frac{4}{\\sqrt{t^{2}+(t^{2}-4)^{2}}}$\n[직각삼각형의 닮음의 활용] 그림과 같이 $\\angle A=90^{\\circ}$인 직각삼각형 $ABC$의 꼭짓점 $A$에서 변 $BC$에 내린 수선의 발을 $H$라 하면 $\\triangle ABC \\backsim \\triangle HBA \\backsim \\triangle HAC$(AA 닮음)이므로 다음이 모두 성립해. ① $AB^{2}=BH \\times BC$ ② $AC^{2}=CH \\times BC$ ③ $AH^{2}=BH \\times CH$\n즉, $PM=OP-OM=\\sqrt{t^{2}+(t^{2}-4)^{2}}-\\frac{4}{\\sqrt{t^{2}+(t^{2}-4)^{2}}}=\\frac{t^{2}+(t^{2}-4)^{2}-4}{\\sqrt{t^{2}+(t^{2}-4)^{2}}}=\\frac{t^{4}-7t^{2}+12}{\\sqrt{t^{2}+(t^{2}-4)^{2}}}$이므로\n$\\frac{T(t)}{S(t)}=\\frac{PM}{OM}=\\frac{t^{4}-7t^{2}+12}{\\sqrt{t^{2}+(t^{2}-4)^{2}}} \\times \\frac{\\sqrt{t^{2}+(t^{2}-4)^{2}}}{4}=\\frac{t^{4}-7t^{2}+12}{4}=\\frac{(t^{2}-3)(t+2)(t-2)}{4}$\n(이하 동일)\n[다른 풀이 ②: 두 직각삼각형 $OBP$, $OMB$의 넓이를 $S(t)$와 $T(t)$의 식으로 나타내어 넓이의 비 이용하기]\n두 직각삼각형 $OBP$와 $OMB$는 AA 닮음이므로 닮음비는 $OP:OB$이고 넓이의 비는 $OP^{2}:OB^{2}$이야. ($\\angle OBP=\\angle OMB=90^{\\circ}$, $\\angle O$는 공통 $\\therefore \\triangle OBP \\backsim \\triangle OMB$(AA 닮음))\n한편, $\\triangle OBP=\\frac{1}{2}(\\triangle OAB+\\triangle PBA)=\\frac{1}{2}\\{S(t)+T(t)\\}$이고, $\\triangle OMB=\\frac{1}{2}\\triangle OAB=\\frac{1}{2}S(t)$이므로\n$\\frac{1}{2}\\{S(t)+T(t)\\}$ : $\\frac{1}{2}S(t)=OP^{2}:OB^{2}$에서 $\\frac{1}{2}\\{S(t)+T(t)\\} \\times OB^{2}=\\frac{1}{2}S(t) \\times OP^{2}$\n$T(t) \\times OB^{2}=S(t) \\times (OP^{2}-OB^{2})$\n$\\therefore \\frac{T(t)}{S(t)}=\\frac{OP^{2}-OB^{2}}{OB^{2}}=\\frac{BP^{2}}{OB^{2}}$ (직각삼각형 $OBP$에서 피타고라스 정리에 의해 $OP^{2}-OB^{2}=BP^{2}$이야)\n(이하 동일)", "img": "IMG_4962.jpg", "answer_value": "$\\frac{5}{4}$"}, {"id": "A204", "section": "A", "num": 204, "page": 58, "topic": "좌표평면에서의 극한의 활용", "answer": "50", "rate": "69%", "problem": "곡선 $y=x^{2}$ 위에 두 점 $P(a, a^{2})$, $Q(a+1, a^{2}+2a+1)$이 있다. 직선 $PQ$와 직선 $y=x$의 교점의 $x$좌표를 $f(a)$라 할 때, $100 \\lim_{a \\to 0} f(a)$의 값을 구하시오. (4점) [단서1] 두 점 $P$, $Q$를 지나는 직선의 방정식을 구해. [단서2] 직선 $PQ$의 방정식과 직선 $y=x$의 방정식을 연립하여 $x$의 값을 구해.", "explanation": "정답 공식: 두 직선의 교점의 $x$좌표는 두 직선의 방정식으로 이루어진 연립방정식의 해와 같다.\n1st 직선 $PQ$와 직선 $y=x$의 교점의 $x$좌표를 구하자.\n직선 $PQ$의 방정식은 (두 점 $(x_{1}, y_{1})$, $(x_{2}, y_{2})$를 지나는 직선의 방정식은 $y-y_{1}=\\frac{y_{2}-y_{1}}{x_{2}-x_{1}} \\times (x-x_{1})$ (단, $x_{1} \\ne x_{2}$))\n$y=\\frac{(a^{2}+2a+1)-a^{2}}{(a+1)-a} \\times (x-a)+a^{2}=(2a+1)x-(a^{2}+a)$\n이때, 직선 $PQ$와 직선 $y=x$의 교점의 $x$좌표는 $x=(2a+1)x-(a^{2}+a)$에서 $2ax=a^{2}+a$\n즉, $x=\\frac{a^{2}+a}{2a}=\\frac{a+1}{2} (\\because a \\ne 0 \\cdots(*))$이므로 $f(a)=\\frac{a+1}{2}$\n$\\therefore 100 \\lim_{a \\to 0} f(a)=100 \\lim_{a \\to 0} \\frac{a+1}{2}=100 \\times \\frac{1}{2}=50$ ($f(x)$가 다항함수이면 $\\lim_{x \\to a} f(x)=f(a)$)\n[수능 핵강: 문제에서 조건 찾아내기] $(*)$와 같이 $a \\ne 0$이라고 할 수 있는 것은 문제에서 주어져 있어. 어디?? 직선 $PQ$와 직선 $y=x$의 교점의 $x$좌표를 구하는 과정인 $2ax=a^{2}+a$에서 $a=0$이면 $x$좌표는 무한히 많이 존재하므로 문제에서 주어진 $f(a)$는 정의내릴 수 없는 함수가 돼. 따라서 문제에서 '두 직선의 교점의 $x$좌표를~'이라는 말 속에 $x$좌표는 존재해야 하고 그러기 위해서는 $a \\ne 0$이어야 한다는 것을 알 수 있지!", "img": "IMG_4963.jpg"}, {"id": "A205", "section": "A", "num": 205, "page": 58, "topic": "좌표평면에서의 극한의 활용", "answer": "①", "rate": "(판독 불가)", "problem": "그림과 같이 좌표평면 위의 두 원 $C_{1}$: $x^{2}+y^{2}=1$, $C_{2}$: $(x-1)^{2}+y^{2}=r^{2} \\left(0<r<\\sqrt{2}\\right)$이 제1사분면에서 만나는 점을 $P$라 하자. 점 $P$의 $x$좌표를 $f(r)$라 할 때, $\\lim_{r \\to \\sqrt{2}-} \\frac{f(r)}{4-r^{4}}$의 값은? (4점)\n[단서1] $C_{1}$, $C_{2}$의 원의 방정식을 연립하면 점 $P$의 좌표를 알 수 있어. [단서2] $r=\\sqrt{2}$에서의 좌극한값을 구해. 이때 분모를 인수분해하여 약분해야겠지?", "explanation": "정답 공식: 두 원의 방정식을 연립하여 점 $P$의 $x$좌표를 구한다.\n1st 점 $P$는 두 원 $C_{1}$, $C_{2}$의 교점이므로 두 원의 방정식을 연립하여 점 $P$의 $x$좌표를 구해.\n두 원 $C_{1}$: $x^{2}+y^{2}=1 \\cdots$ ㉠, $C_{2}$: $(x-1)^{2}+y^{2}=r^{2} \\cdots$ ㉡에서 ㉠-㉡을 하면\n$x^{2}-(x-1)^{2}=1-r^{2}$, $2x-1=1-r^{2}$\n따라서 $x=\\frac{1}{2}(2-r^{2})$이므로 $f(r)=\\frac{1}{2}(2-r^{2})$\n2nd $\\frac{0}{0}$ 꼴의 극한은 유리화 또는 인수분해하여 극한값을 구해.\n$\\therefore \\lim_{r \\to \\sqrt{2}-} \\frac{f(r)}{4-r^{4}} = \\lim_{r \\to \\sqrt{2}-} \\frac{2-r^{2}}{2(2+r^{2})(2-r^{2})}$ ($4-r^{4}=2^{2}-(r^{2})^{2}=(2+r^{2})(2-r^{2})$; $2-r^{2}$이 분자, 분모의 공통인수이므로 약분해)\n$= \\lim_{r \\to \\sqrt{2}-} \\frac{1}{2(2+r^{2})} = \\frac{1}{2(2+2)} = \\frac{1}{8}$\n[개념·공식: $\\frac{0}{0}$ 꼴의 극한] 두 함수 $f(x)$, $g(x)$와 임의의 실수 $a$에 대하여 $f(a)=g(a)=0$이면 $\\lim_{x \\to a} \\frac{f(x)}{g(x)}$는 $\\frac{0}{0}$ 꼴이다. 이때, ① $f(x)$, $g(x)$가 모두 다항식이면 $f(x)$, $g(x)$를 각각 인수분해하고 공통인수를 약분하여 극한값을 구한다. ② $f(x)$, $g(x)$ 중 무리식이 있으면 근호를 포함한 쪽을 유리화하고 공통인수를 약분하여 극한값을 구한다.", "img": "IMG_4963.jpg", "answer_value": "$\\frac{1}{8}$"}, {"id": "A206", "section": "A", "num": 206, "page": 59, "topic": "좌표평면에서의 극한의 활용", "answer": "1", "rate": "68%", "problem": "그림과 같이 곡선 $y=\\sqrt{x}$ 위의 점 $P\\left(t, \\sqrt{t}\\right)$를 지나고 선분 $OP$에 수직인 직선 $l$의 $x$절편과 $y$절편을 각각 $f(t)$, $g(t)$라 할 때, $\\lim_{t \\to \\infty} \\frac{g(t)-f(t)}{g(t)+f(t)}$의 값을 구하시오. (단, $O$는 원점, $t \\ne 0$) (4점) [단서1] 분모의 최고차항으로 분자, 분모를 각각 나누어 극한값을 구하자. [단서2] (선분 $OP$의 기울기)$=\\frac{\\sqrt{t}}{t}$", "explanation": "정답 공식: 두 직선이 서로 수직이면 이 두 직선의 기울기의 곱은 $-1$이다.\n1st 두 직선이 수직이면 기울기의 곱은 $-1$임을 이용하여 $l$의 방정식을 구해.\n두 점 $O$, $P$를 지나는 직선의 기울기는 $\\frac{\\sqrt{t}}{t}$이므로 이 직선에 수직인 직선의 기울기는 $-\\sqrt{t}$이다. (수직인 두 직선의 기울기의 곱은 $-1$이므로 (구하는 직선의 기울기)$=-\\frac{1}{\\frac{\\sqrt{t}}{t}}=-\\frac{t}{\\sqrt{t}}=-\\sqrt{t}$)\n즉, $l$은 기울기가 $-\\sqrt{t}$이고, 점 $P\\left(t, \\sqrt{t}\\right)$를 지나는 직선이므로 직선 $l$의 방정식은 $y-\\sqrt{t}=-\\sqrt{t}(x-t)$ (기울기가 $m$이고 점 $(a, b)$를 지나는 직선의 방정식은 $y-b=m(x-a)$)\n$\\therefore y=-\\sqrt{t} x+(t+1)\\sqrt{t}$\n2nd 직선의 $x$절편은 $y=0$일 때 $x$값이고, $y$절편은 $x=0$일 때 $y$값이야.\n이 직선의 $x$절편과 $y$절편이 각각 $f(t)$, $g(t)$이므로 $f(t)=t+1$, $g(t)=(t+1)\\sqrt{t}$ ($y=0$일 때, $\\sqrt{t} x=(t+1)\\sqrt{t}$이므로 $x$절편 $f(t)$는 $f(t)=t+1$이야. $x=0$일 때, $y=(t+1)\\sqrt{t}$이므로 $y$절편 $g(t)$는 $g(t)=(t+1)\\sqrt{t}$야.)\n$\\therefore \\lim_{t \\to \\infty} \\frac{g(t)-f(t)}{g(t)+f(t)} = \\lim_{t \\to \\infty} \\frac{(t+1)\\sqrt{t}-(t+1)}{(t+1)\\sqrt{t}+(t+1)}$\n$= \\lim_{t \\to \\infty} \\frac{(t+1)\\left(\\sqrt{t}-1\\right)}{(t+1)\\left(\\sqrt{t}+1\\right)}$\n$= \\lim_{t \\to \\infty} \\frac{\\sqrt{t}-1}{\\sqrt{t}+1}$ (분모의 최고차항 $\\sqrt{t}$로 분자, 분모를 각각 나눠)\n$= \\lim_{t \\to \\infty} \\frac{1-\\frac{1}{\\sqrt{t}}}{1+\\frac{1}{\\sqrt{t}}} = 1$\n[함정] $\\sqrt{\\ }$가 있어서 유리화를 해야 한다고 착각할 수 있지만, 유리화 후에도 $\\frac{\\infty}{\\infty}$ 꼴이 그대로기 때문에 최고차항으로 나눠줘야 해.\n[개념·공식: 함수의 극한값 구하는 방법] ① $\\frac{\\infty}{\\infty}$ 꼴: 분모, 분자를 분모의 최고차항으로 나눈다. ② $\\frac{0}{0}$ 꼴: 1) 분수식은 인수분해한 후 약분한다. 2) 무리식은 유리화한다. ③ $\\infty-\\infty$ 꼴: 1) 다항식은 최고차항으로 묶는다. 2) 무리식은 유리화한다. ④ $0 \\times \\infty$ 꼴: $\\frac{\\infty}{\\infty}$, $\\frac{0}{0}$ 꼴로 변형한다.", "img": "IMG_4964.jpg"}, {"id": "A207", "section": "A", "num": 207, "page": 59, "topic": "좌표평면에서의 극한의 활용", "answer": "①", "rate": "47%", "problem": "양수 $k$에 대하여 함수 $f(x)$를 $f(x)=\\left|\\frac{kx}{x-1}\\right|$라 하자. 실수 $t$에 대하여 곡선 $y=f(x)$와 직선 $y=t$가 만나는 점의 개수를 $g(t)$라 하자. 함수 $g(t)$가 $\\lim_{t \\to 0+} g(t)+\\lim_{t \\to 2-} g(t)+g(4)=5$를 만족시킬 때, $f(3)$의 값은? (4점)\n[단서1] $f(x)=\\left|\\frac{kx}{x-1}\\right|=\\left|\\frac{k}{x-1}+k\\right|$의 그래프를 그릴 수 있어야 해. 함수 $y=\\frac{k}{x-1}+k$의 그래프를 그린 후 $x$축 아랫부분을 $x$축 위로 꺾어 올리면 돼. [단서2] $f(x)=\\left|\\frac{kx}{x-1}\\right|$의 그래프를 그린 후, $t$의 값을 변화시키며 $x$축에 평행한 직선 $y=t$를 그려봐. 두 그래프의 교점의 개수가 바뀌는 $t$의 값에 주목하도록 해. [단서3] $f(x)=\\left|\\frac{kx}{x-1}\\right|$의 그래프의 점근선이 $x=1$, $y=k$이므로 $t=k$의 좌우에서 $g(t)$의 값이 바뀔 거야. 이 조건을 이용해 $k$의 값을 찾아내야 해.", "explanation": "정답 공식: 유리함수 $y=\\frac{k}{x-a}+b$의 그래프의 점근선은 $x=a$, $y=b$이다. 함수 $y=|f(x)|$의 그래프는 $y=f(x)$의 그래프의 $x$축 아랫부분을 $x$축에 대하여 대칭이동시켜 그린다.\n1st 함수 $f(x)=\\left|\\frac{kx}{x-1}\\right|$의 그래프를 그리자.\n$f(x)=\\left|\\frac{kx}{x-1}\\right|=\\left|\\frac{k(x-1)+k}{x-1}\\right|=\\left|\\frac{k}{x-1}+k\\right|$이므로 함수 $y=f(x)$의 그래프는 [그림 1]과 같다.\n($f(x)=\\left|\\frac{k}{x-1}+k\\right|$이므로 $y=f(x)$의 그래프는 $y=\\frac{k}{x-1}+k$의 그래프를 그린 후 $x$축 아랫부분을 $x$축에 대하여 대칭이동시킨 모양이야. 이때, $k$가 양수인 것 기억해!!)\n2nd 함수 $g(t)$를 구하자. ([그림 2] 참고)\n(i) $t<0$일 때, 곡선 $y=f(x)$와 직선 $y=t$는 만나지 않으므로 $g(t)=0$\n(ii) $t=0$ 또는 $t=k$일 때, 곡선 $y=f(x)$와 직선 $y=t$는 한 점에서 만나므로 $g(t)=1$\n(iii) $0<t<k$ 또는 $t>k$일 때, 곡선 $y=f(x)$와 직선 $y=t$는 두 점에서 만나므로 $g(t)=2$\n(i)~(iii)에 의해 $g(t)=\\begin{cases} 0 & (t<0) \\\\ 1 & (t=0\\text{ 또는 }t=k) \\\\ 2 & (0<t<k\\text{ 또는 }t>k) \\end{cases}$\n3rd $\\lim_{t \\to 0+} g(t)$, $\\lim_{t \\to 2-} g(t)$의 값을 찾아 $k$의 값을 구하자.\n$\\lim_{t \\to 0+} g(t)=2$이고, ($t \\to 0+$는 $t$가 $0$보다 크면서 $0$에 접근하는 거니까 $0<t<k$일 때의 $g(t)$의 값을 생각하면 돼. 그리고 $\\lim_{t \\to 0+} g(t)$를 $\\lim_{t \\to 0+} f(t)$로 착각하지 않도록 주의해.)\n모든 양수 $a$에 대하여 $\\lim_{t \\to a-} g(t)=2$이므로 $\\lim_{t \\to 2-} g(t)=2$ ($g(t)=\\begin{cases} 0 & (t<0) \\\\ 1 & (t=0\\text{ 또는 }t=k) \\\\ 2 & (0<t<k\\text{ 또는 }t>k) \\end{cases}$이므로 $\\lim_{t \\to k-} g(t)=\\lim_{t \\to k+} g(t)=2$야. 즉 모든 양수 $a$에 대해 $\\lim_{t \\to a-} g(t)=2$라고 할 수 있어.)\n즉, $\\lim_{t \\to 0+} g(t)+\\lim_{t \\to 2-} g(t)+g(4)=5$에서 $2+2+g(4)=5$이므로 $g(4)=1$이다.\n그런데 함수 $g(t)$에서 함숫값이 $1$인 경우는 $t=0$ 또는 $t=k$이므로 $g(4)=1$에서 $k=4$이다. ($k$는 양수라 했지?)\n따라서 $f(x)=\\left|\\frac{4x}{x-1}\\right|$이므로 $f(3)=\\left|\\frac{4 \\times 3}{3-1}\\right|=\\left|\\frac{12}{2}\\right|=6$", "img": "IMG_4964.jpg", "answer_value": "$6$"}, {"id": "A208", "section": "A", "num": 208, "page": 60, "topic": "좌표평면에서의 극한의 활용", "answer": "④", "rate": "51%", "problem": "실수 $t$에 대하여 직선 $y=t$가 함수 $y=|x^{2}-1|$의 그래프와 만나는 점의 개수를 $f(t)$라 할 때, $\\lim_{t \\to 1-} f(t)$의 값은? (4점)\n[단서1] $y=|x^{2}-1|$의 그래프를 그린 후, $t$의 값의 범위에 따라 $f(t)$의 값을 구해봐. [단서2] $t=1$에서의 좌극한값을 구해.", "explanation": "정답 공식: 좌표평면에 그래프를 그려 $t$의 값에 따른 교점의 개수를 파악한다.\n1st 함수 $y=|x^{2}-1|$의 그래프를 그려 봐.\n($y=|f(x)|$의 그래프는 $y=f(x)$의 그래프의 $x$축 윗부분은 그대로, $x$축 아랫부분은 $x$축에 대하여 대칭이동시켜 그리면 돼)\n그림과 같이 $y=|x^{2}-1|$의 그래프를 그려서 $t$의 값에 따라 직선 $y=t$와 만나는 점의 개수 $f(t)$를 조사하면\n$f(t)=\\begin{cases} 2 & (t>1) \\\\ 3 & (t=1) \\\\ 4 & (0<t<1) \\\\ 2 & (t=0) \\\\ 0 & (t<0) \\end{cases}$\n$\\therefore \\lim_{t \\to 1-} f(t)=4$\n[필수] 함수 $y=f(t)$의 그래프를 그릴 때 극한값이 존재하지 않아도 함숫값이 존재하는 점들까지 정확하게 표시해야 해!", "img": "IMG_4965.jpg", "answer_value": "$4$"}, {"id": "A209", "section": "A", "num": 209, "page": 60, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "12", "rate": "60%", "problem": "[내신 유형별 서술형 문제] 최고차항의 계수가 $2$인 이차함수 $f(x)$에 대하여 $\\lim_{x \\to 1} \\left\\{\\frac{1}{\\sqrt{x+3}f(x)} - \\frac{1}{2f(x)}\\right\\} = -\\frac{1}{32}$ 일 때, $f(3)$의 값을 구하고 그 과정을 서술하시오. (10점) [단서1] $f(x)=2x^{2}+ax+b$ [단서2] $\\lim_{x \\to 1} \\left\\{\\frac{1}{\\sqrt{x+3}f(x)} - \\frac{1}{2f(x)}\\right\\}$은 수렴해. [단서3] $a$, $b$의 값을 구하면 $f(3)$을 구할 수 있어.", "explanation": "정답 공식: $\\lim_{x \\to a} \\frac{g(x)}{f(x)}=\\alpha \\ne 0$이고 $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이다.\n[단서+발상] 단서1: $f(x)$는 최고차항의 계수가 $2$인 이차함수이므로 함수 $f(x)=2x^{2}+ax+b$ ($a$, $b$는 상수)로 둘 수 있다. (적용) 단서2: 극한값이 존재하므로 식을 정리하여 함수의 극한에 대한 성질을 적용할 수 있다. (발상) 단서3: $f(x)$가 결정되면 $f(3)$을 계산할 수 있다. 극한의 성질을 적용하여 $a$, $b$의 값을 결정하여 $f(3)$의 값을 구할 수 있다. (적용)\n[문제 풀이 순서]\n1st 함수 $f(x)=2x^{2}+ax+b$라 하고 식을 정리하자.\n$f(x)=2x^{2}+ax+b$ ($a$, $b$는 상수)라 하면 ($f(x)$가 최고차항의 계수가 $2$인 이차함수이므로 $f(x)$의 이차항의 계수는 $2$야)\n$\\lim_{x \\to 1} \\frac{1}{f(x)} \\left(\\frac{1}{\\sqrt{x+3}} - \\frac{1}{2}\\right)$\n$= \\lim_{x \\to 1} \\left(\\frac{1}{2x^{2}+ax+b} \\times \\frac{2-\\sqrt{x+3}}{2\\sqrt{x+3}}\\right)$\n$= \\lim_{x \\to 1} \\left\\{\\frac{1}{2x^{2}+ax+b} \\times \\frac{\\left(2-\\sqrt{x+3}\\right)\\left(2+\\sqrt{x+3}\\right)}{2\\sqrt{x+3} \\times \\left(2+\\sqrt{x+3}\\right)}\\right\\}$\n$= \\lim_{x \\to 1} \\left\\{\\frac{1}{2x^{2}+ax+b} \\times \\frac{-(x-1)}{2\\sqrt{x+3} \\times \\left(2+\\sqrt{x+3}\\right)}\\right\\} = -\\frac{1}{32}$\n즉, $\\lim_{x \\to 1} \\frac{x-1}{(2x^{2}+ax+b) \\times 2\\sqrt{x+3} \\times \\left(2+\\sqrt{x+3}\\right)} = \\frac{1}{32}$\n2nd 함수의 극한에 대한 성질을 적용하여 $f(x)$를 구하자.\n$x \\to 1$일 때 (분자)$\\to 0$이고, 극한값이 $0$이 아니므로 (분모)$\\to 0$이어야 한다. ($\\lim_{x \\to a} \\frac{g(x)}{f(x)}=\\alpha \\ne 0$이고 $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$)\n즉, $\\lim_{x \\to 1} (2x^{2}+ax+b)=0$에서 $2+a+b=0 \\therefore b=-a-2$\n$\\lim_{x \\to 1} \\left\\{\\frac{x-1}{(2x^{2}+ax+b) \\times 2\\sqrt{x+3} \\times \\left(2+\\sqrt{x+3}\\right)}\\right\\}$\n$= \\lim_{x \\to 1} \\left\\{\\frac{x-1}{(2x^{2}+ax-a-2) \\times 2\\sqrt{x+3} \\times \\left(2+\\sqrt{x+3}\\right)}\\right\\}$\n$= \\lim_{x \\to 1} \\left\\{\\frac{x-1}{(x-1)(2x+a+2) \\times 2\\sqrt{x+3} \\times \\left(2+\\sqrt{x+3}\\right)}\\right\\}$\n$= \\lim_{x \\to 1} \\left\\{\\frac{1}{(2x+a+2) \\times 2\\sqrt{x+3} \\times \\left(2+\\sqrt{x+3}\\right)}\\right\\}$\n$=\\frac{1}{(4+a) \\times 4 \\times 4}=\\frac{1}{32}$\n이므로 $a=-2$, $b=0$\n3rd $f(3)$의 값을 구하자.\n$f(x)=2x^{2}-2x$이므로 $f(3)=2 \\times 3^{2}-2 \\times 3=12$\n[채점 기준표]\n1st $f(x)=2x^{2}+ax+b$라 하고 식을 정리한다. (4점)\n2nd 함수의 극한의 성질을 이용하여 $f(x)$를 구한다. (5점)\n3rd $f(3)$의 값을 구한다. (1점)", "img": "IMG_4965.jpg"}, {"id": "A210", "section": "A", "num": 210, "page": 61, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "500", "rate": "55%", "problem": "최고차항의 계수가 $1$인 삼차함수 $f(x)$와 함수 $g(x)= \\begin{cases} x-3 & (x \\ge 4) \\\\ -x+2 & (2<x<4) \\\\ 1 & (x=2) \\\\ -3x+6 & (x<2) \\end{cases}$ 에 대하여 $\\lim_{x \\to 0} \\frac{f(x)}{g(x+2)}$와 $\\lim_{x \\to 4} f(2x-3)g(x)$의 값이 모두 존재할 때, $f(10)$의 값을 구하고 그 과정을 서술하시오. (10점)", "explanation": "정답 공식: $\\lim_{x \\to a} f(x)$의 값이 존재하면 함수 $f(x)$의 $x=a$에서의 좌극한값과 우극한값이 같다.\n단서1: $f(x)$는 최고차항의 계수가 $1$인 삼차함수이므로 $f(x)=x^{3}+ax^{2}+bx+c$라 할 수 있다.\n단서2: 극한값이 존재하므로 $\\lim_{x \\to 0+} \\frac{f(x)}{g(x+2)}=\\lim_{x \\to 0-} \\frac{f(x)}{g(x+2)}$이고 $\\lim_{x \\to 4+} f(2x-3)g(x)=\\lim_{x \\to 4-} f(2x-3)g(x)$이어야 한다.\n단서3: $a$, $b$, $c$의 값을 각각 결정하고 $f(10)$을 계산한다.\n1st 함수 $f(x)$의 일차항의 계수와 상수항을 결정하자.\n$f(x)=x^{3}+ax^{2}+bx+c$ ($a$, $b$, $c$는 상수)라 하자.\n$\\lim_{x \\to 0} \\frac{f(x)}{g(x+2)}$의 값이 존재하고 $\\lim_{x \\to 0} g(x+2)=0$이므로 ($x+2=t$라 하면 $\\lim_{x \\to 0+} g(x+2)=\\lim_{t \\to 2+} (-t+2)=0$, $\\lim_{x \\to 0-} g(x+2)=\\lim_{t \\to 2-} (-3t+6)=0$) $\\lim_{x \\to 0} f(x)=f(0)=0$이어야 한다. 따라서 $f(0)=c=0$이므로 $f(x)=x^{3}+ax^{2}+bx$이다.\n$\\lim_{x \\to 0+} \\frac{f(x)}{g(x+2)}=\\lim_{x \\to 0-} \\frac{f(x)}{g(x+2)} \\cdots$㉠이어야 한다.\n$\\lim_{x \\to 0+} \\frac{f(x)}{g(x+2)}=\\lim_{x \\to 0+} \\frac{x^{3}+ax^{2}+bx}{-(x+2)+2}=\\lim_{x \\to 0+} \\frac{x^{3}+ax^{2}+bx}{-x}=\\lim_{x \\to 0+} (-x^{2}-ax-b)=-b$\n$\\lim_{x \\to 0-} \\frac{f(x)}{g(x+2)}=\\lim_{x \\to 0-} \\frac{x^{3}+ax^{2}+bx}{-3(x+2)+6}=\\lim_{x \\to 0-} \\frac{x^{3}+ax^{2}+bx}{-3x}=\\lim_{x \\to 0-} \\left(-\\frac{1}{3} x^{2}-\\frac{a}{3} x-\\frac{b}{3}\\right)=-\\frac{b}{3}$\n즉, ㉠에서 $-b=-\\frac{b}{3} \\therefore b=0 \\therefore f(x)=x^{3}+ax^{2} \\cdots$㉡\n2nd 함수 $f(x)$의 이차항의 계수를 결정하자.\n$\\lim_{x \\to 4} f(2x-3)g(x)$의 값이 존재하므로 $\\lim_{x \\to 4+} f(2x-3)g(x)=\\lim_{x \\to 4-} f(2x-3)g(x) \\cdots$㉢이어야 한다.\n이때 $\\lim_{x \\to 4+} f(2x-3)=\\lim_{x \\to 4-} f(2x-3)=f(2 \\times 4-3)=f(5)$이고 $\\lim_{x \\to 4+} g(x)=\\lim_{x \\to 4+} (x-3)=1$, $\\lim_{x \\to 4-} g(x)=\\lim_{x \\to 4-} (-x+2)=-2$이므로\n$\\lim_{x \\to 4+} f(2x-3)g(x)=f(5) \\times 1=f(5)$, $\\lim_{x \\to 4-} f(2x-3)g(x)=f(5) \\times (-2)=-2f(5)$\n즉, ㉢에서 $f(5)=-2f(5) \\therefore f(5)=0$\n㉡에 의하여 $f(5)=5^{3}+a \\times 5^{2}=125+25a=0$, $25a=-125 \\therefore a=-5 \\therefore f(x)=x^{3}-5x^{2}$\n3rd $f(10)$의 값을 구하자.\n$\\therefore f(10)=10^{3}-5 \\times 10^{2}=1000-500=500$\n[채점 기준표] 1st $\\lim_{x \\to 0} \\frac{f(x)}{g(x+2)}$의 값이 존재함을 이용하여 일차항의 계수와 상수항 결정 (4.5점) / 2nd $\\lim_{x \\to 4} f(2x-3)g(x)$의 값이 존재함을 이용하여 이차항의 계수 결정 (4.5점) / 3rd $f(10)$의 값 (1점)", "img": "IMG_4966.jpg"}, {"id": "A211", "section": "A", "num": 211, "page": 61, "topic": "함수의 극한에 대한 성질", "answer": "$\\frac{25}{44}$", "rate": "80%", "problem": "두 함수 $f(x)$, $g(x)$가 다음 조건을 만족시킬 때, $\\lim_{x \\to \\infty} h(x)$의 값을 구하고 그 과정을 서술하시오. (10점) (가) $\\lim_{x \\to \\infty} x^{2} f(x)=\\frac{1}{3}$ (나) $\\lim_{x \\to \\infty} \\frac{g(x)}{x}=4$ (다) $h(x)=\\frac{2g(x)+x^{3} f(x)}{6g(x)-7x^{2} f(x)g(x)}$", "explanation": "정답 공식: $\\lim_{x \\to a} f(x)$, $\\lim_{x \\to a} g(x)$의 값이 존재할 때, $\\lim_{x \\to a} \\{f(x) \\pm g(x)\\}=\\lim_{x \\to a} f(x) \\pm \\lim_{x \\to a} g(x)$, $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=\\frac{\\lim_{x \\to a} f(x)}{\\lim_{x \\to a} g(x)}$이다.\n단서1, 2: $\\lim_{x \\to \\infty} x^{2} f(x)$, $\\lim_{x \\to \\infty} \\frac{g(x)}{x}$는 수렴하므로 $h(x)$를 함수의 극한의 성질을 적용할 수 있는 식으로 변형해야 한다. 분모, 분자에 적절한 다항식을 곱하거나 나눠서 변형한다.\n1st 분모, 분자를 $x$로 나누어 함수의 극한의 성질을 적용할 수 있는 형태로 $h(x)$의 식을 변형하자.\n$\\lim_{x \\to \\infty} \\frac{2g(x)+x^{3} f(x)}{6g(x)-7x^{2} f(x)g(x)} = \\lim_{x \\to \\infty} \\frac{2 \\times \\frac{g(x)}{x} + x^{2} f(x)}{6 \\times \\frac{g(x)}{x} - 7x^{2} f(x) \\times \\frac{g(x)}{x}}$\n2nd 함수의 극한의 성질을 이용하여 $\\lim_{x \\to \\infty} h(x)$의 값을 구하자.\n$= \\frac{2 \\lim \\frac{g(x)}{x} + \\lim x^{2} f(x)}{6 \\lim \\frac{g(x)}{x} - 7 \\lim x^{2} f(x) \\times \\lim \\frac{g(x)}{x}} = \\frac{2 \\times 4+\\frac{1}{3}}{6 \\times 4-7 \\times \\frac{1}{3} \\times 4} = \\frac{25}{44}$\n[채점 기준표] 1st 분모, 분자를 $x$로 나누어 $h(x)$의 식 변형 (5.5점) / 2nd $\\lim_{x \\to \\infty} h(x)$의 값 (4.5점)\n다른 풀이: 조건을 만족하는 함수를 구하여 극한값 구하기\n$\\lim_{x \\to \\infty} x^{2} f(x)=\\frac{1}{3}$에서 $f(x)=\\frac{1}{3x^{2}} (x \\ne 0)$이라 할 수 있고, $\\lim_{x \\to \\infty} \\frac{g(x)}{x}=4$에서 $g(x)=4x$라 할 수 있어.\n$h(x)=\\frac{2 \\times 4x+x^{3} \\times \\frac{1}{3x^{2}}}{6 \\times 4x-7x^{2} \\times \\frac{1}{3x^{2}} \\times 4x}=\\frac{8x+\\frac{x}{3}}{24x-\\frac{28x}{3}}=\\frac{\\frac{25x}{3}}{\\frac{44x}{3}}=\\frac{25}{44} (\\because x \\ne 0)$이므로 $\\lim_{x \\to \\infty} h(x)=\\frac{25}{44}$", "img": "IMG_4966.jpg, IMG_4967.jpg"}, {"id": "A212", "section": "A", "num": 212, "page": 62, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "10", "rate": "60%", "problem": "삼차함수 $f(x)$가 다음 조건을 만족시킬 때, $f(2)$의 값을 구하고 그 과정을 서술하시오. (10점) (가) $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=2$ (나) $\\lim_{x \\to 0} \\frac{f(x)}{x^{2}} \\left(\\frac{6}{x^{2}+x+2}-3\\right)=-\\frac{3}{2}$", "explanation": "정답 공식: $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=b$이고 $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이다.\n단서1: $f(x)$는 $x-1$을 인수로 가지지만 $(x-1)^{m} (m \\ge 2)$을 인수로 갖진 않다. 왜냐하면 $2$ 이상인 자연수 $m$에 대하여 $f(x)$가 $(x-1)^{m}$을 인수로 가지면 $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=0$이기 때문이다.\n단서2: (가), (나)를 통해 알아낸 인수가 $x-1$, $x$이므로 $f(x)=x(x-1)(ax+b)$라 하고 상수 $a$, $b$를 구할 수 있다.\n1st 함수의 극한의 성질을 이용하여 $f(1)$, $f(0)$의 값을 구하자.\n조건 (가)에서 $x \\to 1$일 때 (분모)$\\to 0$이고 극한값이 존재하므로 (분자)$\\to 0$이어야 한다. 즉, $f(1)=0$이어야 한다.\n조건 (나)에서 $\\lim_{x \\to 0} \\frac{f(x)}{x^{2}} \\left(\\frac{6}{x^{2}+x+2}-3\\right)=\\lim_{x \\to 0} \\left\\{\\frac{f(x)}{x^{2}} \\times \\frac{6-3(x^{2}+x+2)}{x^{2}+x+2}\\right\\}=\\lim_{x \\to 0} \\left\\{\\frac{f(x)}{x^{2}} \\times \\frac{-3x(x+1)}{x^{2}+x+2}\\right\\}=\\lim_{x \\to 0} \\left\\{\\frac{f(x)}{x} \\times \\frac{-3(x+1)}{x^{2}+x+2}\\right\\}=-\\frac{3}{2}$\n이므로 $x \\to 0$일 때 (분모)$\\to 0$이고 극한값이 존재하므로 (분자)$\\to 0$이어야 한다. 즉, $f(0)=0$이어야 한다.\n2nd 함수의 극한의 성질을 이용하여 $f(x)$를 결정하자.\n$f(x)$는 삼차함수이고 $x$와 $x-1$을 인수로 가져야 하므로 $f(x)=x(x-1)(ax+b)$ ($a$, $b$는 상수, $a \\ne 0$)로 놓을 수 있다.\n조건 (나)에 대입하면 $\\lim_{x \\to 0} \\left\\{\\frac{x(x-1)(ax+b)}{x^{2}} \\times \\frac{-3x(x+1)}{x^{2}+x+2}\\right\\}=\\lim_{x \\to 0} \\left\\{(x-1)(ax+b) \\times \\frac{-3(x+1)}{x^{2}+x+2}\\right\\}=(-b) \\times \\left(-\\frac{3}{2}\\right)=\\frac{3b}{2}=-\\frac{3}{2}$ 이므로 $b=-1$이다.\n조건 (가)에서 $\\lim_{x \\to 1} \\frac{f(x)}{x-1}=\\lim_{x \\to 1} \\frac{x(x-1)(ax-1)}{x-1}=\\lim_{x \\to 1} \\{x(ax-1)\\}=a-1=2$ 이므로 $a=3$이다.\n따라서 $f(x)=x(x-1)(3x-1)$이다.\n3rd $f(2)$의 값을 구하자.\n$f(2)=2(2-1)(6-1)=10$\n[채점 기준표] 1st $f(1)$, $f(0)$의 값 (4.5점) / 2nd $f(x)$ 결정 (4.5점) / 3rd $f(2)$의 값 (1점)", "img": "IMG_4967.jpg"}, {"id": "A213", "section": "A", "num": 213, "page": 63, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "9", "rate": "65%", "problem": "다항함수 $f(x)$가 다음 조건을 만족시킨다. (가) $\\lim_{x \\to \\infty} \\frac{f(x)-x^{3}}{x^{2}+2x-1}=3$ (나) $\\lim_{x \\to 2} \\frac{f(x)}{(x-2)^{2}}=a$ 실수 $a$의 값을 구하고 그 과정을 서술하시오. (10점)", "explanation": "정답 공식: $\\lim_{x \\to a} \\frac{g(x)}{f(x)}=a$이고 $\\lim_{x \\to a} f(x)=0$이면 $\\lim_{x \\to a} g(x)=0$이다.\n단서1: 함수 $f(x)-x^{3}$은 이차항의 계수가 $3$인 이차함수임을 알 수 있다. 왜냐하면 $f(x)-x^{3}$이 삼차 이상의 다항식이면 $\\lim_{x \\to \\infty} \\frac{f(x)-x^{3}}{x^{2}+2x-1}=\\infty$ 또는 $-\\infty$이다. 또한 $f(x)-x^{3}$이 일차 이하의 다항식이면 극한은 $0$이다.\n단서2: $f(x)$는 $(x-2)^{2}$을 인수로 갖고 있음을 알 수 있다. 그렇지 않다면 $\\lim_{x \\to 2} \\frac{f(x)}{(x-2)^{2}}=\\infty$ 또는 $-\\infty$이기 때문이다.\n1st $f(x)-x^{3}=3x^{2}+px+q$라 하고 함수의 극한값을 이용하여 상수 $p$와 $q$의 관계를 구하자.\n조건 (가)에서 함수 $f(x)-x^{3}$은 최고차항의 계수가 $3$인 이차함수이다. $f(x)=x^{3}+3x^{2}+px+q$ ($p$, $q$는 상수)라 하면\n조건 (나)에서 $x \\to 2$일 때 극한값이 존재하고 (분모)$\\to 0$이므로 (분자)$\\to 0$이어야 한다.\n즉, $\\lim_{x \\to 2} f(x)=0$에서 $8+12+2p+q=0 \\therefore q=-2p-20$\n$\\left(\\lim_{x \\to 2} f(x)=\\lim_{x \\to 2} \\frac{f(x)}{(x-2)^{2}} \\times \\lim_{x \\to 2} (x-2)^{2}=a \\times 0=0\\right)$\n2nd 조립제법을 이용하여 $f(x)$를 결정하자.\n이때 $f(x)=x^{3}+3x^{2}+px-2p-20$이고, $f(2)=0$이므로 조립제법을 이용하면 $f(x)=(x-2)(x^{2}+5x+p+10)$\n그런데 조건 (나)에 의해 방정식 $x^{2}+5x+p+10=0$은 $x=2$를 근으로 가진다. ($f(x)$는 $(x-2)^{2}$을 인수로 가지므로 방정식 $f(x)=0$은 $x=2$를 중근으로 가져)\n따라서 $4+10+p+10=0$이므로 $p=-24$이다.\n즉, $f(x)=(x-2)(x^{2}+5x-14)=(x-2)^{2}(x+7)$이다.\n3rd $a$의 값을 구하자.\n$\\lim_{x \\to 2} \\frac{f(x)}{(x-2)^{2}}=\\lim_{x \\to 2} \\frac{(x-2)^{2}(x+7)}{(x-2)^{2}}=9 \\therefore a=9$\n[채점 기준표] 1st $p$와 $q$의 관계 (3.5점) / 2nd 조립제법으로 $f(x)$ 결정 (5.5점) / 3rd $a$의 값 (1점)", "img": "IMG_4968.jpg"}, {"id": "A214", "section": "A", "num": 214, "page": 63, "topic": "함수의 극한값의 존재", "answer": "$-7$, $1$", "rate": "65%", "problem": "곡선 $f(x)=x^{2}-3x+4$와 직선 $y=kx$가 만나는 점의 개수를 $g(k)$라 하자. $\\lim_{k \\to a} g(k)$의 값이 존재하지 않도록 하는 $a$의 값을 모두 구하고 그 과정을 서술하시오. (10점)", "explanation": "정답 공식: $\\lim_{x \\to a-} f(x)=a$, $\\lim_{x \\to a+} f(x)=b$이고 $a=b$이면 $\\lim_{x \\to a} f(x)$는 수렴한다.\n단서1: 곡선 $y=f(x)$와 직선 $y=kx$의 교점의 $x$좌표는 방정식 $f(x)-kx=0$의 해이기 때문에 $f(x)-kx=0$의 해의 개수가 교점의 개수이다. 따라서 판별식을 이용하여 해의 개수를 조사한다.\n단서2: $\\lim_{k \\to a} g(k)$가 존재하지 않기 위해서는 $\\lim g(k)=\\infty$ 또는 $-\\infty$이거나 $\\lim_{k \\to a-} g(k) \\ne \\lim_{k \\to a+} g(k)$이다. 그런데 곡선과 직선이 일치하지 않으면 교점의 개수가 $\\infty$일 수 없으므로 $\\lim_{k \\to a-} g(k) \\ne \\lim_{k \\to a+} g(k)$인 경우만 고려해도 충분하다.\n1st 판별식을 이용하여 곡선 $y=f(x)$와 $y=kx$가 만나는 점의 개수를 구하자.\n방정식 $f(x)-kx=x^{2}-(k+3)x+4=0$의 판별식을 $D$라 하자.\n$D=(k+3)^{2}-16=k^{2}+6k-7=(k+7)(k-1)$로\n$D>0$을 만족하는 $k$의 값의 범위는 $k>1$ 또는 $k<-7$이다. 즉, $k>1$ 또는 $k<-7$일 때, $g(k)=2$이다.\n$D=0$을 만족하는 $k$의 값은 $-7$, $1$이다. 즉, $k=-7$, $1$일 때, $g(k)=1$이다.\n$D<0$을 만족하는 $k$의 값의 범위는 $-7<k<1$이다. 즉, $-7<k<1$일 때, $g(k)=0$이다.\n이를 정리하면 $g(k)= \\begin{cases} 2 & (k>1) \\\\ 1 & (k=1) \\\\ 0 & (-7<k<1) \\\\ 1 & (k=-7) \\\\ 2 & (k<-7) \\end{cases}$\n2nd $\\lim_{k \\to a-} g(k) \\ne \\lim_{k \\to a+} g(k)$를 만족하는 $a$의 값을 찾자.\n실수 $k$에 대하여 $\\lim_{k \\to -7+} g(k) \\ne \\lim_{k \\to -7-} g(k)$이고 $\\lim_{k \\to 1+} g(k) \\ne \\lim_{k \\to 1-} g(k)$이므로 함수 $g(k)$는 $a=-7$과 $a=1$에서 $\\lim_{k \\to a} g(k)$의 값이 존재하지 않는다.\n따라서 구하는 값은 $-7$, $1$이다.\n[채점 기준표] 1st 판별식으로 교점의 개수 (5.5점) / 2nd $a$의 값 (4.5점)", "img": "IMG_4968.jpg"}, {"id": "A215", "section": "A", "num": 215, "page": 64, "topic": "∞/∞ 꼴의 극한", "answer": "80", "rate": "65%", "problem": "$\\lim_{x \\to \\infty} \\sum_{k=1}^{80} \\frac{x^{4}\\left(\\sqrt{x+6}-\\sqrt{x}\\right)^{4}}{(kx+1)(kx+x+1)}$의 값을 구하고 그 과정을 서술하시오. (10점)", "explanation": "정답 공식: $\\lim_{x \\to \\infty} \\sum_{k=1}^{n} a_{k} f(x)=\\sum_{k=1}^{n} \\lim_{x \\to \\infty} a_{k} f(x)$이고 $\\frac{1}{AB}=\\frac{1}{B-A}\\left(\\frac{1}{A}-\\frac{1}{B}\\right)$\n단서: $\\lim_{x \\to \\infty} \\sum_{k=1}^{80} \\frac{x^{4}\\left(\\sqrt{x+6}-\\sqrt{x}\\right)^{4}}{(kx+1)(kx+x+1)}=\\sum_{k=1}^{80} \\lim_{x \\to \\infty} \\frac{x^{4}\\left(\\sqrt{x+6}-\\sqrt{x}\\right)^{4}}{(kx+1)(kx+x+1)}$이다. 왜냐하면 식에서 $k$와 $x$는 서로에게 영향을 미치는 문자가 아니기 때문이다. 즉, $k$의 값이 $x$의 값에 미치는 영향이 없고 반대로 $x$의 값이 $k$의 값에 미치는 영향이 없다. 따라서 $k$에 관한 급수의 값을 먼저 구하고 $x$에 대한 극한값을 구하나 $x$에 대한 극한값을 구하고 $k$에 관한 급수의 값을 구하나 같다. 문자 $x$로 인해 식을 바로 구하기 어렵기 때문에 $x$에 대한 극한을 구하여 문자 $x$를 없애서 $k$에 관한 식 $g(k)$를 구할 수 있다. 그리고 이를 통해 $\\sum_{k=1}^{80} g(k)$의 값을 구할 수 있다.\n1st 식을 함수의 극한의 성질을 이용하여 $k$에 관한 식으로 나타내자.\n$\\frac{x^{4}\\left(\\sqrt{x+6}-\\sqrt{x}\\right)^{4}}{(kx+1)(kx+x+1)}$의 분모, 분자를 $x^{2}$으로 나누면 ($(kx+1)(kx+x+1)$이 $x$에 관한 이차식이기 때문에 극한값을 적용하여 이 식을 $k$에 관한 식으로 만들려면 $x^{2}$으로 나눠야 함을 알 수 있어.)\n$\\frac{x^{2}}{\\left(k+\\frac{1}{x}\\right)\\left(k+1+\\frac{1}{x}\\right)} \\times \\left(\\sqrt{x+6}-\\sqrt{x}\\right)^{4}$이다.\n이때 $\\sqrt{x+6}-\\sqrt{x}=\\frac{6}{\\sqrt{x+6}+\\sqrt{x}}$에서 $\\left(\\sqrt{x+6}-\\sqrt{x}\\right)^{4}=\\left(\\frac{6}{\\sqrt{x+6}+\\sqrt{x}}\\right)^{4}$이므로\n$\\frac{x^{2}}{\\left(k+\\frac{1}{x}\\right)\\left(k+1+\\frac{1}{x}\\right)} \\times \\left(\\frac{6}{\\sqrt{x+6}+\\sqrt{x}}\\right)^{4} = \\frac{1}{\\left(k+\\frac{1}{x}\\right)\\left(k+1+\\frac{1}{x}\\right)} \\times \\left(\\frac{6\\sqrt{x}}{\\sqrt{x+6}+\\sqrt{x}}\\right)^{4}$ ($x^{2}=\\left(\\sqrt{x}\\right)^{4}$이므로)\n$\\lim_{x \\to \\infty} \\frac{1}{\\left(k+\\frac{1}{x}\\right)\\left(k+1+\\frac{1}{x}\\right)}=\\frac{1}{k(k+1)}$이고 $\\lim_{x \\to \\infty} \\left(\\frac{6\\sqrt{x}}{\\sqrt{x+6}+\\sqrt{x}}\\right)^{4}=3^{4}$이므로\n$\\lim_{x \\to \\infty} \\left[\\frac{1}{\\left(k+\\frac{1}{x}\\right)\\left(k+1+\\frac{1}{x}\\right)} \\times \\left(\\frac{6\\sqrt{x}}{\\sqrt{x+6}+\\sqrt{x}}\\right)^{4}\\right]=\\frac{3^{4}}{k(k+1)}$이다.\n2nd $\\frac{1}{AB}=\\frac{1}{B-A}\\left(\\frac{1}{A}-\\frac{1}{B}\\right)$을 적용하여 값을 구하자.\n$\\lim_{x \\to \\infty} \\sum_{k=1}^{80} \\frac{x^{4}\\left(\\sqrt{x+6}-\\sqrt{x}\\right)^{4}}{(kx+1)(kx+x+1)}=\\sum_{k=1}^{80} \\left\\{\\frac{1}{k(k+1)} \\times 3^{4}\\right\\}=3^{4} \\times \\sum_{k=1}^{80} \\frac{1}{k(k+1)}=3^{4} \\times \\sum_{k=1}^{80} \\left(\\frac{1}{k}-\\frac{1}{k+1}\\right)=3^{4} \\times \\left(1-\\frac{1}{81}\\right)=80$\n[채점 기준표] 1st 함수의 극한의 성질을 이용하여 $k$에 관한 식으로 나타낸다 (9점) / 2nd $\\frac{1}{AB}=\\frac{1}{B-A}\\left(\\frac{1}{A}-\\frac{1}{B}\\right)$을 적용하여 값을 구한다 (1점)", "img": "IMG_4969.jpg"}, {"id": "A216", "section": "A", "num": 216, "page": 64, "topic": "도형의 길이에 대한 극한", "answer": "13", "rate": "25%", "problem": "좌표평면 위의 두 직선 $12x+5y=0$과 $12x+(5-t)y-12t=0$이 한 점 $A$에서 만나고, 직선 $12x+(5-t)y-12t=0 (0<t<5)$이 $x$축과 만나는 점을 $P$, $y$축과 만나는 점을 $Q$라 하자. 두 삼각형 $AOP$, $POQ$에 내접하는 원의 반지름의 길이를 각각 $R_{1}(t)$, $R_{2}(t)$라 할 때, $\\lim_{t \\to 0+} \\frac{15R_{2}(t)}{R_{1}(t)}$의 값을 구하고 그 과정을 서술하시오. (단, $O$는 원점이다.) (10점)", "explanation": "정답 공식: 세 변의 길이가 $a$, $b$, $c$인 삼각형 $ABC$의 넓이를 $S$, 내접원의 반지름의 길이를 $r$라 하면 $S=\\frac{1}{2} r(a+b+c)$이다.\n단서1: 연립방정식의 해를 이용하여 교점 $A$의 좌표를 구할 수 있어. 두 직선의 방정식 $l_{1}$: $ax+by+c=0$, $l_{2}$: $a'x+b'y+c'=0$의 해는 두 직선 $l_{1}$과 $l_{2}$의 교점의 $x$좌표와 $y$좌표이다.\n단서2: 삼각형 세 변의 길이와 넓이를 알면 내접원의 반지름의 길이를 구할 수 있어. 삼각형의 세 꼭짓점과 내접원의 중심을 연결하면 세 개의 삼각형이 만들어지고, 삼각형의 한 변을 밑변으로, 반지름을 높이로 하는 삼각형 세 개의 넓이의 합은 삼각형 넓이가 된다.\n1st 교점 $A$의 좌표를 구하자.\n두 직선 $12x+5y=0$과 $12x+(5-t)y-12t=0$을 연립하여 교점을 구하자. $12x+5y=0$이므로 $12x+(5-t)y-12t=12x+5y-ty-12t=0-ty-12t=0$\n따라서 $t \\ne 0$이므로 $y=-12$이고 $x=5$이다. 즉, 교점 $A(5, -12)$이다.\n2nd 삼각형의 넓이를 이용하여 내접원의 반지름의 길이 $R_{1}(t)$, $R_{2}(t)$를 구하자.\n직선 $12x+(5-t)y-12t=0$이 $x$축과 만나는 점은 $P(t, 0)$, $y$축과 만나는 점은 $Q\\left(0, \\frac{12t}{5-t}\\right)$가 되어 좌표평면에 나타낼 수 있다.\n삼각형 $AOP$의 넓이는 (높이는 점 $A$의 $y$좌표의 절댓값 $12$) $\\frac{1}{2} \\times OP \\times 12=\\frac{1}{2} \\times R_{1}(t) \\times (OP+OA+AP) \\cdots$㉠\n이때 $AO=\\sqrt{5^{2}+12^{2}}=13$, $OP=t$ (단, $0<t<5$), $AP=\\sqrt{(5-t)^{2}+(-12-0)^{2}}=\\sqrt{t^{2}-10t+169}$이므로\n㉠에서 $12t=R_{1}(t)\\left(t+13+\\sqrt{t^{2}-10t+169}\\right)$, $R_{1}(t)=\\frac{12t}{t+13+\\sqrt{t^{2}-10t+169}}$이다.\n삼각형 $POQ$의 넓이는 (직각삼각형) $\\frac{1}{2} \\times OP \\times OQ=\\frac{1}{2} \\times R_{2}(t) \\times (OP+OQ+PQ) \\cdots$㉡\n이때 $OP=t$이고, $OQ=\\frac{12t}{5-t}$이므로 $PQ=\\sqrt{t^{2}+\\left(\\frac{12t}{5-t}\\right)^{2}}$\n㉡에서 $t \\times \\frac{12t}{5-t}=R_{2}(t)\\left\\{t+\\frac{12t}{5-t}+\\sqrt{t^{2}+\\left(\\frac{12t}{5-t}\\right)^{2}}\\right\\}$\n$R_{2}(t)=\\frac{\\frac{12t^{2}}{5-t}}{t+\\frac{12t}{5-t}+\\sqrt{t^{2}+\\left(\\frac{12t}{5-t}\\right)^{2}}}$이다.\n3rd $\\lim_{t \\to 0+} \\frac{15R_{2}(t)}{R_{1}(t)}$의 값을 구하자.\n$\\lim_{t \\to 0+} \\frac{15R_{2}(t)}{R_{1}(t)}=\\lim_{t \\to 0+} 15 \\times \\frac{\\frac{R_{2}(t)}{t}}{\\frac{R_{1}(t)}{t}}$\n$=\\lim_{t \\to 0+} 15 \\times \\frac{\\left[\\frac{\\frac{12t}{5-t}}{t+\\frac{12t}{5-t}+\\sqrt{t^{2}+\\left(\\frac{12t}{5-t}\\right)^{2}}}\\right]}{\\left[\\frac{12}{t+13+\\sqrt{t^{2}-10t+169}}\\right]}$\n$=\\lim_{t \\to 0+} 15 \\times \\left[\\frac{\\frac{12}{5-t}}{1+\\frac{12}{5-t}+\\sqrt{1+\\left(\\frac{12}{5-t}\\right)^{2}}}\\right] \\times \\frac{t+13+\\sqrt{t^{2}-10t+169}}{12}$\n$=15 \\times \\left[\\frac{\\frac{12}{5}}{1+\\frac{12}{5}+\\sqrt{1+\\left(\\frac{12}{5}\\right)^{2}}}\\right] \\times \\frac{26}{12}=15 \\times \\frac{12}{5+12+13} \\times \\frac{26}{12}=13$\n[채점 기준표] 1st 교점 $A$의 좌표 (1점) / 2nd 내접원의 반지름의 길이 $R_{1}(t)$, $R_{2}(t)$ (8점) / 3rd 극한값 (1점)", "img": "IMG_4969.jpg, IMG_4970.jpg"}, {"id": "A217", "section": "A", "num": 217, "page": 65, "topic": "가우스 기호를 포함한 함수의 극한", "answer": "$\\frac{3}{2}$", "rate": "50%", "problem": "$\\lim_{x \\to \\infty} \\frac{\\left[\\sqrt{9x^{2}+5x}\\right]-\\sqrt{x}}{\\left[\\sqrt{4x^{2}+3x}\\right]-\\sqrt{x}}$의 값을 구하고 그 과정을 서술하시오. (단, $[x]$는 $x$보다 크지 않은 최대 정수이다.) (10점)", "explanation": "정답 공식: 정수 $n$에 대하여 $[x]=n$이면 $x=n+a$이다. (단, $0 \\le a<1$)\n단서: 정수 $n$에 대하여 $[x]=n$이라 하면 $0 \\le a<1$인 어떤 실수 $a$에 대해서 $x=n+a$이다. 따라서 $x=[x]+a$이므로 $[x]=x-a$가 된다.\n1st $[x]=x-a$를 이용하여 주어진 식을 변형하자.\n$\\left[\\sqrt{9x^{2}+5x}\\right]=\\sqrt{9x^{2}+5x}-\\alpha (0 \\le \\alpha<1)$, $\\left[\\sqrt{4x^{2}+3x}\\right]=\\sqrt{4x^{2}+3x}-\\beta (0 \\le \\beta<1)$로 놓으면\n$\\lim_{x \\to \\infty} \\frac{\\left[\\sqrt{9x^{2}+5x}\\right]-\\sqrt{x}}{\\left[\\sqrt{4x^{2}+3x}\\right]-\\sqrt{x}}=\\lim_{x \\to \\infty} \\frac{\\sqrt{9x^{2}+5x}-\\alpha-\\sqrt{x}}{\\sqrt{4x^{2}+3x}-\\beta-\\sqrt{x}}$\n2nd 함수의 극한의 성질을 적용할 수 있게 식을 변형한 뒤 극한값을 구하자.\n분모, 분자를 $x$로 나누면 $=\\lim_{x \\to \\infty} \\frac{\\sqrt{9+\\frac{5}{x}}-\\frac{\\alpha}{x}-\\sqrt{\\frac{1}{x}}}{\\sqrt{4+\\frac{3}{x}}-\\frac{\\beta}{x}-\\sqrt{\\frac{1}{x}}}=\\frac{\\sqrt{9}}{\\sqrt{4}}=\\frac{3}{2}$\n[채점 기준표] 1st $[x]=x-a$를 이용하여 식 변형 (5점) / 2nd 식을 변형한 뒤 극한값 (5점)\n다른 풀이: $x \\to \\infty$일 때 $[x] \\fallingdotseq x$임을 이용하기\n$x \\to \\infty$일 때 $\\left[\\sqrt{9x^{2}+5x}\\right] \\fallingdotseq \\sqrt{9x^{2}+5x}$이고 $\\left[\\sqrt{4x^{2}+3x}\\right] \\fallingdotseq \\sqrt{4x^{2}+3x}$이므로\n$\\lim_{x \\to \\infty} \\frac{\\left[\\sqrt{9x^{2}+5x}\\right]-\\sqrt{x}}{\\left[\\sqrt{4x^{2}+3x}\\right]-\\sqrt{x}}=\\lim_{x \\to \\infty} \\frac{\\sqrt{9x^{2}+5x}-\\sqrt{x}}{\\sqrt{4x^{2}+3x}-\\sqrt{x}}=\\lim_{x \\to \\infty} \\frac{\\sqrt{9+\\frac{5}{x}}-\\sqrt{\\frac{1}{x}}}{\\sqrt{4+\\frac{3}{x}}-\\sqrt{\\frac{1}{x}}}=\\frac{\\sqrt{9}}{\\sqrt{4}}=\\frac{3}{2}$", "img": "IMG_4970.jpg"}, {"id": "A218", "section": "A", "num": 218, "page": 66, "topic": "가우스 기호를 포함한 함수의 극한", "answer": "448", "rate": "30%", "problem": "함수 $f(x)$는 $f(x)= \\begin{cases} \\left[\\sqrt{x}\\right] & (x \\ge 0) \\\\ 0 & (x<0) \\end{cases}$이고, 실수 $m$에 대하여 두 함수 $g(x)=-|x|+m$의 그래프와 $y=f(x)$의 그래프의 교점의 개수를 $h(m)$이라 하자. $m<20$인 범위에서 함수 $h(m)$이 $\\lim_{m \\to a-} h(m) \\ne \\lim_{m \\to a+} h(m)$을 만족시키는 서로 다른 실수 $a$의 값은 $a_{1}$, $a_{2}$, $a_{3}$, …, $a_{n}$의 $n$개이다. $n(a_{1}+a_{2}+a_{3}+\\cdots+a_{n})$의 값을 구하고 그 과정을 서술하시오. (단, $[x]$는 $x$보다 크지 않은 최대 정수이다.) (10점)", "explanation": "정답 공식: $f(x)=[x]$는 구간 $(n, n+1)$에서 연속이고 $x=n$에서 불연속이다. (단, $n$은 정수이다.)\n단서1: $f(x)$는 $x$가 제곱수일 때 불연속이다. 따라서 $n^{2} \\le x<(n+1)^{2}$일 때 함수 $f(x)$의 그래프 개형을 그려야 한다.\n단서2: $f(x)$와 $g(x)$의 그래프 개형을 그리면 두 함수의 교점이 어디에 생기는지 쉽게 알 수 있고 이를 통해 $h(m)$을 쉽게 그릴 수 있다.\n1st $x$의 값의 범위에 따른 $f(x)$의 값을 구하자.\n함수 $f(x)$는 $x \\ge 0$에서 $\\sqrt{x}$보다 크지 않은 최대의 정수이므로 $f(x)$는 다음과 같다. ($y=\\left[\\sqrt{x}\\right]$는 $\\sqrt{x}$가 정수인 점에서 불연속이기 때문에 $n \\le \\sqrt{x}<n+1$, 즉 $n^{2} \\le x<(n+1)^{2}$에서의 범위를 생각하면 충분해.)\n(i) $0 \\le x<1$일 때, $0 \\le \\sqrt{x}<1$이므로 $f(x)=0$\n(ii) $1 \\le x<4$일 때, $1 \\le \\sqrt{x}<2$이므로 $f(x)=1$\n(iii) $4 \\le x<9$일 때, $2 \\le \\sqrt{x}<3$이므로 $f(x)=2$\n(iv) $9 \\le x<16$일 때, $3 \\le \\sqrt{x}<4$이므로 $f(x)=3$\n(v) $16 \\le x<25$일 때, $4 \\le \\sqrt{x}<5$이므로 $f(x)=4$\n(vi) $25 \\le x<36$일 때, $5 \\le \\sqrt{x}<6$이므로 $f(x)=5 \\cdots$\n2nd 두 함수 $f(x)$와 $g(x)$의 그래프를 그리자.\n함수 $g(x)=-|x|+m$의 그래프와 함수 $y=f(x)$의 그래프는 그림과 같다. ($m<0$, $m=0$, $m=1$, $m=2$, $m=5$, $m=6$ 등의 경우 표시)\n3rd $m$의 값의 범위에 따른 $h(m)$의 값을 구하고, 이를 그래프로 나타내자.\n$m<0$: $h(m)=0$ / $m=0$: $1$ / $0<m<1$: $2$ / $1 \\le m<2$: $1$ / $2 \\le m<5$: $2$ / $5 \\le m<6$: $1$ / $6 \\le m<11$: $2$ / $11 \\le m<12$: $1$ / $12 \\le m<19$: $2$ / $19 \\le m<20$: $1$\n따라서 함수 $h(m)$의 그래프는 그림과 같다.\n4th 그래프를 통해 $\\lim_{m \\to a-} h(m) \\ne \\lim_{m \\to a+} h(m)$인 $a$의 값을 모두 구하여 $n(a_{1}+a_{2}+a_{3}+\\cdots+a_{n})$의 값을 구하자.\n함수 $h(m)$은 $m=0$, $1$, $2$, $5$, $6$, $11$, $12$, $19$, $20$, …에서 $\\lim_{m \\to a-} h(m) \\ne \\lim_{m \\to a+} h(m)$이다.\n$m<20$인 범위에서 이를 만족시키는 서로 다른 실수 $a$의 값은 $a=0$, $1$, $2$, $5$, $6$, $11$, $12$, $19$로 $8$개이다.\n$\\therefore n(a_{1}+a_{2}+\\cdots+a_{n})=8 \\times (0+1+2+5+6+11+12+19)=8 \\times 56=448$\n[채점 기준표] 1st $f(x)$의 값 (3점) / 2nd 그래프 (3점) / 3rd $h(m)$의 값과 그래프 (3점) / 4th $a$의 값과 $n(a_{1}+\\cdots+a_{n})$ (1점)", "img": "IMG_4971.jpg"}, {"id": "A219", "section": "A", "num": 219, "page": 67, "topic": "좌표평면에서의 여러 가지 극한", "answer": "③", "rate": "40%", "problem": "두 실수 $a$, $b$에 대하여 함수 $f(x)$는 $f(x)= \\begin{cases} 2^{x+a} & (x \\le 0) \\\\ (x+b)^{2} & (x>0) \\end{cases}$이다. 실수 $t$에 대하여 $x$에 대한 방정식 $f(x)=t$의 서로 다른 실근의 개수를 $g(t)$라 할 때, 함수 $g(t)$는 다음 조건을 만족시킨다. $\\lim_{t \\to k-} g(t) \\ne \\lim_{t \\to k+} g(t)$와 $\\lim_{t \\to 2k-} g(t) \\ne \\lim_{t \\to 2k+} g(t)$를 모두 만족시키는 양수 $k$가 존재한다. $\\lim_{t \\to 16-} g(t) \\times \\lim_{t \\to 16+} g(t)=2$가 되도록 하는 두 실수 $a$, $b$의 순서쌍 $(a, b)$에 대하여 $a+b$의 최댓값과 최솟값의 곱은? (4점)", "explanation": "정답 공식: $\\lim_{x \\to a+} f(x)=L$일 때, $L$을 $x=a$에서 $f(x)$의 우극한값이라 하고 $\\lim_{x \\to a-} f(x)=L$일 때, $L$을 $x=a$에서 $f(x)$의 좌극한값이라 한다.\n단서1: $x$축이 점근선이고 $(0, 2^{a})$까지 오른쪽 위로 올라가는 곡선이야.\n단서2: $(-b, 0)$이 꼭짓점이고 아래로 볼록한 곡선이야.\n단서3: 함수 $y=f(x)$의 그래프와 $y=t$ ($t$는 실수)가 만나는 교점의 개수가 서로 다른 실근의 개수야.\n단서4: $y=g(t)$는 $t=k$, $t=2k$에서 좌극한값과 우극한값이 다르다는 것을 의미해.\n단서5: $y=f(x)$, $y=t$가 두 점에서 만나는 경우가 반드시 있어야 함을 알 수 있어.\n1st 실수 $b$의 부호에 따라 각 경우에 따른 $y=f(x)$의 그래프와 $y=g(t)$의 그래프를 그려 조건을 만족시키는 경우를 확인하자.\n함수 $g(t)$에서의 주어진 조건과 $\\lim_{t \\to 16-} g(t) \\times \\lim_{t \\to 16+} g(t)=2$에서 $k=16$ 또는 $2k=16$\n($y$축에 평행한 직선을 그려 보면 $(1)$, $(2)$처럼 만나는 교점의 개수가 직선 위, 아래를 기준으로 달라지는 경우를 찾을 수 있을 거야. 예를 들어 $(1)$은 $y=16$과 $y=f(x)$와의 교점의 개수가 $2$이며 $16$에서의 우극한값은 $1$((1) 위에서 만나는 교점의 개수가 $1$)이고 좌극한값은 $2$((1) 아래에서 만나는 교점의 개수가 $2$)가 됨을 알 수 있어.)\n(i) $b<0$인 경우\n① $2^{a}=16$, $b^{2}=8$일 때, $k=8$이고 함수 $f(x)$와 $g(t)$의 그래프를 그리면 그림과 같다.\n$\\lim_{t \\to 16-} g(t) \\times \\lim_{t \\to 16+} g(t)=2 \\times 1=2$이므로 조건을 만족시킨다. ($t=16$의 왼쪽에서 $g(t)$의 값은 $2$에 수렴하고, 오른쪽에서 $1$에 수렴해.) 따라서 $a=4$, $b=-2\\sqrt{2}$\n② $2^{a}=16$, $b^{2}=32$일 때, $k=16$이고 $\\lim_{t \\to 16-} g(t) \\times \\lim_{t \\to 16+} g(t)=3 \\times 2=6$이므로 조건을 만족시키지 않는다.\n③ $2^{a}=8$, $b^{2}=16$일 때, $k=8$이고 $\\lim_{t \\to 16-} g(t) \\times \\lim_{t \\to 16+} g(t)=2 \\times 1=2$이므로 조건을 만족시킨다. 따라서 $a=3$, $b=-4$\n④ $2^{a}=32$, $b^{2}=16$일 때, $k=16$이고 $\\lim_{t \\to 16-} g(t) \\times \\lim_{t \\to 16+} g(t)=3 \\times 2=6$이므로 조건을 만족시키지 않는다.\n(ii) $b>0$인 경우\n① $2^{a}=16$, $b^{2}=8$일 때, $k=8$이고 $\\left(y=\\left(x+2\\sqrt{2}\\right)^{2}\\right) \\lim_{t \\to 16-} g(t) \\times \\lim_{t \\to 16+} g(t)=2 \\times 1=2$이므로 조건을 만족시킨다. 따라서 $a=4$, $b=2\\sqrt{2}$\n② $2^{a}=16$, $b^{2}=32$일 때, $k=16$이고 $\\left(y=\\left(x+4\\sqrt{2}\\right)^{2}\\right) \\lim_{t \\to 16-} g(t) \\times \\lim_{t \\to 16+} g(t)=1 \\times 0=0$이므로 조건을 만족시키지 않는다.\n③ $2^{a}=8$, $b^{2}=16$일 때, $k=8$이고 함수 $f(x)$와 $g(t)$의 그래프를 그리면 다음과 같다.\n$(y=(x+4)^{2}) \\lim_{t \\to 16-} g(t) \\times \\lim_{t \\to 16+} g(t)=0 \\times 1=0$이므로 조건을 만족시키지 않는다.\n④ $2^{a}=32$, $b^{2}=16$일 때, $k=16$이고 $(y=(x+4)^{2}) \\lim_{t \\to 16-} g(t) \\times \\lim_{t \\to 16+} g(t)=1 \\times 2=2$이므로 조건을 만족시킨다. 따라서 $a=5$, $b=4$\n2nd 가능한 경우의 순서쌍 $(a, b)$를 구하고 $a+b$의 최댓값과 최솟값의 곱을 구해.\n(i), (ii)에 의하여 두 실수 $a$, $b$의 순서쌍은 $\\left(4, -2\\sqrt{2}\\right)$, $(3, -4)$, $\\left(4, 2\\sqrt{2}\\right)$, $(5, 4)$이고 $a+b$의 값은 $4-2\\sqrt{2}$, $-1$, $4+2\\sqrt{2}$, $9$이다.\n따라서 $a+b$의 최댓값은 $9$, 최솟값은 $-1$이므로 그 곱은 $9 \\times (-1)=-9$ ($2<2\\sqrt{2}<3$이므로 $4-2\\sqrt{2}$는 $1$보다 크고 $2$보다 작은 값이고, $4+2\\sqrt{2}$는 $6$보다 크고 $7$보다 작은 값이야. 따라서 최댓값은 $9$, 최솟값은 $-1$이 돼.)", "img": "IMG_4972.jpg, IMG_4973.jpg", "note": "(경미) 1st 보충 설명의 'y축에 평행한 직선을 그려 보면'은 직선 y=t(x축에 평행한 직선)를 뜻하므로 'x축에 평행한 직선'이 맞다. 책(사진) 원문의 오타이며, 풀이와 정답(③, -9)은 맞다.", "answer_value": "$-9$"}, {"id": "A220", "section": "A", "num": 220, "page": 68, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "16", "rate": "36%", "problem": "상수항과 계수가 모두 음이 아닌 정수인 두 다항함수 $f(x)$, $g(x)$가 다음 조건을 만족시킬 때, $f(2)+g(2)$의 값을 구하시오. (4점) (가) $\\lim_{x \\to \\infty} \\{f(x)\\}^{2} \\frac{g(x)}{x^{5}}=4$ (나) $\\lim_{x \\to 0} \\frac{f(x)\\{g(x)\\}^{2}}{x^{5}}=2$", "explanation": "정답 공식: $\\frac{\\infty}{\\infty}$ 꼴의 극한의 극한값이 존재하면 분모와 분자의 차수가 같아야 한다. $\\frac{0}{0}$ 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n단서1: 함수 $\\{f(x)\\}^{2} g(x)$의 차수가 $5$이고 최고차항의 계수는 $4$임을 알 수 있어.\n단서2: 함수 $f(x)\\{g(x)\\}^{2}$이 다항함수이므로 $f(0)\\{g(0)\\}^{2}=0$이고, 다항함수 $h(x)$에 대하여 $f(x)\\{g(x)\\}^{2}=x^{5} h(x)$, $h(0)=2$임을 알 수 있어.\n1st 조건 (가)와 (나)를 모두 만족시키는 두 다항함수 $f(x)$와 $g(x)$의 차수를 각각 구해.\n조건 (가)에서 $\\lim_{x \\to \\infty} \\{f(x)\\}^{2} \\frac{g(x)}{x^{5}}=4$가 되려면 분모와 분자의 차수가 같아야 하므로 분자의 차수는 $5$가 되어야 한다. 즉, 함수 $\\{f(x)\\}^{2} g(x)$의 차수는 $5$이다.\n이때, 두 함수 $f(x)$, $g(x)$의 차수는 아래의 세 가지 경우가 될 수 있다.\n(i) $f(x)$: 상수함수, $g(x)$: 오차함수 (ii) $f(x)$: 일차함수, $g(x)$: 삼차함수 (iii) $f(x)$: 이차함수, $g(x)$: 일차함수\n한편, 조건 (나)에서 $\\lim_{x \\to 0} \\frac{f(x)\\{g(x)\\}^{2}}{x^{5}}=2$이고 $\\lim_{x \\to 0} x^{5}=0$이므로 $\\lim_{x \\to 0} f(x)\\{g(x)\\}^{2}=0$\n따라서 어떤 다항함수 $h(x)$에 대하여 $f(x)\\{g(x)\\}^{2}=x^{5} h(x) (h(0) \\ne 0)$라 할 수 있다.\n($f(x)\\{g(x)\\}^{2}=x^{k} h(x)$ ($k$는 자연수)라 하면 $k<5$일 때 극한값이 존재하지 않아. $k>5$일 때 극한값$=0 \\ne 2$이므로 성립하지 않아. 따라서 $k=5$가 되어야 해.)\n(i) $f(x)$: 상수함수, $g(x)$: 오차함수일 때, 다항식 $f(x)\\{g(x)\\}^{2}$에서 오직 $g(x)$만이 $x$를 인수로 가지므로 $x^{5} h(x)$를 만족시키지 않는다.\n(ii) $f(x)$: 일차함수, $g(x)$: 삼차함수일 때, $f(x)\\{g(x)\\}^{2}=x^{5} h(x)$를 만족시키기 위해서는 $f(x)=ax$, $g(x)=x^{2}(bx+c)$ (단, $a$, $b$, $c$는 음이 아닌 정수, $a \\ne 0$, $b \\ne 0$)\n(iii) $f(x)$: 이차함수, $g(x)$: 일차함수일 때, 다항식 $f(x)\\{g(x)\\}^{2}$의 차수가 $4$가 되므로 $x^{5} h(x)$를 만족시키지 않는다.\n(i), (ii), (iii)에 의하여 $f(x)=ax$, $g(x)=x^{2}(bx+c)$ (단, $a$, $b$, $c$는 음이 아닌 정수, $a \\ne 0$, $b \\ne 0$)\n2nd 조건 (가)와 (나)를 모두 만족시키는 두 함수 $f(x)$, $g(x)$를 각각 구해.\n조건 (가)에서 $\\lim_{x \\to \\infty} \\{f(x)\\}^{2} \\frac{g(x)}{x^{5}}=\\lim_{x \\to \\infty} (ax)^{2} \\frac{x^{2}(bx+c)}{x^{5}}=\\lim_{x \\to \\infty} a^{2} \\frac{x^{4}(bx+c)}{x^{5}}=\\lim_{x \\to \\infty} \\left(a^{2} b+a^{2} \\frac{c}{x}\\right)=a^{2} b=4$\n조건 (나)에서 $\\lim_{x \\to 0} \\frac{f(x)\\{g(x)\\}^{2}}{x^{5}}=\\lim_{x \\to 0} \\frac{ax\\{x^{2}(bx+c)\\}^{2}}{x^{5}}=\\lim_{x \\to 0} \\frac{ax^{5}(bx+c)^{2}}{x^{5}}=a \\lim_{x \\to 0} (bx+c)^{2}=ac^{2}=2$\n이때, $a^{2} b=4$, $ac^{2}=2$를 만족시키는 음이 아닌 세 정수 $a$, $b$, $c$는 $a=2$, $b=1$, $c=1$이다. ($a^{2} b=4$에서 $a=1$ 또는 $a=2$인데 $a=1$일 때 $ac^{2}=2$에서 $c^{2}=2$가 되므로 $c$가 음이 아닌 정수가 될 수 없어. 따라서 $a=2$이고 $a=2$를 대입하여 $b$, $c$의 값을 각각 구할 수 있어.)\n$\\therefore f(x)=2x$, $g(x)=x^{2}(x+1)$\n3rd $f(2)+g(2)$의 값을 구해.\n$\\therefore f(2)+g(2)=2 \\times 2+2^{2} \\times (2+1)=4+4 \\times 3=4+12=16$", "img": "IMG_4973.jpg"}, {"id": "A221", "section": "A", "num": 221, "page": 69, "topic": "새롭게 정의된 함수의 극한", "answer": "②", "rate": "31%", "problem": "이차함수 $f(x)=(x-k)^{2} (k>0)$이 있다. 양수 $a$에 대하여 함수 $g(x)= \\begin{cases} f(x) & (x \\le 3) \\\\ kf(x-a) & (x>3) \\end{cases}$이 다음 조건을 만족시킬 때, [보기]에서 옳은 것만을 있는 대로 고른 것은? (4점) (가) $\\lim_{x \\to 3} g(x)$가 존재한다. (나) 함수 $y=g(x)$의 그래프는 $x$축과 오직 한 점에서만 만난다. [보기] ㄱ. $f(1)=1$이면 $g(2)=0$이다. ㄴ. $g(k+a)<g(3)$ ㄷ. $(k-1)(k-2) \\ge 0$", "explanation": "정답 공식: 상수 $k$와 이차함수 $f(x)$에 대하여 $0<k<1$이면 곡선 $y=kf(x)$의 폭은 곡선 $y=f(x)$의 폭보다 넓고, $k>1$이면 곡선 $y=kf(x)$의 폭은 곡선 $y=f(x)$의 폭보다 좁다.\n단서1: $y=kf(x-a)$의 그래프는 함수 $y=f(x)$의 그래프를 $x$축의 방향으로 $a$만큼 평행이동한 후 $k$배를 하면 돼.\n단서2: $x=3$에서의 좌극한값과 우극한값이 같아야 해.\n1st 조건을 만족시키는 함수 $y=g(x)$의 그래프를 찾아.\n조건 (가)를 만족시키려면 $\\lim_{x \\to 3-} g(x)=\\lim_{x \\to 3+} g(x)$이어야 한다.\n이때, $\\lim_{x \\to 3-} g(x)=\\lim_{x \\to 3-} f(x)=f(3)$ (이차함수 $f(x)$는 연속이므로 성립해), $\\lim_{x \\to 3+} g(x)=\\lim_{x \\to 3+} kf(x-a)=kf(3-a)$에서 $f(3)=kf(3-a)$이므로 $x=3$에서 두 함수 $y=f(x)$, $y=kf(x-a)$의 그래프는 만나야 한다. …㉠\n한편, 함수 $g(x)$는 $x=3$의 좌우에서 서로 다른 함수로 정의되어 있으므로 이차함수 $f(x)=(x-k)^{2}$에 대하여 $k>3$, $k=3$, $k<3$인 경우로 나누어 조건을 만족시키는 함수 $y=g(x)$의 그래프를 찾자.\n($f(x)=(x-k)^{2}$이므로 곡선 $y=f(x)$는 $x=k$에서 $x$축과 접하고 $kf(x-a)=k(x-a-k)^{2}$이므로 곡선 $y=kf(x-a)$는 $x=k+a$에서 $x$축과 접해.)\n(i) $k>3$일 때, ㉠을 만족시키도록 두 함수의 그래프를 그리면 [그림 1]과 같다. ($a$가 양수이므로 $k+a$가 $k$보다 오른쪽에 위치해.)\n이때, 이차함수 $f(x)$의 이차항의 계수는 $1$, 이차함수 $kf(x-a)$의 이차항의 계수는 $k$이므로 [그림 1]과 같이 함수 $y=kf(x-a)$의 그래프의 폭이 함수 $y=f(x)$의 그래프의 폭보다 넓으려면 $0<k<1$이어야 한다. 이것은 $k>3$에 모순이므로 이때의 조건 (가)를 만족시키는 함수 $y=g(x)$는 존재하지 않는다.\n(ii) $k=3$일 때, $g(x)= \\begin{cases} (x-3)^{2} & (x \\le 3) \\\\ 3(x-a-3)^{2} & (x>3) \\end{cases}$이므로\n$\\lim_{x \\to 3-} g(x)=\\lim_{x \\to 3-} (x-3)^{2}=0$, $\\lim_{x \\to 3+} g(x)=\\lim_{x \\to 3+} 3(x-a-3)^{2}=3a^{2}>0$ ($a>0$이므로)\n즉, $\\lim_{x \\to 3-} g(x) \\ne \\lim_{x \\to 3+} g(x)$이므로 조건 (가)를 만족시키지 않는다.\n(iii) $k<3$일 때, $k+a>3$, $k+a=3$, $k+a<3$인 경우로 나누면\ni) $k+a>3$인 경우, ㉠을 만족시키도록 그래프를 그리면 [그림 2]와 같다. 그런데 이때의 함수 $y=g(x)$의 그래프는 $x$축과 서로 다른 두 점에서 만나므로 조건 (나)를 만족시키지 않는다.\nii) $k+a=3$인 경우, $\\lim_{x \\to 3-} g(x)=f(3)>0$ ($k<3$이고 $f(k)=0$이므로 $f(3)>0$이야), $\\lim_{x \\to 3+} g(x)=\\lim_{x \\to 3+} k(x-a-k)^{2}=k(3-a-k)^{2}=k(3-3)^{2}=0$ ($k+a=3$이므로 $-a-k=-3$)\n즉, $\\lim_{x \\to 3-} g(x) \\ne \\lim_{x \\to 3+} g(x)$이므로 조건 (가)를 만족시키지 않는다.\niii) $k+a<3$인 경우, ㉠을 만족시키도록 그래프를 그리면 [그림 3]과 같다. 이것은 두 조건 (가), (나)를 모두 만족시킨다.\n(i)~(iii)에 의하여 조건을 만족시키는 함수 $y=g(x)$의 그래프는 [그림 4]와 같고 $k<k+a<3$이다. …㉡\n2nd ㄱ, ㄴ, ㄷ의 참, 거짓을 확인해.\nㄱ. $f(1)=(1-k)^{2}=1$에서 $1-k= \\pm 1 \\therefore k=2 (\\because k>0)$\n따라서 $f(x)=(x-2)^{2}$이므로 $g(2)=f(2)=(2-2)^{2}=0$ (참) ($x \\le 3$에서 $g(x)=f(x)$지?)\nㄴ. [그림 4]에 의하여 $g(k+a)<g(3)$ (참)\nㄷ. 두 함수 $y=f(x)$, $y=kf(x-a)$의 그래프는 [그림 3]과 같고 함수 $y=f(x)$의 그래프의 폭이 함수 $y=kf(x-a)$의 그래프의 폭보다 넓으므로 $k>1$이다. 이때, ㉡에서 $k<3$이므로 조건을 만족시키는 $k$의 값의 범위는 $1<k<3 \\cdots$㉢이다.\n한편, $(k-1)(k-2) \\ge 0$에서 $k \\le 1$ 또는 $k \\ge 2$이고 이것은 ㉢을 만족시키지 않는다. (거짓)\n따라서 옳은 것은 ㄱ, ㄴ이다.\n수능 핵강 - ㄷ이 거짓임을 반례로 확인하기: $1<k<3$을 만족시키는 $k$의 값 중 $k \\le 1$ 또는 $k \\ge 2$를 만족시키지 않는 $k$의 값을 반례로 잡자.\n$k=\\frac{3}{2}$일 때, $g(x)= \\begin{cases} \\left(x-\\frac{3}{2}\\right)^{2} & (x \\le 3) \\\\ \\frac{3}{2}\\left(x-a-\\frac{3}{2}\\right)^{2} & (x>3) \\end{cases}$이므로\n$\\lim_{x \\to 3-} g(x)=\\left(3-\\frac{3}{2}\\right)^{2}=\\frac{9}{4}$이고 $\\lim_{x \\to 3+} g(x)=\\frac{3}{2}\\left(3-a-\\frac{3}{2}\\right)^{2}=\\frac{3}{2}\\left(\\frac{3}{2}-a\\right)^{2}$\n조건 (가)를 만족시키려면 $\\frac{9}{4}=\\frac{3}{2}\\left(\\frac{3}{2}-a\\right)^{2}$에서 $\\frac{3}{2}=\\left(\\frac{3}{2}-a\\right)^{2}$, $\\frac{3}{2}-a= \\pm \\frac{\\sqrt{6}}{2} \\therefore a=\\frac{3 \\pm \\sqrt{6}}{2}$\n그런데 $k<k+a<3$에서 $\\frac{3}{2}+a<3$, 즉 $a<\\frac{3}{2}$이어야 하므로 $a=\\frac{3-\\sqrt{6}}{2}$이야.\n$\\therefore g(x)= \\begin{cases} \\left(x-\\frac{3}{2}\\right)^{2} & (x \\le 3) \\\\ \\frac{3}{2}\\left(x-3+\\frac{\\sqrt{6}}{2}\\right)^{2} & (x>3) \\end{cases}$ 이 함수 $g(x)$는 두 조건 (가), (나)를 모두 만족시키고 $(k-1)(k-2)=\\left(\\frac{3}{2}-1\\right)\\left(\\frac{3}{2}-2\\right)=\\frac{1}{2} \\times \\left(-\\frac{1}{2}\\right)=-\\frac{1}{4}<0$이므로 ㄷ은 거짓이야.", "img": "IMG_4974.jpg, IMG_4975.jpg", "answer_value": "ㄱ, ㄴ"}, {"id": "A222", "section": "A", "num": 222, "page": 70, "topic": "넓이에 대한 극한의 활용", "answer": "②", "rate": "30%", "problem": "그림과 같이 좌표평면 위의 점 $A(0, 1)$을 지나고 $x$축에 접하는 원 $C$가 있다. 원 $C$가 $y$축과 만나는 또 다른 점을 $P$라 하고, $x$축과 접하는 점을 $Q(t, 0)$이라 하자. 삼각형 $APQ$의 넓이를 $S(t)$, 원 $C$의 반지름의 길이를 $r(t)$라 할 때, $\\lim_{t \\to \\infty} \\frac{S(t)}{t \\times r(t)}$의 값은? (단, $t>1$이다.) (4점)", "explanation": "정답 공식: 넓이를 구하는 삼각형의 밑변과 높이를 $x$축 또는 $y$축과 평행하도록 잡아서 넓이를 $t$에 대하여 나타낸다.\n단서1: 원이 지나는 점이 주어졌으니까 원의 방정식에 대입하면 등식이 성립하겠지?\n단서2: 원이 $x$축과 접하게 되면 원의 반지름의 길이는 원의 중심의 $y$좌표의 절댓값과 같아.\n1st $x$축에 접하는 원의 반지름의 길이는 원의 중심의 $y$좌표의 절댓값과 같아.\n원 $C$는 $x$축 위의 점 $Q(t, 0)$과 접하고, 반지름의 길이가 $r(t)$이므로 원의 중심은 $(t, r(t))$이다.\n원 $C$의 방정식은 $(x-t)^{2}+\\{y-r(t)\\}^{2}=\\{r(t)\\}^{2} \\cdots$㉠\n([축에 접하는 원] 원 $(x-a)^{2}+(y-b)^{2}=r^{2}$에 대하여 (1) $x$축에 접하는 원: $r=|b|$ (2) $y$축에 접하는 원: $r=|a|$ (3) $x$축, $y$축에 접하는 원: $r=|a|=|b|$)\n2nd $S(t)$, $r(t)$를 $t$에 관한 식으로 나타내보자.\n원 $C$가 점 $A(0, 1)$을 지나므로 ㉠에 $x$ 대신 $0$, $y$ 대신 $1$을 대입하자.\n$(0-t)^{2}+\\{1-r(t)\\}^{2}=\\{r(t)\\}^{2}$, $t^{2}+1-2r(t)+\\{r(t)\\}^{2}=\\{r(t)\\}^{2} \\therefore r(t)=\\frac{t^{2}+1}{2} \\cdots$㉡\n한편, $S(t)=\\frac{1}{2} \\times AP \\times OQ=\\frac{1}{2} \\times AP \\times t$이므로 $AP$의 길이만 구하면 된다.\n그림과 같이 원의 중심 $(t, r(t))$에서 $AP$에 수선의 발 $H$를 내리면 $AH=OH-OA=r(t)-1 \\therefore AP=2AH=2\\{r(t)-1\\}$\n(주의: 원 위의 두 점과 원의 중심을 세 꼭짓점으로 하는 삼각형은 이등변삼각형이고 이등변삼각형의 꼭지각에서 밑변에 내린 수선은 밑변을 이등분해.)\n$\\therefore S(t)=\\frac{1}{2} \\times AP \\times t=\\frac{1}{2} \\times 2\\{r(t)-1\\} \\times t=t\\{r(t)-1\\}$\n이것에 ㉡을 대입하면 $S(t)=t\\left(\\frac{t^{2}+1}{2}-1\\right)=\\frac{t(t^{2}-1)}{2} \\cdots$㉢\n3rd ㉡, ㉢을 구하는 극한에 대입하자.\n$\\therefore \\lim_{t \\to \\infty} \\frac{S(t)}{t \\times r(t)}=\\lim_{t \\to \\infty} \\frac{\\frac{t(t^{2}-1)}{2}}{t \\times \\frac{t^{2}+1}{2}}=\\lim_{t \\to \\infty} \\frac{t^{3}-t}{t^{3}+t}=1$\n($\\frac{\\infty}{\\infty}$ 꼴의 극한값을 계산할 때, 분모, 분자의 차수가 같으니까 최고차항의 계수의 비로 구한 거야.)", "img": "IMG_4975.jpg", "answer_value": "$1$"}, {"id": "A223", "section": "A", "num": 223, "page": 71, "topic": "1등급 대비", "answer": "25", "rate": "12%", "problem": "최고차항의 계수가 양수인 이차함수 $f(x)$와 함수 $g(x)=\\frac{1}{3} x+a$에 대하여 함수 $h(x)= \\begin{cases} g(x)+f(x) & (f(x) \\ge g(x)) \\\\ g(x)-f(x) & (f(x)<g(x)) \\end{cases}$가 다음 조건을 만족시킨다. (가) $\\lim_{x \\to a-} h(x) \\ne \\lim_{x \\to a+} h(x)$를 만족시키는 실수 $a$의 값은 $2$뿐이다. (나) 모든 실수 $k$에 대하여 $\\lim_{x \\to k} |h(x)-1|$의 값이 존재한다. $h(0)=\\frac{7}{3}$일 때, $h(5)$의 값을 구하시오. (단, $a$는 상수이다.) (4점)", "explanation": "정답 공식: $\\lim_{x \\to 2-} h(x) \\ne \\lim_{x \\to 2+} h(x)$이므로 $\\lim_{x \\to \\beta-} h(x)=\\lim_{x \\to \\beta+} h(x)$인 $\\beta$를 이용하여 $a$의 값을 구하고 함수 $f(x)$, $g(x)$를 구한다.\n단서+발상 [유형 02+14]\n단서1: 함수 $h(x)$가 이차함수 $f(x)$와 일차함수 $g(x)$의 대소 관계를 통해 정의된다는 점에 주목한다. 함수 $f(x)$와 $g(x)$의 위치 관계를 확인하고 $h(x)$를 $x$의 값의 범위를 이용하여 정의할 수 있다. (이차함수 $f(x)$와 일차함수 $g(x)$의 위치 관계에 따라 함수 $h(x)$가 어떤 경우에 연속이 안 되는지 추론할 수 있어.)\n단서2: 정의된 함수 $h(x)$에서 조건 (가)를 이용하여 방정식 $f(x)=g(x)$의 서로 다른 두 실근을 $x_{1}$, $x_{2}$라 하면 $x_{1}=2$ 또는 $x_{2}=2$가 될 수 있다. (함수 $h(x)$의 극한값이 존재하지 않는 $x$의 값이 $2$뿐이므로 나머지 $x$의 값에서 극한이 존재한다는 것을 이용할 수 있어.)\n단서3: $x_{1}=2$인 경우와 $x_{2}=2$인 경우로 나누어 조건 (나)를 만족시키는 경우를 확인해 $g(2)$의 값을 구한다. ($2$ 이외의 $x$의 값에서 함수 $h(x)$의 극한이 존재한다는 것을 이용하여 조건 (나)의 식을 통해 미정계수를 알아낼 수 있어.)\n1st 함수 $f(x)$와 $g(x)$의 위치 관계를 알아내고 함수 $h(x)$를 $x$의 범위로 설정하여 정의해.\n모든 실수 $x$에 대하여 $f(x) \\ge g(x)$이면 $h(x)=g(x)+f(x)$이므로 조건 (가)를 만족시키지 않는다. (불연속이 되는 $x$의 값이 존재하지 않아.)\n따라서 두 함수 $f(x)$, $g(x)$의 그래프가 서로 다른 두 점에서 만난다.\n방정식 $f(x)=g(x)$의 서로 다른 두 실근을 $x_{1}$, $x_{2} (x_{1}<x_{2})$라 하면 $x \\le x_{1}$일 때 $f(x) \\ge g(x)$, $x_{1}<x<x_{2}$일 때 $f(x)<g(x)$, $x \\ge x_{2}$일 때 $f(x) \\ge g(x)$를 만족시키므로 함수 $h(x)$를 다음과 같이 정의할 수 있다.\n$h(x)= \\begin{cases} g(x)+f(x) & (x \\le x_{1}\\text{ 또는 }x \\ge x_{2}) \\\\ g(x)-f(x) & (x_{1}<x<x_{2}) \\end{cases}$\n2nd 조건을 이용하여 방정식 $f(x)=g(x)$의 서로 다른 두 실근 $x_{1}$, $x_{2}$ 중 $2$가 되는 실근을 구해.\n한편, 함수 $h(x)$는 $x=x_{1}$과 $x=x_{2}$를 제외한 모든 실수에서 극한값을 가지므로 조건 (가)에 의하여 $x_{1}=2$ 또는 $x_{2}=2$이다. ($\\lim_{x \\to a-} h(x) \\ne \\lim_{x \\to a+} h(x)$인 $a$의 값이 $a=x_{1}$인지 $a=x_{2}$인지 확인해야 해.)\n(i) $x_{1}=2$인 경우\n$\\lim_{x \\to x_{2}-} h(x) \\ne \\lim_{x \\to x_{2}+} h(x)$이면 조건 (가)에 모순이므로 $\\lim_{x \\to x_{2}-} h(x)=\\lim_{x \\to x_{2}+} h(x)$이다.\n$\\lim_{x \\to x_{2}-} h(x)=g(x_{2})-f(x_{2})=0$, $\\lim_{x \\to x_{2}+} h(x)=g(x_{2})+f(x_{2})=2g(x_{2})$이므로 $g(x_{2})=0$ ($x_{1}<x<x_{2}$일 때 $f(x)<g(x)$이므로 $h(x)=g(x)-f(x)$이고, $x \\ge x_{2}$일 때 $f(x) \\ge g(x)$이므로 $h(x)=g(x)+f(x)$야.)\n이때, 직선 $y=g(x)$의 기울기가 양수이므로 (기울기는 $\\frac{1}{3}$) $g(x_{1})=g(2)<0$이다.\n$\\lim_{x \\to x_{1}-} h(x)=g(x_{1})+f(x_{1})=2g(x_{1})=2g(2)$, $\\lim_{x \\to x_{1}+} h(x)=g(x_{1})-f(x_{1})=0$이므로\n(모든 실수 $k$에 대하여 $\\lim_{x \\to k} |h(x)-1|$의 값이 존재한다는 조건 (나)를 만족시켜야 해. 그런데 $\\lim_{x \\to x_{1}-} h(x) \\ne \\lim_{x \\to x_{1}+} h(x)$인 경우이므로 $\\lim_{x \\to x_{1}} |h(x)-1|$의 값이 존재하는지 확인해야 해.)\n$\\lim_{x \\to x_{1}-} |h(x)-1|=|2g(2)-1|>1$ ($g(x_{1})=g(2)<0$이므로 $2g(2)-1<-1$이야. 따라서 $|2g(2)-1|>1$이 돼.), $\\lim_{x \\to x_{1}+} |h(x)-1|=|0-1|=1$\n$\\therefore \\lim_{x \\to x_{1}-} |h(x)-1| \\ne \\lim_{x \\to x_{1}+} |h(x)-1|$\n따라서 $\\lim_{x \\to x_{1}} |h(x)-1|$의 값이 존재하지 않으므로 조건 (나)를 만족시키지 않는다.\n(ii) $x_{2}=2$인 경우\n$\\lim_{x \\to x_{1}-} h(x) \\ne \\lim_{x \\to x_{1}+} h(x)$이면 조건 (가)에 모순이므로 $\\lim_{x \\to x_{1}-} h(x)=\\lim_{x \\to x_{1}+} h(x)$이다.\n$\\lim_{x \\to x_{1}-} h(x)=g(x_{1})+f(x_{1})=2g(x_{1})$, $\\lim_{x \\to x_{1}+} h(x)=g(x_{1})-f(x_{1})=0$이므로 $g(x_{1})=0$\n이때, 직선 $y=g(x)$의 기울기가 양수이므로 $g(x_{2})=g(2)>0$이다.\n$\\lim_{x \\to x_{2}-} h(x)=g(x_{2})-f(x_{2})=0$, $\\lim_{x \\to x_{2}+} h(x)=g(x_{2})+f(x_{2})=2g(x_{2})=2g(2)$이므로\n$\\lim_{x \\to x_{2}-} |h(x)-1|=|0-1|=1$, $\\lim_{x \\to x_{2}+} |h(x)-1|=|2g(2)-1|$\n조건 (나)에 의하여 $2g(2)-1= \\pm 1 \\therefore g(2)=0$ 또는 $g(2)=1$\n이때, $g(2)>0$이므로 $g(2)=1$\n(i), (ii)에 의하여 $x_{2}=2$이다.\n3rd $g(2)$의 값과 $h(0)=\\frac{7}{3}$을 이용하여 함수 $g(x)$와 $f(x)$를 구해.\n$g(2)=1$이므로 $g(2)=\\frac{2}{3}+a=1$에서 $a=\\frac{1}{3} \\therefore g(x)=\\frac{1}{3} x+\\frac{1}{3}$\n또, $g(x_{1})=0$이므로 $g(x_{1})=\\frac{1}{3} x_{1}+\\frac{1}{3}=0$에서 $x_{1}=-1$\n즉, $f(x_{1})=f(-1)=g(-1)=0$, $f(x_{2})=f(2)=g(2)=1$\n상수 $p$에 대하여 $f(x)-g(x)=p(x+1)(x-2) (p>0)$라 하면 $x_{1}<0<x_{2}$이므로 $h(0)=g(0)-f(0)=2p$ ($x_{1}=-1$, $x_{2}=2$이므로 $x_{1}<0<x_{2}$야.)\n$h(0)=\\frac{7}{3}$이므로 $2p=\\frac{7}{3}$에서 $p=\\frac{7}{6} \\therefore f(x)=\\frac{7}{6}(x+1)(x-2)+g(x)$\n4th $h(5)$의 값을 구해.\n$x_{2}<5$이고 $g(5)=\\frac{5}{3}+\\frac{1}{3}=2$이므로 $h(5)=g(5)+f(5)=g(5)+21+g(5)=2+21+2=25$\n1등급 대비 특강 - 극한값의 존재: 문제의 조건을 통해 $h(x)$는 $x=2$에서만 극한값이 존재하지 않고, $|h(x)-1|$은 실수 전체에서 극한값이 존재함을 알 수 있어. 따라서 $x \\ne 2$인 모든 $x$에서 $h(x)$가 극한값을 가지므로 $|h(x)-1|$에서도 극한값을 가짐을 어렵지 않게 알 수 있어. 한편, $\\lim_{x \\to 2-} h(x)=0$이고 $\\lim_{x \\to 2+} h(x)=2g(2)>0$이므로 $x=2$에서도 $|h(x)-1|$의 극한값이 존재하기 위해서는 $1=|2g(2)-1|$을 만족해야 하고, $g(2)>0$이므로 $g(2)=1$이 됨을 알 수 있어.\nMy Top Secret (서울대 선배의 1등급 대비 전략): 이 문제처럼 새롭게 정의된 함수를 다루는 문제를 풀 때, 주어진 조건들을 모두 만족시킬 수 있는 그래프의 개형을 한번 그려봐. 그래프의 개형을 그리며 문제의 상황을 차분하게 정리하는 것이 처음부터 계산하는 것보다 더 큰 도움이 되기도 해.", "img": "IMG_4976.jpg, IMG_4977.jpg"}, {"id": "A224", "section": "A", "num": 224, "page": 72, "topic": "새롭게 정의된 함수의 극한 [유형 14] (2등급 대비)", "answer": "①", "rate": "15%", "problem": "두 자연수 $a$, $b$에 대하여 함수 $f(x)$는 $f(x)= \\begin{cases} 2x^{3}-6x+1 & (x \\le 2) \\\\ a(x-2)(x-b)+9 & (x>2) \\end{cases}$이다. 실수 $t$에 대하여 함수 $y=f(x)$의 그래프와 직선 $y=t$가 만나는 점의 개수를 $g(t)$라 하자. $g(k)+\\lim_{t \\to k-} g(t)+\\lim_{t \\to k+} g(t)=9$를 만족시키는 실수 $k$의 개수가 $1$이 되도록 하는 두 자연수 $a$, $b$의 순서쌍 $(a, b)$에 대하여 $a+b$의 최댓값은? (4점)", "explanation": "2등급? $x>2$에서 함수 $f(x)$가 확정되지 않은 상황인데 주어진 극한 조건을 통해 가능한 함수 $f(x)$의 그래프의 개형들 중 조건을 모두 만족시키는 상황을 추론하고, 그 중 $a+b$가 최대가 되도록 하는 가능한 순서쌍 $(a, b)$를 구해야 하는, 따져 주어야 할 것이 많은 문제였다.\n단서+발상 [유형 14]\n단서1: $x>2$에서 함수 $f(x)$는 최고차항의 계수가 $a$인 이차함수이고 그 그래프는 점 $(2, 9)$를 항상 지난다는 것을 알 수 있다. 이때, $a$, $b$는 자연수이므로 $f(x)$의 $x>2$에서의 개형은 $b \\le 2$인 경우와 $b>2$인 경우에 따라 달라진다는 것을 알 수 있다. ($x>2$에서 두 점 $(2, 9)$와 $(b, 9)$를 지나는 이차함수의 그래프를 생각해 봐.)\n단서2: 가능한 함수 $f(x)$의 그래프의 개형들에서 $g(t)$를 파악하여 $g(k)+\\lim_{t \\to k-} g(t)+\\lim_{t \\to k+} g(t)=9$가 되도록 하는 실수 $k$가 $1$개만 존재하도록 하는 개형을 찾으면 된다. ($x=k$에서의 함숫값, 좌극한값, 우극한값을 다 따로 따져서 그 합이 $9$가 되는 경우를 찾아.)\n주의: $a(b-2)^{2}=48$를 만족시키는 순서쌍 $(a, b)$를 구할 때 이 방정식은 $b>2$인 경우에서 나왔으므로 순서쌍 $(48, 1)$은 포함하지 않아야 한다.\n핵심 정답 공식: $\\lim_{t \\to k-} g(k)$의 의미는 함수 $y=f(x)$의 그래프와 직선 $y=k$보다 아주 조금 아래 있는 직선과 만나는 점의 개수이고, $\\lim_{t \\to k+} g(k)$의 의미는 함수 $y=f(x)$의 그래프와 직선 $y=k$보다 아주 조금 위에 있는 직선과 만나는 점의 개수이다.\n1st $x \\le 2$일 때 삼차함수 $f(x)$의 그래프의 개형을 알아보자.\n$x \\le 2$일 때, 삼차함수 $f(x)=2x^{3}-6x+1$에 대하여 $f'(x)=6x^{2}-6=6(x^{2}-1)=6(x-1)(x+1)$이므로 $f'(x)=0$에서 $x=-1$ 또는 $x=1$이다.\n함수 $f(x)$의 증가와 감소를 표로 나타내면: $x<-1$에서 $f'(x)>0$ 증가, $x=-1$에서 극대, $-1<x<1$에서 감소, $x=1$에서 극소, $1<x<2$에서 증가, $f(2)=5$\n$x>2$일 때, 이차함수 $f(x)=a(x-2)(x-b)+9$의 그래프는 두 점 $(2, 9)$와 $(b, 9)$를 지나고, $a>0$ ($\\because a$가 자연수)이므로 아래로 볼록한 그래프이다. 또한, 직선 $x=2$와 비교하여 이차함수 $f(x)$의 그래프의 대칭축 $x=1+\\frac{b}{2}$의 위치에 따라 함수 $f(x)$의 개형은 다음 $2$가지 경우가 있다. (이차함수 $y=f(x)$의 $y$절편의 값이 같은 두 점 $(a, c)$, $(b, c)$를 알면 함수 $f(x)$의 대칭축은 $x=\\frac{a+b}{2}$야.)\n(i) 대칭축이 $x=2$ 이하인 경우의 개형: [그림 1] (ii) 대칭축이 $x=2$보다 오른쪽인 경우의 개형: [그림 2] (극솟값 $m$)\n2nd 이차함수 $f(x)$가 지나는 두 점 $(2, 9)$와 $(b, 9)$ 중 $b$의 값에 따라 함수 $g(t)$를 예상해 보자.\n(i) 함수 $f(x)$의 그래프의 대칭축이 $x=2$이거나 $x=2$보다 왼쪽에 위치한 경우\n$1+\\frac{b}{2} \\le 2 \\therefore b \\le 2$. $b$는 자연수이므로 $b=1$ 또는 $b=2$이다.\n$x>2$에서 함수 $f(x)$는 증가하므로 그 그래프는 [그림 1]과 같다.\n이때, $-3<k<5$인 모든 실수 $k$에 대하여 $g(k)=3$, $\\lim_{t \\to k-} g(t)=3$, $\\lim_{t \\to k+} g(t)=3 \\cdots$㉠이므로\n$g(k)+\\lim_{t \\to k-} g(t)+\\lim_{t \\to k+} g(t)=9 \\cdots(*)$를 만족시키는 실수 $k$의 개수가 $1$이 아니다.\n(ii) 함수 $f(x)$의 그래프의 대칭축이 $x=2$보다 오른쪽에 위치한 경우\n$1+\\frac{b}{2}>2 \\therefore b>2$\n함수 $f(x)$의 그래프는 직선 $x=1+\\frac{b}{2}$에 대하여 대칭이므로 함수 $f(x)$는 $x=1+\\frac{b}{2}$에서 극솟값을 갖는다. 이 극솟값을 $m$이라 하자.\n① $m>-3$인 경우: $m$과 $5$ 중 크지 않은 값을 $m_{1}$이라 하면 $-3<k<m_{1}$인 모든 실수 $k$에 대하여 ㉠이 성립하므로 $(*)$을 만족시키는 실수 $k$의 개수가 $1$이 아니다.\n② $m<-3$인 경우: $m<k<-3$인 모든 실수 $k$에 대하여 ㉠이 성립하므로 $(*)$을 만족시키는 실수 $k$의 개수가 $1$이 아니다.\n③ $m=-3$인 경우: $k$의 값에 따라 $g(k)$, $\\lim_{t \\to k-} g(t)$, $\\lim_{t \\to k+} g(t)$의 값을 각각 구해 보자.\n$k$의 값에 따른 표: $k<-3$: $g(k)=1$, 좌극한 $1$, 우극한 $1$ / $k=-3$: $3$, $1$, $5$ / $-3<k<5$: $5$, $5$, $5$ / $k=5$: $4$, $5$, $2$ / $5<k<9$: $2$, $2$, $2$ / $k=9$: $1$, $2$, $1$ / $k>9$: $1$, $1$, $1$\n즉, $(*)$를 만족시키는 실수 $k$의 값은 $-3$뿐이다.\n(i), (ii)에 의하여 $b>2$, $m=-3$이다.\n$f\\left(1+\\frac{b}{2}\\right)=-3$에서 $a\\left(\\frac{b}{2}-1\\right)\\left(1-\\frac{b}{2}\\right)+9=-3$, $a\\left(\\frac{b}{2}-1\\right)^{2}=12$, $a(b-2)^{2}=48$\n$48=2^{4} \\times 3$이므로 구하는 두 자연수 $a$, $b$의 모든 순서쌍 $(a, b)$는 $(48, 3)$, $(12, 4)$, $(3, 6)$이다.\n따라서 $a+b$의 최댓값은 $48+3=51$이다.\n변준서(건국대 수의예과 2024년 입학) 선배의 조언: 문제에서 '두 자연수 $a$, $b$'같이 특수한 조건들은 동그라미 쳐서 표시했지? 이런 문제에서 그래프를 그리는 게 당연하지는 않지만 그래도 직관적으로 파악할 수 있기 때문에 그리기 쉽다면 바로 그려봐. $x>2$에서의 최고차항의 계수 $a$가 양수인 것을 자연수라는 조건 때문에 파악할 수 있었어. 하지만 이차함수의 그래프의 꼭짓점의 위치를 모르니까 함수를 단정적으로 그릴 수는 없더라고. 대략적으로 그려나가면서 조건을 충족시키도록 계속 변신시켜 나가야 해. 한번에 예쁘게 그리는 것보다는 전체적인 모양을 파악한 뒤, 수정해 나갈 수 있다는 것이 엄청 중요한 것 같아. 그리고 극한값을 생각하기 편하게 $t$보다 살짝 크거나 $t$보다 살짝 작은 값을 생각하며 $x$축에 평행한 직선 $y=t$를 그어 보면서 조건을 만족시키는 경우를 찾았던 것 같아. 아! 마지막에 정답 케이스를 찾았는데 부정방정식이 나와서 식겁했지만 처음의 자연수 조건 덕분에 문제없이 풀었던 것 같아.", "img": "IMG_4977.jpg, IMG_4978.jpg, IMG_4979.jpg", "note": "(경미) 핵심 정답 공식의 'lim_{t→k-} g(k)', 'lim_{t→k+} g(k)'는 g(t)로 써야 하고, 대칭축 보충 설명의 'y절편의 값이 같은 두 점 (a,c),(b,c)'는 '함숫값(y좌표)이 같은 두 점'이 맞다. 둘 다 책 원문의 오타이며, 풀이와 정답(①, 51)은 맞다.", "answer_value": "$51$"}, {"id": "A225", "section": "A", "num": 225, "page": 74, "topic": "1등급 대비", "answer": "40", "rate": "19%", "problem": "최고차항의 계수가 양수인 이차함수 $f(x)$가 다음 조건을 만족시킨다. (가) $\\lim_{x \\to 0-} \\frac{\\sqrt{x^{2}}-f(x)}{x+f(x)} \\times \\lim_{x \\to 0+} \\frac{\\sqrt{x^{2}}-f(x)}{x+f(x)}=-2$ (나) $\\lim_{x \\to a} \\frac{f(x-4)f(x+1)}{\\sqrt{x^{2}}-3}$의 값이 존재하지 않는 실수 $a$의 개수는 $1$이다. $f(24)$의 값을 구하시오. (4점)", "explanation": "정답 공식: 실수 $a$와 두 함수 $f(x)$, $g(x)$에 대하여 $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=a$ ($a$는 상수)일 때, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이다.\n단서+발상 [유형 01+16]\n단서1: $f(x)$는 최고차항의 계수가 양수인 이차함수이므로 모든 점에서 극한값이 존재하고, $f(x)=px^{2}+qx+r (p>0)$의 형태로 놓을 수 있다.\n단서2: $x \\to 0-$일 때, $x<0$이므로 $\\sqrt{x^{2}}=|x|=-x$이고 $x \\to 0+$일 때, $x>0$이므로 $\\sqrt{x^{2}}=|x|=x$이다. 조건 (가)에서의 두 극한을 계산할 때, 이를 적용하여 식을 정리한 후 계산할 수 있다.\n단서3: 조건 (나)에 주어진 극한이 존재하지 않도록 하는 실수 $a$의 값은 분모가 $0$이 되도록 하는 경우이다. $\\lim_{x \\to a} \\left(\\sqrt{x^{2}}-3\\right)=0$, $\\sqrt{a^{2}}-3=0$, 즉 $|a|=3$인 경우이다. 실수 $a$의 개수가 $1$이므로 $a=3$일 때와 $a=-3$일 때의 경우로 나누어 함수 $f(x)$를 구할 수 있다. ($f(x-4)f(x+1)$은 다항함수이므로 모든 점에서 극한값이 존재하는 함수야. 따라서 극한값이 존재하지 않는 실수 $a$가 될 수 있는 값은 분모를 $0$으로 만드는 $x=3$, $x=-3$뿐이야.)\n1st 조건 (가)를 이용하여 이차함수 $f(x)$의 식을 간단하게 나타내.\n조건 (가)에서 $\\lim_{x \\to 0-} \\frac{\\sqrt{x^{2}}-f(x)}{x+f(x)}=\\lim_{x \\to 0-} \\frac{-x-f(x)}{x+f(x)}=\\lim_{x \\to 0-} -\\frac{x+f(x)}{x+f(x)}=-1$ ($\\sqrt{x^{2}}=|x|$에서 $x \\to 0-$이므로 $x<0$이고 $|x|=-x$)\n$\\lim_{x \\to 0+} \\frac{\\sqrt{x^{2}}-f(x)}{x+f(x)}=\\lim_{x \\to 0+} \\frac{x-f(x)}{x+f(x)}$ ($x \\to 0+$이므로 $x>0$이고 $|x|=x$)\n$\\lim_{x \\to 0-} (\\cdots) \\times \\lim_{x \\to 0+} (\\cdots)=(-1) \\times \\lim_{x \\to 0+} \\frac{x-f(x)}{x+f(x)}=-2 \\therefore \\lim_{x \\to 0+} \\frac{x-f(x)}{x+f(x)}=2$\n세 상수 $p$, $q$, $r$에 대하여 $f(x)=px^{2}+qx+r (p>0)$라 하면 이것을 대입하면 $\\lim_{x \\to 0+} \\frac{-px^{2}-(q-1)x-r}{px^{2}+(q+1)x+r}=2$\n$r \\ne 0$일 때, $\\lim_{x \\to 0+} \\frac{-px^{2}-(q-1)x-r}{px^{2}+(q+1)x+r}=-\\frac{r}{r}=-1$, 즉 조건 (가)에 모순이므로 $r=0$이다. ($\\lim_{x \\to 0+} \\frac{x-f(x)}{x+f(x)}=2$에서 $f(0) \\ne 0$이면 극한값은 $-\\frac{f(0)}{f(0)}=-1$이므로 모순이야. 따라서 $f(0)=0$임을 알 수 있어.) $r=0$일 때, $\\lim_{x \\to 0+} \\frac{-px^{2}-(q-1)x}{px^{2}+(q+1)x} = \\lim_{x \\to 0+} \\frac{x\\{-px-(q-1)\\}}{x\\{px+(q+1)\\}} = \\lim_{x \\to 0+} \\frac{-px-(q-1)}{px+(q+1)} = \\frac{-q+1}{q+1} = 2$\n$-q+1=2q+2$, $-3q=1 \\therefore q=-\\frac{1}{3}$\n$\\therefore f(x)=px^{2}-\\frac{1}{3}x = x\\left(px-\\frac{1}{3}\\right)$\n2nd 가능한 경우의 실수 $a$의 값을 구해.\n조건 (나)에서 $\\lim_{x \\to a} \\left(\\sqrt{x^{2}}-3\\right) \\ne 0$이면 $\\lim_{x \\to a} \\frac{f(x-4)f(x+1)}{\\sqrt{x^{2}}-3}$의 값이 존재하므로, 값이 존재하지 않으려면 $\\lim_{x \\to a} \\left(\\sqrt{x^{2}}-3\\right)=0$이어야 한다.\n$\\lim_{x \\to a} \\left(\\sqrt{x^{2}}-3\\right)=\\sqrt{a^{2}}-3=0 \\left(\\sqrt{x^{2}}=|x|\\right)$, $|a|-3=0$, $|a|=3 \\therefore a=-3$ 또는 $a=3$\n3rd 조건 (나)를 만족시키는 이차함수 $f(x)$의 최고차항의 계수 $p$의 값을 구해.\n(i) 극한값이 존재하지 않는 실수 $a$가 $-3$일 때, $x=3$에서 극한값이 존재하고 $\\lim_{x \\to 3} \\left(\\sqrt{x^{2}}-3\\right)=0$이므로 (조건 (나)에서 극한값이 존재하지 않는 실수 $a$의 개수는 $1$이므로 $x=-3$에서 존재하지 않으면 $x=3$에서 존재해야 돼.)\n$\\lim_{x \\to 3} f(x-4)f(x+1)=f(-1) \\times f(4)=0$\n이것을 $f(x)=x\\left(px-\\frac{1}{3}\\right)$에 대입하면 $-\\left(-p-\\frac{1}{3}\\right) \\times 4\\left(4p-\\frac{1}{3}\\right)=0$, $4\\left(p+\\frac{1}{3}\\right)\\left(4p-\\frac{1}{3}\\right)=0 \\therefore p=-\\frac{1}{3}$ 또는 $p=\\frac{1}{12}$\n(ii) 극한값이 존재하지 않는 실수 $a$가 $3$일 때, $x=-3$에서 극한값이 존재하고 $\\lim_{x \\to -3} \\left(\\sqrt{x^{2}}-3\\right)=0$이므로\n$\\lim_{x \\to -3} f(x-4)f(x+1)=f(-7) \\times f(-2)=0$\n이것을 대입하면 $-7\\left(-7p-\\frac{1}{3}\\right) \\times (-2)\\left(-2p-\\frac{1}{3}\\right)=0$, $14\\left(7p+\\frac{1}{3}\\right)\\left(2p+\\frac{1}{3}\\right)=0 \\therefore p=-\\frac{1}{21}$ 또는 $p=-\\frac{1}{6}$\n이때 $p>0$이므로 (i), (ii)에 의하여 $p=\\frac{1}{12}$\n4th $f(24)$의 값을 구해.\n따라서 $f(x)=x\\left(\\frac{x}{12}-\\frac{1}{3}\\right)=\\frac{1}{12}x(x-4)$이므로 $f(24)=\\frac{1}{12} \\times 24 \\times (24-4)=2 \\times 20=40$\n[My Top Secret] $f(x)=0$인 $x$는 $0$ 또는 $\\frac{1}{3p}$인데 $p>0$이므로 방정식 $f(x)=0$는 음수인 실근을 가질 수 없어. 한편, 극한값이 존재하지 않는 실수 $a$가 $3$일 때, 즉 $x=-3$에서 극한값이 존재하면 조건 (나)의 극한이 수렴하기 위해서는 $f(-7) \\times f(-2)=0$이어야 해. 하지만 이는 모순이므로 상수 $p$의 값을 직접 구하지 않아도 해당 경우는 정답이 될 수 없음을 알 수 있어. 따라서 조건 (나)의 극한의 값이 존재하지 않는 실수 $a$는 $-3$이고 $x=3$에서 조건 (나)의 극한이 수렴한다는 것을 알 수 있어.\n[함수의 극한에 대한 성질] $\\lim_{x \\to a} f(x)=\\alpha$, $\\lim_{x \\to a} g(x)=\\beta$일 때 ① $\\lim cf(x)=c\\alpha$ ② $\\lim \\{f(x) \\pm g(x)\\}=\\alpha \\pm \\beta$ ③ $\\lim f(x)g(x)=\\alpha\\beta$ ④ $\\lim \\frac{f(x)}{g(x)}=\\frac{\\alpha}{\\beta} (g(x) \\ne 0, \\beta \\ne 0)$", "img": "IMG_4979.jpg,IMG_4980.jpg"}, {"id": "A226", "section": "A", "num": 226, "page": 76, "topic": "새로운 함수의 의미를 파악하고, 이를 주어진 조건과 연결지어 함수의 미정계수 구하기", "answer": "28", "rate": "11%", "problem": "세 실수 $a(a \\ne 0)$, $b$, $k$에 대하여 함수 $f(x)= \\begin{cases} ax^{2}+(2b-3)x+a^{2}-3 & (x<k) \\\\ -\\frac{1}{3}ax^{2}+(b+5)x+a^{2}-1 & (x \\ge k) \\end{cases}$ 라 하자. 함수 $g(x)=\\lim_{t \\to x+} \\frac{|f(t)|}{f(t)} - \\lim_{t \\to x-} \\frac{|f(t)|}{f(t)}$ 에 대하여 두 함수 $f(x)$, $g(x)$가 다음 조건을 만족시킨다. (가) 임의의 실수 $a$에 대하여 $\\lim_{x \\to a} f(x)$가 존재한다. (나) 두 함수 $y=g(x)$와 $y=-4\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|+2$의 그래프의 서로 다른 교점의 개수는 $5$이다. $k=p+q\\sqrt{17}$일 때, $16(p+q)$의 값을 구하시오. (단, $p$, $q$는 유리수이다.) (4점)", "explanation": "[유형 02+04+14] 새로운 함수의 의미를 파악하고, 이를 주어진 조건과 연결지어 함수의 미정계수 구하기 [1등급 대비]\n왜 1등급? $\\lim_{t \\to x+} \\frac{|f(t)|}{f(t)}$와 $\\lim_{t \\to x-} \\frac{|f(t)|}{f(t)}$의 의미를 이해하여 새로운 함수의 함숫값을 찾아내는 것이 키포인트. 절댓값 기호 안이 양수, $0$, 음수인 경우로 나눈 후 좌극한과 우극한의 개념을 정확히 적용하는 것이 어려웠다.\n단서1 $f(x)$는 $x=k$를 기준으로 식이 다른 두 이차함수로 정의되고, 최고차항의 계수가 $a$, $-\\frac{1}{3}a$로 부호가 다르므로 $y=f(x)$의 그래프는 아래로 볼록 ↔ 위로 볼록인 포물선으로 바뀌어 그려진다.\n단서2 $|A|=A(A>0)$, $0(A=0)$, $-A(A<0)$이므로 $f(x)>0$이면 $\\frac{|f(x)|}{f(x)}=1$, $f(x)<0$이면 $\\frac{|f(x)|}{f(x)}=-1$. 이를 이용해 $g(x)$의 함숫값을 구하고, $f(x)=0$이 되는 $x$의 좌우에서 부호 변화를 확인하여 경우를 나눈다.\n단서3 $y=\\log_{2} \\left(\\frac{x}{2}\\right)$의 그래프를 이용해 $y=-4\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|+2$의 그래프를 그린 후, $g(x)$의 함숫값을 통해 교점의 좌표를 구하면 $f(x)$의 미정계수를 구할 수 있다.\n단서4 임의의 실수에서 $f(x)$의 극한값이 존재하므로 $x=k$에서도 극한값이 존재해야 한다. 따라서 $x=k$를 두 이차함수의 식에 각각 대입했을 때 두 값이 같아야 한다.\n주의: $g(x)$가 가능한 함숫값은 $-2$, $0$, $2$뿐이다.\n핵심 정답 공식: 다항함수 $f(x)$에서 $f(\\alpha)=0$이고 $x=\\alpha$의 좌우에서 $f(x)$의 부호가 달라지면 $\\lim_{x \\to \\alpha+} \\frac{|f(x)|}{f(x)}$와 $\\lim_{x \\to \\alpha-} \\frac{|f(x)|}{f(x)}$는 절댓값은 $1$로 같고 부호는 서로 반대이다.\n1st 조건 (가)를 이용하여 함수 $g(x)$를 유추하자.\n$f_{1}(x)=ax^{2}+(2b-3)x+a^{2}-3$, $f_{2}(x)=-\\frac{1}{3}ax^{2}+(b+5)x+a^{2}-1$이라 하면 $f(x)=f_{1}(x)(x<k)$, $f_{2}(x)(x \\ge k)$. $a>0$이면 아래로 볼록 → 위로 볼록, $a<0$이면 위로 볼록 → 아래로 볼록인 모양.\n(i) $x=\\alpha$에서 $f(x)>0$ 또는 $f(x)<0$인 경우 ($x=\\alpha$ 좌우에서 부호가 바뀌지 않음): $f(x)>0$이면 $g(\\alpha)=1-1=0$, $f(x)<0$이면 $g(\\alpha)=-1-(-1)=0$. 따라서 $g(\\alpha)=0$.\n(ii) $f(\\alpha)=0$이고 $x=\\alpha$의 좌우에서 $f(x)$의 부호가 음$(-)$에서 양$(+)$으로 변하는 경우: $x>\\alpha$이면 $f(x)>0$, $x<\\alpha$이면 $f(x)<0$이므로 $\\lim_{t \\to \\alpha+} \\frac{|f(t)|}{f(t)}=1$, $\\lim_{t \\to \\alpha-} \\frac{|f(t)|}{f(t)}=-1$에서 $g(\\alpha)=1-(-1)=2$.\n(iii) $f(\\alpha)=0$이고 $x=\\alpha$의 좌우에서 $f(x)$의 부호가 양$(+)$에서 음$(-)$으로 변하는 경우: $x>\\alpha$이면 $f(x)<0$, $x<\\alpha$이면 $f(x)>0$이므로 $\\lim_{t \\to \\alpha+} \\frac{|f(t)|}{f(t)}=-1$, $\\lim_{t \\to \\alpha-} \\frac{|f(t)|}{f(t)}=1$에서 $g(\\alpha)=-1-1=-2$.\n(i), (ii), (iii)에 의하여 함수 $g(x)$의 함숫값은 $-2$, $0$, $2$ 중 하나이다.\n2nd $y=-4\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|+2$의 그래프를 그리고 $y=g(x)$의 그래프와의 교점의 좌표를 찾아보자.\n$y=\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|=|\\log_{2} x -1|$의 그래프는 [그림 1]과 같고($x=2$에서 $0$), 따라서 $y=-4\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|+2$의 그래프는 [그림 2]와 같다($x=2$에서 최댓값 $2$, $x=\\sqrt{2}$, $2\\sqrt{2}$에서 $0$, $x=1$, $4$에서 $-2$).\n$g(x)$의 함숫값은 $-2$, $0$, $2$뿐이므로 교점의 $y$좌표는 $-2$, $0$, $2$만 가능하다.\n(1) $-4\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|+2=-2$: $\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|=1$에서 $\\frac{x}{2}=2 \\therefore x=4$, $\\frac{x}{2}=\\frac{1}{2} \\therefore x=1$\n(2) $-4\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|+2=0$: $\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|=\\frac{1}{2}$에서 $\\frac{x}{2}=\\sqrt{2} \\therefore x=2\\sqrt{2}$, $\\frac{x}{2}=\\frac{1}{\\sqrt{2}} \\therefore x=\\sqrt{2}$\n(3) $-4\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|+2=2$: $\\left|\\log_{2} \\left(\\frac{x}{2}\\right)\\right|=0$에서 $\\frac{x}{2}=1 \\therefore x=2$\n조건 (나)에서 교점의 개수가 $5$이므로 교점의 좌표는 $(1,-2)$, $\\left(\\sqrt{2},0\\right)$, $(2,2)$, $\\left(2\\sqrt{2},0\\right)$, $(4,-2)$이다.\n즉, $g(1)=g(4)=-2$, $g(2)=2$이므로 (ii), (iii)에 의해 $f(1)=f(2)=f(4)=0$이다.\n3rd $f(1)=f(2)=f(4)=0$임을 이용하여 함수 $f(x)$를 구하자.\n(주의: $x<k$일 때와 $x \\ge k$일 때 식이 다르므로 $k$의 값이 $1$, $2$, $4$를 기준으로 어떤 범위에 있는지 구분해야 한다.)\n$k \\le 1$이면 $f_{2}(1)=f_{2}(2)=f_{2}(4)=0$이어야 하는데 $f_{2}(x)$는 이차함수이므로 성립하지 않는다. $k>4$이면 $f_{1}(1)=f_{1}(2)=f_{1}(4)=0$이어야 하는데 $f_{1}(x)$도 이차함수이므로 성립하지 않는다. (이차함수에서 어떤 함숫값을 갖는 서로 다른 $x$의 값은 최대 $2$개)\n따라서 $1<k \\le 4$이므로 $f(1)=f_{1}(1)$, $f(4)=f_{2}(4) \\cdots$㉠\n$a<0$이면 $y=f_{1}(x)$는 위로 볼록, $y=f_{2}(x)$는 아래로 볼록이므로 $f_{1}(1)=f_{2}(4)=0$이면서 $g(1)=g(4)=-2$를 만족시키는 그래프의 개형은 [그림 3]과 같다. 그런데 이 경우 $f_{1}(2) \\ne 0$이고 $f_{2}(2) \\ne 0$이므로 $f(2)=0$이 성립하지 않는다. 따라서 $a>0$이어야 한다.\n㉠에 의하여 $f(1)=f_{1}(1)=a+2b-3+a^{2}-3=0$이므로 $a^{2}+a+2b-6=0 \\cdots$㉡\n$f(4)=f_{2}(4)=-\\frac{16}{3}a+4b+20+a^{2}-1=0$이므로 $a^{2}-\\frac{16}{3}a+4b+19=0 \\cdots$㉢\n㉡$\\times 2-$㉢을 하면 $a^{2}+\\frac{22}{3}a-31=0$, $3a^{2}+22a-93=0$, $(3a+31)(a-3)=0 \\therefore a=3 (\\because a>0)$\n$a=3$을 ㉡에 대입하면 $9+3+2b-6=0$, $2b=-6 \\therefore b=-3$\n$\\therefore f(x)=\\begin{cases} 3x^{2}-9x+6 & (x<k) \\\\ -x^{2}+2x+8 & (x \\ge k) \\end{cases}$\n4th 조건 (가)를 이용하여 $k$의 값을 구하자.\n조건 (가)에 의하여 $x=k$에서 $\\lim_{x \\to k} f(x)$가 존재해야 하므로 $\\lim_{x \\to k-} f(x)=\\lim_{x \\to k+} f(x)$이어야 한다.\n즉, $\\lim_{x \\to k-} (3x^{2}-9x+6)=\\lim_{x \\to k+} (-x^{2}+2x+8)$에서 $3k^{2}-9k+6=-k^{2}+2k+8$, $4k^{2}-11k-2=0$\n$\\therefore k=\\frac{11 \\pm 3\\sqrt{17}}{8}$ ($\\sqrt{17}=4.1\\cdots$이므로 $\\frac{11+3\\sqrt{17}}{8}=2.9\\cdots$, $\\frac{11-3\\sqrt{17}}{8}=-0.1\\cdots$)\n그런데 $1<k \\le 4$이므로 $k=\\frac{11+3\\sqrt{17}}{8}$이다.\n따라서 $p=\\frac{11}{8}$, $q=\\frac{3}{8}$이므로 $16(p+q)=16 \\times \\left(\\frac{11}{8}+\\frac{3}{8}\\right)=16 \\times \\frac{14}{8}=28$\n[1등급 대비 특강] $k=\\frac{11+3\\sqrt{17}}{8}=2.9\\cdots$이므로 $y=f(x)$의 그래프는 $x=1$, $2$에서 $x$축과 만나는 아래로 볼록한 포물선이 $x=k$에서 위로 볼록한 포물선으로 바뀌어 $x=4$에서 $x$축과 만나는 개형이다.\n[My Top Secret] 주어진 함수를 바탕으로 새로운 함수가 제시될 때에는 그 함수의 식이나 그래프가 의미하는 바를 우선 파악하려고 시도하는 것이 좋다. 절댓값 기호를 포함한 함수의 성질과 극한의 정의를 바탕으로 조건을 해석하는 내용이 최고난도로 종종 등장하므로, 개념에 필요한 정의, 증명, 그래프 등을 복합적으로 함께 정리해야 한다.", "img": "IMG_4981.jpg"}, {"id": "A227", "section": "A", "num": 227, "page": 78, "topic": "두 함수 f(x), g(x)의 극한값의 존재 유무와 함수 f(x)/g(x)의 극한값을 이용하여 f(x), g(x)의 미정계수 구하기", "answer": "4", "rate": "19%", "problem": "양수 $m$과 $0$이 아닌 실수 $a$에 대하여 두 함수 $f(x)= \\begin{cases} x^{2}+(a-1)x-a^{2}+2 & (x \\le 2m) \\\\ -3x+4a & (x>2m) \\end{cases}$, $g(x)= \\begin{cases} ax-a & (x \\le m+1) \\\\ x-a+1 & (x>m+1) \\end{cases}$ 이 다음 조건을 만족시킨다. (가) $\\lim_{x \\to \\alpha-} f(x) \\ne \\lim_{x \\to \\alpha+} f(x)$, $\\lim_{x \\to \\beta-} g(x) \\ne \\lim_{x \\to \\beta+} g(x)$인 실수 $\\alpha$, $\\beta$가 존재한다. (나) 모든 실수 $k$에 대하여 $\\lim_{x \\to k} \\frac{f(x)}{g(x)}$의 값이 존재한다. $m+g(a^{2})$의 값을 구하시오. (4점)", "explanation": "[유형 02+16] 두 함수 $f(x)$, $g(x)$의 극한값의 존재 유무와 함수 $\\frac{f(x)}{g(x)}$의 극한값을 이용하여 $f(x)$, $g(x)$의 미정계수 구하기 [2등급 대비]\n왜 2등급? 구간에 따라 다르게 정의된 두 함수의 극한값의 존재 유무를 이용하여 두 함수를 구하는 문제. $f(x)$, $g(x)$가 각각 극한값이 존재하지 않는 $x$의 값에 대하여 $\\frac{f(x)}{g(x)}$의 극한값이 존재함을 이용하여 미정계수를 구하는 것이 어려웠다.\n단서1 $f(x)$는 $x<2m$, $x>2m$에서 각각 다항함수이므로 이 범위의 모든 $x$에서 극한값이 존재한다. 마찬가지로 $g(x)$는 $x<m+1$, $x>m+1$에서 각각 다항함수이므로 극한값이 존재한다.\n단서2 조건 (가)에서 $f(x)$와 $g(x)$ 각각에서 극한값이 존재하지 않는 $x$의 값이 주어졌으므로 실수 $\\alpha$, $\\beta$를 $m$에 대한 식으로 나타낼 수 있다.\n단서3 조건 (나)에서 모든 실수 $k$에 대하여 $\\lim_{x \\to k} \\frac{f(x)}{g(x)}$의 값이 존재하므로 $k=2m$일 때 함수의 극한의 성질을 통해 $\\alpha$, $\\beta$ 사이의 관계식을 찾아낼 수 있고, 이를 통해 양수 $m$의 값을 구한다.\n주의: $\\lim_{x \\to k} \\frac{f(x)}{g(x)}$와 $\\lim_{x \\to k} g(x)$의 값이 존재하는 경우 함수의 극한의 성질을 이용해 $\\lim_{x \\to k} f(x)$의 값이 존재함을 확인할 수 있어야 한다.\n핵심 정답 공식: $x=k$에서의 좌극한과 우극한이 같을 때 $f(x)$의 $x=k$에서의 극한값이 존재하고, 그 역도 성립한다. 즉, $\\lim_{x \\to k+} f(x)=\\lim_{x \\to k-} f(x)=\\alpha \\Leftrightarrow \\lim_{x \\to k} f(x)=\\alpha$\n1st 문제의 조건을 만족시키는 $m$의 값을 구해.\n$f(x)$는 $x=2m$을 제외한 모든 실수에서 극한값을 가지므로($x<2m$에서 이차함수, $x>2m$에서 일차함수) 조건 (가)에서 $\\alpha=2m$이다. 즉, $\\lim_{x \\to 2m-} f(x) \\ne \\lim_{x \\to 2m+} f(x)$이다.\n또한 $g(x)$는 $x=m+1$을 제외한 모든 실수에서 극한값을 가지므로 조건 (가)에서 $\\beta=m+1$이다. 즉, $\\lim_{x \\to (m+1)-} g(x) \\ne \\lim_{x \\to (m+1)+} g(x)$이다.\n이때 $\\alpha \\ne \\beta$라 하면 $g(x)$는 $x=\\beta$에서만 극한값이 존재하지 않으므로 $x=\\alpha$에서는 극한값이 존재한다. 즉, $\\lim_{x \\to 2m} g(x)$의 값이 존재하고, 조건 (나)에 의해 $\\lim_{x \\to 2m} \\frac{f(x)}{g(x)}$의 값도 존재하므로\n$\\lim_{x \\to 2m} f(x)=\\lim_{x \\to 2m} \\left\\{\\frac{f(x)}{g(x)} \\times g(x)\\right\\} = \\lim_{x \\to 2m} \\frac{f(x)}{g(x)} \\times \\lim_{x \\to 2m} g(x)$에서 $\\lim_{x \\to 2m} f(x)$의 값도 존재한다.\n그런데 이는 $\\lim_{x \\to 2m-} f(x) \\ne \\lim_{x \\to 2m+} f(x)$라는 조건에 모순이다. 따라서 $\\alpha=\\beta$여야 하므로 $2m=m+1 \\therefore m=1$\n2nd 조건 (나)를 만족시키는 $a$의 값을 구해.\n$m=1$을 대입하면 $f(x)=\\begin{cases} x^{2}+(a-1)x-a^{2}+2 & (x \\le 2) \\\\ -3x+4a & (x>2) \\end{cases}$, $g(x)=\\begin{cases} ax-a & (x \\le 2) \\\\ x-a+1 & (x>2) \\end{cases}$이고, $x \\le 2$일 때 $g(x)=a(x-1)$이므로 $g(1)=0$이다.\n조건 (나)에 의해 $\\lim_{x \\to 1} \\frac{f(x)}{g(x)}=\\lim_{x \\to 1} \\frac{x^{2}+(a-1)x-a^{2}+2}{a(x-1)}$의 값이 존재하고 $\\lim_{x \\to 1} g(x)=g(1)=0$이므로 $\\lim_{x \\to 1} f(x)=0$이어야 한다.\n즉, $\\lim_{x \\to 1} \\{x^{2}+(a-1)x-a^{2}+2\\}=1+a-1-a^{2}+2=0$, $-a^{2}+a+2=0$, $-(a+1)(a-2)=0 \\therefore a=-1$ 또는 $a=2$\n이제 $x=2$에서 조건 (나)를 만족시키는 $a$의 값을 찾자.\n(i) $a=-1$인 경우: $f(x)=\\begin{cases} x^{2}-2x+1 & (x \\le 2) \\\\ -3x-4 & (x>2) \\end{cases}$, $g(x)=\\begin{cases} -x+1 & (x \\le 2) \\\\ x+2 & (x>2) \\end{cases}$이므로\n$\\lim_{x \\to 2-} \\frac{f(x)}{g(x)}=\\lim \\frac{x^{2}-2x+1}{-x+1}=\\frac{4-4+1}{-2+1}=-1$, $\\lim_{x \\to 2+} \\frac{f(x)}{g(x)}=\\lim \\frac{-3x-4}{x+2}=-\\frac{10}{4}=-\\frac{5}{2}$\n즉, 좌극한$\\ne$우극한이므로 조건 (나)를 만족시키지 않는다.\n(ii) $a=2$인 경우: $f(x)=\\begin{cases} x^{2}+x-2 & (x \\le 2) \\\\ -3x+8 & (x>2) \\end{cases}$, $g(x)=\\begin{cases} 2x-2 & (x \\le 2) \\\\ x-1 & (x>2) \\end{cases}$이므로\n$\\lim_{x \\to 2-} \\frac{f(x)}{g(x)}=\\frac{4+2-2}{4-2}=2$, $\\lim_{x \\to 2+} \\frac{f(x)}{g(x)}=\\frac{-6+8}{2-1}=2$\n즉, 좌극한=우극한이므로 조건 (나)를 만족시킨다.\n(i), (ii)에 의해 $a=2$이다.\n3rd $m+g(a^{2})$의 값을 구해.\n$a=2$에서 $g(x)=\\begin{cases} 2x-2 & (x \\le 2) \\\\ x-1 & (x>2) \\end{cases}$이므로 $g(a^{2})=g(4)=4-1=3 \\therefore m+g(a^{2})=1+3=4$\n[My Top Secret] $\\alpha \\ne \\beta$인 경우를 생각할 때, $y=g(x)$가 $x=\\beta$에서만 극한값이 존재하지 않는 함수이므로 $y=g(x)$가 $x=\\alpha$에서 극한값을 가진다는 사실을 빠르게 찾을 수 있다면 $\\alpha \\ne \\beta$인 경우의 모순을 쉽게 찾을 수 있다.", "img": "IMG_4983.jpg"}, {"id": "A228", "section": "A", "num": 228, "page": 79, "topic": "함수의 극한을 이용한 다항함수의 결정", "answer": "⑤", "rate": "18%", "problem": "최고차항의 계수가 $1$인 두 삼차함수 $f(x)$, $g(x)$가 다음 조건을 만족시킨다. (가) $g(1)=0$ (나) $\\lim_{x \\to n} \\frac{f(x)}{g(x)}=(n-1)(n-2) (n=1, 2, 3, 4) g(5)$의 값은? (4점)", "explanation": "[유형 16] 함수의 극한을 이용한 다항함수의 결정 [1등급 대비]\n왜 1등급? 함수의 극한의 성질을 이용하여 주어진 조건을 만족시키는 다항함수를 추론하는 문제. $x \\to a$일 때 분수 형태의 함수의 극한값이 존재하고 $x \\to a$일 때 (분모)$\\to 0$이면 (분자)$\\to 0$임을 적용하는 것이 어려웠다.\n단서1 $\\lim_{x \\to 1} \\frac{f(x)}{g(x)}=0$이고 $g(1)=0$이므로 $f(1)=0$이어야 해.\n단서2 $f(1)=0$, $g(1)=0$이므로 $f(x)=(x-1)(x-a)(x-b)$, $g(x)=(x-1)(x-c)(x-d)$로 놓을 수 있어.\n단서+발상: 먼저 조건 (나)의 식에 $n=1$, $n=2$를 차례로 대입하고 $g(1)=0$과 분수 꼴의 극한의 성질에 의하여 다항함수 $f(x)$가 갖는 인수를 찾아 $f(x)$의 식을 완성한다. 이제 $f(x)$와 $n=3$, $n=4$를 조건 (나)의 식에 차례로 대입하여 $g(x)$가 갖는 인수를 찾아 $g(x)$의 식을 완성하고 $g(5)$의 값을 구한다.\n주의: $\\lim_{x \\to a} \\frac{f(x)}{g(x)}=0$일 때, $\\lim_{x \\to a} g(x)=0$이면 $\\lim_{x \\to a} f(x)=0$이지만 $\\lim_{x \\to a} f(x)=0$이어도 꼭 $\\lim_{x \\to a} g(x)=0$인 것은 아니다.\n핵심 정답 공식: 분수 꼴의 극한의 극한값이 존재하고 $x \\to a$일 때, (분모)$\\to 0$이면 (분자)$\\to 0$이어야 한다.\n1st $n=1$, $2$일 때, 극한값이 존재하는 조건을 가지고 $f(x)$를 구해.\n조건 (나)에 $n=1$, $2$를 차례로 대입하면 $\\lim_{x \\to 1} \\frac{f(x)}{g(x)}=0 \\cdots$㉠, $\\lim_{x \\to 2} \\frac{f(x)}{g(x)}=0 \\cdots$㉡\n조건 (가)의 $g(1)=0$에서 $g(x)$는 $(x-1)$을 인수로 가지므로 ㉠이 성립하려면 $f(x)$도 $(x-1)$을 인수로 가져야 한다.\n$f(x)=(x-1)(x-a)(x-b)$, $g(x)=(x-1)(x-c)(x-d)$ ($a$, $b$, $c$, $d$는 상수)라 두고 ㉠에 대입하면 $\\lim_{x \\to 1} \\frac{(x-a)(x-b)}{(x-c)(x-d)}=0$\n극한값이 $0$이 되려면 $a$ 또는 $b$가 $1$이 되어야 한다. $a=1$이라 하면 $f(x)=(x-1)^{2}(x-b)$\n마찬가지로 ㉡에 대입하면 $f(x)$는 $(x-2)$를 인수로 가져야 하므로 $f(x)=(x-1)^{2}(x-2)$\n2nd $n=3$, $4$일 때, 주어진 극한값을 이용하여 $g(x)$를 구해.\n조건 (나)에 $n=3$, $4$를 대입하면 $\\lim_{x \\to 3} \\frac{f(x)}{g(x)}=2$, $\\lim_{x \\to 4} \\frac{f(x)}{g(x)}=6$이므로\n$\\lim_{x \\to 3} \\frac{(x-1)(x-2)}{(x-c)(x-d)} = 2 \\times \\frac{1}{(3-c)(3-d)}=2$에서 $(3-c)(3-d)=1$, $9-3(c+d)+cd=1 \\therefore 3(c+d)-cd=8 \\cdots$㉢\n$\\lim_{x \\to 4} \\frac{(x-1)(x-2)}{(x-c)(x-d)} = 3 \\times \\frac{2}{(4-c)(4-d)}=6$에서 $(4-c)(4-d)=1$, $16-4(c+d)+cd=1 \\therefore 4(c+d)-cd=15 \\cdots$㉣\n㉢, ㉣을 연립하면 $c+d=7$, $cd=13$ (㉣-㉢: $c+d=7$, ㉢에 대입하면 $21-cd=8$이므로 $cd=13$) (함정: $c$, $d$의 값을 각각 구하는 것보다 $c+d$, $cd$의 값을 구하여 이용하는 것이 효율적!)\n따라서 $g(x)=(x-1)(x-c)(x-d)$에 $x=5$를 대입하면 $g(5)=4(5-c)(5-d)=4\\{25-5(c+d)+cd\\}=4(25-5 \\times 7+13)=12$\n[1등급 대비 특강] 함수 $f(x)$가 $(x-1)^{2}$을 인수로 가지는 이유: $\\lim_{x \\to 0} \\frac{x^{2}}{x}=\\lim_{x \\to 0} x=0$에서 분모를 $0$으로 만드는 인자 $x$를 분모가 인수로 가지고 있으므로 극한값이 존재하려면 분자도 $x$를 인수로 가져야 하고, 극한값이 $0$이므로 분자는 최소 $x^{2}$을 인수로 가져야 한다. 따라서 자연수 $m$, $n$에 대하여 $\\lim_{x \\to 0} \\frac{x^{m}}{x^{n}}=0$이면 $m>n$이어야 한다. 이를 이용하면 $\\lim_{x \\to n} \\frac{f(x)}{g(x)}=0$이고 $g(x)$가 $(x-n)^{k}$을 인수로 가질 때 극한값이 $0$이려면 $f(x)$는 최소 $(x-n)^{k+1}$을 인수로 가져야 한다. 이 문제의 조건 (가)에서 $g(x)$가 $x-1$을 인수로 갖고 조건 (나)에서 $\\lim_{x \\to 1} \\frac{f(x)}{g(x)}=0$이므로 $f(x)$는 $(x-1)^{2}$을 인수로 가져야 한다.\n[My Top Secret] 함수의 극한이 수렴하는 조건을 묻는 문항이다. 분모가 $0$으로 가면 분자가 $0$으로 가야 하고, 분자가 $0$으로 가는데 극한값이 $0$이 아니면 분모가 $0$으로 가는 것을 잘 알아 두어야 한다. 분자가 $0$으로 가는데 극한값이 $0$이면 분모가 $0$으로 가는지는 알 수 없다.", "img": "IMG_4984.jpg", "answer_value": "$12$"}, {"id": "A229", "section": "A", "num": 229, "page": 80, "topic": "좌극한값과 우극한값에 대한 조건을 만족시키는 함수 찾기", "answer": "311", "rate": "9%", "problem": "두 양수 $a$, $b(a<b)$에 대하여 함수 $f(x)$는 $f(x)= \\begin{cases} |-ax^{2}+b| & (x \\le 0) \\\\ x^{2}-2ax+b^{2} & (x>0) \\end{cases}$ 이다. 양의 실수 $t$에 대하여 직선 $y=t$가 함수 $y=f(x)$의 그래프와 만나는 서로 다른 점의 개수를 $g(t)$라 하자. 함수 $g(t)$는 최솟값 $2$를 갖고, 두 상수 $\\alpha$, $\\beta$에 대하여 다음 조건을 만족시킨다. (가) $\\left|\\lim_{t \\to \\alpha-} g(t) - \\lim_{t \\to \\alpha+} g(t)\\right|=2$ (나) $\\lim_{t \\to \\beta-} g(t) - \\lim_{t \\to \\beta+} g(t)+1=g(\\beta)$ (다) $g(\\alpha) \\ne g(\\beta)$. $f\\left(\\frac{1}{2}\\right)=\\alpha$, $\\alpha+24\\beta=30$일 때, $f(-2)+f(1)=\\frac{q}{p}$이다. $p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수이다.) (4점)", "explanation": "[유형 01+14+16] 좌극한값과 우극한값에 대한 조건을 만족시키는 함수 찾기 [1등급 대비]\n왜 1등급? 함수의 극한의 성질을 이용해 조건을 해석하고, 대소 관계에 따라 나누어진 경우들 중 조건을 만족시키는 그래프를 찾는 문제. 여러 경우 중에서 세 조건 (가), (나), (다)를 모두 만족시키는 $y=f(x)$의 그래프의 개형을 찾는 과정이 까다로웠다.\n단서1 $\\left|\\lim_{t \\to \\alpha-} g(t)-\\lim_{t \\to \\alpha+} g(t)\\right|=2$에서 $t=\\alpha$에서의 좌극한값과 우극한값의 차가 $2$이므로 $t=\\alpha$에서 극한값이 존재하지 않는다는 것을 알 수 있다. ($t=\\alpha$에서 극한값이 존재하면 좌극한=우극한이므로 조건 (가)를 만족시키지 않아.)\n단서2 조건 (가)와 마찬가지로 $t=\\beta$에서 극한값이 존재하면 $g(\\beta)=1$이 돼. 그런데 $g(t)$의 최솟값이 $2$이므로 $t=\\beta$에서 극한값이 존재할 수 없어.\n단서2(발상) $t=\\beta$에서 극한값이 존재한다면 좌극한값과 우극한값이 일치하므로 $\\lim_{t \\to \\beta-} g(t)-\\lim_{t \\to \\beta+} g(t)=0$이다. 즉, 조건 (나)에 의하여 $g(\\beta)=1$이 되어야 하는데 이는 $g(t)$의 최솟값이 $2$인 조건에 맞지 않는다. 따라서 $t=\\beta$에서 극한값이 존재하지 않는다. 또한 $y=f(x)$의 그래프의 꼭짓점의 $y$좌표와 $y$절편의 대소 관계에 따라 경우를 나누어 세 조건 (가), (나), (다)를 모두 만족시키는 경우를 찾는다.\n주의: $y=f(x)$의 그래프의 꼭짓점과 $y$절편의 위치에 따라 직선 $y=t$와의 교점의 개수가 달라짐을 파악하고 $g(t)$를 구한다.\n핵심 정답 공식: $t=\\alpha$, $t=\\beta$에서 $g(t)$의 극한값이 존재하지 않으므로 $\\alpha$, $\\beta$의 값을 구할 때, 극한값이 존재하지 않는 점에서만 따져주면 된다.\n1st 함수 $y=f(x)$의 그래프의 개형을 알아봐.\n$y=-ax^{2}+b$의 그래프는 꼭짓점의 좌표가 $(0, b)$이고 위로 볼록한 곡선이므로 $x \\le 0$에서 $y=|-ax^{2}+b|$의 그래프는 $y<0$인 부분을 $x$축에 대하여 대칭이동한 모양이다.\n또, $y=x^{2}-2ax+b^{2}=(x-a)^{2}-a^{2}+b^{2}$이고 $a<b$에서 $a^{2}<b^{2}$이므로 $-a^{2}+b^{2}>0$. 따라서 $x>0$에서 그래프는 꼭짓점의 좌표가 $(a, b^{2}-a^{2})$이고 아래로 볼록한 곡선이다.\n2nd 경우에 따른 $g(t)$를 구하고 그 중 조건을 만족시키는 $g(t)$를 찾아.\n세 실수 $b$, $b^{2}$, $b^{2}-a^{2}$의 대소 관계에 따라 경우를 나누자.\n(i) $b^{2}-a^{2}<b^{2}<b$일 때: $g(t)=\\begin{cases} 2 & (0<t<b^{2}-a^{2}) \\\\ 3 & (t=b^{2}-a^{2}) \\\\ 4 & (b^{2}-a^{2}<t<b^{2}) \\\\ 3 & (b^{2} \\le t \\le b) \\\\ 2 & (t>b) \\end{cases}$. 최솟값 $2$ 조건은 만족. $\\lim_{t \\to (b^{2}-a^{2})-} g(t)=2$, $\\lim_{t \\to (b^{2}-a^{2})+} g(t)=4$, $\\lim_{t \\to b^{2}-} g(t)=4$, $\\lim_{t \\to b^{2}+} g(t)=3$, $\\lim_{t \\to b-} g(t)=3$, $\\lim_{t \\to b+} g(t)=2$이므로 $\\alpha=b^{2}-a^{2}$일 때 조건 (가)를 만족시키지만 조건 (나)를 만족시키는 $\\beta$의 값은 존재하지 않는다.\n(ii) $b^{2}-a^{2}<b^{2}=b$일 때: $g(t)=\\begin{cases} 2 & (0<t<b^{2}-a^{2}) \\\\ 3 & (t=b^{2}-a^{2}) \\\\ 4 & (b^{2}-a^{2}<t<b) \\\\ 3 & (t=b) \\\\ 2 & (t>b) \\end{cases}$. $\\lim_{t \\to (b^{2}-a^{2})-} g(t)=2$, $\\lim_{t \\to (b^{2}-a^{2})+} g(t)=4$, $\\lim_{t \\to b-} g(t)=4$, $\\lim_{t \\to b+} g(t)=2$이므로 $\\alpha=b^{2}-a^{2}$ 또는 $\\alpha=b$일 때 조건 (가)를 만족시키고, $\\beta=b$일 때 조건 (나)를 만족시키지만 $g(b^{2}-a^{2})=g(b)=3$이므로 조건 (다)를 만족시키지 않는다.\n(iii) $b^{2}-a^{2}<b<b^{2}$일 때: $g(t)=\\begin{cases} 2 & (0<t<b^{2}-a^{2}) \\\\ 3 & (t=b^{2}-a^{2}) \\\\ 4 & (b^{2}-a^{2}<t \\le b) \\\\ 3 & (b<t<b^{2}) \\\\ 2 & (t \\ge b^{2}) \\end{cases}$. $\\lim_{t \\to (b^{2}-a^{2})-} g(t)=2$, $\\lim_{t \\to (b^{2}-a^{2})+} g(t)=4$, $\\lim_{t \\to b-} g(t)=4$, $\\lim_{t \\to b+} g(t)=3$, $\\lim_{t \\to b^{2}-} g(t)=3$, $\\lim_{t \\to b^{2}+} g(t)=2$이므로 $\\alpha=b^{2}-a^{2}$일 때 조건 (가)를 만족시키고, $\\beta=b^{2}$일 때 조건 (나)를 만족시킨다. 또, $g(b^{2}-a^{2})=3$, $g(b^{2})=2$이므로 조건 (다)를 만족시킨다.\n(iv) $b^{2}-a^{2}=b<b^{2}$일 때: $g(t)=\\begin{cases} 2 & (0<t<b) \\\\ 3 & (b \\le t<b^{2}) \\\\ 2 & (t \\ge b^{2}) \\end{cases}$. 최솟값 $2$ 조건은 만족. $\\lim_{t \\to b-} g(t)=2$, $\\lim_{t \\to b+} g(t)=3$, $\\lim_{t \\to b^{2}-} g(t)=3$, $\\lim_{t \\to b^{2}+} g(t)=2$이므로 조건 (가)를 만족시키는 $\\alpha$의 값은 존재하지 않는다. ($\\beta=b^{2}$일 때 조건 (나)를 만족시키기는 해.)\n(v) $b<b^{2}-a^{2}<b^{2}$일 때: $g(t)=\\begin{cases} 2 & (0<t \\le b) \\\\ 1 & (b<t<b^{2}-a^{2}) \\\\ 2 & (t=b^{2}-a^{2}) \\\\ 3 & (b^{2}-a^{2}<t<b^{2}) \\\\ 2 & (t \\ge b^{2}) \\end{cases}$. 이때 $g(t)$의 최솟값은 $1$이므로 최솟값이 $2$라는 조건을 만족시키지 않는다.\n(i)~(v)에 의하여 조건을 만족시키는 함수 $g(t)$는 (iii)과 같다.\n3rd $a$, $b$의 값을 구하여 함수 $f(x)$를 완성해.\n(iii)에 의하여 $\\alpha=b^{2}-a^{2}$, $\\beta=b^{2}$이므로 $f\\left(\\frac{1}{2}\\right)=\\alpha$에서 $\\left(\\frac{1}{2}\\right)^{2}-2a \\times \\frac{1}{2}+b^{2}=b^{2}-a^{2}$ ($\\frac{1}{2}>0$이므로 $x=\\frac{1}{2}$을 $f(x)=x^{2}-2ax+b^{2}$에 대입)\n$a^{2}-a+\\frac{1}{4}=0$, $\\left(a-\\frac{1}{2}\\right)^{2}=0 \\therefore a=\\frac{1}{2} \\Rightarrow \\alpha=b^{2}-\\frac{1}{4}$\n또, $\\alpha+24\\beta=30$에서 $\\left(b^{2}-\\frac{1}{4}\\right)+24b^{2}=30$, $25b^{2}=\\frac{121}{4}$, $b^{2}=\\frac{121}{100} \\therefore b=\\frac{11}{10} (\\because b>0)$\n$\\therefore f(x)=\\begin{cases} \\left|-\\frac{1}{2}x^{2}+\\frac{11}{10}\\right| & (x \\le 0) \\\\ x^{2}-x+\\frac{121}{100} & (x>0) \\end{cases}$\n4th $f(-2)+f(1)$의 값을 구하고 $p+q$를 계산해.\n$f(-2)=\\left|-\\frac{1}{2} \\times (-2)^{2}+\\frac{11}{10}\\right|=\\left|-\\frac{9}{10}\\right|=\\frac{9}{10}$, $f(1)=1^{2}-1+\\frac{121}{100}=\\frac{121}{100}$이므로 $f(-2)+f(1)=\\frac{9}{10}+\\frac{121}{100}=\\frac{211}{100}$\n따라서 $p=100$, $q=211$이므로 $p+q=100+211=311$이다.\n[1등급 대비 특강] 조건을 만족시키는 $b$, $b^{2}$, $b^{2}-a^{2}$의 대소 관계: $y=f(x)$의 그래프의 개형에 따라 $g(t)$를 찾았다면 조건을 모두 만족시키는 경우를 찾기 위해 $g(t)$가 불연속이 되는 부분에 집중해야 한다. 불연속이 되는 $t$의 값 중에서 조건 (가)를 만족시키는 $\\alpha$, 조건 (나)를 만족시키는 $\\beta$가 존재하는지 확인하고 이 $\\alpha$, $\\beta$에 대하여 조건 (다)를 만족시키는지 확인해야 한다. 세 가지 조건 중 하나라도 만족시키지 못하는 경우를 모두 지워보면 $b^{2}-a^{2}<b<b^{2}$인 경우만 성립한다.", "img": "IMG_4985.jpg"}, {"id": "A230", "section": "A", "num": 230, "page": 82, "topic": "복잡하게 정의된 함수의 그래프와 x축에 평행한 직선이 만나는 서로 다른 점의 개수로 정의된 함수 파악하기", "answer": "141", "rate": "21%", "problem": "이차함수 $f(x)=x^{2}+2x+2$와 실수 $t$에 대하여 함수 $g(x)$는 $g(x)= \\begin{cases} f(x) & (x<0) \\\\ |f(-x)-t| & (x \\ge 0) \\end{cases}$ 이다. 함수 $y=g(x)$의 그래프와 직선 $y=\\frac{t}{3}$가 만나는 서로 다른 모든 점의 개수를 $h(t)$라 하자. $\\lim_{t \\to a-} h(t) \\ne \\lim_{t \\to a+} h(t)$인 모든 실수 $a$를 작은 수부터 크기순으로 나열한 것을 $a_{1}$, $a_{2}$, …, $a_{m}$ ($m$은 자연수)라 할 때, $\\sum_{k=1}^{m} \\{4a_{k} \\times h(a_{k})\\}$의 값을 구하시오. (4점)", "explanation": "[유형 20] 복잡하게 정의된 함수의 그래프와 $x$축에 평행한 직선이 만나는 서로 다른 점의 개수로 정의된 함수 파악하기 [2등급 대비]\n왜 2등급? 실수 $t$에 대하여 $x<0$, $x \\ge 0$에서 각각 다른 함수로 정의된 함수의 그래프와 $x$축에 평행한 직선이 만나는 서로 다른 점의 개수로 정의된 함수 $h(t)$의 좌극한값과 우극한값이 서로 다른 $t$의 값을 찾는 문제. $x \\ge 0$에서 $y=g(x)$의 그래프의 꼭짓점의 $y$좌표가 $|1-t|$이고 직선의 방정식은 $y=\\frac{t}{3}$이므로 $t$의 값에 따라 직선 $y=\\frac{t}{3}$보다 꼭짓점의 $y$좌표의 변화가 더 크다는 것을 파악하는 것이 어려웠다.\n단서1·단서3 $y=g(x)$의 그래프의 개형을 파악해야 한다. $x<0$일 때 $y=g(x)$의 그래프는 $y=f(x) (x<0)$의 그래프이고, $x \\ge 0$일 때 $g(x)=|f(-x)-t|$이므로 그래프는 $y=f(x)$의 그래프를 $y$축에 대하여 대칭이동한 후 $y$축의 방향으로 $-t$만큼 평행이동시킨 그래프에서 $y<0$인 부분을 $x$축에 대하여 대칭이동한 그래프이다.\n단서2 $x<0$일 때는 $y=g(x)$의 그래프가 고정되어 있으므로 $t$의 값에 따라 직선을 움직이면서 교점의 개수를 찾는다. $x \\ge 0$일 때는 $t$의 값에 따라 그래프가 변하므로 가능한 $y=g(x)$의 그래프를 빠짐없이 그려 직선 $y=\\frac{t}{3}$과의 서로 다른 교점의 개수를 찾는다.\n(단서: $h(t)$의 좌극한값과 우극한값이 서로 다른 점의 $x$좌표가 $a$라는 것. $h(t)$의 좌극한값과 우극한값이 서로 다른 점의 모든 $x$좌표와 그 때의 함숫값의 곱을 구해서 그 값들의 합을 계산하라는 것.)\n주의: $x \\ge 0$에서 $t$의 값에 따라 $y=g(x)$의 그래프의 개형이 바뀌므로 가능한 그래프의 개형을 모두 그리고 직선 $y=\\frac{t}{3}$과의 교점의 개수를 구해야 한다.\n핵심 정답 공식: $x<0$일 때와 $x \\ge 0$일 때의 $y=g(x)$의 그래프와 직선 $y=\\frac{t}{3}$의 서로 다른 교점의 개수를 더하여 함수 $h(t)$를 구한다.\n1st $x<0$일 때 함수 $y=g(x)$의 그래프와 직선 $y=\\frac{t}{3}$가 만나는 서로 다른 모든 점의 개수를 구해.\n$f(x)=x^{2}+2x+2=(x+1)^{2}+1$이므로 $x<0$일 때 $y=g(x)$의 그래프는 꼭짓점의 좌표가 $(-1, 1)$이고 $y$축과 만나는 점의 $y$좌표가 $2$인 아래로 볼록한 포물선이다.\n$y=g(x) (x<0)$의 그래프와 직선 $y=\\frac{t}{3}$가 만나는 서로 다른 점의 개수를 $r(t)$라 하면\n(i) $\\frac{t}{3}<1$, 즉 $t<3$일 때 $r(t)=0$\n(ii) $\\frac{t}{3}=1$, 즉 $t=3$일 때 $r(t)=1$\n(iii) $1<\\frac{t}{3}<2$, 즉 $3<t<6$일 때 $r(t)=2$\n(iv) $\\frac{t}{3} \\ge 2$, 즉 $t \\ge 6$일 때 $r(t)=1$ (주의: 직선 $y=\\frac{t}{3}=2$일 때는 $x<-1$인 점에서만 한 번 만나. $x=0$일 때도 만난다고 착각하면 안 돼.)\n(i)~(iv)에 의하여 $r(t)=\\begin{cases} 0 & (t<3) \\\\ 1 & (t=3) \\\\ 2 & (3<t<6) \\\\ 1 & (t \\ge 6) \\end{cases} \\cdots$㉠\n2nd $x \\ge 0$일 때 $t$의 값에 따라 경우를 나누고 함수 $y=g(x)$의 그래프와 직선 $y=\\frac{t}{3}$가 만나는 서로 다른 모든 점의 개수를 구해.\n(함정: $t$의 값이 변함에 따라 $y=|f(-x)-t|$의 그래프와 직선 $y=\\frac{t}{3}$의 위치가 동시에 변하므로 $t$의 값으로 인해 나타나는 모든 그래프의 개형을 빠짐없이 찾아야 해.)\n$|f(-x)-t|=|(-x+1)^{2}+1-t|=|(x-1)^{2}+1-t|$이므로 $x \\ge 0$일 때 $y=g(x)$의 그래프는 $y=(x-1)^{2}+1-t (x \\ge 0)$의 그래프에서 $y<0$인 부분을 $x$축에 대하여 대칭이동하여 그린 그래프와 같다. ($y=f(-x)-t$의 그래프는 꼭짓점의 좌표가 $(1, 1-t)$이고 $y$축과 만나는 점의 $y$좌표가 $2-t$인 아래로 볼록한 포물선. 꼭짓점 $A$, $y$절편 $B$가 $x$축 위/아래에 있는지에 따라 개형이 달라져.)\n$y=g(x) (x \\ge 0)$의 그래프와 직선 $y=\\frac{t}{3}$가 만나는 서로 다른 점의 개수를 $s(t)$라 하면\n(i) $1-t>0$이고 $1-t>\\frac{t}{3}$일 때, 즉 $t<\\frac{3}{4}$일 때 $s(t)=0$\n(ii) $1-t=\\frac{t}{3}$, 즉 $t=\\frac{3}{4}$일 때 $s(t)=1$\n(iii) $1-t \\ge 0$이고 $1-t<\\frac{t}{3}<2-t$일 때, 즉 $\\frac{3}{4}<t \\le 1$일 때 $s(t)=2$ ($1-t<\\frac{t}{3}$에서 $t>\\frac{3}{4}$이고 $\\frac{t}{3}<2-t$에서 $t<\\frac{3}{2}$이므로 $\\frac{3}{4}<t<\\frac{3}{2}$)\n(iv) $1-t<0$, $2-t>0$이고 $t-1<\\frac{t}{3}<2-t$일 때, 즉 $1<t<\\frac{3}{2}$일 때 $s(t)=2$\n(v) $1-t<0$, $2-t>0$이고 $t-1=\\frac{t}{3}$일 때, 즉 $t=\\frac{3}{2}$일 때 $s(t)=3$\n(vi) $1-t<0$, $2-t>0$이고 $2-t<\\frac{t}{3}<t-1$일 때, 즉 $\\frac{3}{2}<t<2$일 때 $s(t)=3$ ($2-t<\\frac{t}{3}$에서 $t>\\frac{3}{2}$이고 $\\frac{t}{3}<t-1$에서 $t>\\frac{3}{2}$이므로 $t>\\frac{3}{2}$)\n(vii) $2-t \\le 0$, $1-t<0$이고 $t-2<\\frac{t}{3}<t-1$일 때, 즉 $2 \\le t<3$일 때 $s(t)=3$ ($t-2<\\frac{t}{3}$에서 $t<3$이고 $\\frac{t}{3}<t-1$에서 $t>\\frac{3}{2}$이므로 $\\frac{3}{2}<t<3$)\n(viii) $2-t<0$, $1-t<0$이고 $t-2=\\frac{t}{3}$일 때, 즉 $t=3$일 때 $s(t)=3$\n(ix) $2-t<0$, $1-t<0$이고 $0<\\frac{t}{3}<t-2$일 때, 즉 $t>3$일 때 $s(t)=2$\n(i)~(ix)에 의하여 $s(t)=\\begin{cases} 0 & (t<\\frac{3}{4}) \\\\ 1 & (t=\\frac{3}{4}) \\\\ 2 & (\\frac{3}{4}<t<\\frac{3}{2}) \\\\ 3 & (\\frac{3}{2} \\le t \\le 3) \\\\ 2 & (t>3) \\end{cases} \\cdots$㉡\n3rd 조건을 만족시키는 $a$의 값을 모두 구하고 $\\sum \\{4a_{k} \\times h(a_{k})\\}$의 값을 구해.\n$h(t)=r(t)+s(t)$이므로 ㉠, ㉡에 의하여 $h(t)=\\begin{cases} 0 & (t<\\frac{3}{4}) \\\\ 1 & (t=\\frac{3}{4}) \\\\ 2 & (\\frac{3}{4}<t<\\frac{3}{2}) \\\\ 3 & (\\frac{3}{2} \\le t<3) \\\\ 4 & (3 \\le t<6) \\\\ 3 & (t \\ge 6) \\end{cases}$\n이때 $\\lim_{t \\to a-} h(t) \\ne \\lim_{t \\to a+} h(t)$인 모든 실수 $a$(극한값이 존재하지 않는 $t$의 값)를 작은 수부터 나열하면 $a_{1}=\\frac{3}{4}$, $a_{2}=\\frac{3}{2}$, $a_{3}=3$, $a_{4}=6$이고, $h(a_{1})=1$, $h(a_{2})=3$, $h(a_{3})=4$, $h(a_{4})=3$이므로\n$\\sum_{k=1}^{m} \\{4a_{k} \\times h(a_{k})\\}=\\sum_{k=1}^{4} \\{4a_{k} \\times h(a_{k})\\}=4 \\times \\frac{3}{4} \\times 1+4 \\times \\frac{3}{2} \\times 3+4 \\times 3 \\times 4+4 \\times 6 \\times 3=141$\n[톡톡 풀이: $s(t)$를 방정식 $|f(-x)-t|=\\frac{t}{3} (x \\ge 0)$의 서로 다른 실근의 개수로 구하기]\n$s(t)$는 $y=|f(-x)-t| (x \\ge 0)$의 그래프와 직선 $y=\\frac{t}{3}$가 만나는 서로 다른 점의 개수이므로 방정식 $|f(-x)-t|=\\frac{t}{3} (x \\ge 0)$의 서로 다른 실근의 개수로 생각할 수도 있다.\n$|f(-x)-t|=\\frac{t}{3}$에서 $f(-x)-t=\\frac{t}{3}$ 또는 $f(-x)-t=-\\frac{t}{3}$이므로 $f(-x)=\\frac{4}{3}t$ 또는 $f(-x)=\\frac{2}{3}t$\n따라서 $s(t)$는 $x \\ge 0$일 때 $y=f(-x)$의 그래프와 직선 $y=\\frac{4}{3}t$가 만나는 점의 개수와 직선 $y=\\frac{2}{3}t$가 만나는 점의 개수의 합이다.\n$f(-x)=x^{2}-2x+2=(x-1)^{2}+1$이므로 $y=f(-x) (x \\ge 0)$의 그래프는 꼭짓점 $(1, 1)$, $y$절편 $2$인 포물선이다.\n$y=f(-x) (x \\ge 0)$의 그래프와 직선 $y=\\frac{4}{3}t$가 만나는 서로 다른 점의 개수를 $m(t)$라 하면\n(i) $\\frac{4}{3}t<1$, 즉 $t<\\frac{3}{4}$일 때 $m(t)=0$\n(ii) $\\frac{4}{3}t=1$, 즉 $t=\\frac{3}{4}$일 때 $m(t)=1$\n(iii) $1<\\frac{4}{3}t \\le 2$, 즉 $\\frac{3}{4}<t \\le \\frac{3}{2}$일 때 $m(t)=2$\n(iv) $\\frac{4}{3}t>2$, 즉 $t>\\frac{3}{2}$일 때 $m(t)=1$\n$\\therefore m(t)=\\begin{cases} 0 & (t<\\frac{3}{4}) \\\\ 1 & (t=\\frac{3}{4}) \\\\ 2 & (\\frac{3}{4}<t \\le \\frac{3}{2}) \\\\ 1 & (t>\\frac{3}{2}) \\end{cases} \\cdots$㉠\n또, $y=f(-x) (x \\ge 0)$의 그래프와 직선 $y=\\frac{2}{3}t$가 만나는 서로 다른 점의 개수를 $n(t)$라 하면\n(i) $\\frac{2}{3}t<1$, 즉 $t<\\frac{3}{2}$일 때 $n(t)=0$ (ii) $\\frac{2}{3}t=1$, 즉 $t=\\frac{3}{2}$일 때 $n(t)=1$ (iii) $1<\\frac{2}{3}t \\le 2$, 즉 $\\frac{3}{2}<t \\le 3$일 때 $n(t)=2$ (iv) $\\frac{2}{3}t>2$, 즉 $t>3$일 때 $n(t)=1$\n$\\therefore n(t)=\\begin{cases} 0 & (t<\\frac{3}{2}) \\\\ 1 & (t=\\frac{3}{2}) \\\\ 2 & (\\frac{3}{2}<t \\le 3) \\\\ 1 & (t>3) \\end{cases} \\cdots$㉡\n따라서 $s(t)=m(t)+n(t)$이므로 ㉠, ㉡에 의하여 $s(t)=\\begin{cases} 0 & (t<\\frac{3}{4}) \\\\ 1 & (t=\\frac{3}{4}) \\\\ 2 & (\\frac{3}{4}<t<\\frac{3}{2}) \\\\ 3 & (\\frac{3}{2} \\le t \\le 3) \\\\ 2 & (t>3) \\end{cases}$ (이하 동일)\n[My Top Secret] $x<0$에서 $y=g(x)$의 그래프는 고정되어 있으므로 직선 $y=\\frac{t}{3}$과의 교점의 개수는 구하기 쉽다. 그러나 $x \\ge 0$에서는 그래프가 $t$의 값에 따라 변화하므로 교점의 개수를 구하기 어렵다. 따라서 고정할 수 있는 것은 고정하여 최대한 간단하게 만들면 쉽게 해결할 수 있다. 즉, $x \\ge 0$에서 교점의 개수는 방정식 $|f(-x)-t|=\\frac{t}{3} (x \\ge 0)$의 서로 다른 실근의 개수와 같으므로 절댓값을 없애 $f(-x)=\\frac{2t}{3}$ 또는 $f(-x)=\\frac{4t}{3}$로 나타내어 실근의 개수를 계산하면 쉽게 접근할 수 있다.", "img": "IMG_4987.jpg"}, {"id": "A231", "section": "A", "num": 231, "page": 85, "topic": "새롭게 정의된 함수의 그래프를 이용하여 함수의 극한값 구하기", "answer": "4", "rate": "15%", "problem": "실수 $k$와 함수 $f(x)= \\begin{cases} 2^{x-2} & (x<2) \\\\ 2^{-x+2} & (x \\ge 2) \\end{cases}$ 에 대하여 함수 $g(x)$를 $g(x)=|f(x)-k|+k$라 하자. 직선 $y=2k$와 함수 $y=g(x)$의 그래프가 만나는 점의 개수를 $h(k)$라 할 때, $\\lim_{k \\to \\frac{1}{4}-} \\left\\{h(k)h\\left(k+\\frac{1}{4}\\right)\\right\\}$의 값을 구하시오. (4점)", "explanation": "[유형 20] 새롭게 정의된 함수의 그래프를 이용하여 함수의 극한값 구하기 [1등급 대비]\n왜 1등급? $y=g(x)$의 그래프와 직선 $y=2k$의 교점의 개수를 새로운 함수 $h(k)$로 정의하여 $h(k)$에 대한 극한값을 구하는 문제. 구간에 따라 다르게 정의된 $f(x)$와 절댓값을 이용하여 정의된 $y=g(x)$의 그래프를 나타내고 적절히 $k$의 값의 범위를 나누어 $h(k)$를 구하는 것이 어려웠다.\n단서1 $g(x)=\\begin{cases} f(x) & (f(x) \\ge k) \\\\ -f(x)+2k & (f(x)<k) \\end{cases}$이다. 이때 $y=-f(x)+2k$의 그래프는 $y=f(x)$의 그래프를 직선 $y=k$에 대하여 대칭이동한 것이다.\n단서2 $y=f(x)$의 그래프를 이용하여 $y=g(x)$의 그래프를 유추한 후 $k$의 값의 범위를 나누어 $h(k)$를 구한다.\n단서3 $\\lim_{k \\to \\frac{1}{4}-} h(k)$, $\\lim_{k \\to \\frac{1}{4}-} h\\left(k+\\frac{1}{4}\\right)$의 값을 각각 구해 곱하면 된다. (각각의 극한값이 존재하는 두 함수의 곱의 극한값은 각각의 극한값의 곱)\n주의: 절댓값이 포함된 함수의 그래프를 그릴 때는 절댓값 안의 부호가 $0$보다 크거나 같을 때와 $0$보다 작을 때로 나누어 생각한다.\n핵심 정답 공식: $|f(x)-k|+k = f(x) (f(x) \\ge k)$, $-f(x)+2k (f(x)<k)$이다. 또한 $y=F(x)$의 그래프를 직선 $y=k$에 대하여 대칭이동시킨 그래프의 식은 $2k-y=F(x)$, 즉 $y=-F(x)+2k$이다.\n1st 함수 $y=f(x)$의 그래프를 그려보자.\n$y=2^{x-2}$의 그래프는 $y=2^{x}$의 그래프를 $x$축의 방향으로 $2$만큼 평행이동한 것이고, $y=2^{-x+2}$의 그래프는 $y=2^{-x}$의 그래프를 $x$축의 방향으로 $2$만큼 평행이동한 것이므로 $y=f(x)$의 그래프는 [그림 1]과 같다. ($x=2$에 대하여 대칭이고 최댓값 $f(2)=1$, $x$축이 점근선)\n2nd $k$의 값의 범위를 나누어 $h(k)$를 구하자.\n$g(x)=|f(x)-k|+k = f(x) (f(x) \\ge k)$, $-f(x)+2k (f(x)<k)$이므로 $y=g(x)$의 그래프는 $y=f(x)$의 그래프에서 직선 $y=k$의 윗부분은 그대로 두고, 아랫부분은 직선 $y=k$에 대하여 대칭이동시킨 것이다. (실수 주의: 절댓값을 포함한 함수의 그래프는 실수가 많이 나오는 부분)\n(i) $k \\le 0$일 때: 모든 실수 $x$에 대하여 $f(x)>k$이므로 $g(x)=f(x)>0 \\ge 2k$. 직선 $y=2k$와 만나는 점은 없다. $\\therefore h(k)=0$\n(ii) $0<k<\\frac{1}{2}$일 때$(2k<1)$: $y=f(x)$와 직선 $y=k$가 만나는 두 점을 $A$, $B$라 하면 $y=g(x)$의 그래프는 [그림 3]과 같다. $y=g(x)$의 점근선이 $y=2k$이므로 $y=2k<1$인 범위에서 만나는 점은 $2$개이다. $\\therefore h(k)=2$\n(iii) $k=\\frac{1}{2}$일 때$(2k=1)$: 직선 $y=2k$와 $y=g(x)$의 그래프가 만나는 점은 $1$개이다. $\\therefore h(k)=1$\n(iv) $\\frac{1}{2}<k<1$일 때$(2k>1)$: 직선 $y=2k$와 $y=g(x)$의 그래프가 만나는 점은 없다. $\\therefore h(k)=0$\n(v) $k \\ge 1$일 때: 모든 실수 $x$에 대하여 $g(x)=-f(x)+2k<2k$이므로 만나는 점은 없다. $\\therefore h(k)=0$\n3rd 함수 $y=h(k)$의 그래프를 이용하여 주어진 극한값을 구하자.\n$h(k)=\\begin{cases} 0 & (k \\le 0\\text{ 또는 }k>\\frac{1}{2}) \\\\ 1 & (k=\\frac{1}{2}) \\\\ 2 & (0<k<\\frac{1}{2}) \\end{cases}$\n따라서 $\\lim_{k \\to \\frac{1}{4}-} h(k)=2$, $\\lim_{k \\to \\frac{1}{4}-} h\\left(k+\\frac{1}{4}\\right)=2$이므로 ($k \\to \\frac{1}{4}-$일 때 $k+\\frac{1}{4} \\to \\frac{1}{2}-$이므로 $k+\\frac{1}{4}=t$라 하면 $\\lim_{k \\to \\frac{1}{4}-} h\\left(k+\\frac{1}{4}\\right)=\\lim_{t \\to \\frac{1}{2}-} h(t)$)\n$\\lim_{k \\to \\frac{1}{4}-} \\left\\{h(k)h\\left(k+\\frac{1}{4}\\right)\\right\\}=\\lim_{k \\to \\frac{1}{4}-} h(k) \\times \\lim_{k \\to \\frac{1}{4}-} h\\left(k+\\frac{1}{4}\\right)=2 \\times 2=4$\n[1등급 대비 특강: $x$에 대한 방정식을 이용하여 함수 $h(k)$ 파악하기] $y=g(x)$의 그래프와 직선 $y=2k$가 만나는 점의 개수는 방정식 $g(x)=2k$, 즉 $|f(x)-k|=k$의 서로 다른 실근의 개수, 즉 $f(x)=0$ 또는 $f(x)=2k$를 만족시키는 서로 다른 실근의 개수이다. 모든 실수 $x$에 대해서 $f(x)>0$이므로 $f(x)=2k$의 실근의 개수만 생각하면 된다. 따라서 실근의 개수는 $2k \\le 0$일 때 $0$개, $0<2k<1$일 때 $2$개, $2k=1$일 때 $1$개, $2k>1$일 때 $0$개임을 쉽게 파악할 수 있다.", "img": "IMG_4990.jpg"}];
